bool retain_port_visual_controller_ready(ObjectActor& actor,
                                         const ObjectGroup& group) noexcept {
 // The direct renderer has no native VisualObject+0x38 pointer. Its same-
 // actor port controller is the embedded scheduler plus the installed
 // Character ObjectGroup resource/clip bank. Publish readiness only after
 // those resources are complete; this fact is independent of current frames.
 const bool ready=actor.kind==1&&actor.identity&&actor.scheduler.active()&&
     actor.animation_table_id>=0&&
     group.animation_table==actor.animation_table_id&&
     group.draws.size()==group.resource.primitives.size()&&
     !group.clips.empty()&&
     group.clips.find(actor.scheduler.clip().anim)!=group.clips.end();
 actor.port_visual_controller_ready=ready;
 return ready;
}
