ScriptSummonActorOwnerV1* script_summon_owner(
    NativeCryptRoomRuntime& runtime,std::uintptr_t identity) {
 const auto found=runtime.script_npcs_by_identity.find(identity);
 if(found==runtime.script_npcs_by_identity.end()||!found->second||
    !found->second->actor||found->second->actor->identity!=identity)return nullptr;
 return found->second;
}

int script_summon_object_base(void* raw,ScriptCtor::Identity identity,
                              std::uint32_t go_ids,std::string& error) {
 auto* context=static_cast<ScriptSummonFactoryContextV1*>(raw);
 auto* record=context&&context->factory?context->factory->find_character(identity):nullptr;
 if(!context||!context->runtime||!record||!identity||go_ids!=0||
    record->character.identity!=identity||record->game_object.identity!=identity) {
  error="CreateNPC ObjectBase constructor lost its same-Record GO_IDS=0 source argument";
  return 1;
 }
 return 0;
}

constexpr std::size_t kScriptSummonGroupHeadroom=24;
// The retained DACT actor stores the packaged asset basename (with extension)
// while the ModelDict holds the authored path.
std::string script_summon_model_basename(const std::string& path) {
 const auto separator=path.find_last_of("/\\");
 return path.substr(separator==std::string::npos?0:separator+1);
}
// Builds the canonical ObjectGroup of a Character model no Level actor stages
// (install_script_summon_object_group, bound by the Level loader once it has
// reserved the group headroom the installer needs).
using ScriptSummonGroupInstaller=ObjectGroup*(*)(AAssetManager*,const std::string&,
                                                 std::int32_t,std::string&);
ScriptSummonGroupInstaller script_summon_group_installer=nullptr;
int script_summon_factory_component(void* raw,ScriptCtor::Component component,
    ScriptCtor::Identity identity,ScriptFactory::ComponentStorage::Slot* slot,
    std::string& error) {
 auto* context=static_cast<ScriptSummonFactoryContextV1*>(raw);
 if(!context||!context->runtime||!context->factory||!slot||!identity) {
  error="CreateNPC component provider has no active canonical runtime";return 1;
 }
 auto* record=context->factory->find_character(identity);
 if(!record||record->character.identity!=identity||
    record->game_object.identity!=identity||record->source_handle<0) {
  error="CreateNPC component provider lost the factory Record identity";return 1;
 }
 auto* owner=script_summon_owner(*context->runtime,identity);
 if(component==ScriptCtor::Component::game_object) {
  ObjectGroup* selected_group=nullptr;
  ObjectActor* selected_actor=nullptr;
  bool actor_appended=false;
  if(owner||record->dynamic_character_table_id<0||record->dynamic_character_table_id>INT16_MAX||
     std::size_t(record->dynamic_character_table_id)>=actor_character_names.size()||
     std::size_t(record->dynamic_character_table_id)>=actor_character_property_rows.size()||
     actor_character_names[std::size_t(record->dynamic_character_table_id)]!=record->dynamic_character_table_name||
     actor_character_fields.empty()) {
   error="CreateNPC CharacterTable row/name is not unique in retained data";return 1;
  }
  const auto& properties=actor_character_property_rows[std::size_t(record->dynamic_character_table_id)];
  const auto model_field=std::find(actor_character_fields.begin(),actor_character_fields.end(),"ModelFile");
  const auto animation_field=std::find(actor_character_fields.begin(),actor_character_fields.end(),"AnimTable");
  if(model_field==actor_character_fields.end()||animation_field==actor_character_fields.end()||
     actor_model_table.values.empty()) {
   error="CreateNPC CharacterTable ModelFile or AnimTable field is unavailable";return 1;
  }
  const auto model_index=static_cast<std::size_t>(model_field-actor_character_fields.begin());
  const auto animation_index=static_cast<std::size_t>(animation_field-actor_character_fields.begin());
  if(model_index>=properties.size()||properties[model_index]<0||
     animation_index>=properties.size()||properties[animation_index]<0||
     std::size_t(properties[model_index])>=actor_model_table.values.size()||
     std::size_t(properties[animation_index])>=actor_animation_tables.characters.size()) {
   error="CreateNPC CharacterTable ModelFile/AnimTable OID is outside retained catalog";return 1;
  }
  const auto model_name=script_summon_model_basename(
      actor_model_table.values[std::size_t(properties[model_index])]);
  const auto animation_id=properties[animation_index];
  auto group=std::find_if(object_groups.begin(),object_groups.end(),[&](const ObjectGroup& candidate){
   return candidate.animation_table==animation_id&&
       ((!candidate.instances.empty()&&candidate.instances.front().model==model_name)||
        candidate.installed_model==model_name);
  });
  if(group==object_groups.end()) {
   // No Level actor uses this CharacterTable model (a Player skill summoning a
   // Dummy or a risen Zombie): build its canonical group from the same model,
   // Idle clip and clip bank the Level loader stages for an actor.
   if(!script_summon_group_installer) {
    error="CreateNPC CharacterTable model has no installed canonical ObjectGroup and no on-demand installer is bound";
    return 1;
   }
   if(!script_summon_group_installer(context->runtime->assets,model_name,
        animation_id,error))return 1;
   group=std::prev(object_groups.end());
  }
  if(group->resource.rest_scene.graph.empty()||
     group->draws.size()!=group->resource.primitives.size()) {
   error="CreateNPC CharacterTable model has no installed canonical ObjectGroup/animation draw bank";return 1;
  }
  selected_group=&*group;
  try {
   auto staged=std::make_unique<ScriptSummonActorOwnerV1>();
   dh2::objects::Record description{};
   description.kind=1;description.name=record->game_object.name;
   description.character=record->dynamic_character_table_name;
   description.model=model_name;
   description.position={record->game_object.world_x,record->game_object.world_y,0.f};
   description.scale={1.f,1.f,1.f};
   for(unsigned i=0;i<4;++i)description.placement[i*5]=1.f;
   description.placement[12]=description.position[0];
   description.placement[13]=description.position[1];
   description.placement[14]=description.position[2];
   selected_group->instances.emplace_back(description);actor_appended=true;
   selected_actor=&selected_group->instances.back();
   staged->actor=selected_actor;staged->group=selected_group;staged->record=record;
   auto& actor=*selected_actor;actor.identity=identity;actor.source_handle=record->source_handle;
   actor.character_table_id=static_cast<std::int16_t>(record->dynamic_character_table_id);
   actor.animation_table_id=animation_id;
   actor.source_module_index=std::numeric_limits<std::uint32_t>::max();
   actor.source_record=std::numeric_limits<std::uint32_t>::max();
   actor.source_object_module_id=record->game_object.module_id_64;
   // The factory constructor publishes +0x28 only after all Character ctor
   // stages complete; this facade must not claim constructor readiness early.
   actor.source_save_eligibility_28=0;actor.source_deleted_81=0;
   actor.position=description.position;actor.initial_position=description.position;
   actor.rotation_degrees=description.rotation_degrees;actor.scale=description.scale;
   actor.placement=description.placement;actor.source_updates_enabled=true;
   actor.renderer_visible=true;actor.search_projection.object.identity=identity;
   const auto* idle=dh2::data::animation_state(actor_animation_tables,
       animation_id,"Idle");
   if(!idle)throw std::runtime_error(
       "CreateNPC has no retained Idle sequence for its selected Character AnimTable");
   const auto idle_sequence=static_cast<std::int32_t>(
       idle-actor_animation_tables.sequences.data());
   if(!actor.scheduler.start(actor_animation_tables,idle_sequence,
       actor_random,error))
    throw std::runtime_error("CreateNPC could not install its Character scheduler: "+error);
   actor.animator_sequence_closed_48=0;
   if(!retain_port_visual_controller_ready(actor,*selected_group))
    throw std::runtime_error(
        "CreateNPC could not retain the installed Character scheduler/clip bank");
   actor.search_projection.character.identity=identity;
   actor.search_projection.character.object=&actor.search_projection.object;
   actor.search_projection.is_character=1;
   auto* stable=staged.get();context->runtime->script_npc_owners.push_back(std::move(staged));
   if(!context->runtime->script_npcs_by_identity.emplace(identity,stable).second||
      !context->runtime->actors.emplace(identity,&actor).second) {
    context->runtime->script_npcs_by_identity.erase(identity);context->runtime->actors.erase(identity);
    context->runtime->script_npc_owners.pop_back();
    if(actor_appended&&!selected_group->instances.empty()&&
       &selected_group->instances.back()==selected_actor)selected_group->instances.pop_back();
    error="CreateNPC Character identity already exists in active runtime";return 1;
   }
   context->runtime->actor_records.push_back(&actor);context->owner=stable;
   slot->canonical_owner=&actor;return 0;
  } catch(...) {
   if(actor_appended&&selected_group&&!selected_group->instances.empty()&&
      &selected_group->instances.back()==selected_actor)selected_group->instances.pop_back();
   error="CreateNPC stable actor facade allocation failed";return 1;
  }
 }
 // Character::Character constructs the controllable (step 2) before CharTimers
 // (step 4, which creates the shared timer/state owner), so only the later
 // components can require the Coordinator.
 const bool coordinator_required=component!=ScriptCtor::Component::controllable;
 if(!owner||!owner->actor||(coordinator_required&&
      (!record->coordinator||record->coordinator->owner()!=identity))) {
  error="CreateNPC component adoption ran before its stable Actor/Coordinator existed";
  return 1;
 }
 auto& actor=*owner->actor;
 if(component==ScriptCtor::Component::ai) {
  if(owner->native_ai||actor.native_ai||!source_char_ai.ready||source_char_ai.by_character.count(identity)) {
   error="CreateNPC CharAI identity is already registered or shared registry is unavailable";return 1;
  }
  try {
   auto projection=std::make_shared<NativeCharAIProjection>();
   projection->character_identity=identity;
   projection->ai_identity=reinterpret_cast<std::uintptr_t>(&projection->state);
   projection->animation_state.owner_byte14a8=-1; // Character C1 initializes the signed OOI-type byte to -1.
   projection->relations=&actor.aggro;projection->state.identity=projection->ai_identity;
   source_char_ai.projections.reserve(source_char_ai.projections.size()+1);
   source_char_ai.queue_order.reserve(source_char_ai.queue_order.size()+1);
   source_char_ai.queue_registered.reserve(source_char_ai.queue_registered.size()+1);
   source_char_ai.by_character.reserve(source_char_ai.by_character.size()+1);
   CharAIAppendContext append_context{&source_char_ai};
   const dh2::character_ai_initialization::Services ai_services{&append_context,append_char_ai};
   if(dh2::character_ai_initialization::construct(&projection->state,kNativeCharAIDispatchToken,
       &ai_services,&projection->constructor_result)!=dh2::character_ai_initialization::Status::complete||
      projection->constructor_result.queue_calls!=1||!projection->constructor_result.queued||
      dh2::character_ai_association::associate(&projection->state,identity)!=
       dh2::character_ai_association::Status::complete||projection->state.owner_04!=identity) {
    const auto queued=std::find(source_char_ai.queue_order.begin(),source_char_ai.queue_order.end(),projection->ai_identity);
    if(queued!=source_char_ai.queue_order.end())source_char_ai.queue_order.erase(queued);
    actor.spawn_owner.reset();error="CreateNPC CharAI constructor/association failed";return 1;
   }
   projection->state.tree_7c.count=actor.aggro.out_count;
   projection->state.tree_94.count=actor.aggro.in_count;
   source_char_ai.projections.push_back(projection);
   if(!source_char_ai.by_character.emplace(identity,projection.get()).second)
    throw std::runtime_error("duplicate CharAI Character association");
   if(source_char_ai_queue.register_ai(projection->ai_identity,native_char_ai_owner(*projection))!=
      dh2::character_ai_queue_owner_v1::Status::complete)
    throw std::runtime_error("CharAI scheduler rejected the source Summon");
   source_char_ai.queue_registered.push_back(projection->ai_identity);
   owner->native_ai=projection;actor.native_ai=std::move(projection);owner->ai_registered=true;
   slot->canonical_owner=&actor.native_ai->state;return 0;
  } catch(const std::exception& exception) {
   error=std::string("CreateNPC CharAI adoption failed: ")+exception.what();return 1;
  }
 }
 switch(component) {
 case ScriptCtor::Component::controllable:
  owner->controllable.character=identity;
  owner->controllable.controller=0;
  slot->canonical_owner=&owner->controllable;return 0;
 case ScriptCtor::Component::controller:
  if(owner->controllable.character!=identity||record->faery_controller.character) {
   error="CreateNPC controller component has a duplicate or foreign controllable";return 1;
  }
  // character_faery_controller_v1::bind insists on a registered Record, which
  // only exists after the whole constructor transaction. Publish the same
  // aggregate it assigns; the constructor's controller association then proves
  // it aliases this controllable and the controller slot.
  record->faery_controller.character=identity;
  record->faery_controller.controller=
      reinterpret_cast<std::uintptr_t>(&record->faery_controller);
  record->faery_controller.controllable=
      reinterpret_cast<std::uintptr_t>(&owner->controllable);
  record->faery_controller.global_blocked=0;
  record->faery_controller.locked=0;
  record->faery_controller.forced=0;
  owner->controllable.controller=record->faery_controller.controller;
  slot->canonical_owner=&record->faery_controller;return 0;
 case ScriptCtor::Component::animator:slot->canonical_owner=&actor.scheduler;return 0;
 case ScriptCtor::Component::properties:slot->canonical_owner=&actor.properties;return 0;
 case ScriptCtor::Component::game_object:case ScriptCtor::Component::inventory:
 case ScriptCtor::Component::timers:case ScriptCtor::Component::ai:
 case ScriptCtor::Component::state_machine:case ScriptCtor::Component::net_state_primary:
 case ScriptCtor::Component::net_state_secondary:break;
 }
 error="CreateNPC component has no one canonical adopted owner";return 1;
}

int script_summon_factory_associate(void* raw,ScriptCtor::Association association,
    ScriptCtor::Identity identity,const ScriptFactory::ComponentStorage& components,
    std::string& error) {
 auto* context=static_cast<ScriptSummonFactoryContextV1*>(raw);
 auto* record=context&&context->factory?context->factory->find_character(identity):nullptr;
 auto* owner=context&&context->runtime?script_summon_owner(*context->runtime,identity):nullptr;
 if(!record||!owner||!owner->actor||owner->record!=record||
    record->character.identity!=identity) {
  error="CreateNPC association lost its same-identity factory/actor owner";return 1;
 }
 using Association=ScriptCtor::Association;
 switch(association) {
 case Association::target_list:
  return record->character.object==&record->aggro_object?0:1;
 case Association::controller:
  if(record->faery_controller.character==identity&&
     record->faery_controller.controller&&
     record->faery_controller.controllable==
        reinterpret_cast<std::uintptr_t>(&owner->controllable)&&
     components.find(ScriptCtor::Component::controller)==&record->faery_controller&&
     components.find(ScriptCtor::Component::controllable)==&owner->controllable)
   return 0;
  break;
 case Association::timers:
  if(record->coordinator&&record->coordinator->owner()==identity&&
     components.find(ScriptCtor::Component::timers)==record->coordinator.get())return 0;
  break;
 case Association::ai:
  if(owner->native_ai&&owner->native_ai->character_identity==identity&&
     owner->native_ai->state.owner_04==identity&&
     components.find(ScriptCtor::Component::ai)==&owner->native_ai->state)return 0;
  break;
 case Association::animator:
  if(components.find(ScriptCtor::Component::animator)==&owner->actor->scheduler)return 0;
  break;
 case Association::state_machine:
  if(record->coordinator&&record->coordinator->owner()==identity&&
     components.find(ScriptCtor::Component::state_machine)==record->coordinator.get())return 0;
  break;
 case Association::properties:
  if(components.find(ScriptCtor::Component::properties)==&owner->actor->properties)return 0;
  break;
 }
 error="CreateNPC association does not alias its canonical component owner";
 return 1;
}

int script_summon_factory_register_state(void* raw,ScriptCtor::Identity identity,
    std::uint32_t state,std::string& error) {
 auto* context=static_cast<ScriptSummonFactoryContextV1*>(raw);
 auto* record=context&&context->factory?context->factory->find_character(identity):nullptr;
 if(!record||!record->coordinator||record->coordinator->owner()!=identity||state>=20) {
  error="CreateNPC RegisterState has no same-Record Coordinator or valid source state";return 1;
 }
 const auto handler=reinterpret_cast<std::uintptr_t>(&dh2_character_state_transition);
 if(!handler||!record->coordinator->register_source_state(identity,state,handler)) {
  error="CreateNPC RegisterState could not attach to its canonical Coordinator";return 1;
 }
 return 0;
}

void script_summon_factory_rollback(void* raw,ScriptCtor::Action action,
    std::uint32_t value,ScriptCtor::Identity identity,
    ScriptFactory::ComponentStorage&) noexcept {
 auto* context=static_cast<ScriptSummonFactoryContextV1*>(raw);
 auto* record=context&&context->factory?context->factory->find_character(identity):nullptr;
 auto* owner=context&&context->runtime?script_summon_owner(*context->runtime,identity):nullptr;
 if(action==ScriptCtor::Action::state) {
  if(record&&record->coordinator&&value<20) {
   const auto handler=reinterpret_cast<std::uintptr_t>(&dh2_character_state_transition);
   (void)record->coordinator->unregister_source_state(identity,value,handler);
  }
  return;
 }
 if(action!=ScriptCtor::Action::component||!owner)return;
 const auto component=static_cast<ScriptCtor::Component>(value);
 if(component==ScriptCtor::Component::ai&&owner->native_ai) {
  const auto ai_identity=owner->native_ai->ai_identity;
  if(owner->ai_registered) {
   (void)source_char_ai_queue.remove_ai(ai_identity);
   auto& registered=source_char_ai.queue_registered;
   registered.erase(std::remove(registered.begin(),registered.end(),ai_identity),registered.end());
   owner->ai_registered=false;
  }
  auto& order=source_char_ai.queue_order;
  order.erase(std::remove(order.begin(),order.end(),ai_identity),order.end());
  source_char_ai.by_character.erase(identity);
  auto& projections=source_char_ai.projections;
  projections.erase(std::remove_if(projections.begin(),projections.end(),[&](const auto& item){
   return item==owner->native_ai;
  }),projections.end());
  owner->actor->native_ai.reset();owner->native_ai.reset();
 }
 if(component==ScriptCtor::Component::controller&&record)
  dh2::character_faery_controller_v1::retire(record->faery_controller);
 if(component==ScriptCtor::Component::game_object&&owner->actor) {
  context->runtime->actors.erase(identity);
  auto& rows=context->runtime->actor_records;
  rows.erase(std::remove(rows.begin(),rows.end(),owner->actor),rows.end());
  context->runtime->script_npcs_by_identity.erase(identity);
  owner->actor->source_room_zone_managed=true;
  owner->actor->renderer_visible=false;
  owner->actor->source_updates_enabled=false;
  owner->actor->source_handle=-1;
  owner->actor->port_visual_controller_ready=false;
  owner->actor->identity=0;
  owner->actor->kind=0;
  owner->record=nullptr;owner->registered=false;
 }
}

