 row->source_provenance_ready=0;
 row->save_eligibility_28=record.game_object.save_eligibility_28;
 row->deleted_81=record.game_object.deleted_81;
 row->save_facts_ready=record.game_object.save_facts_ready;
 row->world_x=actor.position[0];row->world_y=actor.position[1];
