int script_summon_load_default_properties(void* raw,ScriptFactory::Record& record,
    std::string& error) {
 auto* context=static_cast<ScriptSummonFactoryContextV1*>(raw);
 if(!context||!context->runtime) {error="CreateNPC property context is absent";return 1;}
 auto* owner=script_summon_owner(*context->runtime,record.character.identity);
 if(!owner||!owner->actor||owner->record!=&record||!context->request||
    record.dynamic_character_table_id!=context->request->arguments.character_table_oid||
    record.dynamic_character_table_name!=context->request->character_table_name||
    !record.constructor.constructor_complete||!record.serialized_constructor_fields_ready||
    !record.game_object.go_ids_0f4_ready||record.game_object.go_ids_0f4!=0) {
  error="CreateNPC default property load lacks its completed same-Record Character constructor";return 1;
 }
 if(!context->source_handle_tracked) {
  try {context->runtime->source_handles.push_back(record.source_handle);}
  catch(...) {error="CreateNPC active source-handle tracking allocation failed";return 1;}
  context->source_handle_tracked=true;
 }
 const auto row=static_cast<std::size_t>(record.dynamic_character_table_id);
 if(row>=actor_character_names.size()||row>=actor_character_property_rows.size()||
    actor_character_names[row]!=record.dynamic_character_table_name||
    actor_character_names.size()!=actor_character_property_rows.size()) {
  error="CreateNPC CharacterTable default row/name is absent or ambiguous";return 1;
 }
 auto& actor=*owner->actor;
 const auto field_index=[](const char* name)->std::size_t {
  const auto found=std::find(actor_character_fields.begin(),actor_character_fields.end(),name);
  return found==actor_character_fields.end()?std::numeric_limits<std::size_t>::max():
      static_cast<std::size_t>(found-actor_character_fields.begin());
 };
 const auto model_index=field_index("ModelFile"),animation_index=field_index("AnimTable");
 if(model_index>=actor_character_property_rows[row].size()||
    animation_index>=actor_character_property_rows[row].size()||
    actor_character_property_rows[row][model_index]<0||
    actor_character_property_rows[row][animation_index]<0||
    std::size_t(actor_character_property_rows[row][model_index])>=actor_model_table.values.size()||
    std::size_t(actor_character_property_rows[row][animation_index])>=actor_animation_tables.characters.size()) {
  error="CreateNPC ModelFile or AnimTable OID is outside its retained catalog";return 1;
 }
 dh2::data::reset_properties(actor_property_rules,actor.properties,
     &actor_character_property_rows[row]);
 if(!dh2::data::recalc_properties_with_class(actor_class_tables,
       actor_property_rules,actor.properties,error))return 1;
 const auto model_id=actor.properties.resolved[model_index];
 const auto animation_id=actor.properties.resolved[animation_index];
 if(model_id!=actor_character_property_rows[row][model_index]||
    animation_id!=actor_character_property_rows[row][animation_index]||
    model_id<0||std::size_t(model_id)>=actor_model_table.values.size()||
    animation_id<0||std::size_t(animation_id)>=actor_animation_tables.characters.size()) {
  error="CreateNPC resolved CharacterTable defaults differ from retained source OIDs";return 1;
 }
 record.property_id_13c8=static_cast<std::int16_t>(row);
 record.template_id_13ca=-1;
 actor.character_table_id=static_cast<std::int16_t>(row);
 actor.character_template_id=-1;
 actor.model=script_summon_model_basename(
     actor_model_table.values[static_cast<std::size_t>(model_id)]);
 record.source_model_name=actor.model;
 actor.base_class=actor.properties.base;
 actor.class_id=actor.properties.resolved.size()>26?actor.properties.resolved[26]:-1;
 if(!record.coordinator||!owner->native_ai||!actor.native_ai) {
  error="CreateNPC same-Record Coordinator and CharAI component owners are incomplete";return 1;
 }
 actor.animation_table_id=animation_id;
 actor.search_projection.object.position[0]=actor.position[0];
 actor.search_projection.object.position[1]=actor.position[1];
 actor.search_projection.object.position[2]=actor.position[2];
 if(actor.properties.resolved.size()>199) {
  actor.search_projection.character.source_word_1310=actor.properties.resolved[198];
  actor.search_projection.character.source_word_1314=actor.properties.resolved[199];
 }
 if(!script_summon_bind_manager_fields(*context,record,error))return 1;
 error.clear();return 0;
}

int script_summon_prepare_player_placement(ScriptSummonFactoryContextV1& context,
    const dh2::character_script_summon_v1::Request& request,
    dh2::character_script_summon_v1::Placement* placement,std::string& error) {
 if(!context.runtime||!placement||!native_actor_ready||
    request.container_identity!=prince_character.identity()||
    !context.runtime->level.native_floor) {
  error="Player _Summon placement lost the live Player or floor owner";return 1;
 }
 const auto active=source_level_owner.snapshot();
 // _Summon: PFWorld::GetFloorHeightAt(position) misses -> the summoner's own
 // position; Character::SetInitialPosition then snaps the Z.
 float position[3]{};
 for(unsigned axis=0;axis<3;++axis) {
  const float origin=prince_runtime.subobjects.position[axis];
  const float delta=request.arguments.offset[axis];
  if(!std::isfinite(origin)||!std::isfinite(delta)||
     !std::isfinite(context.player_rotation_degrees[axis])) {
   error="Player _Summon position or rotation is non-finite";return 1;
  }
  position[axis]=request.arguments.relative_to_summoner?origin+delta:delta;
 }
 dh2::navigation::HeightHit hit{};
 const dh2::navigation::CollisionWorld* world=nullptr;
 const int query=source_level_owner.query_floor(active.generation,position,0,&hit,&world);
 if(query<0) {error="Player _Summon GetFloorHeightAt provider is unavailable";return 1;}
 if(query==0)std::copy_n(prince_runtime.subobjects.position,3,position);
 const int floor_status=source_level_owner.set_initial_position_height(active.generation,position);
 if(floor_status<0) {error="Player _Summon SetInitialPosition floor provider is unavailable";return 1;}
 placement->floor_hit=floor_status==1;
 std::copy_n(position,3,placement->position.begin());
 std::copy(context.player_rotation_degrees.begin(),context.player_rotation_degrees.end(),
           placement->rotation.begin());
 context.placement=*placement;
 error.clear();return 0;
}

int script_summon_prepare_placement(void* raw,
    const dh2::character_script_summon_v1::Request& request,
    dh2::character_script_summon_v1::Placement* placement,std::string& error) {
 auto* context=static_cast<ScriptSummonFactoryContextV1*>(raw);
 if(context&&context->player_summoner)
  return script_summon_prepare_player_placement(*context,request,placement,error);
 if(!context||!context->runtime||!context->caller||!context->caller->container||
    !context->caller->container->owner.object||!placement||
    request.container_identity!=context->caller->container->owner.object->identity||
    !context->runtime->level.native_floor) {
  error="CreateNPC placement lost the exact current container or floor owner";return 1;
 }
 auto* manager_row=context->runtime->manager.find_by_identity(request.container_identity);
 const auto actor_found=context->runtime->actors.find(request.container_identity);
 auto* summoner=actor_found==context->runtime->actors.end()?nullptr:actor_found->second;
 if(!manager_row||manager_row!=context->caller->container->owner.object||
    manager_row->identity!=request.container_identity||!summoner||
    summoner->identity!=request.container_identity||summoner->source_handle!=manager_row->source_handle) {
  error="CreateNPC relative placement has no same-identity live summoner transform";return 1;
 }
 for(unsigned axis=0;axis<3;++axis) {
  const float origin=summoner->position[axis];
  const float delta=request.arguments.offset[axis];
  if(!std::isfinite(origin)||!std::isfinite(delta)) {
   error="CreateNPC position or offset is non-finite";return 1;
  }
  placement->position[axis]=request.arguments.relative_to_summoner?origin+delta:delta;
  placement->rotation[axis]=summoner->rotation_degrees[axis];
  if(!std::isfinite(placement->rotation[axis])) {
   error="CreateNPC source summoner rotation is non-finite";return 1;
  }
 }
 const auto active=source_level_owner.snapshot();
 float positioned[3]={placement->position[0],placement->position[1],placement->position[2]};
 const int floor_status=source_level_owner.set_initial_position_height(active.generation,positioned);
 if(floor_status<0) {error="CreateNPC SetInitialPosition floor provider is unavailable";return 1;}
 placement->floor_hit=floor_status==1;
 std::copy_n(positioned,3,placement->position.begin());
 context->placement=*placement;
 error.clear();return 0;
}

