// GameObject::_Summon's shared tail: the source Character factory plus the
// CreateNPC/SetInitialPosition/SetPosition/SetRotation/room lifecycle. The caller
// supplies the summoner-specific ObjectManager seed (container or Player) and a
// factory context whose placement/room callbacks know that summoner.
int native_run_script_summon(NativeCryptRoomRuntime& runtime,
    const ScriptSummonFactoryContextV1& prepared_context,
    const dh2::character_script_summon_v1::Request* request,
    dh2::object_manager_runtime_owner_v1::GameObject& manager_seed,
    std::uintptr_t* identity,std::string& error) {
 try {
  runtime.script_summon_contexts.reserve(runtime.script_summon_contexts.size()+1);
  auto persistent=std::make_shared<ScriptSummonFactoryContextV1>(prepared_context);
  runtime.script_summon_contexts.push_back(persistent);
  auto& factory_context=*persistent;
  // The request lives on the caller's stack; only the retired Record's
  // rollback (runtime + factory) reads this context after the call.
  struct RequestGuard {
   ScriptSummonFactoryContextV1& context;
   ~RequestGuard(){context.request=nullptr;}
  } request_guard{factory_context};
  // Reserve vector/map capacity before the source Character factory publishes
  // its ObjectManager and CharacterList rows. Both the Record and Actor facade
  // then keep stable heap addresses for this active Level.
  runtime.script_npc_owners.reserve(runtime.script_npc_owners.size()+1);
  runtime.script_npcs_by_identity.reserve(runtime.script_npcs_by_identity.size()+1);
  runtime.actors.reserve(runtime.actors.size()+1);
  runtime.actor_records.reserve(runtime.actor_records.size()+1);
  runtime.source_handles.reserve(runtime.source_handles.size()+1);
  factory_context.runtime=&runtime;factory_context.factory=runtime.character_factory.get();
  factory_context.request=request;
  const ScriptFactory::Services factory_services{
      &factory_context,script_summon_factory_component,
      script_summon_factory_associate,script_summon_factory_register_state,
      script_summon_factory_rollback,script_summon_object_base};
  const dh2::character_script_summon_v1::Services lifecycle{
      &factory_context,script_summon_prepare_placement,
      script_summon_load_default_properties,script_summon_set_initial_position,
      script_summon_set_rotation,script_summon_set_marker,script_summon_try_room,
      script_summon_add_no_room,script_summon_zone_entered,
      script_summon_set_spawn_state};
  manager_seed.source_module_index=std::numeric_limits<std::uint32_t>::max();
  manager_seed.source_record=std::numeric_limits<std::uint32_t>::max();
  manager_seed.source_provenance_ready=0;manager_seed.save_facts_ready=0;
  manager_seed.save_eligibility_28=0;manager_seed.deleted_81=0;
  manager_seed.go_ids_0f4=0;manager_seed.go_ids_0f4_ready=0;
  manager_seed.zoning_enabled_2ee=1;manager_seed.visible_80=1;
  dh2::character::aggro_search::GameObject aggro_seed{};
  aggro_seed.visible=1;aggro_seed.character_2ee=1;aggro_seed.character_2f0=0;
  dh2::character_script_summon_v1::Result result{};
  const auto status=dh2::character_script_summon_v1::summon(
      *runtime.character_factory,*request,manager_seed,aggro_seed,
      factory_services,lifecycle,&result,error);
  if(status!=dh2::character_script_summon_v1::Status::complete||
     result.reached!=dh2::character_script_summon_v1::Stage::complete||
     !result.character_identity||!factory_context.source_handle_tracked) {
   if(error.empty())error="GameObject::_Summon lifecycle did not reach its source tail";
   return 1;
  }
  auto* actor_owner=script_summon_owner(runtime,result.character_identity);
  auto* record=runtime.character_factory->find(result.source_handle);
  auto* manager_row=runtime.manager.find_by_source_handle(result.source_handle);
  if(!actor_owner||!actor_owner->actor||!record||!manager_row||
     actor_owner->record!=record||manager_row->identity!=record->character.identity||
     !record->object_registered||!record->character_listed) {
   error="GameObject::_Summon tail lost the canonical same-identity Character/manager row";return 1;
  }
  *identity=result.character_identity;error.clear();return 0;
 } catch(const std::exception& exception) {
  error=std::string("GameObject::_Summon native source adapter failed: ")+exception.what();return 1;
 } catch(...) {
  error="GameObject::_Summon native source adapter failed";return 1;
 }
}

int native_source_summon_character(void* raw,
    const dh2::character_script_summon_v1::Request* request,
    std::uintptr_t* identity,std::string& error) {
 if(identity)*identity=0;
 auto* caller=static_cast<SourceContainerCallbackContext*>(raw);
 if(!caller||!caller->runtime||!caller->container||!request||!identity||
    !caller->container->owner.object||request->container_identity!=
      caller->container->owner.object->identity||!caller->runtime->character_factory||
    !caller->runtime->level.native_floor||!request->arguments.request_spawn_state) {
  error="GameObject::_Summon provider lacks the exact active container/Level factory or source arguments";return 1;
 }
 auto& runtime=*caller->runtime;
 if(runtime.manager.find_by_identity(request->container_identity)!=
      caller->container->owner.object||runtime.actors.find(request->container_identity)==runtime.actors.end()) {
  error="GameObject::_Summon caller is not the retained current ObjectManager actor";return 1;
 }
 auto* container_row=runtime.manager.find_by_identity(request->container_identity);
 if(!container_row||container_row->module_id_64<0) {
  error="GameObject::_Summon container has no source ObjectBase module ID";return 1;
 }
 const auto container_actor=runtime.actors.find(request->container_identity);
 if(container_actor==runtime.actors.end()||!container_actor->second||
    container_actor->second->identity!=request->container_identity) {
  error="GameObject::_Summon has no live caller Character/ObjectActor transform";return 1;
 }
 dh2::object_manager_runtime_owner_v1::GameObject manager_seed{};
 manager_seed.module_id_64=container_row->module_id_64;
 manager_seed.world_x=container_actor->second->position[0];
 manager_seed.world_y=container_actor->second->position[1];
 ScriptSummonFactoryContextV1 factory_context{};
 factory_context.caller=caller;
 return native_run_script_summon(runtime,factory_context,request,manager_seed,
                                 identity,error);
}

// GameObject::_Summon with the local Player Character as the summoner (the
// Player skill VM's Summon). The Player is not a container and has no RoomZone,
// so the room tail takes the AddNoRoomObject fallback.
int native_player_summon_character(
    const dh2::character_script_summon_v1::Request* request,
    const std::array<float,3>& rotation_degrees,
    std::uintptr_t* identity,std::string& error) {
 if(identity)*identity=0;
 if(!request||!identity||!active_crypt_room_runtime||!native_actor_ready||
    request->container_identity!=prince_character.identity()||
    !active_crypt_room_runtime->character_factory||
    !active_crypt_room_runtime->level.native_floor) {
  error="Player GameObject::_Summon lacks the live Player, Level factory or source arguments";return 1;
 }
 auto& runtime=*active_crypt_room_runtime;
 auto* player_row=runtime.manager.find_by_identity(request->container_identity);
 if(!player_row||player_row->identity!=request->container_identity) {
  error="Player GameObject::_Summon lost the Player ObjectManager row";return 1;
 }
 // Character::CreateNPC spawns through ObjectManager::Spawn -> GetNewObject
 // with module -1 (ObjectBase's constructor default), so the new Character
 // keeps the seed's default module id.
 dh2::object_manager_runtime_owner_v1::GameObject manager_seed{};
 manager_seed.world_x=prince_runtime.subobjects.position[0];
 manager_seed.world_y=prince_runtime.subobjects.position[1];
 ScriptSummonFactoryContextV1 factory_context{};
 factory_context.player_summoner=true;
 factory_context.player_rotation_degrees=rotation_degrees;
 return native_run_script_summon(runtime,factory_context,request,manager_seed,
                                 identity,error);
}

bool native_level_save_direct_actor_v1(
        NativeLevelSaveObjectFactsContextV1&,std::uintptr_t,ObjectActor*&,
        dh2::object_manager_runtime_owner_v1::GameObject*&,std::string&);
bool native_level_save_read_direct_character_view_v1(void*,std::uintptr_t,
        dh2::character_level_save_serialize_v1::View*,std::string&);
bool native_level_save_read_direct_game_object_fields_v1(void*,std::uintptr_t,
        dh2::level_savegame_owner_v1::GameObjectFields*,std::string&);
AuthoredCryptFaeryOwner* native_level_save_factory_faery_v1(
        NativeLevelSaveObjectFactsContextV1& context,
        const dh2::character_runtime_factory_v1::Record& record,
        std::string& error) {
 const auto active=source_level_owner.snapshot();
 auto* manager=&source_level_owner.object_manager();
 if(active.phase!=dh2::source_level_owner_v1::Phase::active||
    active.generation!=context.level_generation||!active_crypt_room_runtime||
    !active_crypt_room_runtime->character_factory||
    active.object_manager_identity!=reinterpret_cast<std::uintptr_t>(manager)||
    !record.character.identity||record.character.identity!=record.game_object.identity||
    record.character.object!=&record.aggro_object||
    !record.object_registered||!record.character_listed||
    !record.serialized_constructor_fields_ready) {
  error="Faery Character save lacks its active completed factory constructor receipt";
  return nullptr;
 }
 auto* owner=native_faery_owner(record.character.identity);
 if(!owner||!owner->registered||!owner->constructed||!owner->properties_ready||
    owner->record!=&record||owner->identity!=record.character.identity||
    !record.source_properties_ready()||!record.init_post_complete()||
    owner->source.source_handle!=record.source_handle||
    owner->source.module_index!=record.game_object.source_module_index||
    owner->source.source_record!=record.game_object.source_record||
    !record.game_object.source_provenance_ready||
    record.source_handle!=owner->source.source_handle) {
  error="Faery Character save source/adoption/InitPost owners are incomplete";
  return nullptr;
 }
 const auto* manager_row=manager->find_by_source_handle(record.source_handle);
 const auto& properties_slot=record.components.slots[static_cast<std::size_t>(
     dh2::character_constructor_owner_v1::Component::properties)];
 const auto& state_slot=record.components.slots[static_cast<std::size_t>(
     dh2::character_constructor_owner_v1::Component::state_machine)];
 const auto* ai=record.canonical_ai();
 if(!manager_row||manager_row->identity!=record.character.identity||
    manager_row->source_handle!=record.source_handle||
    manager_row->source_module_index!=owner->source.module_index||
    manager_row->source_record!=owner->source.source_record||
    !manager_row->source_provenance_ready||
    manager->find_by_identity(record.character.identity)!=manager_row||
    !properties_slot.constructed||properties_slot.canonical_owner!=&owner->properties||
    properties_slot.character_record!=&record||
    !state_slot.constructed||state_slot.canonical_owner!=record.coordinator.get()||
    state_slot.character_record!=&record||!record.coordinator||
    record.coordinator->owner()!=record.character.identity||!ai||
    ai->owner_04!=record.character.identity||
    // -1 is the CharStateMachine constructor value of a Faery not yet focused.
    record.coordinator->state.current<-1||record.coordinator->state.current>=20) {
  error="Faery Character save does not resolve one manager row and canonical component owners";
  return nullptr;
 }
 return owner;
}

bool native_level_save_read_factory_character_view_v1(void* raw,
        const dh2::character_runtime_factory_v1::Record& record,
        dh2::character_level_save_serialize_v1::View* output,
        std::string& error) {
 using namespace dh2::character_level_save_serialize_v1;
 if(!raw||!output) {
  error="Faery Character serializer requires its active context and output";
  return true;
 }
 auto& context=*static_cast<NativeLevelSaveObjectFactsContextV1*>(raw);
 auto* owner=native_level_save_factory_faery_v1(context,record,error);
 if(!owner)return true;
 auto& saved=context.direct_properties_saved;
 auto& resolved=context.direct_properties_resolved;
 static_assert(sizeof(owner->properties.saved)==896);
 static_assert(sizeof(owner->properties.resolved)==896);
 // CharacterProperties::writeAs stores the inert ARM32 vtable word followed
 // by the exact 224 source property words. This header is serialized data,
 // never a host pointer.
 constexpr std::array<std::uint8_t,4> legacy_header{0xc0,0xbb,0x96,0x00};
 const auto& saved_header=record.serialized_property_headers_ready
     ?record.serialized_properties_saved_header:legacy_header;
 const auto& resolved_header=record.serialized_property_headers_ready
     ?record.serialized_properties_resolved_header:legacy_header;
 std::copy(saved_header.begin(),saved_header.end(),saved.begin());
 std::copy(resolved_header.begin(),resolved_header.end(),resolved.begin());
 std::memcpy(saved.data()+legacy_header.size(),owner->properties.saved.data(),
             sizeof(owner->properties.saved));
 std::memcpy(resolved.data()+legacy_header.size(),owner->properties.resolved.data(),
             sizeof(owner->properties.resolved));

 const auto& visual=record.faery_visual;
 const auto& authored=owner->source.authored_world_transform;
 const auto& pose=visual.position;
 if(!dh2::character_faery_visual_facade_v1::ready(
        visual,record.character.identity)||
    !std::isfinite(pose[0])||!std::isfinite(pose[1])||!std::isfinite(pose[2])||
    !std::isfinite(authored[3])||!std::isfinite(authored[4])||
    !std::isfinite(authored[5])||
    record.game_object.world_x!=pose[0]||record.game_object.world_y!=pose[1]||
    record.serialized_dead_1449>1) {
  error="Faery Character save pose/property owners are not source-ready";
  return true;
 }
 // Character::Serialize writes the live GameObject EulerXYZ at +0x16c in
 // radians (GameObject::UpdateRotation advances it; GameObject::InitPost
 // converted the authored degrees). It is not derived from the quaternion.
 const auto& live_rotation=record.faery_controller.rotation.rotation;
 if(!std::isfinite(live_rotation[0])||!std::isfinite(live_rotation[1])||
    !std::isfinite(live_rotation[2])) {
  error="Faery Character save rotation is not finite";
  return true;
 }
 View view{};
 view.state_machine_state=static_cast<std::uint32_t>(record.coordinator->state.current);
 view.is_player=0;
 view.properties_primary={saved.data(),saved.size()};
 view.properties_secondary={resolved.data(),resolved.size()};
 view.position={reinterpret_cast<const std::uint8_t*>(pose.data()),sizeof(pose)};
 view.rotation={reinterpret_cast<const std::uint8_t*>(live_rotation),12};
 view.dead=record.serialized_dead_1449;
 view.vector_1306={reinterpret_cast<const std::uint8_t*>(
       record.quick_save_position_1468.data()),sizeof(record.quick_save_position_1468)};
 view.vector_1309={reinterpret_cast<const std::uint8_t*>(
       record.revive_position_1474.data()),sizeof(record.revive_position_1474)};
 *output=view;
 error.clear();return false;
}

bool native_level_save_read_factory_game_object_fields_v1(void* raw,
        const dh2::character_runtime_factory_v1::Record& record,
        dh2::level_savegame_owner_v1::GameObjectFields* output,
        std::string& error) {
 if(!raw||!output) {
  error="Faery GameObject serializer requires its active context and output";
  return true;
 }
 auto& context=*static_cast<NativeLevelSaveObjectFactsContextV1*>(raw);
 auto* owner=native_level_save_factory_faery_v1(context,record,error);
 if(!owner)return true;
 const auto& object=record.game_object;
 if(!object.serialized_flag_8a_ready||object.serialized_flag_8a>1||
    !object.save_facts_ready||object.spawn_probability_result_270< -1||
    object.spawn_probability_result_270>100||object.visible_80>1||
    object.visible_80!=std::uint8_t(
        record.faery_visual.visible)) {
  error="Faery GameObject Serialize fields are not retained on the canonical factory GameObject";
  return true;
 }
 *output={object.visible_80,object.serialized_flag_8a,
          object.spawn_probability_result_270};
 error.clear();return false;
}

bool native_level_save_read_factory_group_info_v1(void* raw,
        std::uintptr_t group_identity,std::int32_t* word_36,
        std::uint8_t* flag_40,std::uint8_t* flag_41,std::string& error) {
 auto* context=static_cast<NativeLevelSaveObjectFactsContextV1*>(raw);
 const auto active=source_level_owner.snapshot();
 if(!context||active.phase!=dh2::source_level_owner_v1::Phase::active||
    active.generation!=context->level_generation||!group_identity||
    !word_36||!flag_40||!flag_41||
    !source_char_ai.groups.owns(group_identity)) {
  error="Faery Character GroupInfo identity has no canonical level owner";
  return true;
 }
 dh2::character_group_info_owner_v1::Tail tail{};
 if(!source_char_ai.groups.read_tail(group_identity,&tail)||
    tail.flag_40>1||tail.flag_41>1) {
  error="Faery Character GroupInfo tail is not source-owned or valid";
  return true;
 }
 *word_36=tail.word_36;*flag_40=tail.flag_40;*flag_41=tail.flag_41;
 error.clear();return false;
}
bool native_level_save_read_object_facts_v1(void* raw,
        const dh2::object_manager_runtime_owner_v1::GameObject& row,
        const dh2::character_runtime_factory_v1::Record* record,
        dh2::level_savegame_owner_v1::Object* output,std::string& error) {
 using CharacterQuery=dh2::character_ai_classification::Query;
 if(!raw||!output||!row.identity||row.source_handle<0) {
  error="LevelSavegame source facts require one identified ObjectManager row";
  return true;
 }
 const auto& context=*static_cast<const NativeLevelSaveObjectFactsContextV1*>(raw);
 const auto active=source_level_owner.snapshot();
 auto* manager=&source_level_owner.object_manager();
 if(active.phase!=dh2::source_level_owner_v1::Phase::active||
    !active.source_level||active.player_character!=prince_character.identity()||
    active.generation!=context.level_generation||
    active.object_manager_identity!=reinterpret_cast<std::uintptr_t>(manager)||
    manager->find_by_source_handle(row.source_handle)!=&row) {
  error="LevelSavegame source facts do not match the active level's canonical ObjectManager row";
  return true;
 }

 // Rows the LevelSavegame never writes. ObjectBase::ObjectBase stores 0 at +0x28
 // and Projectile::Projectile (0x3e5e40) leaves it, so the pooled
 // ProjectileManager objects are listed with a zero eligibility gate and
 // __SaveObjects skips them. A Character created by GameObject::_Summon is
 // eligible in the source (Character::Character stores 1), but the port has no
 // dynamic-Character LevelSavegame reload path for it yet: leave the temporary
 // ally out of the image (loudly) rather than failing the whole save.
 {
  const bool projectile=active_crypt_level_projection&&
      active_crypt_level_projection->projectile_owner&&
      active_crypt_level_projection->projectile_owner->find(row.identity);
  const bool summoned=!projectile&&active_crypt_room_runtime&&
      active_crypt_room_runtime->script_npcs_by_identity.count(row.identity);
  if(projectile||summoned) {
   if(summoned)
    __android_log_print(ANDROID_LOG_WARN,"DH2Native",
        "LevelSavegame skips script-summoned Character %s | dynamic Character reload is not implemented",
        row.name.c_str());
   dh2::level_savegame_owner_v1::Object facts{};
   facts.identity=row.identity;
   facts.name=row.name;
   facts.manager_key=row.name;
   facts.type_word=row.live_fields.module_id_64?
       *row.live_fields.module_id_64:row.module_id_64;
   facts.enabled=0;
   facts.is_character=summoned?1:0;
   *output=std::move(facts);
   error.clear();
   return false;
  }
 }
 auto publish_noncharacter_facts=[&](const dh2::world::SourceObjectCensusV1& source)->bool {
  std::uint8_t gate=0,deleted=0;
  if(record||!row.source_provenance_ready||row.name.empty()||
     row.name!=source.name||row.source_handle!=source.source_handle||
     row.source_module_index!=source.module_index||
     row.source_record!=source.source_record||
     row.module_id_64!=source.source_module_id||
     !row.object_init_post_ready||!row.save_facts_ready||
     !row.visible_80_ready||!row.serialized_flag_8a_ready||
     !row.read_save_base_facts(&gate,&deleted))return false;
  dh2::level_savegame_owner_v1::Object facts{};
  facts.identity=row.identity;
  facts.name=row.name;
  facts.manager_key=row.name;
  facts.type_word=row.live_fields.module_id_64?
      *row.live_fields.module_id_64:row.module_id_64;
  facts.enabled=gate;
  facts.is_character=0;
  facts.is_player=0;
  facts.is_local_player=0;
  facts.source_flag_129=deleted;
  *output=std::move(facts);
  error.clear();
  return true;
 };
 auto source_for_row=[&](const char* gametype)->const dh2::world::SourceObjectCensusV1* {
  const auto& sources=active_level_assets.source_object_census;
  const auto found=std::find_if(sources.begin(),sources.end(),[&](const auto& source){
   return source.gametype==gametype&&source.source_handle==row.source_handle&&
       source.module_index==row.source_module_index&&
       source.source_record==row.source_record&&source.name==row.name;
  });
  return found==sources.end()?nullptr:&*found;
 };

 // ProjectileManager::_Create 0x3e693c spawns every pooled Projectile and
 // LaserTypeProjectile through ObjectManager::Spawn, so they are keyed
 // ObjectManager rows (Projectile_000, LTProjectile_000...). ObjectBase::ObjectBase
 // 0x33f310 initializes the +0x28 save byte to 0 and Projectile::Projectile
 // 0x3e5e40 never raises it; LevelSavegame::__SaveObjects 0x462d84 writes only
 // objects with +0x28 set, so a projectile row is visited and skipped. The facts
 // report that gate; they are not a Character or any serializable class.
 if(!record&&active_crypt_level_projection&&
    active_crypt_level_projection->projectile_owner&&
    active_crypt_level_projection->projectile_owner->find(row.identity)) {
  dh2::level_savegame_owner_v1::Object facts{};
  facts.identity=row.identity;
  facts.name=row.name;
  facts.manager_key=row.name;
  facts.type_word=row.live_fields.module_id_64?
      *row.live_fields.module_id_64:row.module_id_64;
  facts.enabled=0;
  facts.is_character=0;
  facts.is_player=0;
  facts.is_local_player=0;
  facts.source_flag_129=0;
  *output=std::move(facts);
  error.clear();
  return false;
 }

 // TriggerZoneExitLevel is a non-Character GameObject in this same keyed
 // ObjectManager. Its inherited Trigger virtual serializer is dispatched by
 // __SaveObjects even though it has no CharacterList entry.
 if(row.exit_level.definition_ready) {
  const auto* source=source_for_row("TriggerZoneExitLevel");
  if(record||!row.source_provenance_ready||row.name.empty()||
     !row.object_init_post_ready||!row.save_facts_ready||!row.visible_80_ready||
     !row.serialized_flag_8a_ready||row.visible_80>1||
     row.serialized_flag_8a>1||row.spawn_probability_result_270!=-2||
     !row.trigger_save_state_ready||!source||
     !publish_noncharacter_facts(*source)) {
   error="LevelSavegame TriggerZoneExitLevel facts lack their canonical source, base-field, or Trigger save receipts";
   return true;
  }
  return false;
 }

 // DestructibleContainer's class owner publishes the Container state receipt
 // on the same ObjectManager row and pins its exact MGP source occurrence.
 if(row.container_state_ready) {
  if(!active_crypt_room_runtime) {
   error="LevelSavegame Container row has no active source class owner";return true;
  }
  const auto found=std::find_if(active_crypt_room_runtime->source_destructible_containers.begin(),
      active_crypt_room_runtime->source_destructible_containers.end(),
      [&](const auto& candidate){return candidate&&candidate->owner.object==&row;});
  if(found==active_crypt_room_runtime->source_destructible_containers.end()||
     (*found)->source.gametype!="DestructibleContainer"||
     !source_for_row("DestructibleContainer")||
     !publish_noncharacter_facts(*source_for_row("DestructibleContainer"))) {
   error="LevelSavegame Container row lacks its exact canonical source or InitPost facts";return true;
  }
  return false;
 }

 // QuestMoveInZone has no Serialize override in the source image; its exact
 // MGP owner therefore dispatches GameObject::Serialize at 0x38b9e4.
 if(active_crypt_room_runtime) {
  const auto found=std::find_if(active_crypt_room_runtime->source_move_in_zones.begin(),
      active_crypt_room_runtime->source_move_in_zones.end(),
      [&](const auto& candidate){return candidate&&candidate->object==&row;});
  if(found!=active_crypt_room_runtime->source_move_in_zones.end()) {
   const auto* source=source_for_row("QuestMoveInZone");
   if((*found)->source.gametype!="QuestMoveInZone"||!source||
      !publish_noncharacter_facts(*source)) {
    error="LevelSavegame GameObject row lacks its exact QuestMoveInZone source or InitPost facts";return true;
   }
   return false;
  }
 }

 if(row.door.definition_ready) {
  const auto* source=source_for_row("Door");
  if(row.door.state_936<0||row.door.state_936>3||!source||
     !publish_noncharacter_facts(*source)) {
   error="LevelSavegame Door row lacks its source class, DoorStates, or InitPost receipt";
   return true;
  }
  return false;
 }

 const bool player=row.identity==prince_character.identity();
 ObjectActor* actor=nullptr;
 AuthoredCryptFaeryOwner* faery=nullptr;
 const std::string* source_name=nullptr;
 if(player) {
  if(row.source_handle!=3||
     (!row.name.empty()&&row.name!="PlayerCharacter_0")) {
   error="LevelSavegame Player row lost its retained handle/name identity";
   return true;
  }
 } else {
  actor=native_char_ai_actor(row.identity);
  if(actor) {
   source_name=&actor->name;
   if(actor->kind!=1||actor->identity!=row.identity||
      actor->source_handle!=row.source_handle||
      (!row.name.empty()&&actor->name!=row.name)||
      !row.source_provenance_ready||
      actor->source_module_index!=row.source_module_index||
      actor->source_record!=row.source_record||
      actor->source_object_module_id!=(row.live_fields.module_id_64?
          *row.live_fields.module_id_64:row.module_id_64)||
      row.live_fields.save_eligibility_28!=&actor->source_save_eligibility_28||
      row.live_fields.deleted_81!=&actor->source_deleted_81) {
    error="LevelSavegame Character row has no matching retained source actor provenance";
    return true;
   }
  } else if(active_crypt_room_runtime) {
   const auto found=std::find_if(active_crypt_room_runtime->faeries.begin(),
       active_crypt_room_runtime->faeries.end(),[&](const auto& candidate){
        return candidate.registered&&candidate.identity==row.identity;
       });
   if(found!=active_crypt_room_runtime->faeries.end()) {
    faery=&*found;
    source_name=&faery->source.name;
    if(!record||faery->record!=record||faery->source.source_handle!=row.source_handle||
       faery->source.module_index!=row.source_module_index||
       faery->source.source_record!=row.source_record||
       !row.source_provenance_ready||
       row.module_id_64!=static_cast<std::int32_t>(faery->source.module_index)||
       (!row.name.empty()&&row.name!=faery->source.name)) {
     error="LevelSavegame Faery row differs from its canonical source/factory owner";
     return true;
    }
   }
  }
  if(!actor&&!faery) {
   error="LevelSavegame Character row has no retained source actor or Faery owner: "+row.name;
   return true;
  }
 }
 if(record&&(record->source_handle!=row.source_handle||
     record->character.identity!=row.identity||
     record->game_object.identity!=row.identity||
     !record->object_registered||!record->character_listed)) {
  error="LevelSavegame Character factory Record differs from this manager identity";
  return true;
 }
 if(!row.save_facts_ready) {
  error="LevelSavegame ObjectBase +0x28/+0x81 facts are unavailable for this manager row: "+row.name;
  return true;
 }

 std::uint8_t gate=0,deleted=0;
 if(player) {
  gate=prince_character.save_eligibility_28();
  deleted=prince_character.deleted_81();
  std::uint8_t projected_gate=0,projected_deleted=0;
  if(row.live_fields.save_eligibility_28!=
          prince_character.save_eligibility_28_storage()||
     row.live_fields.deleted_81!=prince_character.deleted_81_storage()||
     !row.read_save_base_facts(&projected_gate,&projected_deleted)||
     projected_gate!=gate||projected_deleted!=deleted) {
   error="LevelSavegame Player save bytes differ from the canonical Player owner";
   return true;
  }
 } else if(!row.read_save_base_facts(&gate,&deleted)) {
  error="LevelSavegame source Character save bytes are unavailable or invalid";
  return true;
 }

 // Every Character present in the source CharacterList is a concrete
 // Character implementation whose vtable reports IsCharacter=true.
 std::size_t occurrences=0;
 const bool listed=native_characters.contains_identity(row.identity,&occurrences);
 if(!listed||occurrences!=1) {
  error="LevelSavegame Character classification lacks its unique canonical CharacterList row";
  return true;
 }
 std::uint8_t is_player=0;
 if(player) is_player=1;
 else {
  std::uint32_t char_type=0;
  if(!native_character_classification_for_identity(row.identity,
        CharacterQuery::type,char_type)) {
   error="LevelSavegame Character::IsPlayer lacks its source CharType";
   return true;
  }
  is_player=char_type?std::uint8_t(char_type==1):
      std::uint8_t(source_name&&
          source_name->find("PlayerCharacter")!=std::string::npos);
 }
 if(is_player&& !player) {
  error="LevelSavegame classified a noncanonical Character row as the Player";
  return true;
 }

 dh2::level_savegame_owner_v1::Object facts{};
 facts.identity=row.identity;
 if(player) facts.name="PlayerCharacter_0";
  else facts.name=*source_name;
 facts.manager_key=facts.name;
 facts.type_word=row.live_fields.module_id_64?
     *row.live_fields.module_id_64:row.module_id_64;
 facts.enabled=gate;
 facts.is_character=1;
 facts.is_player=is_player;
 facts.is_local_player=std::uint8_t(player&&is_player);
 facts.source_flag_129=deleted;
 *output=std::move(facts);
 error.clear();
 return false;
}
bool native_level_save_serialize_noncharacter_v1(void* raw,
        const dh2::object_manager_runtime_owner_v1::GameObject& row,
        std::vector<std::uint8_t>& output,std::string& error) {
 auto* context=static_cast<NativeLevelSaveObjectFactsContextV1*>(raw);
 const auto active=source_level_owner.snapshot();
 auto* manager=&source_level_owner.object_manager();
 if(!context||active.phase!=dh2::source_level_owner_v1::Phase::active||
    active.generation!=context->level_generation||
    active.object_manager_identity!=reinterpret_cast<std::uintptr_t>(manager)||
    manager->find_by_identity(row.identity)!=&row) {
  error="non-Character Serialize lost its canonical active ObjectManager row";
  return true;
 }
 auto source_for_row=[&](const char* gametype)->const dh2::world::SourceObjectCensusV1* {
  const auto& sources=active_level_assets.source_object_census;
  const auto found=std::find_if(sources.begin(),sources.end(),[&](const auto& source){
   return source.gametype==gametype&&source.source_handle==row.source_handle&&
       source.module_index==row.source_module_index&&
       source.source_record==row.source_record&&source.name==row.name;
  });
  return found==sources.end()?nullptr:&*found;
 };
 auto base_fields=[&](const dh2::world::SourceObjectCensusV1* source,
                      dh2::level_savegame_owner_v1::GameObjectFields& fields)->bool {
  const auto visible=row.live_fields.visible_80?
      *row.live_fields.visible_80:row.visible_80;
  const auto enabled=row.live_fields.serialized_flag_8a?
      *row.live_fields.serialized_flag_8a:row.serialized_flag_8a;
  if(!source||!row.source_provenance_ready||row.source_handle!=source->source_handle||
     row.name!=source->name||row.source_module_index!=source->module_index||
     row.source_record!=source->source_record||row.module_id_64!=source->source_module_id||
     !row.object_init_post_ready||!row.save_facts_ready||!row.visible_80_ready||
     !row.serialized_flag_8a_ready||visible>1||enabled>1||
     visible!=row.visible_80||enabled!=row.serialized_flag_8a||
     // Every surviving nonplayer row reached CheckSpawnProbability's
     // successful InitPost branch, which leaves its serialized cache sentinel.
     row.spawn_probability_result_270!=-2)return false;
  fields={visible,enabled,
          row.spawn_probability_result_270};
  return true;
 };
 dh2::level_savegame_owner_v1::GameObjectFields base{};
 if(row.exit_level.definition_ready) {
  const auto* source=source_for_row("TriggerZoneExitLevel");
  if(!row.trigger_save_state_ready||!base_fields(source,base)) {
   error="TriggerZoneExitLevel::Serialize lacks its exact Trigger and source InitPost receipts";return true;
  }
  const dh2::level_savegame_owner_v1::TriggerFields fields{
      base,row.trigger_pending_3b8,row.trigger_max_count_3b4};
  return !dh2::level_savegame_owner_v1::serialize_trigger(&fields,output,error);
 }
 if(row.container_state_ready) {
  const auto* source=source_for_row("DestructibleContainer");
  const bool owned=active_crypt_room_runtime&&
      std::any_of(active_crypt_room_runtime->source_destructible_containers.begin(),
          active_crypt_room_runtime->source_destructible_containers.end(),
          [&](const auto& candidate){return candidate&&candidate->owner.object==&row&&
              candidate->source.gametype=="DestructibleContainer";});
  if(!owned||row.container_state_394<0||row.container_state_394>4||
     !base_fields(source,base)) {
   error="Container::Serialize lacks its canonical class/state or source InitPost receipt";return true;
  }
  const dh2::level_savegame_owner_v1::ContainerFields fields{
      base,static_cast<std::uint8_t>(row.container_state_394)};
  return !dh2::level_savegame_owner_v1::serialize_container(&fields,output,error);
 }
 if(active_crypt_room_runtime) {
  const auto found=std::find_if(active_crypt_room_runtime->source_move_in_zones.begin(),
      active_crypt_room_runtime->source_move_in_zones.end(),
      [&](const auto& candidate){return candidate&&candidate->object==&row;});
  if(found!=active_crypt_room_runtime->source_move_in_zones.end()) {
   const auto* source=source_for_row("QuestMoveInZone");
   if((*found)->source.gametype!="QuestMoveInZone"||!base_fields(source,base)) {
    error="GameObject::Serialize lacks its exact QuestMoveInZone InitPost receipt";return true;
   }
   return !dh2::level_savegame_owner_v1::serialize_game_object(&base,output,error);
  }
 }
 if(row.door.definition_ready) {
  const auto* source=source_for_row("Door");
  if(row.door.state_936<0||row.door.state_936>3||!base_fields(source,base)) {
   error="Door::Serialize lacks its canonical DoorStates or source InitPost receipt";return true;
  }
  const dh2::level_savegame_owner_v1::DoorFields fields{
      base,row.door.state_936};
  return !dh2::level_savegame_owner_v1::serialize_door(&fields,output,error);
 }
 error="eligible non-Character row has no proven source virtual Serialize dispatch";
 return true;
}
dh2::character_ai_queue_owner_v1::OwnerProjection native_char_ai_owner(
        const NativeCharAIProjection& projection) {
 auto* actor=native_char_ai_actor(projection.character_identity);
 if(!actor&&projection.character_identity!=prince_character.identity()&&
    !projection.authored_faery)
  throw std::runtime_error("Native CharAI owner Character is not retained");
 const auto& state=projection.state;
 auto forced=std::uint8_t((state.word_08>>8)&0xff),locked=std::uint8_t(state.word_08&0xff);
 // +8 is CharAI's aggro-delay countdown, never the Character controller.
 // SpawnOwner retains the real per-Character controller bytes when available.
 if(actor&&!native_source_controller_gates(*actor,forced,locked))
  throw std::runtime_error("Native CharAI controller projection owner mismatch");
 return {projection.character_identity,forced,locked,
  actor?actor->visible_80:(projection.authored_faery?projection.owner_visible:std::uint8_t(1)),
  actor?actor->zoning_enabled_2ee:(projection.authored_faery?projection.owner_zoning_enabled:std::uint8_t(0)),
  actor?actor->in_zone_2f0:(projection.authored_faery?projection.owner_in_zone:std::uint8_t(0))};
}
std::int32_t native_char_ai_queue_query(void*,dh2::character_ai_queue::State*,
        dh2::character_ai_queue::Entry* entry,
        const dh2::character_ai_queue::Request* request,std::uint32_t* output) {
 using Operation=dh2::character_ai_queue::Operation;
 using Classification=dh2::character_ai_classification::Query;
 if(!entry||!entry->owner||!request||!output||request->subject!=entry->owner->identity)return 1;
 const auto found=source_char_ai.by_character.find(request->subject);
 if(found==source_char_ai.by_character.end()||!found->second||found->second->ai_identity!=entry->ai)return 1;
 if(request->operation==Operation::is_zonable) {
  if(request->subject==prince_character.identity()) {
   const dh2::player_character_zonability_v1::Owner player{request->subject};
   dh2::player_character_zonability_v1::Result result{};
   if(dh2::player_character_zonability_v1::evaluate(&player,&result)!=
      dh2::player_character_zonability_v1::Status::complete)return 1;
   *output=result.zonable;return 0;
  }
  if(found->second->authored_faery){*output=found->second->updates_enabled;return 0;}
  auto* actor=native_char_ai_actor(request->subject);if(!actor)return 1;
  try {*output=native_actor_zonability(*actor);return 0;}catch(...) {return 1;}
 }
 auto* actor=native_char_ai_actor(request->subject);
 if(!actor&&request->subject!=prince_character.identity()&&
    !found->second->authored_faery)return 1;
 Classification query;
 if(request->operation==Operation::is_faerie)query=Classification::faerie;
 else if(request->operation==Operation::is_follower)query=Classification::follower;
 else return 1;
 if(found->second->authored_faery){*output=query==Classification::faerie;return 0;}
 if(!actor){*output=0;return 0;}
 try {*output=native_character_classification(*actor,query);return 0;}catch(...) {return 1;}
}
std::int32_t native_char_ai_turn_query(void*,dh2::character_ai_turn::State* state,
        dh2::character_ai_turn::Query query,std::uintptr_t owner,std::uint32_t* output) {
 using TurnQuery=dh2::character_ai_turn::Query;
 using Classification=dh2::character_ai_classification::Query;
 if(!state||!output||state->owner!=owner)return 1;
 const auto found=source_char_ai.by_character.find(owner);
 if(found==source_char_ai.by_character.end()||!found->second||found->second->ai_identity!=state->ai)return 1;
 if(query==TurnQuery::virtual_is_player) {
  *output=owner==prince_character.identity();return 0;
 }
 auto* actor=native_char_ai_actor(owner);
 if(!actor&&owner!=prince_character.identity()&&!found->second->authored_faery)return 1;
 if(!actor){
  *output=found->second->authored_faery&&query==TurnQuery::is_faerie;
  return 0;
 }
 try {
  *output=native_character_classification(*actor,
      query==TurnQuery::is_follower?Classification::follower:Classification::faerie);
  return 0;
 }catch(...) {return 1;}
}
bool native_char_ai_has_turn(ObjectActor& actor) {
 const auto found=source_char_ai.by_character.find(actor.identity);
 if(found==source_char_ai.by_character.end()||!found->second)
  throw std::runtime_error("Native Character AI turn owner is missing");
 const auto& projection=*found->second;
 const auto refreshed=source_char_ai_queue.refresh_owner(projection.ai_identity,
     native_char_ai_owner(projection));
 if(refreshed!=dh2::character_ai_queue_owner_v1::Status::complete)
  throw std::runtime_error("Native Character AI turn owner refresh failed");
 dh2::character_ai_turn::State state{projection.ai_identity,actor.identity};
 const auto globals=source_char_ai_queue.turn_globals();
 const dh2::character_ai_turn::Services services{nullptr,native_char_ai_turn_query};
 dh2::character_ai_turn::Result result{};
 if(dh2::character_ai_turn::evaluate(&state,&globals,&services,&result)!=
    dh2::character_ai_turn::Status::complete)
  throw std::runtime_error("Source CharAI IsMyTurn projection failed");
 return result.value!=0;
}
void advance_native_char_ai_queue(std::uint32_t dt_ms) {
 for(const auto& projection:source_char_ai.projections) {
  if(!projection)throw std::runtime_error("Null retained CharAI projection");
  if(source_char_ai_queue.refresh_owner(projection->ai_identity,
       native_char_ai_owner(*projection))!=dh2::character_ai_queue_owner_v1::Status::complete)
   throw std::runtime_error("Source CharAI owner refresh failed before Level update");
 }
 const dh2::character_ai_queue_owner_v1::Services services{nullptr,native_char_ai_queue_query};
 dh2::character_ai_queue_owner_v1::Result result{};
 if(source_char_ai_queue.advance(dt_ms,controller_global_blocked!=0,&services,&result)!=
    dh2::character_ai_queue_owner_v1::Status::complete)
  throw std::runtime_error("Source CharAI update queue advance failed");
}

std::int32_t NativeCryptRoomRuntime::initialize_zone_position(
        void*,const dh2::module_room_zone_bounds::Request* request) {
 if(!request||request->operation!=dh2::module_room_zone_bounds::Operation::set_position||
    !request->room_zone||!request->update_position)return 1;
 // The selected native renderer has no native Zone allocation. The portable
 // RoomZone owner applies the verified SetPosition/AABB field composition.
 return 0;
}

std::int32_t NativeCryptRoomRuntime::enroll_service(
        void* context,const dh2::room_zone_enrollment::Request* request,
        std::uint32_t* value) {
 auto* self=static_cast<NativeCryptRoomRuntime*>(context);
 if(!self||!request||!value)return 1;
 if(request->object==self->player_identity&&
    request->operation==dh2::room_zone_enrollment::Operation::is_zonable) {
  *value=0; // Character::IsZonable rejects Player before reading position.
  return 0;
 }
 const auto faery=std::find_if(self->faeries.begin(),self->faeries.end(),
     [&](const auto& item){return item.identity==request->object&&item.constructed;});
 if(faery!=self->faeries.end()&&
    request->operation==dh2::room_zone_enrollment::Operation::is_zonable) {
  *value=0; // IDA: Character::IsZonable returns false for IsFaerie.
  return 0;
 }
 const auto found=self->actors.find(request->object);
 if(found==self->actors.end()||!found->second) {
  // Source non-Character rows (Door, Trigger, containers, MoveInZone) have
  // no port RoomZone membership owner yet. RoomZone::AddInitialObject skips
  // a non-zonable object, leaving it on HandleNoRoomObjects' always-active
  // list; answer that for them instead of failing level enrollment. The
  // original zones Door/Trigger (IsZonable 1), so they are not culled here.
  if(request->operation==dh2::room_zone_enrollment::Operation::is_zonable&&
     self->manager.find_by_identity(request->object)) {
   *value=0;return 0;
  }
  return 1;
 }
 auto& actor=*found->second;
 switch(request->operation) {
 case dh2::room_zone_enrollment::Operation::is_zonable:
  try {*value=native_actor_zonability(actor);return 0;}catch(...){return 1;}
 case dh2::room_zone_enrollment::Operation::remove_from_room:
 case dh2::room_zone_enrollment::Operation::append_to_room:
  // The RoomZone owner wraps this callback and commits the member-node change
  // only after it succeeds, preserving the source callback/list order.
  return request->room_zone?0:1;
 case dh2::room_zone_enrollment::Operation::sync_visibility:
  if(request->auxiliary!=actor.visual_object_2d8)return 1;
  try {
   const bool zonable=native_actor_zonability(actor);
   actor.renderer_visible=actor.visible_80!=0&&
       !(zonable&&actor.zoning_enabled_2ee&&actor.in_zone_2f0==0);
  } catch(...) { return 1; }
  return 0;
 case dh2::room_zone_enrollment::Operation::zone_state_callback:
  actor.source_updates_enabled=request->value!=0;
  return 0;
 }
 return 1;
}

std::int32_t NativeCryptRoomRuntime::transition_service(
        void* context,const dh2::crypt_room_zone_owner_v1::TransitionRequest* request,
        std::uint32_t* value) {
 auto* self=static_cast<NativeCryptRoomRuntime*>(context);
 if(!self||!request||!request->room_zone)return 1;
 using Operation=dh2::crypt_room_zone_owner_v1::TransitionOperation;
 if(request->operation==Operation::query_module_visited||
    request->operation==Operation::set_module_visited) {
  if(!self->module_owner)return 1;
  auto found=std::find_if(self->module_owner->modules.begin(),
      self->module_owner->modules.end(),[&](const auto& module){
       return module.module_index==request->module_index;
      });
  if(found==self->module_owner->modules.end())return 1;
  if(request->operation==Operation::query_module_visited) {
   if(!value)return 1;
   *value=found->visited;return 0;
  }
  found->visited=1;return 0;
 }
 if(request->operation==Operation::zone_entered||
    request->operation==Operation::zone_exited) {
  const auto found=self->manager.find_by_identity(request->actor);
  if(!found)return 1;
  auto object=found->enrollment_view();
  const dh2::room_zone_enrollment::Services services{
      self,&NativeCryptRoomRuntime::enroll_service};
  dh2::room_zone_enrollment::Result result{};
  const auto status=request->operation==Operation::zone_entered
      ?dh2::room_zone_enrollment::zone_entered(&object,&services,&result)
      :dh2::room_zone_enrollment::zone_exited(&object,&services,&result);
  return status==dh2::room_zone_enrollment::Status::complete?0:1;
 }
 if(request->actor)return 1;
 bool changed=false;
 if(request->operation==Operation::add_room_object||
    request->operation==Operation::remove_room_object) {
  // RoomZone::Activate/DeActivate call ObjectManager::AddRoomObjects/
  // DelRoomObjects on the zone's member list (this+916), in list order.
  // The RoomZone object itself is not on the RoomObjectList.
  dh2::crypt_room_zone_owner_v1::ZoneView view{};
  bool found_zone=false;
  for(std::size_t i=0;i<self->zones.zone_count()&&!found_zone;++i)
   if(self->zones.zone_at(i,&view)&&view.identity==request->room_zone)found_zone=true;
  if(!found_zone)return 1;
  const bool adding=request->operation==Operation::add_room_object;
  for(std::size_t m=0;m<view.member_count;++m) {
   const auto status=adding
       ?self->manager.add_room_object(view.members[m],&changed)
       :self->manager.remove_room_object(view.members[m],&changed);
   if(status!=dh2::object_manager_runtime_owner_v1::Status::ok)return 1;
  }
  return 0;
 }
 return 1;
}

bool NativeCryptRoomRuntime::update_frustum(
    const std::array<float,3>& player_position) {
 if(!room_zones_enabled) {
  manager.reset_visible_room_zone_count();
  return true;
 }
 std::uint32_t planes[6][4]{};
 for(unsigned plane=0;plane<6;++plane)
  for(unsigned component=0;component<4;++component)
   planes[plane][component]=source_camera.frustum.planes[plane][component];
 const dh2::crypt_room_zone_owner_v1::UpdateServices services{
     this,&NativeCryptRoomRuntime::transition_service};
 dh2::crypt_room_zone_owner_v1::UpdateResult result{};
 const auto status=zones.update_frustum(planes,player_position.data(),&services,&result);
 if(status!=dh2::crypt_room_zone_owner_v1::Status::complete) {
  __android_log_print(ANDROID_LOG_ERROR,"DH2Native",
      "Crypt RoomZone frustum update failed | status %s | module %u | operation %u",
      dh2::crypt_room_zone_owner_v1::status_name(status),result.failed_module_index,
      unsigned(result.failed_operation));
  return false;
 }
 manager.reset_visible_room_zone_count();
 for(std::uint32_t i=0;i<result.zones_visible;++i)manager.add_visible_room_zone();
 return true;
}

bool NativeCryptRoomRuntime::prepare_authored_faeries(
    const std::vector<dh2::world::GeneratedCryptFaerySourceV1>& descriptors,
    std::string& error) {
 error.clear();
 faeries.clear();
 faeries.reserve(descriptors.size());
 std::set<dh2::object_manager_runtime_owner_v1::SourceHandle> handles;
 for(const auto& descriptor:descriptors) {
  const auto factory=dh2::object_creation_map_v1::resolve(
      descriptor.object_type.c_str());
  if(factory.status!=dh2::object_creation_map_v1::Status::resolved||
     !factory.entry||factory.entry->constructor!=
        dh2::object_creation_map_v1::Constructor::character||
     descriptor.source_handle<4||descriptor.ai_table_id<0||
     std::size_t(descriptor.ai_table_id)>=actor_ai_tables.rows.size()||
     actor_ai_tables.rows[std::size_t(descriptor.ai_table_id)].type!=3||
     descriptor.character.empty()||descriptor.template_name!="Faery") {
   error="Generated Crypt Faery source type/factory, source key/name, or CharType=3 AI row is invalid";
   faeries.clear();return false;
  }
  if(!descriptor.activate_condition.empty()||
     !descriptor.deactivate_condition.empty()) {
   error="Generated Faery source conditions require the live ConditionData provider";
   faeries.clear();return false;
  }
  if(!handles.insert(descriptor.source_handle).second||
     manager.find_by_source_handle(descriptor.source_handle)) {
   error="Generated Crypt Faery source handle collides with an existing ObjectManager entry";
   faeries.clear();return false;
  }
  faeries.emplace_back();
  auto& owner=faeries.back();
  owner.source=descriptor;
  const auto character_row=std::find(actor_character_names.begin(),
      actor_character_names.end(),descriptor.character);
  if(character_row==actor_character_names.end()||
     actor_character_property_rows.size()!=actor_character_names.size()) {
   error="Generated Crypt Faery CharacterTable row is not retained";
   faeries.clear();return false;
  }
  owner.character_table_row=static_cast<std::int32_t>(
      character_row-actor_character_names.begin());
  const auto& base=actor_character_property_rows[
      static_cast<std::size_t>(owner.character_table_row)];
  if(base[1]!=descriptor.ai_table_id) {
   error="Generated Crypt Faery descriptor AI id differs from its canonical Character properties";
   faeries.clear();return false;
  }
  // Property loading/recalculation is source-ordered inside the same factory
  // Record's InitPost prefix, after CheckSpawnProbability/SafeGetCharPropsId.
  owner.properties_ready=false;
  std::copy_n(descriptor.authored_world_transform,3,owner.visual_position.begin());
  const float half=3.14159265358979323846f/360.f;
  const float rx=descriptor.authored_world_transform[3]*half;
  const float ry=descriptor.authored_world_transform[4]*half;
  const float rz=descriptor.authored_world_transform[5]*half;
  const float sx=std::sin(rx),cx=std::cos(rx),sy=std::sin(ry),cy=std::cos(ry),
              sz=std::sin(rz),cz=std::cos(rz);
  owner.visual_rotation={sx*cy*cz-cx*sy*sz,cx*sy*cz+sx*cy*sz,
                         cx*cy*sz-sx*sy*cz,cx*cy*cz+sx*sy*sz};
  std::copy_n(descriptor.authored_world_transform+6,3,owner.visual_scale.begin());
  // The authored MGP world transform seeds this render-local pose only. The
  // canonical ObjectManager/Character projections are created by the source
  // Character factory after all constructor components succeed.
 }
 return true;
}

int NativeCryptRoomRuntime::faery_component(
    void* raw,dh2::character_constructor_owner_v1::Component component,
    dh2::character_constructor_owner_v1::Identity identity,
    dh2::character_runtime_factory_v1::ComponentStorage::Slot* slot,
    std::string& error) {
 using Component=dh2::character_constructor_owner_v1::Component;
 auto* owner=static_cast<AuthoredCryptFaeryOwner*>(raw);
 if(!owner||!slot||!slot->character_record||!identity) {
  error="Authored Faery component provider lacks the factory Record/slot";
  return 1;
 }
 auto* record=slot->character_record;
 if(record->character.identity!=identity||record->game_object.identity!=identity) {
  error="Authored Faery component identity differs from the canonical factory Record";
  return 1;
 }
 if(owner->record&&owner->record!=record) {
  error="Authored Faery component provider was rebound to a different Record";
  return 1;
 }
 owner->record=record;
 owner->identity=identity;
 switch(component) {
 case Component::game_object:
  slot->canonical_owner=&record->game_object;return 0;
 case Component::controllable:
  owner->controllable={identity,0};
  slot->canonical_owner=&owner->controllable;return 0;
 case Component::ai:
  if(!construct_authored_faery_char_ai(*owner,error))return 1;
  if(!owner->native_ai||owner->native_ai->character_identity!=identity||
     owner->native_ai->state.owner_04!=identity) {
   error="Authored Faery CharAI provider did not retain the factory Character identity";
   return 1;
  }
  slot->canonical_owner=&owner->native_ai->state;return 0;
 case Component::animator:
  // The existing per-Character Faery visual facade is the one mutable pose
  // owner. Immutable BDAE data is selected later and is not copied here.
  slot->canonical_owner=&record->faery_visual;return 0;
 case Component::properties:
  slot->canonical_owner=&owner->properties;return 0;
 case Component::controller:
  owner->controller={reinterpret_cast<std::uintptr_t>(&owner->controller),
                     identity,
                     reinterpret_cast<std::uintptr_t>(&owner->controllable),
                     0,0};
  owner->controllable.controller=owner->controller.identity;
  slot->canonical_owner=&owner->controller;return 0;
 default:
  error="Authored Faery component is not provided by its canonical owner";
  return 1;
 }
}

int NativeCryptRoomRuntime::faery_associate(
    void* raw,dh2::character_constructor_owner_v1::Association association,
    dh2::character_constructor_owner_v1::Identity identity,
    const dh2::character_runtime_factory_v1::ComponentStorage& components,
    std::string& error) {
 using Association=dh2::character_constructor_owner_v1::Association;
 auto* owner=static_cast<AuthoredCryptFaeryOwner*>(raw);
 auto* record=owner?owner->record:nullptr;
 if(!record||identity!=owner->identity||record->character.identity!=identity) {
  error="Authored Faery association does not match its canonical factory Record";
  return 1;
 }
 switch(association) {
 case Association::target_list:
  // The Character's aggro GameObject is already embedded in this same Record;
  // the ObjectManager/CharacterList roster is enrolled after factory Add.
  return record->character.object==&record->aggro_object?0:1;
 case Association::controller:
  if(!owner->controller.identity||owner->controller.character!=identity||
     owner->controllable.character!=identity||
     owner->controllable.controller!=owner->controller.identity) {
   error="Authored Faery default controller is not attached to its Character controllable";
   return 1;
  }
  return 0;
 case Association::timers:
  if(!record->coordinator||record->coordinator->owner()!=identity)break;
  return 0;
 case Association::ai:
  if(owner->native_ai&&owner->native_ai->state.owner_04==identity&&
     components.find(dh2::character_constructor_owner_v1::Component::ai)==
       &owner->native_ai->state)return 0;
  break;
 case Association::animator:
  if(components.find(dh2::character_constructor_owner_v1::Component::animator)==
       &record->faery_visual)return 0;
  break;
 case Association::state_machine:
  if(record->coordinator&&record->coordinator->owner()==identity&&
     components.find(dh2::character_constructor_owner_v1::Component::state_machine)==
       record->coordinator.get())return 0;
  break;
 case Association::properties:
  if(components.find(dh2::character_constructor_owner_v1::Component::properties)==
       &owner->properties)return 0;
  break;
 }
 error="Authored Faery Character association lacks its same-Record component owner";
 return 1;
}

int NativeCryptRoomRuntime::faery_register_state(
    void* raw,dh2::character_constructor_owner_v1::Identity identity,
    std::uint32_t state,std::string& error) {
 auto* owner=static_cast<AuthoredCryptFaeryOwner*>(raw);
 if(!owner||!owner->record||owner->identity!=identity||state>=20||
    !owner->record->coordinator||owner->record->coordinator->owner()!=identity) {
  error="Authored Faery Character RegisterState lacks its canonical Coordinator";
  return 1;
 }
 const auto handler=reinterpret_cast<std::uintptr_t>(
     &dh2_character_state_transition);
 if(!handler||!owner->record->coordinator->register_source_state(
       identity,state,handler)) {
  error="Authored Faery RegisterState could not retain the source handler on its canonical Coordinator";
  return 1;
 }
 return 0;
}

void NativeCryptRoomRuntime::faery_rollback(
    void* raw,dh2::character_constructor_owner_v1::Action action,
    std::uint32_t value,dh2::character_constructor_owner_v1::Identity identity,
    dh2::character_runtime_factory_v1::ComponentStorage&) noexcept {
 auto* owner=static_cast<AuthoredCryptFaeryOwner*>(raw);
 if(!owner||owner->identity!=identity)return;
 if(action==dh2::character_constructor_owner_v1::Action::state) {
  if(value<20&&owner->record&&owner->record->coordinator) {
   const auto handler=reinterpret_cast<std::uintptr_t>(
       &dh2_character_state_transition);
   (void)owner->record->coordinator->unregister_source_state(
       identity,value,handler);
  }
  return;
 }
 if(action!=dh2::character_constructor_owner_v1::Action::component)return;
 const auto component=static_cast<dh2::character_constructor_owner_v1::Component>(value);
 if(component==dh2::character_constructor_owner_v1::Component::ai)
  (void)retire_authored_faery_char_ai(*owner);
 else if(component==dh2::character_constructor_owner_v1::Component::controller)
  owner->controller={};
 else if(component==dh2::character_constructor_owner_v1::Component::controllable)
  owner->controllable={};
}

extern std::unique_ptr<dh2::native_visual_fx_manager_v1::Catalog> native_fx_catalog;
extern std::unique_ptr<dh2::native_visual_fx_manager_v1::Owner> native_fx_owner;


bool resolve_authored_faery_model(std::uint32_t,
    const dh2::data::PropertyState&,std::string&,std::string&);
bool load_authored_faery_visual_sync(struct AuthoredFaeryInitPostContext&,
                                    std::string&);
bool resolve_authored_faery_owner_bounds(
    AAssetManager*,AuthoredCryptFaeryOwner&,
    dh2::physical::CharacterOwnerBounds&,std::string&);
bool extend_authored_faery_clipbank(
    dh2::character_runtime_factory_v1::Record&,AAssetManager*,std::string&);

struct AuthoredFaeryInitPostContext {
 NativeCryptRoomRuntime* runtime{};
 AuthoredCryptFaeryOwner* owner{};
 std::string provider_error;
};

int faery_init_post_is_player(void* raw,
    const dh2::character_runtime_factory_v1::Record& record,bool* value) {
 auto* context=static_cast<AuthoredFaeryInitPostContext*>(raw);
 if(!context||!context->owner||!value||!context->owner->native_ai||
    record.character.identity!=context->owner->identity)return 1;
 const auto& source=context->owner->source;
 if(source.ai_table_id<0||
    static_cast<std::size_t>(source.ai_table_id)>=actor_ai_tables.rows.size()||
    static_cast<std::size_t>(source.ai_table_id)>=actor_ai_classification_rows.size()||
    actor_ai_tables.rows[static_cast<std::size_t>(source.ai_table_id)].type!=3||
    !context->owner->native_ai->ai_identity||
    context->owner->native_ai->state.owner_04!=record.character.identity)
  return 1;
 // InitPost calls IsPlayer before SafeGet/LoadBase/Recalc and before the
 // candidate NativeCryptRoomRuntime is globally published. Classify this
 // same factory Character using its retained authored AITable row and exact
 // source name, so the source type/name fallback runs without an active-level
 // registry lookup or an invented IsPlayer=false result.
 dh2::character_ai_classification::State state{
     record.character.identity,source.ai_table_id,0,source.character.c_str(),0};
 const dh2::character_ai_classification::Services services{
     nullptr,&native_classification_service};
 dh2::character_ai_classification::Result result{};
 if(dh2::character_ai_classification::query(
       dh2::character_ai_classification::Query::player,&state,&services,
       &result)!=dh2::character_ai_classification::Status::complete)return 1;
 *value=result.word!=0;return 0;
}

int faery_init_post_get_ai_id(void* raw,
    dh2::character_runtime_factory_v1::Record& record,std::int32_t* output) {
 auto* context=static_cast<AuthoredFaeryInitPostContext*>(raw);
 auto* owner=context?context->owner:nullptr;
 if(!owner||!output||owner->record!=&record||
    record.character.identity!=owner->identity||!owner->properties_ready||
    owner->properties.resolved.size()<=1||
    owner->properties.resolved[1]!=owner->source.ai_table_id||
    owner->source.ai_table_id<0||
    static_cast<std::size_t>(owner->source.ai_table_id)>=actor_ai_tables.rows.size())
  return 1;
 *output=owner->properties.resolved[1];return 0;
}

int faery_init_post_check_spawn(void*,
    dh2::character_runtime_factory_v1::Record& record,bool* accepted) {
 if(!accepted||record.game_object.spawn_probability_274<0)return 1;
 auto& roll=record.game_object.spawn_probability_result_270;
 if(roll==-1)
  roll=dh2_random_next(&dh2::random_lifecycle::process_state(),99,0);
 if(roll<0||roll>=99)return 1;
 *accepted=roll<record.game_object.spawn_probability_274;
 return 0;
}

int faery_init_post_safe_get(void* raw,
    dh2::character_runtime_factory_v1::Record& record,std::int16_t* output) {
 auto* context=static_cast<AuthoredFaeryInitPostContext*>(raw);
 auto* owner=context?context->owner:nullptr;
 if(!owner||!output||record.character.identity!=owner->identity||
    owner->character_table_row<0||owner->source.character.empty()||
    actor_character_names.size()!=actor_character_property_rows.size())return 1;
 if(record.property_id_13c8!=-1) {
  if(record.property_id_13c8!=owner->character_table_row)return 1;
  *output=record.property_id_13c8;return 0;
 }
 const auto first=std::find(actor_character_names.begin(),
     actor_character_names.end(),owner->source.character);
 if(first==actor_character_names.end()||
    std::find(std::next(first),actor_character_names.end(),
              owner->source.character)!=actor_character_names.end())return 1;
 const auto id=first-actor_character_names.begin();
 if(id>INT16_MAX||id!=owner->character_table_row)return 1;
 record.property_id_13c8=static_cast<std::int16_t>(id);
 *output=record.property_id_13c8;return 0;
}

int faery_init_post_load_base(void* raw,void* properties_owner,
                              std::int16_t property_id) {
 auto* context=static_cast<AuthoredFaeryInitPostContext*>(raw);
 auto* owner=context?context->owner:nullptr;
 auto fail=[&](const char* reason) {
  if(context)context->provider_error=reason;
  return 1;
 };
 if(!owner)return fail("LoadBaseProperties has no Faery property owner");
 if(!owner->record||owner->record->character.identity!=owner->identity)
  return fail("LoadBaseProperties lost the canonical Character Record");
 const auto* property_component=owner->record->components.find(
     dh2::character_runtime_factory_v1::ctor::Component::properties);
 if(!property_component||property_component!=&owner->properties||
    properties_owner!=property_component)
  return fail("LoadBaseProperties properties argument is not the Record's canonical PropertyState");
 if(property_id!=owner->record->property_id_13c8||
    property_id!=owner->character_table_row||property_id<0||
    std::size_t(property_id)>=actor_character_property_rows.size())
  return fail("LoadBaseProperties CharacterTable ID differs from SafeGet cache/source row");
 if(static_cast<std::size_t>(property_id)>=actor_character_names.size()||
    actor_character_names[static_cast<std::size_t>(property_id)]!=owner->source.character||
    actor_character_property_rows[static_cast<std::size_t>(property_id)][1]!=
       owner->source.ai_table_id)
  return fail("LoadBaseProperties source name/AI does not match the selected CharacterTable row");
 dh2::data::reset_properties(actor_property_rules,owner->properties,
     &actor_character_property_rows[static_cast<std::size_t>(property_id)]);
 owner->properties_ready=false;return 0;
}

int authored_faery_buff_service_v1(void* raw,dh2::data::PropertyView* view,
        const dh2::character_player_buffs_v1::Request* request,
        dh2::character_player_buffs_v1::Response* response) {
 auto* owner=static_cast<AuthoredCryptFaeryOwner*>(raw);
 if(!owner||!owner->record||!view||view!=&owner->buff_properties||!request||
    !response||request->character!=owner->identity||
    request->character!=owner->record->character.identity||
    !owner->record->coordinator)return 1;
 using Operation=dh2::character_player_buffs_v1::Operation;
 switch(request->operation) {
  case Operation::timer_start:
   response->word=owner->record->coordinator->start_timer(request->duration,-1,
       request->event,request->subject);
   return response->word< -1?1:0;
  case Operation::timer_stop:
   return request->id==-1||owner->record->coordinator->stop_timer(
       static_cast<std::uint32_t>(request->id))>=0?0:1;
  case Operation::timer_time_left: {
   const auto& timers=owner->record->coordinator->timers();
   if(request->id<0||!timers.slots)return 1;
   for(std::uint32_t i=0;i<timers.count;++i) {
    if(timers.slots[i].id!=static_cast<std::uint32_t>(request->id))continue;
    return timers.slots[i].active&&dh2_character_timer_time_left(
        &response->elapsed,&response->duration,&timers,
        static_cast<std::uint32_t>(request->id))==1?0:1;
   }
   return 1;
  }
  case Operation::apply_class:
   if(!request->sheet||!request->subject)return 1;
   return int(dh2_class_apply(actor_class_rows.data(),
       static_cast<std::uint32_t>(actor_class_rows.size()),request->id,
       request->sheet,view->resolved));
  case Operation::recalculate:
   return int(dh2_class_recalc_base(actor_class_rows.data(),
       static_cast<std::uint32_t>(actor_class_rows.size()),
       owner->properties.base.data(),view));
  case Operation::fx_release:
   if(!request->subject)return 0;
   if(!native_fx_owner)return 1;
   {
    void* handle=reinterpret_cast<void*>(request->subject);
    std::string error;
    return native_fx_owner->DropAnimatedFX(&handle,error)==
       dh2::native_visual_fx_manager_v1::Status::ok?0:1;
   }
  case Operation::fx_load:
   if(!native_fx_owner||!owner->record||
      owner->record->game_object.identity!=owner->identity)return 1;
   {
    response->identity=0;
    void* handle=nullptr;
    std::string error;
    const auto status=native_fx_owner->GrabAnimFX(request->id,
        &owner->record->game_object,&handle,error);
    if(status==dh2::native_visual_fx_manager_v1::Status::pool_exhausted) {
     response->identity=0;return 0;
    }
    if(status!=dh2::native_visual_fx_manager_v1::Status::ok)return 1;
    response->identity=reinterpret_cast<std::uintptr_t>(handle);return 0;
   }
  case Operation::fx_object:
   if(!request->subject||!native_fx_owner)return 1;
   {
    void* controller=nullptr;
    std::string error;
    if(native_fx_owner->GetAnimController(
         reinterpret_cast<void*>(request->subject),&controller,error)!=
       dh2::native_visual_fx_manager_v1::Status::ok)return 1;
    response->identity=reinterpret_cast<std::uintptr_t>(controller);return 0;
   }
  case Operation::fx_enable:
   if(!native_fx_owner||request->index<0)return 1;
   {
    std::string error;
    return native_fx_owner->PlayAnimControllerClip(
        reinterpret_cast<void*>(request->subject),
        static_cast<std::uint32_t>(request->index),request->enabled==1,error)==
       dh2::native_visual_fx_manager_v1::Status::ok?0:1;
   }
 }
 return 1;
}

int faery_init_post_recalc(void* raw,void* properties_owner,bool force) {
 auto* context=static_cast<AuthoredFaeryInitPostContext*>(raw);
 auto* owner=context?context->owner:nullptr;
 auto* runtime=context?context->runtime:nullptr;
 if(!owner||!runtime||!runtime->character_factory||!force||
    properties_owner!=&owner->properties||!owner->record||
    owner->record->property_id_13c8!=owner->character_table_row)return 1;
 std::string error;
 if(!dh2::data::recalc_properties_with_class(actor_class_tables,
       actor_property_rules,owner->properties,error))return 1;
 if(!owner->buffs) {
  owner->buff_properties=dh2::data::property_view(actor_property_rules,
                                                   owner->properties);
  auto candidate=dh2::character_player_buffs_v1::Owner::create({
      owner->identity,&owner->buff_properties,
      {owner,&authored_faery_buff_service_v1},
      static_cast<std::uint32_t>(actor_class_rows.size()),UINT32_MAX});
  if(!candidate)return 1;
  owner->buffs=std::move(candidate);
 }
 if(owner->properties.resolved[1]!=owner->source.ai_table_id)return 1;
 owner->record->character.source_word_1310=owner->properties.resolved[198];
 owner->record->character.source_word_1314=owner->properties.resolved[199];
 dh2::character_runtime_factory_v1::Result result{};
 if(runtime->character_factory->mark_source_properties_ready(
       owner->source.source_handle,&result,error)!=
       dh2::character_runtime_factory_v1::Status::complete)return 1;
 owner->properties_ready=true;return 0;
}

int faery_init_post_model_name(void* raw,
    dh2::character_runtime_factory_v1::Record& record,std::string* output) {
 auto* context=static_cast<AuthoredFaeryInitPostContext*>(raw);
 auto* owner=context?context->owner:nullptr;
 if(!owner||!output||record.character.identity!=owner->identity||
    !owner->properties_ready||actor_character_fields.empty()||
    actor_model_table.values.empty())return 1;
 const auto model_field=std::find(actor_character_fields.begin(),
     actor_character_fields.end(),"ModelFile");
 if(model_field==actor_character_fields.end())return 1;
 const auto field=static_cast<std::size_t>(model_field-actor_character_fields.begin());
 if(field>=owner->properties.resolved.size())return 1;
 std::int32_t model=owner->properties.resolved[field];
 if(owner->native_ai&&owner->native_ai->state.master_50) {
  if(owner->native_ai->state.master_50!=prince_character.identity()||
     !prince_combat.savegame||native_save_difficulty<0||native_save_difficulty>2)
   return 1;
  const auto faery_id=prince_combat.savegame->current_faery(
      static_cast<std::uint32_t>(native_save_difficulty));
  if(faery_id<0)return 1;
  std::string selected,error;
  if(!resolve_authored_faery_model(static_cast<std::uint32_t>(faery_id),
        owner->properties,selected,error))return 1;
  owner->selected_faery_id=faery_id;
  *output=std::move(selected);return 0;
 }
 owner->selected_faery_id=-1;
 if(model==-1) { output->clear();return 0; }
 if(model<0||static_cast<std::size_t>(model)>=actor_model_table.values.size())return 1;
 *output=actor_model_table.values[static_cast<std::size_t>(model)];
 return output->empty()?1:0;
}

