namespace {
bool source_condition_pointer_present(
    NativeCryptRoomRuntime& runtime,
    const dh2::object_manager_runtime_owner_v1::GameObject& row,
    bool activation,
    bool* present,std::string& error) {
 if(!present)return false;
 *present=false;
 const auto* source=static_cast<const dh2::world::SourceObjectCensusV1*>(nullptr);
 if(row.source_provenance_ready) {
  for(const auto& candidate:active_level_assets.source_object_census) {
   if(candidate.module_index==row.source_module_index&&
      candidate.source_record==row.source_record&&
      candidate.source_handle==row.source_handle) {
    if(source) {
     error="ObjectManager InitPost ConditionData provenance is ambiguous";
     return false;
    }
    source=&candidate;
   }
  }
 }
 std::string_view name;
 if(source)name=activation?source->activate_condition:
                            source->deactivate_condition;
 else {
  const auto actor=runtime.actors.find(row.identity);
  if(actor!=runtime.actors.end()&&actor->second)
   name=activation?actor->second->source_activate_condition:
                   actor->second->source_deactivate_condition;
 }
 if(name.empty()||name=="Invalid")return true;
 if(!native_source_character_conditions) {
  error="ObjectManager InitPost ConditionData table is unavailable";
  return false;
 }
 const std::string owned_name(name);
 const auto* definition=dh2::data::condition_data_v1::find(
     *native_source_character_conditions,owned_name.c_str());
 if(!definition) {
  // ConditionData::Init 0x33eb28 leaves +0x1c null when the authored name is
  // not a v2Conditions row (DARKWOOD's IsLowerThanDW_Phase_3), so the object
  // is unconditional for this activation/deactivation slot.
  __android_log_print(ANDROID_LOG_WARN,"DH2Native",
      "Authored condition is not a v2Conditions row; treated as absent | %s",owned_name.c_str());
  return true;
 }
 *present=true;
 return true;
}
}

bool NativeCryptRoomRuntime::active_list_condition_gate_service(
    void* raw,const GameObject& row,bool* result) {
 auto* context=static_cast<NativeCryptRoomInitPostContext*>(raw);
 if(!context||!context->runtime||!context->error||!result)return false;
 bool present=false;
 if(!source_condition_pointer_present(*context->runtime,row,true,
                                     &present,*context->error))return false;
 if(!row.condition_tested_ac_ready||row.condition_tested_ac>1) {
  *context->error="ObjectManager InitPost activation ConditionData tested byte is unresolved";
  return false;
 }
 *result=!row.condition_tested_ac&&present;
 return true;
}

bool NativeCryptRoomRuntime::read_active_list_flags_service(
    void* raw,const GameObject& row,bool* flag_d0,bool* flag_cc) {
 auto* context=static_cast<NativeCryptRoomInitPostContext*>(raw);
 if(!context||!context->runtime||!context->error||!flag_d0||!flag_cc)
  return false;
 bool present=false;
 if(!source_condition_pointer_present(*context->runtime,row,false,
                                     &present,*context->error))return false;
 if(!row.condition_tested_d0_ready||row.condition_tested_d0>1) {
  *context->error="ObjectManager InitPost deactivation ConditionData tested byte is unresolved";
  return false;
 }
 *flag_d0=row.condition_tested_d0!=0;
 *flag_cc=present;
 return true;
}

