   actor_projection.object.character_2f0=actor->in_zone_2f0;
   actor_projection.object.visible=actor->visible_80;
   actor_projection.character.identity=actor->identity;
   actor_projection.character.object=&actor_projection.object;
   actor_projection.character.source_word_1310=actor->properties.resolved[198];
   actor_projection.character.source_word_1314=actor->properties.resolved[199];
   actor_projection.is_character=1;
   dh2::object_manager_runtime_owner_v1::GameObject projection{};
   projection.identity=actor->identity;
   projection.source_handle=actor->source_handle;
   // ObjectBase ctor 0x33f15c writes +0x29 = 0 at 0x33f1e0 before the
   // completed source row is published to ObjectManager::Add.
   projection.locked_29=0;
   projection.locked_29_ready=1;
   // ObjectBase+100 is the source module ID consumed by
   // ObjectManager::GetObjectByName's final argument. Keep it on the shared
   // manager projection so authored callbacks use canonical name resolution.
   projection.module_id_64=actor->source_object_module_id;
   projection.global_87=actor->source_global_87;
   projection.save_eligibility_28=actor->source_save_eligibility_28;
   projection.deleted_81=actor->source_deleted_81;
   const auto* construction=actor->source_character_construction.get();
   projection.save_facts_ready=construction&&
       construction->source.identity==actor->identity&&
       construction->source.source_component_adoption_complete&&
       construction->source.constructor_save_vectors_ready&&
       actor->source_save_eligibility_28==1;
   projection.source_module_index=actor->source_module_index;
   projection.source_record=actor->source_record;
   projection.source_provenance_ready=1;
   projection.world_x=actor->position[0];projection.world_y=actor->position[1];
   projection.zoning_enabled_2ee=actor->zoning_enabled_2ee;
   projection.visible_80=actor->visible_80;
   projection.visual_object_2d8=actor->visual_object_2d8;
   // ObjectBase constructor (0x33f15c) starts +0x8a enabled; ordered
   // TestEnableCondition publishes the receipt after InitPost.
   projection.serialized_flag_8a=1;
   projection.serialized_flag_8a_ready=0;
   dh2::object_manager_runtime_owner_v1::GameObject::LiveFields actor_fields{};
   actor_fields.world_x=&actor->position[0];
   actor_fields.world_y=&actor->position[1];
   actor_fields.room_zone_2f4=&actor->room_zone_2f4;
   actor_fields.in_room_list_2ef=&actor->in_room_list_2ef;
   actor_fields.zoning_enabled_2ee=&actor->zoning_enabled_2ee;
   actor_fields.in_zone_2f0=&actor->in_zone_2f0;
   actor_fields.visual_object_2d8=&actor->visual_object_2d8;
   actor_fields.visible_80=&actor->visible_80;
   actor_fields.module_id_64=&actor->source_object_module_id;
   actor_fields.global_87=&actor->source_global_87;
   actor_fields.save_eligibility_28=&actor->source_save_eligibility_28;
   actor_fields.deleted_81=&actor->source_deleted_81;
   projection.bind_live_fields(actor_fields);
   const auto actor_entry=actors.emplace(actor->identity,actor);
