bool initialize_player_camera_anchor(std::uintptr_t character,
        dh2::native::crypt_camera_frame_v1::Vec3 character_position,
        std::string& error){
 using namespace dh2::native::crypt_camera_frame_v1;
 if(!character||!native_debug){error="Character::InitCam requires the canonical Player and shared DebugSwitches owner";return false;}
 if(native_debug->runtime().load(native_debug->globals(),native_debug->services())!=
       dh2::debug_switches::Status::complete){error="Character::InitCam DebugSwitches::load failed";return false;}
 std::uint8_t use_static=0;
 if(native_debug->runtime().get_switch("UseStaticCamera",native_debug->globals(),
       native_debug->services(),use_static)!=dh2::debug_switches::Status::complete){
  error="Character::InitCam DebugSwitches::GetSwitch failed for UseStaticCamera";return false;
 }
 float max_distance=0.0f,distance_per_frame=0.0f,threshold=0.0f;
 if(!use_static){
  auto get_design_constant=[&](const char* key,float& out){
   dh2_pycst_result value{};
   if(!actor_design.bytes||dh2_pycst_get(&actor_design,"CharacterDesign",15,
       key,std::uint32_t(std::strlen(key)),&value)){
    error=std::string("Character::InitCam could not read CharacterDesign/")+key;
    return false;
   }
   // PyDataConstants::getConstant returns zero for an absent key; retain its
   // integer result (rather than inventing a camera-specific fallback).
   out=static_cast<float>(value.value);return true;
  };
  if(!get_design_constant("ForwardCamera_Max_Distance",max_distance)||
     !get_design_constant("ForwardCamera_Distance_PerSec",distance_per_frame)||
     !get_design_constant("ForwardCamera_Threshold",threshold))return false;
 }
 if(!initialize_character_camera_anchor(&prince_camera_anchor,character,
       character_position,use_static!=0,max_distance,distance_per_frame,threshold)){
  error="Character::InitCam inputs were rejected by the retained camera anchor";return false;
 }
 error.clear();return true;
}
