bool destroy_source_level_camera_cleanup(std::uintptr_t level,
        std::uint32_t index,std::string& error){
 const auto source=source_level_owner.snapshot();
 if(!level||source.phase!=dh2::source_level_owner_v1::Phase::active||
    source.source_level!=level){
  error="Level::Unload camera cleanup crossed the active source Level";return false;
 }
 if(index==74){
  const auto identity=reinterpret_cast<std::uintptr_t>(&source_camera_level_owner);
  if(!source.cleanup_index_74_known||!source.has_cleanup_index_74||
     source.cleanup_index_74_identity!=identity||!source_camera_level_owner_ready){
   error="Level::Unload CameraLevel +0x128 owner is not the active retained camera";return false;
  }
  source_camera_zoom_input.clear_camera();
  player_camera_animset_playback_owner=dh2::camera_animset_v1::PlaybackOwner{};
  player_camera_animset_bank.clear();player_camera_animset_selection={};
  player_camera_playback=dh2::player_camera_rig_v1::Playback{};
  source_camera_level_owner=dh2::camera_level_runtime_v1::Owner{};
  source_camera_level_owner_ready=false;source_camera_level_has_frame=false;
 }else if(index==75){
  const auto identity=source_camera_overview_owner.projection_identity();
  if(!source.cleanup_index_75_known||!source.has_cleanup_index_75||
     source.cleanup_index_75_identity!=identity||!identity||
     !source_camera_overview_owner.live()){
   error="Level::Unload CameraOverview +0x12c owner is not the active retained overview";return false;
  }
  if(source_camera_overview_owner.active()&&
     !source_camera_overview_owner.deactivate()){
   error="Level::Unload CameraOverview listener detach failed";return false;
  }
  if(!source_camera_overview_owner.destroy(identity)){
   error="Level::Unload CameraOverview exact-owner destruction failed";return false;
  }
 }else{
  error="Level::Unload camera cleanup index is not 74 or 75";return false;
 }
 if(!source_level_owner.clear_level_cleanup_owner(level,index,
       index==74?reinterpret_cast<std::uintptr_t>(&source_camera_level_owner):
          source.cleanup_index_75_identity)){
  error="Level::Unload rejected the completed camera cleanup owner write";return false;
 }
 error.clear();return true;
}
bool retire_source_camera_owners_terminal(std::string& error){
 source_camera_zoom_input.clear_camera();
 if(source_camera_overview_owner.live()){
  const auto identity=source_camera_overview_owner.projection_identity();
  if(source_camera_overview_owner.active()&&
     !source_camera_overview_owner.deactivate()){
   error="Terminal Level teardown could not detach CameraOverview";return false;
  }
  if(!identity||!source_camera_overview_owner.destroy(identity)){
   error="Terminal Level teardown could not destroy the retained CameraOverview";return false;
  }
 }
 reset_source_camera_level_runtime();
 error.clear();return true;
}
