bool read_native_player_character_save_view(
        void*,std::uintptr_t identity,
        dh2::character_level_save_serialize_v1::View* output,
        std::string& error) {
 using namespace dh2::character_level_save_serialize_v1;
 if(!output||identity!=prince_character.identity()||
    !prince_combat.savegame||
    prince_character.save_for(identity)!=prince_combat.savegame.get()||
    !prince_source_ai||
    prince_source_ai->character_identity!=identity||
    prince_source_ai->state.owner_04!=identity||
    !prince_source_ai->ai_identity){
  error="Player Character save requires the same published Character, Save and CharAI owners";
  return true;
 }
 const auto* checkpoint=prince_character.checkpoint_position_1468(identity);
 const auto* revive=prince_character.checkpoint_revive_position_1474(identity);
 if(!checkpoint||!revive||prince_combat.life.dead>1){
  error="Player Character save fields are not retained on the canonical Character owner";
  return true;
 }
 // Character+0x3fc aliases embedded CharAI+52, its optional GroupInfo pointer.
 // Character::Serialize copies the pointed GroupInfo tail, not CharAI bytes.
 dh2::character_group_info_owner_v1::Tail group_tail{};
 const auto group_identity=prince_source_ai->state.group_info_identity;
 if(group_identity&&
    (!source_char_ai.groups.owns(group_identity)||
     !source_char_ai.groups.read_tail(group_identity,&group_tail)||
     group_tail.flag_40>1||group_tail.flag_41>1)){
  error="Player Character GroupInfo pointer has no canonical level-scoped owner";
  return true;
 }
 View view{};
 view.state_machine_state=static_cast<std::uint32_t>(prince_state.current);
 view.is_player=1;
 view.position={reinterpret_cast<const std::uint8_t*>(
      prince_runtime.subobjects.position),sizeof(prince_runtime.subobjects.position)};
 view.rotation={reinterpret_cast<const std::uint8_t*>(
      prince_runtime.rotation.rotation),sizeof(prince_runtime.rotation.rotation)};
 view.dead=static_cast<std::uint8_t>(prince_combat.life.dead);
 view.vector_1306={reinterpret_cast<const std::uint8_t*>(checkpoint),12};
 view.vector_1309={reinterpret_cast<const std::uint8_t*>(revive),12};
 if(group_identity){
  view.has_group_info=1;
  view.group_word_36=group_tail.word_36;
  view.group_flag_40=group_tail.flag_40;
  view.group_flag_41=group_tail.flag_41;
 }
 *output=view;
 error.clear();
 return false;
}
