void native_level_save_restore_script_invoke_v1(void* raw,
        dh2::character::ScriptLifecycleState64* state,
        const dh2::character::ScriptLifecycleRequest32* request,
        dh2::character::ScriptLifecycleResponse16* response) {
 using namespace dh2::character;
 auto* context=static_cast<NativeLevelSaveRestoreScriptContextV1*>(raw);
 if(!context||!context->record||!context->owner||!state||!request||!response)
  throw std::runtime_error("LevelSavegame AIS lifecycle owner is missing");
 auto& record=*context->record;auto& owner=*context->owner;
 auto* ai=record.canonical_ai();
 auto* session=record.source_external_ais.get();
 if(!ai||ai->owner_04!=record.character.identity||
    state->owner!=record.character.identity||!session||!session->ready()||
    state->active!=record.external_ais.identity||
    state->pending!=record.external_ais.identity||!owner.external_skills||
    !owner.external_skills->prepared())
  throw std::runtime_error("LevelSavegame AIS lifecycle no longer matches its same-Record owners");
 const auto dispatch=[&](dh2::monster_external_script::Event event) {
  std::string failure;
  if(session->dispatch(event,0,failure)!=
      dh2::monster_external_script::Status::complete)
   throw std::runtime_error(failure.empty()?"AIS Lua callback failed":failure);
 };
 switch(request->service) {
  case script_timer_stop:
   if(static_cast<std::int32_t>(request->argument0)!=-1&&
      (!record.coordinator||record.coordinator->stop_timer(request->argument0)<0))
    throw std::runtime_error("source Character timer stop failed");
   break;
  case script_design_tick: {
   const char* key=request->argument0==0x33?"AI_Tick":
       request->argument0==0x34?"DoT_Tick":nullptr;
   if(!key||!actor_design.bytes)throw std::runtime_error("source Character AI tick design is unavailable");
   dh2_pycst_result value{};
   if(dh2_pycst_get(&actor_design,"CharacterDesign",15,key,
         static_cast<std::uint32_t>(std::strlen(key)),&value)||!value.found)
    throw std::runtime_error("source Character AI tick design lookup failed");
   response->word=static_cast<std::uint32_t>(value.value);break;
  }
  case script_timer_start: {
   if(!record.coordinator)throw std::runtime_error("source Character Coordinator is unavailable");
   const auto timer=record.coordinator->start_timer(request->argument0,-1,
                                                    request->argument1,0);
   if(timer<0)throw std::runtime_error("source Character timer allocation failed");
   if(request->argument1==0x33)ai->word_10=static_cast<std::uint32_t>(timer);
   else if(request->argument1==0x34)ai->word_14=static_cast<std::uint32_t>(timer);
   else throw std::runtime_error("source Character timer event has no CharAI slot");
   response->word=static_cast<std::uint32_t>(timer);break;
  }
  case script_owner_is_dead:
   if(request->subject!=record.character.identity)throw std::runtime_error("source Character dead query identity differs");
   response->word=record.serialized_dead_1449;break;
  case script_skill_cleanup:
  case script_spell_cleanup: {
   dh2::native::ghost_skill_update_v1::CleanupResult result{};
   std::string failure;
   const auto list=request->service==script_skill_cleanup?
       dh2::character_ai_set_skills_and_spells::List::skill:
       dh2::character_ai_set_skills_and_spells::List::faery;
   if(dh2::native::ghost_skill_update_v1::cleanup_list(*session,
         *owner.external_skills,record.character.identity,list,result,failure))
    throw std::runtime_error(failure.empty()?"source AIS skill cleanup failed":failure);
   response->word=result.callbacks;break;
  }
  case script_ais_terminate: dispatch(dh2::monster_external_script::Event::terminate);break;
  case script_ais_init: dispatch(dh2::monster_external_script::Event::init);break;
  case script_ais_init_post: dispatch(dh2::monster_external_script::Event::init_post);break;
  case script_ais_init_final: dispatch(dh2::monster_external_script::Event::init_final);break;
  default: throw std::runtime_error("LevelSavegame AIS lifecycle reached an unbound source service");
 }
}
bool native_level_save_support_factory_character_restore_v1(void* raw,
        const dh2::character_runtime_factory_v1::Record& record,
        const dh2::level_savegame_player_load_v1::FactoryDeserializeState& state,
        bool* supported,std::string& error) {
 using namespace dh2::level_savegame_player_load_v1;
 if(!supported){error="Factory Character restore requires an admission output";return true;}
 *supported=false;
 auto* facts=static_cast<NativeLevelSaveObjectFactsContextV1*>(raw);
 const auto active=source_level_owner.snapshot();
 auto* owner=native_faery_owner(record.character.identity);
 auto* ai=record.canonical_ai();
 bool existing_buff_fx_owner_supported=true;
 if(owner&&owner->buffs) {
  if(owner->buffs->declarations()>owner->buffs->count()||
     (owner->buffs->declarations()&&!native_fx_owner))
   existing_buff_fx_owner_supported=false;
  for(std::uint32_t i=0;i<owner->buffs->count();++i) {
   dh2::character_player_buffs_v1::Snapshot buff{};
   if(!owner->buffs->snapshot(i,&buff)) {
    error="same-Record buff snapshot failed restore preflight";return false;
   }
   if(buff.fx) {
    if(!native_fx_owner)existing_buff_fx_owner_supported=false;
    else {
     void* controller=nullptr;std::string fx_error;
     if(native_fx_owner->GetAnimController(
          reinterpret_cast<void*>(buff.fx),&controller,fx_error)!=
        dh2::native_visual_fx_manager_v1::Status::ok)
      existing_buff_fx_owner_supported=false;
    }
   }
  }
 }
 float position[3]{},rotation[3]{};
 std::memcpy(position,state.position.data(),sizeof(position));
 std::memcpy(rotation,state.rotation.data(),sizeof(rotation));
 const char* unsupported=nullptr;
 const auto fail_if=[&](bool condition,const char* why) {
  if(!unsupported&&condition)unsupported=why;
 };
 fail_if(!facts||active.phase!=dh2::source_level_owner_v1::Phase::active||
    active.generation!=facts->level_generation,"no active Level generation owner");
 fail_if(!owner||owner->record!=&record||owner->identity!=record.character.identity,
    "no authored Faery owner on this Record");
 fail_if(!ai||!owner||!owner->native_ai||&owner->native_ai->state!=ai,
    "Faery CharAI owner differs");
 fail_if(!record.coordinator,"Faery Record has no Coordinator");
 fail_if(record.coordinator&&!record.coordinator->bound(),"Faery Coordinator is not bound");
 fail_if(record.coordinator&&record.coordinator->owner()!=record.character.identity,
    "Faery Coordinator owner differs");
 fail_if(state.object_base_flag_80>1||state.object_base_flag_8a>1,
    "ObjectBase bytes are not booleans");
 // Character::Deserialize reads the dead byte and state; the supported closure
 // is the alive Idle row. GameObject::Deserialize's +0x270 compare is only a
 // source assertion (spawnProbRolled == m_spawnProbRolled) and gates nothing.
 // A saved state outside 0..0x11 (the unfocused -1 a Faery has before its first
 // Update) takes Character::Deserialize's alive branch: SM_SetIdleState(false).
 fail_if(state.dead!=0||(state.state_machine_state!=3&&state.state_machine_state!=-1),
    "saved Faery is not alive and Idle");
 fail_if(!std::all_of(std::begin(position),std::end(position),[](float v){return std::isfinite(v);})||
    !std::all_of(std::begin(rotation),std::end(rotation),[](float v){return std::isfinite(v);}),
    "saved Faery vectors are not finite");
 fail_if(!owner||!owner->properties_ready||!record.init_post_complete()||
    !record.init_final_complete(),"Faery InitPost/InitFinal are incomplete");
 fail_if(!record.pofaerie_physical||!record.pofaerie_physical->created(),
    "Faery POFaerie body is not created");
 fail_if(!owner||!owner->buffs||owner->buffs->character_identity()!=record.character.identity||
    owner->buff_properties.base!=owner->properties.base.data()||
    owner->buff_properties.saved!=owner->properties.saved.data()||
    owner->buff_properties.resolved!=owner->properties.resolved.data(),
    "Faery buff owner is not attached to its property sheets");
 fail_if(!existing_buff_fx_owner_supported,"Faery buff FX teardown is unbound");
 fail_if(!dh2::character_faery_visual_facade_v1::ready(
       record.faery_visual,record.character.identity),"Faery visual facade is not ready");
 fail_if(!record.serialized_constructor_fields_ready,"Faery constructor save fields are not ready");
 fail_if(record.serialized_dead_1449!=0,"live Faery is dead");
 fail_if(record.faery_visual.visible!=bool(state.object_base_flag_80),
    "saved Faery visibility differs from the live Faery (SetVisible is not part of this closure)");
 fail_if(record.coordinator&&record.coordinator->state.current!=3&&
    record.coordinator->state.current!=4&&record.coordinator->state.current!=5,
    "live Faery is not in Idle/Move/Attack");
 fail_if(!record.source_external_ais||!record.source_external_ais->ready()||
    !owner||!owner->external_skills||!owner->external_skills->prepared(),
    "Faery AIS VM/skills are not published");
 fail_if(!ai||record.external_lifecycle.owner!=record.character.identity||
    record.external_lifecycle.active!=record.external_ais.identity||
    record.external_lifecycle.pending!=record.external_ais.identity||
    !record.external_ais.identity||ai->active_ais_1c!=record.external_ais.identity||
    ai->alternate_ais_20!=record.external_ais.identity||
    record.external_lifecycle.timer33!=static_cast<std::int32_t>(ai->word_10)||
    record.external_lifecycle.timer34!=static_cast<std::int32_t>(ai->word_14),
    "Faery AIS lifecycle does not match its CharAI");
 if(unsupported) {
  error=unsupported;return false;
 }
 const auto group_identity=ai->group_info_identity;
 if(bool(state.has_group_info_tail)!=bool(group_identity)) {error="GroupInfo tail presence differs";return false;}
 if(state.has_group_info_tail) {
  dh2::character_group_info_owner_v1::Tail current{};
  if(!source_char_ai.groups.owns(group_identity)||
     !source_char_ai.groups.read_tail(group_identity,&current)) {
   error="GroupInfo pointer is not owned by the active source Level";return false;
  }
 }
 const auto manager=&source_level_owner.object_manager();
 auto* row=manager->find_by_source_handle(record.source_handle);
 if(!row||row->identity!=record.character.identity||
    manager->find_by_identity(record.character.identity)!=row||
    row->visible_80!=record.game_object.visible_80||
    record.game_object.visible_80>1||record.game_object.serialized_flag_8a>1) {
  error="Faery ObjectManager row differs from its GameObject";return false;
 }
 *supported=true;error.clear();return false;
}
bool native_level_save_defers_factory_character_restore_v1(void*,
        const dh2::character_runtime_factory_v1::Record& record) {
 // An authored Faery's Coordinator and AIS are published by its delayed
 // LoadNInit in the first Character::Update. The source reaches the Load after
 // Level::_LoadProcess step 32's ObjectManager::Update; this port loads before
 // the first frame, and PlaceFaeryAndFollowers overwrites the restored pose.
 return native_faery_owner(record.character.identity)&&
     (!record.coordinator||!record.coordinator->bound());
}
bool native_level_save_prepare_factory_character_restore_v1(void* raw,
        const dh2::character_runtime_factory_v1::Record& record,
        const dh2::level_savegame_player_load_v1::FactoryDeserializeState& state,
        std::string& error) {
 bool supported=false;
 if(native_level_save_support_factory_character_restore_v1(raw,record,state,
        &supported,error)||!supported) {
  if(error.empty())error="Faery Character Deserialize closure is unsupported by the active same-Record owners";
  return true;
 }
 error.clear();return false;
}
bool native_level_save_commit_factory_character_restore_v1(void* raw,
        const dh2::character_runtime_factory_v1::Record& const_record,
        const dh2::level_savegame_player_load_v1::FactoryDeserializeState& state,
        std::string& error) {
 using namespace dh2::level_savegame_player_load_v1;
 auto& record=const_cast<dh2::character_runtime_factory_v1::Record&>(const_record);
 if(native_level_save_prepare_factory_character_restore_v1(raw,record,state,error))return true;
 auto* facts=static_cast<NativeLevelSaveObjectFactsContextV1*>(raw);
 auto* owner=native_faery_owner(record.character.identity);
 auto* ai=record.canonical_ai();
 auto* manager=&source_level_owner.object_manager();
 auto* manager_row=manager->find_by_source_handle(record.source_handle);
 float position[3]{},rotation[3]{};
 std::memcpy(position,state.position.data(),sizeof(position));
 std::memcpy(rotation,state.rotation.data(),sizeof(rotation));
 const float half=0.5f; // saved Euler is the live GameObject rotation in radians
 const float rx=rotation[0]*half,ry=rotation[1]*half,rz=rotation[2]*half;
 const float sx=std::sin(rx),cx=std::cos(rx),sy=std::sin(ry),cy=std::cos(ry),
             sz=std::sin(rz),cz=std::cos(rz);
 const std::array<float,4> quaternion{sx*cy*cz-cx*sy*sz,
     cx*sy*cz+sx*cy*sz,cx*cy*sz-sx*sy*cz,cx*cy*cz+sx*sy*sz};
 // Character::Deserialize begins with PROPS_RemoveAllBuffs, before its
 // GameObject and property-image reads. The retained BuffOwner is attached
 // to this same PropertyState and Coordinator; admission above only accepts
 // the empty-declaration case until Faery FX teardown is fully bound.
 dh2::character_player_buffs_v1::Result cleared_buffs{};
 if(owner->buffs->remove_all(&cleared_buffs)!=
       dh2::character_player_buffs_v1::Status::complete) {
  error="same-Record CharProperties::PROPS_RemoveAllBuffs provider failed";
  return true;
 }
 // The existing POFaerie body is the sole physical owner. Apply it before
 // mutating the source projections so a rejected transform preserves them.
 if(record.pofaerie_physical->set_transform(position[0],position[1],rotation[2])!=
       dh2::character_physical_component_v1::Status::complete) {
  error="existing POFaerie rejected Character::Deserialize pose";return true;
 }
 // Character::Deserialize copies the Property images before applying pose and
 // source state. The four-byte headers are kept inert on Record for exact
 // subsequent save serialization; only the 224 words reach PropertyState.
 owner->properties.saved=state.properties.saved;
 owner->properties.resolved=state.properties.resolved;
 record.serialized_properties_saved_header=state.properties.saved_header;
 record.serialized_properties_resolved_header=state.properties.resolved_header;
 record.serialized_property_headers_ready=true;
 record.game_object.visible_80=state.object_base_flag_80;
 record.game_object.serialized_flag_8a=state.object_base_flag_8a;
 record.game_object.serialized_flag_8a_ready=1;
 record.faery_visual.visible=state.object_base_flag_80!=0;
 owner->visual_position={position[0],position[1],position[2]};
 owner->visual_rotation=quaternion;
 dh2::character_faery_motion_v1::place(owner->motion,position);
 record.game_object.world_x=position[0];record.game_object.world_y=position[1];
 record.aggro_object.position[0]=position[0];
 record.aggro_object.position[1]=position[1];
 record.aggro_object.position[2]=position[2];
 record.aggro_object.target_position[0]=position[0];
 record.aggro_object.target_position[1]=position[1];
 record.aggro_object.target_position[2]=position[2];
 record.faery_visual.position=owner->visual_position;
 record.faery_visual.rotation=quaternion;
 owner->source.authored_world_transform[0]=position[0];
 owner->source.authored_world_transform[1]=position[1];
 owner->source.authored_world_transform[2]=position[2];
 for(unsigned axis=0;axis<3;++axis)
  owner->source.authored_world_transform[3+axis]=rotation[axis]*57.2957795f;
 record.faery_controller.rotation.rotation[0]=rotation[0];
 record.faery_controller.rotation.rotation[1]=rotation[1];
 record.faery_controller.rotation.rotation[2]=rotation[2];
 record.faery_controller.rotation.heading_angle=rotation[2];
 record.faery_controller.navigation.motion.position[0]=position[0];
 record.faery_controller.navigation.motion.position[1]=position[1];
 record.faery_controller.navigation.motion.position[2]=position[2];
 std::copy(std::begin(position),std::end(position),record.faery_controller.path.position);
 std::memcpy(record.quick_save_position_1468.data(),state.vector_1468.data(),12);
 std::memcpy(record.revive_position_1474.data(),state.vector_1474.data(),12);
 if(!manager_row||manager_row->identity!=record.character.identity) {
  error="Faery ObjectManager row changed after restore preparation";return true;
 }
 manager_row->world_x=position[0];manager_row->world_y=position[1];
 manager_row->visible_80=state.object_base_flag_80;
 if(state.has_group_info_tail) {
  const dh2::character_group_info_owner_v1::Tail tail{state.group_word_36,
      state.group_flag_40,state.group_flag_41};
  if(!source_char_ai.groups.write_tail(ai->group_info_identity,tail)) {
   error="same-Record GroupInfo owner rejected Character::Deserialize tail";return true;
  }
 }
 try {
  if(record.coordinator->transition(3)<0) {
   error="same-Record Coordinator rejected saved Idle restoration";return true;
  }
  if(faery_external_clear_target(owner,record.character.identity)!=0) {
   error="CharAI::AI_SetTarget source owner rejected target clear";return true;
  }
  ai->last_target_44=ai->target_40;
  NativeLevelSaveRestoreScriptContextV1 script_context{&record,owner};
  const dh2::character::ScriptLifecycleServices16 script_services{
      &script_context,&native_level_save_restore_script_invoke_v1};
  record.external_lifecycle.owner=record.character.identity;
  record.external_lifecycle.active=ai->active_ais_1c;
  record.external_lifecycle.pending=ai->alternate_ais_20;
  record.external_lifecycle.timer33=static_cast<std::int32_t>(ai->word_10);
  record.external_lifecycle.timer34=static_cast<std::int32_t>(ai->word_14);
  if(dh2_character_script_lifecycle(&record.external_lifecycle,
       dh2::character::script_cleanup,0,&script_services)!=1||
     dh2_character_script_lifecycle(&record.external_lifecycle,
       dh2::character::script_ai_script_init,0,&script_services)!=1) {
   error="Character::Deserialize CharAI cleanup/init lifecycle failed";return true;
  }
  ai->active_ais_1c=record.external_lifecycle.active;
  ai->alternate_ais_20=record.external_lifecycle.pending;
  ai->word_10=static_cast<std::uint32_t>(record.external_lifecycle.timer33);
  ai->word_14=static_cast<std::uint32_t>(record.external_lifecycle.timer34);
 } catch(const std::exception& exception) {
  error=std::string("Character::Deserialize source lifecycle failed after prior fields: ")+exception.what();return true;
 } catch(...) {
  error="Character::Deserialize source lifecycle failed after prior fields";return true;
 }
 if(!facts||!owner->properties_ready) {error="Faery visual Sync lost its source owners";return true;}
 error.clear();return false;
}

bool native_level_save_prepare_player_identity_v1(void* raw,std::uintptr_t identity,
        const dh2::level_savegame_player_load_v1::PlayerState& state,
        std::string& error) {
 using namespace dh2::level_savegame_player_load_v1;
 auto* facts=static_cast<NativeLevelSaveObjectFactsContextV1*>(raw);
 const auto active=source_level_owner.snapshot();
 auto* manager=&source_level_owner.object_manager();
 auto* row=manager->find_by_source_handle(3);
 const auto* checkpoint=prince_character.checkpoint_position_1468(identity);
 const auto* revive=prince_character.checkpoint_revive_position_1474(identity);
 const auto group_identity=prince_source_ai?prince_source_ai->state.group_info_identity:0;
 const bool group_present=group_identity&&source_char_ai.groups.owns(group_identity);
 float position[3]{},rotation[3]{};
 std::memcpy(position,state.position.data(),sizeof(position));
 std::memcpy(rotation,state.rotation.data(),sizeof(rotation));
 if(!facts||active.phase!=dh2::source_level_owner_v1::Phase::active||
    active.generation!=facts->level_generation||
    active.object_manager_identity!=reinterpret_cast<std::uintptr_t>(manager)||
    active.player_character!=identity||identity!=prince_character.identity()||
    !row||row->identity!=identity||!row->save_facts_ready||
    !prince_combat.savegame||prince_character.save_for(identity)!=prince_combat.savegame.get()||
    !prince_source_ai||prince_source_ai->character_identity!=identity||
    prince_source_ai->state.owner_04!=identity||!prince_source_ai->ai_identity||
    !checkpoint||!revive||state.object_base_flag_80>1||state.object_base_flag_8a>1||
    state.dead!=0||state.state_machine_state!=3||
    state.game_object_word_270!=prince_character.spawn_probability_result_270()||
    bool(state.has_group_info_tail)!=group_present||
    !std::all_of(std::begin(position),std::end(position),[](float v){return std::isfinite(v);})||
    !std::all_of(std::begin(rotation),std::end(rotation),[](float v){return std::isfinite(v);})) {
  error="Player load preflight lacks the active canonical owners or would require an unbound source state/death transition";
  return true;
 }
 if(state.has_group_info_tail){
  dh2::character_group_info_owner_v1::Tail tail{};
  if(!source_char_ai.groups.read_tail(group_identity,&tail)){
   error="Player load GroupInfo pointer is not owned by the active source Level";
   return true;
  }
 }
 error.clear();return false;
}
bool native_level_save_commit_player_identity_v1(void* raw,std::uintptr_t identity,
        const dh2::level_savegame_player_load_v1::PlayerState& state,
        std::string& error) {
 if(native_level_save_prepare_player_identity_v1(raw,identity,state,error))return true;
 float position[3]{},rotation[3]{};
 std::memcpy(position,state.position.data(),sizeof(position));
 std::memcpy(rotation,state.rotation.data(),sizeof(rotation));
 std::uint32_t checkpoint[3]{},revive[3]{};
 std::memcpy(checkpoint,state.vector_1306.data(),sizeof(checkpoint));
 std::memcpy(revive,state.vector_1309.data(),sizeof(revive));
 if(!prince_character.save_checkpoint_position(identity,checkpoint)||
    !prince_character.save_checkpoint_revive_position(identity,revive)){
  error="Player load checkpoint vectors lost their canonical Character owner";return true;
 }
 if(!prince_character.restore_object_base_flags_v1(identity,
       state.object_base_flag_80,state.object_base_flag_8a)||
    !prince_character.restore_spawn_probability_result_270_v1(
        identity,state.game_object_word_270)) {
  error="Player load canonical scalar commit unexpectedly lost a preflighted owner";
  return true;
 }
 if(state.has_group_info_tail){
  const auto group_identity=prince_source_ai->state.group_info_identity;
  const dh2::character_group_info_owner_v1::Tail tail{
      state.group_word_36,state.group_flag_40,state.group_flag_41};
  if(!source_char_ai.groups.write_tail(group_identity,tail)){
   error="Player load canonical GroupInfo tail commit lost its existing owner";
   return true;
  }
 }
 if(state.state_machine_state==3&&state.dead==0){
  if(prince_combat.life.dead){
   if(!native_player_revive_character_source_v1(identity,error))return true;
  }else if(!native_player_reinitialize_physical_object_v1(identity,error))return true;
  if(prince_character.set_idle_state(false)<0){
   error="Character::Deserialize SM_SetIdleState(false) failed after its supported alive Player branch";return true;
  }
 }
 if(!native_player_deserialize_script_lifecycle_v1(error))return true;
 if(!native_player_deserialize_clear_target_v1(error))return true;
 // Character::Deserialize ends with SetPosition(+0x1450)/SetRotation(+0x145c) when
 // Level +0xF2 (useSpawnPoint) is set and with the saved pose otherwise. The
 // Level-entry Load follows _LoadPlayer, so the SpawnPoint pose already stands;
 // a checkpoint reload keeps applying the saved (entry-time) pose.
 if(source_level_owner.snapshot().checkpoint_load_in_progress!=1&&
    native_level_use_spawn_point_f2){
  error.clear();return false;
 }
 if(prince_body.body){
  const dh2::physical::TransformRequest transform{{position[0]*.01f,
      position[1]*.01f},rotation[2],1};
  if(dh2_native_body_apply_transform(&prince_body,&transform)!=1){
   error="Player load Box2D transform was rejected before logical fields changed";
   return true;
  }
 }
 // The supported alive/Idle Deserialize branch above uses the same Character,
 // CharAI, physical body and Coordinator owners as the source transition.
 if(!native_player_remove_set_position(identity,position,true,error))return true;
 std::memcpy(prince_runtime.rotation.rotation,rotation,sizeof(rotation));
 std::memcpy(prince_runtime.previous_position,position,sizeof(position));
 std::memcpy(prince_runtime.previous_rotation,rotation,sizeof(rotation));
 std::memcpy(prince_runtime.subobjects.previous_position,position,sizeof(position));
 prince_runtime.rotation.heading_angle=rotation[2];
 prince_runtime.subobjects.rotation=rotation[2];
 error.clear();return false;
}
bool native_level_save_apply_player_image_v1(
 const dh2::source_level_owner_v1::Snapshot& active,
 const std::vector<std::uint8_t>& image,bool checkpoint,std::string& error) {
 if(active.phase!=dh2::source_level_owner_v1::Phase::active||
    !active.source_level||!active.source_level_savegame||
    !active_crypt_room_runtime||!active_crypt_room_runtime->character_factory||
    native_host.online){
  error="LevelSavegame Player restore requires the active offline Level/ObjectManager/factory owners";
  return false;
 }
 NativeLevelSaveObjectFactsContextV1 facts{};
 facts.level_generation=active.generation;
 const dh2::character_level_save_serialize_v1::Services player{
     nullptr,&read_native_player_character_save_view,
     &read_native_player_game_object_save_fields};
 NativeLevelSaveIdentityContextV1 identity_context{&facts,player};
 const dh2::character_level_save_serialize_v1::Services identity_services{
     &identity_context,&native_level_save_read_identity_view_v1,
     &native_level_save_read_identity_game_object_v1};
 const dh2::character_level_save_serialize_v1::CanonicalServices
     factory_character_services{&facts,
         &native_level_save_read_factory_character_view_v1,
         &native_level_save_read_factory_game_object_fields_v1,
         &native_level_save_read_factory_group_info_v1};
 const dh2::level_savegame_object_manager_v1::FactsServices source_facts{
     &facts,&native_level_save_read_object_facts_v1,
     &native_level_save_serialize_noncharacter_v1,
     &factory_character_services,&identity_services,
     &native_level_save_is_canonical_character_v1,
     &native_level_save_is_canonical_player_v1};
 dh2::level_savegame_player_load_v1::CommitServices commit{
     &facts,nullptr,nullptr,&native_level_save_prepare_player_identity_v1,
     &native_level_save_commit_player_identity_v1};
 commit.defers_factory_character_restore=
     &native_level_save_defers_factory_character_restore_v1;
 commit.supports_factory_character_restore=
     &native_level_save_support_factory_character_restore_v1;
 commit.prepare_factory_character_restore=
     &native_level_save_prepare_factory_character_restore_v1;
 commit.commit_factory_character_restore=
     &native_level_save_commit_factory_character_restore_v1;
 commit.classify_source_noncharacter_restore=
     &native_level_save_classify_source_noncharacter_v1;
 commit.prepare_source_noncharacter_restore=
     &native_level_save_prepare_source_noncharacter_v1;
 commit.commit_source_noncharacter_restore=
     &native_level_save_commit_source_noncharacter_v1;
 commit.classify_direct_character_restore=
     &native_level_save_classify_direct_character_restore_v1;
 commit.prepare_direct_character_restore=
     &native_level_save_prepare_direct_character_restore_v1;
 commit.commit_direct_character_restore=
     &native_level_save_commit_direct_character_restore_v1;
 dh2::level_savegame_player_load_v1::Result result{};
 const auto status=dh2::level_savegame_player_load_v1::load_player(
     image.data(),image.size(),source_level_owner.object_manager(),
     *active_crypt_room_runtime->character_factory,&source_facts,&commit,
     &result,error);
 if(status!=dh2::level_savegame_player_load_v1::Status::loaded_player_only){
  if(error.empty())error="LevelSavegame PlayerCharacter_0 row was not applied";
  return false;
 }
 // The _level.savegame image is only protected from replacement while it is the
 // image that this load could not fully re-apply. LevelSavegame::LoadCheckPoint
 // 0x46259c reads the sibling checkpoint file and restores the level filename,
 // so a checkpoint (revive) reload never makes _level.savegame stale: the
 // original's next Save writes the live objects, never a protected image.
 const auto protect_level_image=[&]{
  if(!checkpoint)level_savegame_publisher.preserve_existing_image();
 };
 dh2::level_savegame_player_load_v1::FactoryLifecycleResult lifecycle{};
 std::string lifecycle_error;
 const auto lifecycle_status=
     dh2::level_savegame_player_load_v1::restore_factory_character_rows(
         image.data(),image.size(),source_level_owner.object_manager(),
         *active_crypt_room_runtime->character_factory,&source_facts,&commit,
         &lifecycle,lifecycle_error);
 if(lifecycle_status!=dh2::level_savegame_player_load_v1::Status::loaded_player_only) {
  protect_level_image();
  __android_log_print(ANDROID_LOG_WARN,"DH2Native",
      "LevelSavegame non-player Character restore incomplete; %s | checkpoint %u | status %u | %s",
      checkpoint?"level image unaffected":"source image preserved",
      unsigned(checkpoint),unsigned(lifecycle_status),lifecycle_error.c_str());
 }
 dh2::level_savegame_player_load_v1::FactoryLifecycleResult direct_lifecycle{};
 std::string direct_error;
 const auto direct_status=
     dh2::level_savegame_player_load_v1::restore_direct_character_rows(
         image.data(),image.size(),source_level_owner.object_manager(),
         *active_crypt_room_runtime->character_factory,&source_facts,&commit,
         &direct_lifecycle,direct_error);
 if(direct_status!=dh2::level_savegame_player_load_v1::Status::loaded_player_only){
  protect_level_image();
  __android_log_print(ANDROID_LOG_WARN,"DH2Native",
      "LevelSavegame direct Character restore incomplete; %s | checkpoint %u | status %u | %s",
      checkpoint?"level image unaffected":"source image preserved",
      unsigned(checkpoint),unsigned(direct_status),direct_error.c_str());
 }
 dh2::level_savegame_player_load_v1::FactoryLifecycleResult noncharacter_lifecycle{};
 std::string noncharacter_error;
 const auto noncharacter_status=
     dh2::level_savegame_player_load_v1::restore_source_noncharacter_rows(
         image.data(),image.size(),source_level_owner.object_manager(),
         *active_crypt_room_runtime->character_factory,&source_facts,&commit,
         &noncharacter_lifecycle,noncharacter_error);
 if(noncharacter_status!=dh2::level_savegame_player_load_v1::Status::loaded_player_only){
  protect_level_image();
  __android_log_print(ANDROID_LOG_WARN,"DH2Native",
      "LevelSavegame non-Character restore incomplete; %s | checkpoint %u | status %u | %s",
      checkpoint?"level image unaffected":"source image preserved",
      unsigned(checkpoint),unsigned(noncharacter_status),noncharacter_error.c_str());
 }
 // Row accounting follows LevelSavegame::__LoadObjects 0x461e90: a row is
 // applied, skipped by the source (no ObjectManager object answers its key and
 // type, or Character::Deserialize returns early for it) or, only in this port,
 // unsupported -- an object answers but its Deserialize closure is not bound.
 // Only unsupported rows keep the loaded image protected from replacement.
 const std::uint64_t applied_rows=std::uint64_t(lifecycle.rows_fully_applied)+
     direct_lifecycle.rows_fully_applied+noncharacter_lifecycle.rows_fully_applied;
 const std::uint64_t skipped_rows=std::uint64_t(lifecycle.rows_skipped_by_source)+
     direct_lifecycle.rows_skipped_by_source+noncharacter_lifecycle.rows_skipped_by_source;
 const std::uint64_t deferred_rows=lifecycle.rows_deferred;
 const std::uint64_t unsupported_rows=std::uint64_t(lifecycle.rows_unsupported)+
     direct_lifecycle.rows_unsupported+noncharacter_lifecycle.rows_unsupported;
 const std::uint64_t parsed_rows=result.object_rows>0?result.object_rows-1u:0u;
 const std::uint64_t answered_rows=applied_rows+skipped_rows+deferred_rows+unsupported_rows;
 if(answered_rows>parsed_rows){
  protect_level_image();
  __android_log_print(ANDROID_LOG_ERROR,"DH2Native",
      "LevelSavegame restore row accounting exceeded the parsed non-Player row count | parsed %llu | applied %llu | skipped %llu | unsupported %llu",
      static_cast<unsigned long long>(parsed_rows),static_cast<unsigned long long>(applied_rows),
      static_cast<unsigned long long>(skipped_rows),static_cast<unsigned long long>(unsupported_rows));
 }
 const std::uint64_t unanswered_rows=answered_rows>parsed_rows?0u:parsed_rows-answered_rows;
 result.unapplied_object_rows=static_cast<std::uint32_t>(unsupported_rows);
 const bool rows_incomplete=unsupported_rows||
    lifecycle_status!=dh2::level_savegame_player_load_v1::Status::loaded_player_only||
    direct_status!=dh2::level_savegame_player_load_v1::Status::loaded_player_only||
    noncharacter_status!=dh2::level_savegame_player_load_v1::Status::loaded_player_only;
 if(rows_incomplete)protect_level_image();
 std::size_t detail_logged=0;
 for(const auto* detail_set:{&lifecycle.unsupported_detail,&direct_lifecycle.unsupported_detail,
                             &noncharacter_lifecycle.unsupported_detail})
  for(const auto& detail:*detail_set){
   if(detail_logged++>=24)break;
   __android_log_print(ANDROID_LOG_WARN,"DH2Native",
       "LevelSavegame row not applied | checkpoint %u | %s",unsigned(checkpoint),detail.c_str());
  }
 __android_log_print(ANDROID_LOG_INFO,"DH2Native",
     "Source LevelSavegame rows applied | checkpoint %u | generation %u | manager rows %u | Player identity %p | Player payload bytes %u | unapplied rows %u | restored Character rows %u | restored direct Character rows %u | restored non-Character rows %u | skipped by source %u | deferred %u | no live object %llu | replacement protected %u",
     unsigned(checkpoint),
     active.generation,result.object_rows,reinterpret_cast<void*>(result.identity),
     result.payload_bytes,result.unapplied_object_rows,
     lifecycle.rows_fully_applied,direct_lifecycle.rows_fully_applied,
     noncharacter_lifecycle.rows_fully_applied,
     unsigned(skipped_rows),unsigned(deferred_rows),static_cast<unsigned long long>(unanswered_rows),
     unsigned(!checkpoint&&rows_incomplete));
 error.clear();return true;
}
bool native_level_save_load_player_v1(std::string& error) {
 const auto active=source_level_owner.snapshot();
 if(active.phase!=dh2::source_level_owner_v1::Phase::active||
    !active.source_level||!active.source_level_savegame||
    !active_crypt_room_runtime||!active_crypt_room_runtime->character_factory||
    native_host.online){
  error="LevelSavegame Player load requires the active offline Level/ObjectManager/factory owners";
  return false;
 }
 if(level_savegame_player_load_generation==active.generation){error.clear();return true;}
 const auto filename=source_level_owner.level_savegame().filename();
 if(filename.empty()){error="active LevelSavegame filename is unavailable";return false;}
 const auto path=level_savegame_publisher.directory()/std::filesystem::u8path(filename);
 std::error_code ec;
 if(!std::filesystem::exists(path,ec)){
  if(ec){error="LevelSavegame file presence check failed: "+ec.message();return false;}
  level_savegame_publisher.allow_replacement();
  level_savegame_player_load_generation=active.generation;
  error.clear();return true;
 }
 level_savegame_publisher.allow_replacement();
 std::vector<std::uint8_t> image;
 if(!level_savegame_publisher.read(filename,image,error))return false;
 if(!native_level_save_apply_player_image_v1(active,image,false,error))return false;
 level_savegame_player_load_generation=active.generation;
 error.clear();return true;
}
bool native_level_save_load_checkpoint_v1(std::string& error) {
 const auto active=source_level_owner.snapshot();
 if(active.phase!=dh2::source_level_owner_v1::Phase::active||
    !active.source_level||active.source_level_state!=38||
    active.checkpoint_load_in_progress!=1||
    !active.source_level_savegame||active.source_save_slot<0||
    !active_crypt_room_runtime||!active_crypt_room_runtime->character_factory||
    native_host.online||active.difficulty<0||active.difficulty>2){
  error="LevelSavegame checkpoint restore requires the active offline Level state 38 and exact slot/difficulty owners";
  return false;
 }
 std::string filename;
 if(!dh2::level_savegame_owner_v1::format_checkpoint_filename(
       active.source_save_slot,active.difficulty,filename,error))return false;
 // Only Level::CheckpointSave writes this file. Before the first checkpoint,
 // LevelSavegame::LoadCheckPoint caches an absent file and INFO/OBJS restore
 // nothing; keep the live Level objects unchanged in that case.
 {
  std::error_code ec;
  if(!std::filesystem::exists(level_savegame_publisher.directory()/
       std::filesystem::u8path(filename),ec)){
   if(ec){error="LevelSavegame checkpoint presence check failed: "+ec.message();return false;}
   error.clear();return true;
  }
 }
 std::vector<std::uint8_t> image;
 if(!level_savegame_publisher.read_checkpoint(filename,image,error))return false;
 if(!source_level_owner.level_savegame().load_image(
       image.data(),image.size(),error))return false;
 return native_level_save_apply_player_image_v1(active,image,true,error);
}
bool native_player_save_load_checkpoint_v1(std::string& error) {
 const auto active=source_level_owner.snapshot();
 if(active.phase!=dh2::source_level_owner_v1::Phase::active||
    active.source_level_state!=38||active.checkpoint_load_in_progress!=1||
    !active.canonical_player_savegame||
    !active.player_character||active.player_character!=prince_character.identity()||
    !prince_combat.savegame||!prince_combat.save_transport||
    active.canonical_player_savegame!=reinterpret_cast<std::uintptr_t>(prince_combat.savegame.get())||
    active.source_save_slot<0||prince_combat.savegame->slot()!=active.source_save_slot||
    native_host.online){
  error="Player checkpoint QEST load requires the active offline Character/Save/profile owners";
  return false;
 }
 std::string filename;
 try{filename=dh2::data::player_profile_filename_v1(
       static_cast<std::uint32_t>(active.source_save_slot),true,false);}
 catch(...){error="Player checkpoint filename formatting failed";return false;}
 {
  // As above: no Player checkpoint yet means Character::SG_LoadCheckpoint
  // has no cached QEST chunk to apply.
  std::error_code ec;
  if(!std::filesystem::exists(level_savegame_publisher.directory()/
       std::filesystem::u8path(filename),ec)){
   if(ec){error="Player checkpoint presence check failed: "+ec.message();return false;}
   error.clear();return true;
  }
 }
 std::vector<std::uint8_t> image;
 if(!level_savegame_publisher.read_player_checkpoint(filename,image,error))return false;
 return prince_combat.save_transport->load_checkpoint_quests(image,error);
}
bool native_player_character_sg_update_checkpoint_v1(
    std::uint32_t expected_generation,std::string& error);
bool native_source_level_reinit_game_events_v1(
    std::uint32_t expected_generation,std::string& error);
bool native_source_level_load_checkpoint_v1(
    std::uint32_t expected_generation,std::string& error) {
 const auto before=source_level_owner.snapshot();
 if(before.phase!=dh2::source_level_owner_v1::Phase::active||
    before.source_level_state!=38||!before.source_level||
    before.generation!=expected_generation||native_host.online||
    before.quest_owner!=prince_combat.quests.get()||!prince_combat.quests){
  error="Level::LoadCheckpoint requires the same active offline Level generation and canonical Save/QEST owner";
  return false;
 }
 if(!source_level_owner.begin_checkpoint_load(before.source_level)){
  error="Level::LoadCheckpoint +0xf4 gate rejected a stale, reentrant, or non-loaded Level";
  return false;
 }
 // Level::LoadCheckpoint owns +0xf4 around the whole nested sequence. Clear
 // it even when a source prefix fails; earlier source mutations are retained.
 bool succeeded=false;
 std::string failure;
 do {
  if(!native_level_save_load_checkpoint_v1(failure))break;
  // The port binds the Level GameEventManager/Objective owners only for SWAMP
  // (its per-frame GameEventManager::Update has the same gate).
  if(active_level_assets.name=="SWAMP"&&
     !native_source_level_reinit_game_events_v1(expected_generation,failure))break;
  if(!native_player_save_load_checkpoint_v1(failure))break;
  if(!native_player_character_sg_update_checkpoint_v1(
        expected_generation,failure))break;
  succeeded=true;
 } while(false);
 if(!source_level_owner.finish_checkpoint_load(before.source_level)){
  error="Level::LoadCheckpoint could not clear the same Level +0xf4 gate after its source prefix";
  if(!failure.empty())error+=" | "+failure;
  return false;
 }
 const auto after=source_level_owner.snapshot();
 if(after.source_level!=before.source_level||after.generation!=expected_generation||
    after.checkpoint_load_in_progress){
  error="Level::LoadCheckpoint owner changed while clearing the +0xf4 gate";
  return false;
 }
 if(!succeeded){
  error=failure.empty()?"Level::LoadCheckpoint stopped before Character::SG_Update(true)":failure;
  return false;
 }
 error.clear();
 return true;
}
bool native_level_save_objects_all_v1(void* raw,std::uintptr_t savegame,
        std::string& error) {
 auto* facts=static_cast<NativeLevelSaveObjectFactsContextV1*>(raw);
 const auto active=source_level_owner.snapshot();
 if(!facts||active.phase!=dh2::source_level_owner_v1::Phase::active||
    active.generation!=facts->level_generation||
    savegame!=active.source_level_savegame||!active_crypt_room_runtime||
    !active_crypt_room_runtime->character_factory){
  error="LevelSavegame SaveAll crossed the active Level/ObjectManager/factory owners";
  return true;
 }
 if(level_savegame_publisher.replacement_protected()){
  // The loaded image holds saved rows that this port could not re-apply
  // (LevelSavegame::__LoadObjects 0x461e90 would have Deserialize'd every
  // resolvable row), so a live-only Save would erase them. Keep the previous
  // image and let the level change continue, exactly like a blocked Save.
  __android_log_print(ANDROID_LOG_INFO,"DH2Native",
      "LevelSavegame::Save kept the previous image | saved rows were not all re-applied on load | Level generation %u | filename %s",
      facts->level_generation,source_level_owner.level_savegame().filename().c_str());
  error.clear();return false;
 }
 auto player=native_player_character_save_services();
 NativeLevelSaveIdentityContextV1 identity_context{facts,player};
 const dh2::character_level_save_serialize_v1::Services identity_services{
     &identity_context,&native_level_save_read_identity_view_v1,
     &native_level_save_read_identity_game_object_v1};
 const dh2::character_level_save_serialize_v1::CanonicalServices
     factory_character_services{facts,
         &native_level_save_read_factory_character_view_v1,
         &native_level_save_read_factory_game_object_fields_v1,
         &native_level_save_read_factory_group_info_v1};
 const dh2::level_savegame_object_manager_v1::FactsServices source_facts{
     facts,&native_level_save_read_object_facts_v1,
     &native_level_save_serialize_noncharacter_v1,
     &factory_character_services,
     &identity_services,&native_level_save_is_canonical_character_v1,
     &native_level_save_is_canonical_player_v1};
 const auto publisher=level_savegame_publisher.services();
 dh2::level_savegame_object_manager_v1::Result result{};
 const auto status=dh2::level_savegame_object_manager_v1::save_all(
     source_level_owner.level_savegame(),source_level_owner.object_manager(),
     *active_crypt_room_runtime->character_factory,native_host.online,
     &source_facts,&publisher,&result,error);
 if(status!=dh2::level_savegame_object_manager_v1::Status::saved){
  if(error.empty())error="source LevelSavegame INFO/OBJS publication failed";
  return true;
 }
 __android_log_print(ANDROID_LOG_INFO,"DH2Native",
     "Source LevelSavegame published | Level generation %u | manager rows %u | Characters %u | saved rows %u | bytes %u | filename %s",
     facts->level_generation,result.manager_rows,result.character_rows,
     result.save.saved_objects,result.save.bytes,
     source_level_owner.level_savegame().filename().c_str());
 error.clear();return false;
}
std::int32_t native_level_save_objects_all_service_v1(void* raw,
        std::uintptr_t savegame,std::string& error) {
 return native_level_save_objects_all_v1(raw,savegame,error)?1:0;
}
bool native_level_save_active_v1(std::uintptr_t savegame,std::string& error) {
 const auto active=source_level_owner.snapshot();
 if(active.phase!=dh2::source_level_owner_v1::Phase::active||
    !active.source_level||!active.source_level_savegame||
    active.source_level_savegame!=savegame||native_host.online){
  error="LevelSavegame publication currently requires its active offline source owner";
  return false;
 }
 NativeLevelSaveObjectFactsContextV1 facts{};
 facts.level_generation=active.generation;
 const dh2::level_savegame_save_v1::State state{
     active.source_level_savegame,source_level_owner.level_savegame().gate_39(),
     native_host.online,0,0};
 const dh2::level_savegame_save_v1::Services services{
     &facts,&native_level_save_objects_all_service_v1};
 dh2::level_savegame_save_v1::Result result{};
 const auto status=source_level_owner.save_level(&state,&services,&result,error);
 if(status==dh2::level_savegame_save_v1::Status::saved)return true;
 if(status==dh2::level_savegame_save_v1::Status::skipped&&error.empty()){
  // LevelSavegame::Save 0x4615ec is a void call: it returns without calling
  // Savegame::saveAll when +4 is null, the SG block byte +0x39 is set
  // (Level::SG_BlockLevel(true), raised by Script_BlockSaveGame 0x45c8c0 and
  // lifted by Script_SaveGame) or the online non-host gate applies. Its only
  // caller Level::QuickSave 0x3f059c (reached from Level::Unload 0x3f0690 and
  // NativeGoToZone 0x4422b8) discards the result, so a blocked Save is a silent
  // no-op that leaves the previous image untouched and lets the level change
  // continue. Only +0x39 is reachable here: +4 and the offline gate were
  // checked above.
  __android_log_print(ANDROID_LOG_INFO,"DH2Native",
      "LevelSavegame::Save skipped by the source SG block byte | +0x39 %u | Level generation %u | previous image kept",
      unsigned(state.gate_39),facts.level_generation);
  error.clear();return true;
 }
 if(error.empty())error="source LevelSavegame::Save did not publish | status "+
     std::to_string(unsigned(status))+" | +0x39 "+std::to_string(unsigned(state.gate_39))+
     " | service calls "+std::to_string(result.service_calls);
 return false;
}
