 std::size_t roster_count=0;
 if(!native_characters.contains_identity(actor.identity,&roster_count)||roster_count!=1)
  return fail("Character::InitPost direct actor is not the unique CharacterList owner");
 const auto source=std::find_if(active_level_assets.source_character_census.begin(),
     active_level_assets.source_character_census.end(),[&](const auto& candidate) {
      return candidate.module_index==actor.source_module_index&&
          candidate.source_record==actor.source_record&&
          candidate.source_handle==actor.source_handle;
     });
 if(source==active_level_assets.source_character_census.end()||
    source->duplicate_name)
  return fail("Character::InitPost direct actor census/Character tuple differs");
 if(!census_character_matches_actor(*source,actor))
  return fail("Character::InitPost direct actor census/Character tuple differs");
