namespace {
struct DirectCharacterInitFinalContextV1 {
 NativeCryptRoomRuntime* runtime{};
 ObjectActor* actor{};
 std::array<float,3> target_position{};
 std::string provider_error;
};

int direct_character_init_final_invoke_v1(void* raw,
    dh2::character_init_final_v1::State& state,
    const dh2::character_init_final_v1::Request& request,
    dh2::character_init_final_v1::Reply& reply,std::string& error) {
 using namespace dh2::character_init_final_v1;
 auto* context=static_cast<DirectCharacterInitFinalContextV1*>(raw);
 auto* runtime=context?context->runtime:nullptr;
 auto* actor=context?context->actor:nullptr;
 // Character::InitFinal's follow block queries the local Player Character
 // (look vector, target position); every other call names this actor.
 const bool player_query=request.operation==Operation::look_at_vector||
     request.operation==Operation::target_position;
 if(!runtime||!actor||state.character!=actor->identity||
    (!player_query&&request.subject!=actor->identity)||actor->kind!=1||
    !actor->source_character_construction||!actor->spawn_owner||
    !actor->native_ai||actor->native_ai->character_identity!=actor->identity||
    actor->native_ai->state.owner_04!=actor->identity||
    actor->spawn_owner->actor!=actor||
    actor->spawn_owner->character.owner()!=actor->identity) {
  error="Direct Character::InitFinal lost its same-identity Character, Coordinator, or CharAI owner";
  return 1;
 }
 auto* row=runtime->manager.find_by_identity(actor->identity);
 if(!row||runtime->manager.find_by_source_handle(actor->source_handle)!=row||
    row->source_handle!=actor->source_handle||
    row->source_module_index!=actor->source_module_index||
    row->source_record!=actor->source_record||
    !row->object_init_post_ready) {
  error="Direct Character::InitFinal lacks the exact completed ObjectManager InitPost row";
  return 1;
 }
 reply={};
 switch(request.operation) {
  case Operation::spawn_probability:
   if(row->spawn_probability_result_270<0||
      row->spawn_probability_result_270>=99||
      row->spawn_probability_274<0||row->spawn_probability_274>100) {
    error="Direct Character::InitFinal source probability cache is invalid";
    return 1;
   }
   reply.word=row->spawn_probability_result_270;
   return 0;
  case Operation::base_init_final: {
   if(row->deleted_81||row->deleted_state_82||
      row->spawn_probability_result_270>=row->spawn_probability_274) {
    error="Direct Character::InitFinal reached an inconsistent GameObject base gate";
    return 1;
   }
   // The source ObjectBase constructor leaves this optional InitFinal
   // SetEnabled gate clear for these imported Characters. Do not reinterpret
   // it as visibility or silently skip a reached enable operation.
   if(row->init_final_enable_2ed) {
    error="Direct GameObject::InitFinal SetEnabled branch has no bound source service";
    return 1;
   }
   auto& owner=*actor->spawn_owner;
   // Gated (Limbus) Characters create their body at SpawnCharacter; only a
   // Character whose state already owns a body must present it here.
   if(!owner.runtime_ready||
      (owner.character.state.body_present&&!owner.body.body)||
      (owner.pf_object_ready&&owner.runtime.object.user!=actor->identity)||
      !runtime->level.native_floor) {
    error="Direct GameObject::InitFinal lost its same-Character PF/body owner";
    return 1;
   }
   if(!owner.pf_object_ready) {
    if(dh2_nav_object_defaults(&owner.runtime.object)) {
     error="Direct GameObject::InitFinal PFObject defaults rejected";
     return 1;
    }
    const dh2::navigation::ObjectInitRequest init{
     &runtime->level.native_floor->collision_world,&owner.runtime.object,
     actor->identity,
     {actor->position[0],actor->position[1],actor->position[2]},
     owner.config.radius*100.f,0,0};
    if(dh2_nav_init_object(&init)) {
     error="Direct GameObject::InitFinal PFWorld::InitObject failed";
     return 1;
    }
    owner.pf_object_ready=true;
   }
   row->init_final_name_254=row->name;
   if(row->visual_object_2d8) {
    if(row->visual_object_2d8!=actor->visual_object_2d8||
       actor->visual_object_2d8!=actor->identity||
       !owner.visual.update_world(owner.scene,error)) {
     if(error.empty())error="Direct VisualObject::Sync failed on its same-actor scene";
     return 1;
    }
    row->target_node_180=0;
    for(const auto& node:owner.scene.graph) {
     if(node.name=="target_node") {
      row->target_node_180=reinterpret_cast<std::uintptr_t>(&node);
      break;
     }
    }
   }
   // This is the already initialized PFObject owned by this SpawnOwner.
   // Refresh its same-identity registration; never construct a parallel PF
   // object during the later source final phase.
   try { owner.register_runtime_object(); }
   catch(const std::exception& failure) {
    error=std::string("Direct GameObject::UpdatePFObject failed: ")+failure.what();
    return 1;
   }
   return 0;
  }
  case Operation::is_faerie:
  case Operation::is_follower:
  case Operation::is_player: {
   const auto query=request.operation==Operation::is_faerie
       ?dh2::character_ai_classification::Query::faerie
       :request.operation==Operation::is_follower
          ?dh2::character_ai_classification::Query::follower
          :dh2::character_ai_classification::Query::player;
   const auto value=native_character_classification(*actor,query);
   if(value>1) {
    error="Direct Character::InitFinal source AI classification is unavailable";
    return 1;
   }
   reply.word=static_cast<std::int32_t>(value);
   return 0;
  }
  // IDA Character::InitFinal: IsFaerie||IsFollower places the Character at
  // local Player target position + look vector; no local Player is a no-op.
  case Operation::local_player: {
   dh2::character_faery_placement_v1::Reply player{};
   const dh2::character_faery_placement_v1::Request query{
       dh2::character_faery_placement_v1::Operation::local_player,
       actor->identity,0,request.argument0,nullptr,
       static_cast<std::int32_t>(request.argument1)};
   if(native_faery_placement_service(nullptr,query,&player)!=0||!player.identity) {
    reply.character_660=0;return 0;
   }
   dh2::character_faery_placement_v1::Reply character{};
   const dh2::character_faery_placement_v1::Request resolve{
       dh2::character_faery_placement_v1::Operation::player_character,
       player.identity,0,0,nullptr,0};
   if(native_faery_placement_service(nullptr,resolve,&character)!=0) {
    error="Direct Character::InitFinal Player Character resolution failed";return 1;
   }
   reply.character_660=character.identity;return 0;
  }
  case Operation::look_at_vector: {
   dh2::character_faery_placement_v1::Reply placement{};
   const dh2::character_faery_placement_v1::Request query{
       dh2::character_faery_placement_v1::Operation::look_at_vector,
       request.subject,0,0,nullptr,0};
   if(native_faery_placement_service(nullptr,query,&placement)!=0) {
    error="Direct Character::InitFinal Player look-vector provider failed";return 1;
   }
   std::copy_n(&placement.vector.x,3,reply.vector);return 0;
  }
  case Operation::target_position: {
   dh2::character_faery_placement_v1::Reply placement{};
   const dh2::character_faery_placement_v1::Request query{
       dh2::character_faery_placement_v1::Operation::target_position,
       request.subject,0,0,nullptr,0};
   if(native_faery_placement_service(nullptr,query,&placement)!=0) {
    error="Direct Character::InitFinal Player target-position provider failed";return 1;
   }
   context->target_position={placement.vector.x,placement.vector.y,
                             placement.vector.z};
   reply.target=context->target_position.data();
   return 0;
  }
  case Operation::set_position:
   if(!request.vector||!move_direct_actor_v1(*actor,request.vector)) {
    error="Direct Character::InitFinal GameObject SetPosition failed";return 1;
   }
   return 0;
  case Operation::light_set: {
   if(!request.name||actor->visual_object_2d8!=actor->identity||
      row->visual_object_2d8!=actor->visual_object_2d8) {
    error="Direct Character::InitFinal LightSet lost its same-actor VisualObject token";
    return 1;
   }
   actor->source_light_set_id_40=
       dh2::game_object_init_final_v1::light_set_id_from_name(request.name);
   reply.word=actor->source_light_set_id_40;
   return 0;
  }
  case Operation::char_ai_init_final: {
   auto& ai=*actor->native_ai;
   if(!ai.state.active_ais_1c)return 0;
   return native_char_ai_on_init_final(ai,*actor,error)?0:1;
  }
  case Operation::is_local_player:
   reply.word=0;
   return 0;
  case Operation::update_all_skills:
  case Operation::recalculate:
  case Operation::property_int:
  case Operation::save:
   error="Nonplayer direct Character::InitFinal reached a Player-only operation";
   return 1;
 }
 error="Unsupported direct Character::InitFinal operation";
 return 1;
}
} // namespace

bool run_direct_source_character_init_final_v1(
        NativeCryptRoomRuntime& runtime,ObjectActor& actor,std::string& error) {
 error.clear();
 if(actor.source_init_final_complete)return true;
 const auto source=std::find_if(active_level_assets.source_character_census.begin(),
     active_level_assets.source_character_census.end(),[&](const auto& row){
      return row.module_index==actor.source_module_index&&
          row.source_record==actor.source_record&&
          row.source_handle==actor.source_handle;
     });
 if(source==active_level_assets.source_character_census.end()||
    source->duplicate_name||!census_character_matches_actor(*source,actor)||
    actor.kind!=1||!actor.identity||!actor.source_character_construction||
    runtime.actors.find(actor.identity)==runtime.actors.end()||
    runtime.actors.at(actor.identity)!=&actor) {
  error="Direct Character::InitFinal has no exact retained census and actor identity";
  return false;
 }
 auto* row=runtime.manager.find_by_identity(actor.identity);
 if(!row||runtime.manager.find_by_source_handle(actor.source_handle)!=row||
    row->source_handle!=actor.source_handle||
    row->source_module_index!=actor.source_module_index||
    row->source_record!=actor.source_record||
    !row->object_init_post_ready||!actor.source_init_post_terminal_1394) {
  error="Direct Character::InitFinal did not follow its same-row accepted InitPost";
  return false;
 }
 std::size_t roster_count=0;
 if(!native_characters.contains_identity(actor.identity,&roster_count)||
    roster_count!=1) {
  error="Direct Character::InitFinal lost its unique canonical CharacterList entry";
  return false;
 }
 const auto* construction=actor.source_character_construction.get();
 if(!construction||construction->source.identity!=actor.identity||
    !construction->source.source_component_adoption_complete||
    !construction->source.constructor_save_vectors_ready||
    !actor.spawn_owner||actor.spawn_owner->actor!=&actor||
    !actor.spawn_owner->character.bound()||
    !actor.native_ai||actor.native_ai->state.owner_04!=actor.identity) {
  error="Direct Character::InitFinal lost its completed same-owner construction/adoption";
  return false;
 }
 dh2::character_init_final_v1::Visual visual{
     actor.visual_object_2d8?actor.visual_object_2d8:actor.identity,
     actor.source_light_set_id_40};
 dh2::character_init_final_v1::State state{};
 state.character=actor.identity;
 state.initialized_1395=actor.source_init_final_latch_1395;
 state.spawn_probability_274=row->spawn_probability_274;
 state.visual_2d8=row->visual_object_2d8?&visual:nullptr;
 DirectCharacterInitFinalContextV1 context{&runtime,&actor,{},{}};
 const dh2::character_init_final_v1::Services services{
     &context,&direct_character_init_final_invoke_v1};
 dh2::character_init_final_v1::Runtime init_final(&state,services);
 dh2::character_init_final_v1::Result result{};
 const auto status=init_final.initialize(&result,error);
 actor.source_init_final_latch_1395=state.initialized_1395;
 actor.source_light_set_id_40=visual.light_set_40;
 if(status!=dh2::character_init_final_v1::Status::complete||
    (result.decision!=dh2::character_init_final_v1::Decision::initialized&&
     result.decision!=dh2::character_init_final_v1::Decision::probability_rejected&&
     result.decision!=dh2::character_init_final_v1::Decision::already_initialized)) {
  if(error.empty())error="Direct Character::InitFinal source lifecycle failed";
  return false;
 }
 if(state.initialized_1395)actor.source_init_final_complete=1;
 return actor.source_init_final_complete!=0;
}

bool native_level_save_direct_actor_v1(
        NativeLevelSaveObjectFactsContextV1& context,std::uintptr_t identity,
        ObjectActor*& actor,dh2::object_manager_runtime_owner_v1::GameObject*& row,
        std::string& error) {
 const auto active=source_level_owner.snapshot();
 auto* manager=&source_level_owner.object_manager();
 actor=native_char_ai_actor(identity);
 if(active.phase!=dh2::source_level_owner_v1::Phase::active||
    !active.source_level||active.player_character!=prince_character.identity()||
    active.generation!=context.level_generation||
    active.object_manager_identity!=reinterpret_cast<std::uintptr_t>(manager)||
    !actor||actor->kind!=1||actor->identity!=identity||
    actor->source_handle<0||actor->source_module_index==
      std::numeric_limits<std::uint32_t>::max()||actor->source_record==
      std::numeric_limits<std::uint32_t>::max()) {
  error="LevelSavegame direct Character is outside the active retained actor identity";
  return false;
 }
 row=manager->find_by_source_handle(actor->source_handle);
 const auto* construction=actor->source_character_construction.get();
 if(actor->name.empty()||!row||(!row->name.empty()&&row->name!=actor->name)||
    row->identity!=identity||row->source_handle!=actor->source_handle||
    !row->source_provenance_ready||row->source_module_index!=actor->source_module_index||
    row->source_record!=actor->source_record||
    manager->find_by_identity(identity)!=row||
    row->live_fields.visible_80!=&actor->visible_80||
    row->live_fields.save_eligibility_28!=&actor->source_save_eligibility_28||
    row->live_fields.deleted_81!=&actor->source_deleted_81||
    row->live_fields.module_id_64!=&actor->source_object_module_id||
    !construction||construction->source.identity!=identity||
    !construction->source.source_component_adoption_complete||
    !construction->source.constructor_save_vectors_ready||
    actor->source_save_eligibility_28!=1||!row->save_facts_ready||
    !actor->spawn_owner||actor->spawn_owner->actor!=actor||
    actor->spawn_owner->character.owner()!=identity||
    !actor->spawn_owner->character.bound()||
    !actor->spawn_owner->character.source_state_handlers_complete()||
    !actor->native_ai||actor->native_ai->character_identity!=identity||
    actor->native_ai->state.owner_04!=identity||
    !actor->native_ai->ai_identity) {
  error="LevelSavegame direct Character lacks matching manager, component-adoption, FSM, or CharAI owners";
  return false;
 }
 std::size_t occurrences=0;
 if(!native_characters.contains_identity(identity,&occurrences)||occurrences!=1) {
  error="LevelSavegame direct Character lacks its unique canonical CharacterList row";
  return false;
 }
 std::uint32_t type=0;
 if(!native_character_classification_for_identity(identity,
       dh2::character_ai_classification::Query::type,type)||type==1) {
  error="LevelSavegame direct Character has no verified non-Player CharType";
  return false;
 }
 std::uint8_t gate=0,deleted=0;
 if(!row->read_save_base_facts(&gate,&deleted)||gate!=1||
    deleted!=actor->source_deleted_81||actor->visible_80>1||
    actor->combat_state.dead>1||
    actor->spawn_owner->character.state.current<0||
    actor->spawn_owner->character.state.current>=20) {
  error="LevelSavegame direct Character source save fields or state are invalid";
  return false;
 }
 for(unsigned axis=0;axis<3;++axis) {
  if(!std::isfinite(actor->position[axis])||
     !std::isfinite(actor->rotation_degrees[axis])) {
   error="LevelSavegame direct Character transform contains a non-finite source value";
   return false;
  }
 }
 return true;
}

bool native_level_save_read_direct_character_view_v1(void* raw,
        std::uintptr_t identity,dh2::character_level_save_serialize_v1::View* output,
        std::string& error) {
 using namespace dh2::character_level_save_serialize_v1;
 if(!raw||!output||!identity) {
  error="Direct Character serializer requires its active context and identity";
  return true;
 }
 auto& context=*static_cast<NativeLevelSaveObjectFactsContextV1*>(raw);
 ObjectActor* actor=nullptr;
 dh2::object_manager_runtime_owner_v1::GameObject* row=nullptr;
 if(!native_level_save_direct_actor_v1(context,identity,actor,row,error))return true;
 if(!actor->native_ai||actor->native_ai->character_identity!=identity||
    actor->native_ai->state.owner_04!=identity) {
  error="Direct Character serializer lost its canonical CharAI owner";return true;
 }
 auto& saved=context.direct_properties_saved;
 auto& resolved=context.direct_properties_resolved;
 // ARM32 CharacterProperties vtable RVA 0x96bbc0 is inert stream data here,
 // never a host pointer. No imported header is present in this MGP projection.
 constexpr std::array<std::uint8_t,4> legacy_header{0xc0,0xbb,0x96,0x00};
 std::copy(legacy_header.begin(),legacy_header.end(),saved.begin());
 std::copy(legacy_header.begin(),legacy_header.end(),resolved.begin());
 static_assert(sizeof(actor->properties.saved)==896);
 static_assert(sizeof(actor->properties.resolved)==896);
 std::memcpy(saved.data()+legacy_header.size(),actor->properties.saved.data(),
             sizeof(actor->properties.saved));
 std::memcpy(resolved.data()+legacy_header.size(),actor->properties.resolved.data(),
             sizeof(actor->properties.resolved));

 View view{};
 view.state_machine_state=static_cast<std::uint32_t>(
     actor->spawn_owner->character.state.current);
 view.is_player=0;
 view.properties_primary={saved.data(),saved.size()};
 view.properties_secondary={resolved.data(),resolved.size()};
 view.position={reinterpret_cast<const std::uint8_t*>(actor->position.data()),
                sizeof(actor->position)};
 view.rotation={reinterpret_cast<const std::uint8_t*>(actor->rotation_degrees.data()),
                sizeof(actor->rotation_degrees)};
 view.dead=static_cast<std::uint8_t>(actor->combat_state.dead);
 const auto* vectors=&actor->source_character_construction->source;
 view.vector_1306={reinterpret_cast<const std::uint8_t*>(
      vectors->quick_save_position_1468.data()),sizeof(vectors->quick_save_position_1468)};
 view.vector_1309={reinterpret_cast<const std::uint8_t*>(
      vectors->revive_position_1474.data()),sizeof(vectors->revive_position_1474)};
 const auto group_identity=actor->native_ai->state.group_info_identity;
 if(group_identity) {
  dh2::character_group_info_owner_v1::Tail tail{};
  if(!source_char_ai.groups.owns(group_identity)||
     !source_char_ai.groups.read_tail(group_identity,&tail)) {
   error="Direct Character has a non-null GroupInfo link without its canonical pointee owner";
   return true;
  }
  view.has_group_info=1;view.group_word_36=tail.word_36;
  view.group_flag_40=tail.flag_40;view.group_flag_41=tail.flag_41;
 }
 *output=view;
 error.clear();return false;
}

bool native_level_save_read_direct_game_object_fields_v1(void* raw,
        std::uintptr_t identity,dh2::level_savegame_owner_v1::GameObjectFields* output,
        std::string& error) {
 if(!raw||!output||!identity) {
  error="Direct GameObject serializer requires its active context and identity";
  return true;
 }
 auto& context=*static_cast<NativeLevelSaveObjectFactsContextV1*>(raw);
 ObjectActor* actor=nullptr;
 dh2::object_manager_runtime_owner_v1::GameObject* row=nullptr;
 if(!native_level_save_direct_actor_v1(context,identity,actor,row,error))return true;
 // GameObject::Serialize writes ObjectBase +0x80/+0x8a then +0x270.
 // +0x80 is this actor's live visibility byte; the source search projection
 // aliases +0x8a to SpawnOwner::source_enabled, which conditions update.
 // +0x270 is the ObjectManager row's canonical CheckSpawnProbability cache.
 *output={actor->visible_80,
          std::uint8_t(actor->spawn_owner->source_enabled),
          row->spawn_probability_result_270};
 error.clear();return false;
}

bool NativeCharacterInventoryOwnerV1::initialize_source_monster(
        ObjectActor& owner,std::string& error){
 if(inventory||source_init_equipment_attempted){
  error="Monster Character::_InitEquipment cannot create or roll a second inventory";return false;
 }
 source_init_equipment_attempted=true;
 const auto* ai=native_actor_ai_props(owner);
 const auto active=source_level_owner.snapshot();
 if(owner.kind!=1||!owner.identity||owner.identity==prince_character.identity()||
    !native_ai_monster_script(ai)||!owner.spawn_owner||!owner.native_ai||
    owner.spawn_owner->actor!=&owner||owner.spawn_owner->character.owner()!=owner.identity||
    owner.native_ai->character_identity!=owner.identity||native_host.online||
    active.phase!=dh2::source_level_owner_v1::Phase::active||
    active.renderer_projection!=&level||!prince_combat.inventory_loot_tables||
    !prince_combat.loot_power_creation||!prince_combat.item_power_tables||
    !prince_combat.item_presentation||!prince_combat.item_text.invoke||
    !prince_combat.item_text.metadata||native_save_difficulty<0||native_save_difficulty>2){
  error="Monster _InitEquipment requires its active canonical Character/Level and shared offline item owners";return false;
 }
 if(owner.source_character_construction){
  auto& adoption=*owner.source_character_construction;
  if(adoption.source.identity!=owner.identity||
     !adoption.source.source_component_adoption_complete||
     !adoption.inventory.constructed||adoption.inventory.character!=owner.identity){
   error="Monster V4 inventory cannot bind an incomplete or foreign Character constructor projection";return false;
  }
  constructor_inventory_projection=&adoption.inventory;
 }else if(static_mlx_level_active()){
  // Script Summon uses the canonical Character factory, whose constructor
  // owns this exact ItemInventory projection on its Record rather than the
  // static-MGP adoption facade above.
  auto* runtime=active_crypt_room_runtime.get();
  auto* summon=runtime&&owner.identity?
      script_summon_owner(*runtime,owner.identity):nullptr;
  auto* record=summon?summon->record:nullptr;
  const auto* inventory_component=record?
      record->components.find(dh2::character_constructor_owner_v1::Component::inventory):nullptr;
  if(!summon||summon->actor!=&owner||!record||
     record->character.identity!=owner.identity||
     !record->constructor.constructor_complete||
     !record->source_inventory.constructed||
     record->source_inventory.character!=owner.identity||
     inventory_component!=&record->source_inventory){
   error="SWAMP Monster V4 inventory has no completed same-identity factory ItemInventory constructor";return false;
  }
  constructor_inventory_projection=&record->source_inventory;
 }
 const auto property_bits=static_cast<std::uint32_t>(owner.properties.resolved[194]);
 const auto capacity_bits=(property_bits>>8)|((property_bits&0x80000000u)?0xff000000u:0u);
 std::int32_t potion_capacity=0;std::memcpy(&potion_capacity,&capacity_bits,sizeof(potion_capacity));
 if(potion_capacity<0)potion_capacity=0;
 inventory=std::make_unique<dh2::data::FreshInventoryOwnedV4>(
     owner.identity,prince_combat.inventory_loot_tables->borrow(),
     dh2::random_lifecycle::inventory_random_service(),
     static_cast<std::int8_t>(static_cast<std::uint8_t>(potion_capacity)),owner.properties);
 actor=&owner;
 adapter={prince_combat.item_text,prince_combat.item_presentation.get(),inventory.get()};
 services=adapter.inventory_services();
 property_view=dh2::data::property_view(actor_property_rules,owner.properties);
 const dh2::player_initial_equipment_v1::Bindings bindings{
     owner.identity,inventory.get(),&property_view,&services,
     {this,source_initial_equipment}};
 try{
  dh2::player_initial_equipment_v1::Runtime runtime(bindings);
  dh2::player_initial_equipment_v1::Result result{};
  if(runtime.initialize(&result,error)!=dh2::player_initial_equipment_v1::Status::complete){
   if(error.empty())error="Monster Character::_InitEquipment continuation failed";
   return false;
  }
  source_init_equipment_complete=true;
  __android_log_print(ANDROID_LOG_INFO,"DH2Native",
     "Source Monster Character::_InitEquipment | %s | Character %llx | decision %u | loot %d | items %u | auto-equip %u | canonical actor V4",
     owner.name.c_str(),static_cast<unsigned long long>(owner.identity),
     unsigned(result.decision),result.loot,result.captured_items,result.auto_equip_calls);
 }catch(const std::exception& exception){error=exception.what();return false;}
 error.clear();return true;
}
