 bool resume_init_timers(std::string& error) noexcept {
  error.clear();
  if(!initialized||!owner||!ai||!level_context_current()||
     owner->character.owner()!=ai->character_identity||
     ai->state.owner_04!=ai->character_identity||
     lifecycle.owner!=ai->character_identity||
     lifecycle.timer33<0||lifecycle.timer34<0||
     ai->state.word_10!=std::uint32_t(lifecycle.timer33)||
     ai->state.word_14!=std::uint32_t(lifecycle.timer34)) {
   error="Source AI/DoT timer resume lost its same-Character pending Level owner";
   return false;
  }
  auto& timers=owner->character.timers();
  const auto valid=[&](std::int32_t id,std::int32_t event) {
   return id>=0&&std::uint32_t(id)<timers.count&&timers.slots&&
       timers.slots[id].id==std::uint32_t(id)&&timers.slots[id].active&&
       timers.slots[id].event==event;
  };
  if(!valid(lifecycle.timer33,0x33)||!valid(lifecycle.timer34,0x34)) {
   error="Source AI/DoT timer IDs no longer name their original event slots";
   return false;
  }
  const bool paused33=timers.slots[lifecycle.timer33].paused!=0;
  const bool paused34=timers.slots[lifecycle.timer34].paused!=0;
  if(!timer_gates) {
   if(paused33||paused34) {
    error="Resumed source AI/DoT timer became paused before reuse";
    return false;
   }
   return true;
  }
  if(timer_gates!=2||!paused33||!paused34) {
   error="Source AI/DoT timer gate receipt is partial or inconsistent";
   return false;
  }
  if(owner->character.pause_timer(std::uint32_t(lifecycle.timer33),0)!=1) {
   error="Source AI_Tick timer resume failed";return false;
  }
  timer_gates=1;
  if(owner->character.pause_timer(std::uint32_t(lifecycle.timer34),0)!=1) {
   error="Source DoT_Tick timer resume failed after AI_Tick prefix";return false;
  }
  timer_gates=0;
  if(timers.slots[lifecycle.timer33].paused||timers.slots[lifecycle.timer34].paused) {
   error="Source AI/DoT timer resume did not publish both active timer flags";
   return false;
  }
  return true;
 }
 void retire_timers() noexcept {
  if(!owner||!ai)return;
  const auto retire=[&](std::int32_t& timer,std::uint32_t& source_field,unsigned event){
   if(timer<0)return;
   // CharAI::AI_SetDead (0x3d6cdc) stopped this timer and set the source
   // field to -1; the original keeps no second copy, so the projection is
   // simply stale and already retired.
   if(source_field==UINT32_MAX){timer=-1;return;}
   const auto id=timer;
   // CharAI+0x10/+0x14 and ScriptLifecycleState64 are two projections of
   // the same two source timer IDs, not independent timer stores. Refuse to
   // stop a recycled ID if either retained owner no longer agrees.
   const bool coherent=owner->character.owner()==ai->character_identity&&
       source_field==std::uint32_t(id);
   if(!coherent){
    __android_log_print(ANDROID_LOG_ERROR,"DH2Native","Native Ghost timer owner mismatch before VM close | event %x | slot %d | CharAI %u",
     event,id,source_field);
    return;
   }
   const auto status=owner->character.stop_timer(std::uint32_t(id));
   __android_log_print(ANDROID_LOG_INFO,"DH2Native","Native Ghost timer retired before VM close | event %x | slot %d | status %d",
    event,id,status);
   if(status>=0){timer=-1;source_field=UINT32_MAX;}
  };
  retire(lifecycle.timer33,ai->state.word_10,0x33);
  retire(lifecycle.timer34,ai->state.word_14,0x34);
 }
 bool unload_for_character_retirement(std::string& error) noexcept {
  try {
   if(!ai||!owner||!owner->actor||
      ai->character_identity!=owner->actor->identity||
      ai->state.owner_04!=owner->actor->identity||
      owner->character.owner()!=owner->actor->identity) {
    error="Monster AIS retirement lost its same-Character CharAI/Coordinator";
    return false;
   }
   if(!cleanup_complete&&skills.prepared()) {
    if(!vm.ready()) {
     error="Monster AIS has retained skill instances but no live source VM for cleanup";
     return false;
    }
    for(const auto list:{dh2::character_ai_set_skills_and_spells::List::skill,
                         dh2::character_ai_set_skills_and_spells::List::faery}) {
     dh2::native::ghost_skill_update_v1::CleanupResult result{};
     if(dh2::native::ghost_skill_update_v1::cleanup_list(
          vm,skills,ai->character_identity,list,result,error)!=0) {
      if(error.empty())error="Monster AIS source skill cleanup failed";
      return false;
     }
    }
   }
   cleanup_complete=true;
   retire_skill_machine();target_list.reset();pending_skill_commands.clear();
   if(!timers_retired) {
    const auto timer33=lifecycle.timer33,timer34=lifecycle.timer34;
    retire_timers();
    if(lifecycle.timer33!=-1||lifecycle.timer34!=-1||
       (timer33>=0&&ai->state.word_10!=UINT32_MAX)||
       (timer34>=0&&ai->state.word_14!=UINT32_MAX)) {
     error="Monster AIS timer IDs could not be retired from the same Character Coordinator";
     return false;
    }
    timers_retired=true;
   }
   if(!session_reset) {
    const auto status=vm.reset(error);
    if(status!=dh2::monster_external_script::Status::complete) {
     if(error.empty())error="Monster AIS source VM reset failed";
     return false;
    }
    session_reset=true;
   }
   ai->state.active_ais_1c=0;
   ai->state.alternate_ais_20=0;
   lifecycle.active=0;lifecycle.pending=0;
   ais.identity=0;
   initialized=false;
   error.clear();
   return true;
  } catch(const std::exception& exception) {
   error=std::string("Monster AIS retirement failed: ")+exception.what();
  } catch(...) {
   error="Monster AIS retirement failed with an unknown source-owner error";
  }
  return false;
 }
 ~NativeMonsterInitialization(){
  retire_skill_machine();
  // CharAI::AIUnLoadScriptProcess runs both list cleanup loops before timer
  // retirement, destroys the retained script instances, then tears down AIS.
  // Runtime member destruction releases those instances before vm is destroyed.
  if(!cleanup_complete&&ai&&ai->character_identity){
   const auto cleanup=[&](dh2::character_ai_set_skills_and_spells::List list,
                          const char* label){
    dh2::native::ghost_skill_update_v1::CleanupResult result{};
    std::string error;
    if(dh2::native::ghost_skill_update_v1::cleanup_list(
         vm,skills,ai->character_identity,list,result,error))
     __android_log_print(ANDROID_LOG_ERROR,"DH2Native",
       "Native Ghost %s failed before AIS unload | %s",label,
       error.empty()?"source cleanup provider failed":error.c_str());
   };
   cleanup(dh2::character_ai_set_skills_and_spells::List::skill,"_SkillCleanUp");
   cleanup(dh2::character_ai_set_skills_and_spells::List::faery,"_SpellCleanUp");
  }
  if(!timers_retired)retire_timers();
 }
