 static const dh2::world::SourceObjectCensusV1* range_source_object(
        const dh2::object_manager_runtime_owner_v1::GameObject& object,
        const RuntimeLevelAssets* source_assets=nullptr) {
  const auto& rows=source_assets?source_assets->source_object_census:
      active_level_assets.source_object_census;
  for(const auto& row:rows)
   if(row.module_index==object.source_module_index&&
      row.source_record==object.source_record&&
      row.source_handle==object.source_handle)
    return &row;
  return nullptr;
 }
 enum class RangeSourceGate : std::uint8_t {
  unsupported,not_zonable,zonable_noninteractive,zonable_source_state
 };
 static RangeSourceGate range_source_gate(
        const dh2::world::SourceObjectCensusV1* row) noexcept {
  if(!row)return RangeSourceGate::unsupported;
  const auto& type=row->gametype;
  // These exact ObjectFactory classes return false from virtual IsZonable;
  // the source search never reaches their interaction or position providers.
  if(type=="Dummy"||type=="Floor"||type=="Billboard"||type=="RoomZone"||
     type=="Projectile"||type=="SpawnPoint")return RangeSourceGate::not_zonable;
  // These exact constructors/vtables are noninteractive. Decor inherits the
  // GameObject ctor's +0x2ed=0; AnimatedDecor's IsZonable calls MeetCondition,
  // whose source implementation returns 1. Neither needs target position.
  if(type=="Decor"||type=="AnimatedDecor"||type=="QuestMoveInZone"||
     type=="SoundEmitter"||type=="Door"||type=="SpawnSpot"||
     type=="TriggerTrap"||type=="TimerTrap"||type=="ProjectileTrap"||
     type=="CheckpointZone"||type=="TriggerZone"||
     type=="TriggerZoneExitLevel")
   return RangeSourceGate::zonable_noninteractive;
  // These classes call GameObject::MeetCondition (true), then evaluate their
  // source-backed mutable fields in IsInteractive. Their owners publish those
  // fields onto this same ObjectManager row; absent facts are an error below.
  if(type=="Container"||type=="DestructibleContainer"||
     type=="OpenableContainer"||type=="SlotContainer"||
     type=="TriggerObject"||type=="LiftableObject")
   return RangeSourceGate::zonable_source_state;
  return RangeSourceGate::unsupported;
 }
 static bool range_source_interaction_type(
        NativeCryptRoomRuntime* runtime,
        const dh2::object_manager_runtime_owner_v1::GameObject& object,
        const dh2::world::SourceObjectCensusV1& row,
        std::uintptr_t interacting_object,std::int32_t& value) noexcept {
  using namespace dh2::object_manager_runtime_owner_v1;
  if(row.gametype=="DestructibleContainer") {value=8;return true;}
  if(row.gametype=="OpenableContainer"||row.gametype=="SlotContainer") {
   value=0;return true;
  }
  if(row.gametype=="Container") {value=-1;return true;}
  if(row.gametype=="TriggerObject") {
   if(!runtime)runtime=active_crypt_room_runtime.get();
   if(row.data_desc_pydata!="TriggerObjects"||!runtime||
      !runtime->trigger_interaction_tables)return false;
   std::int32_t data_id=-1;
   const auto* trigger=runtime->trigger_interaction_tables->find(
       row.data_desc,&data_id);
   if(!trigger||data_id<0)return false;
   value=trigger->interaction_type;
   return true;
  }
  // These concrete factories do not override GameObject::GetInteractionType;
  // IDA confirms the base implementation returns -1. Their IsZonable and
  // IsInteractive implementations are handled by the exact source gate above.
  if(row.gametype=="Decor"||row.gametype=="AnimatedDecor"||
     row.gametype=="QuestMoveInZone"||row.gametype=="SoundEmitter"||
     row.gametype=="Door"||row.gametype=="SpawnSpot"||
     row.gametype=="TriggerTrap"||row.gametype=="TimerTrap"||
     row.gametype=="ProjectileTrap"||row.gametype=="CheckpointZone"||
     row.gametype=="TriggerZone"||row.gametype=="TriggerZoneExitLevel") {
   value=-1;
   return true;
  }
  if(row.gametype=="LiftableObject") {
   if(!object.liftable_state_ready)return false;
   value=object.liftable_owner_390==0?4:
       object.liftable_owner_390==interacting_object?5:-1;
   return true;
  }
  // Other concrete source classes still require their own exact virtual.
  return false;
 }
 static std::int32_t range_interactive_query(void* raw,
        dh2::character_interactive::Character* character,
        dh2::character_interactive::Query query,std::uintptr_t subject,
        std::uintptr_t interacting_object,std::uint32_t* value) {
  auto* bridge=static_cast<AttackBridge*>(raw);
  if(!bridge||!bridge->init||!character||!value||
     !bridge->init->level_context_current()||
     character->identity!=bridge->range_character.identity||
     interacting_object!=bridge->init->actor().identity)return 1;
  ObjectActor* source=bridge->init->level_runtime?
      actor_in_level(*bridge->init->level_runtime,character->identity):nullptr;
  if(character->identity!=prince_character.identity()&&(!source||source->kind!=1))return 1;
  using Query=dh2::character_interactive::Query;
  if(query==Query::is_dead){
   if(subject!=character->identity)return 1;
   *value=character->identity==prince_character.identity()?
       prince_combat.life.dead:source->combat_state.dead;return 0;
  }
  if(query==Query::is_friend){
   if(subject!=character->ai)return 1;
   return source_relation_for_ooi(character->identity,interacting_object,
       dh2::character_ai_relations::Relation::friend_,*value)?0:1;
  }
  if(subject!=character->identity)return 1;
  const auto classification=query==Query::is_monster?
      dh2::character_ai_classification::Query::monster:
      query==Query::is_faerie?dh2::character_ai_classification::Query::faerie:
      dh2::character_ai_classification::Query::summoned;
  if(character->identity==prince_character.identity()){
   dh2::character_ai_classification::State state{character->identity,
       prince_combat.properties.resolved[1],prince_combat.properties.resolved[0],
       "PlayerCharacter_0",std::uint8_t(prince_combat.life.dead)};
   const dh2::character_ai_classification::Services services{nullptr,native_classification_service};
   dh2::character_ai_classification::Result result{};
   if(dh2::character_ai_classification::query(classification,&state,&services,&result)!=
       dh2::character_ai_classification::Status::complete)return 1;
   *value=result.word;return 0;
  }
  try {*value=native_character_classification(*source,classification);return 0;}
  catch(...){return 1;}
 }
