 static int range_list_next(void* raw) {
  auto* bridge=static_cast<AttackBridge*>(raw);
  if(!bridge||!bridge->init||!bridge->init->level_runtime||
     !bridge->init->level_context_current())return 1;
  return bridge->init->level_runtime->manager.room_object_cursor_next(
      &bridge->target_cursor)?0:1;
 }
 static std::int32_t attack_range_service(void* raw,
        dh2::character_ai_melee_range::State* state,
        const dh2::character_ai_melee_range::Request* request,
        dh2::character_ai_melee_range::Response* response) {
  using namespace dh2::character_ai_melee_range;
  auto* bridge=static_cast<AttackBridge*>(raw);
  if(!bridge||!bridge->init||!state||!request||!response||!bridge->init->ai||
     !bridge->init->owner||state->ai!=bridge->init->ai->ai_identity||
     state->owner!=bridge->init->actor().identity){
   if(bridge){bridge->failed=true;bridge->error="Monster melee-range source owner mismatch";}return 1;
  }
  auto& init=*bridge->init;auto& actor=init.actor();*response={};
  const auto unavailable=[&](const char* why){bridge->failed=true;bridge->error=why;return 1;};
  switch(request->operation){
  case Operation::resolve_object:{
   if(!init.level_runtime||!init.level_context_current()||!request->subject)
    return unavailable("Monster melee range requires the active source Level ObjectManager");
   auto& manager=init.level_runtime->manager;
   const auto* source=manager.find_by_identity(request->subject);
   if(!source||!source->source_handle||manager.find_by_source_handle(source->source_handle)!=source)
    return unavailable("Monster melee candidate did not resolve through ObjectManager handle/object");
   const auto* candidate=actor_in_level(*bridge->init->level_runtime,request->subject);
   if(request->subject!=prince_character.identity()&&
      (!candidate||candidate->kind!=1||candidate->identity!=request->subject))
    return unavailable("Monster melee candidate has no canonical Character owner");
   bridge->resolved={request->subject,0};response->view=&bridge->resolved;return 0;
  }
  case Operation::interaction_type:{
   if(!request->subject)return unavailable("Monster melee InteractionType candidate is null");
   std::uint32_t enemy=0;
   if(!source_relation_for_ooi(state->owner,request->subject,
       dh2::character_ai_relations::Relation::enemy,enemy))
    return unavailable("Monster melee InteractionType requires source AI_IsEnemy");
   response->word=enemy?8u:3u;return 0;
  }
  case Operation::target_position:{
   if(request->subject!=actor.identity&&request->subject!=state->target_40)
    return unavailable("Monster melee GetTargetPosition subject changed");
   float position[3]{};
   if(!native_character_position_for_target(request->subject,position))
    return unavailable("Monster melee GetTargetPosition provider is unavailable");
   const unsigned slot=request->subject==actor.identity?0u:1u;
   for(unsigned axis=0;axis<3;++axis)
    std::memcpy(&bridge->points[slot].words[axis],&position[axis],sizeof(float));
   response->view=&bridge->points[slot];return 0;
  }
  case Operation::melee_radius:{
   ObjectActor* radius_owner=nullptr;
   if(request->kind==Subject::original_ai&&request->subject==init.ai->ai_identity)
    radius_owner=&actor;
   else if(request->kind==Subject::resolved_character_ai)
    radius_owner=actor_in_level(*bridge->init->level_runtime,request->subject);
   if(request->subject==prince_character.identity()){
    float radius=0.f;
    if(!player_melee_radius_v1(radius))return unavailable("Player AI_GetMeleeRadius provider is unavailable");
    std::memcpy(&response->word,&radius,sizeof(radius));return 0;
   }
   if(!radius_owner)
    return unavailable("Monster AI_GetMeleeRadius has no canonical Character owner");
   float radius=0.f;std::string error;
   // AI_GetMeleeRadius falls back to the AITable row when ItemInventory
   // reports no melee weapon (unequipped/template Characters).
   if(!radius_owner->source_inventory||
      !radius_owner->source_inventory->melee_radius(*radius_owner,radius,error)){
    if(dh2::character::player_attack_melee_radius_v1::query(nullptr,&actor_ai_tables,
         radius_owner->properties.resolved[1],&radius)!=
       dh2::character::player_attack_melee_radius_v1::Status::complete)
     return unavailable(error.empty()?"Monster AI_GetMeleeRadius AITable fallback failed":error.c_str());
   }
   std::memcpy(&response->word,&radius,sizeof(radius));return 0;
  }
  case Operation::diagnostic_switch:{
   if(!native_debug)return unavailable("Monster melee debug-switch owner is unavailable");
   if(native_debug->runtime().load(native_debug->globals(),native_debug->services())!=
      dh2::debug_switches::Status::complete)return unavailable("Monster melee debug-switch load failed");
   const char* key=request->key==1?"IsTracingCharAITarget":
       request->key==2?"isTracingCharAITarget":nullptr;
   if(!key)return unavailable("Monster melee debug-switch key is invalid");
   std::uint8_t value=0;
   if(native_debug->runtime().get_switch(key,native_debug->globals(),
       native_debug->services(),value)!=dh2::debug_switches::Status::complete)
    return unavailable("Monster melee debug-switch query failed");
   response->word=value;return 0;
  }
  case Operation::interaction_range:
   return unavailable("Monster melee fallback InteractionRange path is not source-bound");
  }
  return unavailable("Monster melee-range operation is unsupported");
 }
 static std::int32_t attack_ranged_range_service(void* raw,
        dh2::character_ai_ranged_range::State* state,
        const dh2::character_ai_ranged_range::Request* request,
        dh2::character_ai_ranged_range::Response* response) {
  using namespace dh2::character_ai_ranged_range;
  auto* bridge=static_cast<AttackBridge*>(raw);
  if(!bridge||!bridge->init||!state||!request||!response||!bridge->init->ai||
     !bridge->init->owner||state->ai!=bridge->init->ai->ai_identity||
     state->owner!=bridge->init->actor().identity){
   if(bridge){bridge->failed=true;bridge->error="Monster ranged-range source owner mismatch";}return 1;
  }
  auto& init=*bridge->init;auto& actor=init.actor();*response={};
  const auto unavailable=[&](const char* why){bridge->failed=true;bridge->error=why;return 1;};
  switch(request->operation){
  case Operation::resolve_object:{
   if(!request->subject||!init.level_runtime||!init.level_context_current())
    return unavailable("Monster ranged query requires its active source Level ObjectManager");
   auto& manager=init.level_runtime->manager;
   const auto* source=manager.find_by_identity(request->subject);
   if(!source||!source->source_handle||manager.find_by_source_handle(source->source_handle)!=source)
    return unavailable("Monster ranged candidate did not resolve through ObjectManager handle/object");
   bridge->resolved={request->subject,0};response->view=&bridge->resolved;response->identity=source->source_handle;return 0;
  }
  case Operation::can_range_attack:{
   if(request->subject!=actor.identity||!request->minimum||!request->maximum||!request->projectile)
    return unavailable("Monster ranged CanRangeAttack output pointers/owner are invalid");
   std::int32_t parameters[3]{};bool capable=false;std::string error;
   if(!actor.source_inventory||!actor.source_inventory->range_parameters(actor,parameters,capable,error))
    return unavailable(error.empty()?"Monster ranged CanRangeAttack has no canonical V4 provider":error.c_str());
   response->word=capable;
   if(capable){*request->minimum=std::uint32_t(parameters[0]);
    *request->maximum=std::uint32_t(parameters[1]);
    *request->projectile=std::uint32_t(parameters[2]);}
   return 0;
  }
  case Operation::target_position:{
   if(request->subject!=actor.identity&&request->subject!=state->target_40)
    return unavailable("Monster ranged GetTargetPosition subject changed");
   float position[3]{};
   if(!native_character_position_for_target(request->subject,position))
    return unavailable("Monster ranged GetTargetPosition provider is unavailable");
   const unsigned slot=request->subject==actor.identity?0u:1u;
   for(unsigned axis=0;axis<3;++axis)
    std::memcpy(&bridge->points[slot].words[axis],&position[axis],sizeof(float));
   response->view=&bridge->points[slot];return 0;
  }
  case Operation::diagnostic_switch:{
   if(!native_debug)return unavailable("Monster AI_IsInRange debug-switch owner is unavailable");
   auto* backend=native_debug.get();auto* globals=&backend->globals();
   if(request->key==1){bridge->ranged_debug_backend=backend;bridge->ranged_debug_globals=globals;}
   else if(request->key!=2||request->subject!=reinterpret_cast<std::uintptr_t>(bridge->ranged_debug_globals)||
       backend!=bridge->ranged_debug_backend||globals!=bridge->ranged_debug_globals)
    return unavailable("Monster AI_IsInRange lost its captured DebugSwitches global");
   if(backend->runtime().load(*globals,backend->services())!=
      dh2::debug_switches::Status::complete)return unavailable("Monster AI_IsInRange debug-switch load failed");
   const char* key=request->key==1?"IsTracingCharAITarget":
       request->key==2?"isTracingCharAITarget":nullptr;
   if(!key)return unavailable("Monster AI_IsInRange debug-switch key is invalid");
   std::uint8_t value=0;
   if(backend->runtime().get_switch(key,*globals,
       backend->services(),value)!=dh2::debug_switches::Status::complete)
    return unavailable("Monster AI_IsInRange debug-switch query failed");
   response->word=value;response->identity=reinterpret_cast<std::uintptr_t>(globals);return 0;
  }
  case Operation::interaction_type:{
   // AI_IsInCloseRange (0x3d63d8) asks the resolved candidate's virtual +0x90
   // InteractionType for the owner; 8 is the enemy branch. AI_IsInRange has no
   // such call, so only the close caller reaches this operation.
   if(!request->subject)return unavailable("Monster close-range InteractionType candidate is null");
   std::uint32_t enemy=0;
   if(!source_relation_for_ooi(state->owner,request->subject,
       dh2::character_ai_relations::Relation::enemy,enemy))
    return unavailable("Monster close-range InteractionType requires source AI_IsEnemy");
   response->word=enemy?8u:3u;return 0;
  }
  case Operation::interaction_range:
   return unavailable("Monster AI_IsInCloseRange fallback InteractionRange path is not source-bound");
  }
  return unavailable("Monster AI_IsInRange operation is unsupported");
 }
 // CharAI::_UpdateTarget's range ladder (0x3cba10..0x3cbb30) after the Interactive
 // recheck: Character::CanRangeAttack() (virtual +0x124, 0x3a4d3c) selects
 // AI_IsInCloseRange (0x3d63d8) then AI_IsInRange (0x3d6604); without it
 // AI_IsInMeleeRange (0x3d6188) decides event 17 versus 14. The melee leg stays
 // with the caller's existing AI_IsInMeleeRange fact. Close and ranged run the
 // maintained 556B/496B kernels over the Monster's V4 inventory, handle and
 // GetTargetPosition providers above; ranged is only asked when close is false.
 struct TargetRangeFacts {
  bool owner_can_range=false,close=false,ranged=false;
  std::uint32_t distance_bits=0,minimum=0,maximum=0;
 };
 static bool evaluate_target_range(NativeMonsterInitialization& init,
                                   std::uintptr_t target,TargetRangeFacts& facts,
                                   std::string& error) {
  facts={};
  if(!init.ai||!init.owner||!init.owner->actor||!target||!init.initialized||
     !init.level_runtime||!init.level_context_current()){
   error="Monster range ladder lacks its initialized AIS/Level owners";return false;
  }
  auto& actor=init.actor();
  // An unequipped template or Limbus Character has no ItemInventory::
  // CanRangeAttack answer yet; the source call is simply false for it.
  if(!actor.source_inventory||!actor.source_inventory->source_init_equipment_complete)
   return true;
  bool capable=false;
  if(!actor.source_inventory->can_range_attack(actor,capable,error))return false;
  if(!capable)return true;
  facts.owner_can_range=true;
  AttackBridge bridge{};bridge.init=&init;
  const dh2::character_ai_ranged_range::Services services{&bridge,attack_ranged_range_service};
  dh2::character_ai_ranged_range::Result close{};
  dh2::character_ai_ranged_range::State close_state{init.ai->ai_identity,actor.identity,target};
  const auto close_status=dh2::character_ai_ranged_range::evaluate_close(
      &close_state,target,&services,&close);
  if(close_status!=dh2::character_ai_ranged_range::Status::complete||bridge.failed){
   error=bridge.error.empty()?"Monster AI_IsInCloseRange source provider failed":bridge.error;
   facts={};return false;
  }
  // Close aliases maximum with the projectile output, so only the minimum
  // word is meaningful from this leg.
  facts.distance_bits=close.distance_word;facts.minimum=close.minimum_word;
  if(close.value){facts.close=true;return true;}
  dh2::character_ai_ranged_range::Result ranged{};
  dh2::character_ai_ranged_range::State ranged_state{init.ai->ai_identity,actor.identity,target};
  const auto ranged_status=dh2::character_ai_ranged_range::evaluate_ranged(
      &ranged_state,target,&services,&ranged);
  if(ranged_status!=dh2::character_ai_ranged_range::Status::complete||bridge.failed){
   error=bridge.error.empty()?"Monster AI_IsInRange source provider failed":bridge.error;
   facts={};return false;
  }
  facts.ranged=ranged.value!=0;facts.maximum=ranged.maximum_word;
  return true;
 }
 static std::uint32_t attack_query_service(void* raw,
        dh2::character::AttackQueryState16* state,
        const dh2::character::AttackQueryRequest24* request) {
  using namespace dh2::character;
  auto* bridge=static_cast<AttackBridge*>(raw);
  if(!bridge||!bridge->init||!state||!request||!bridge->init->ai||
     !bridge->init->owner||state->owner!=bridge->init->actor().identity||
     request->owner!=state->owner||request->target==0){
   if(bridge){bridge->failed=true;bridge->error="Monster AI_CanAttack query owner/target mismatch";}return 0;
  }
  auto& init=*bridge->init;auto& actor=init.actor();
  switch(static_cast<AttackQueryService>(request->service)){
  case attack_is_enemy:{
   std::uint32_t enemy=0;
   if(!source_relation_for_ooi(state->owner,request->target,
       dh2::character_ai_relations::Relation::enemy,enemy)){
    bridge->failed=true;bridge->error="Monster AI_CanAttack requires source AI_IsEnemy";return 0;
   }
   return enemy;
  }
  case attack_inventory_can_melee:{
   bool melee=false;std::string error;
   if(!actor.source_inventory||!actor.source_inventory->can_melee_attack(actor,melee,error)){
    bridge->failed=true;bridge->error=error.empty()?"Monster AI_CanAttack lacks canonical ItemInventory::CanMeleeAttack":error;return 0;
   }
   return melee;
  }
  case attack_in_melee_range:{
   dh2::character_ai_melee_range::State range_state{
       init.ai->ai_identity,state->owner,request->target};
   const dh2::character_ai_melee_range::Services services{bridge,attack_range_service};
   dh2::character_ai_melee_range::Result result{};
   const auto status=dh2::character_ai_melee_range::evaluate_object(
       &range_state,request->target,&services,&result);
   if(status!=dh2::character_ai_melee_range::Status::complete||bridge->failed){
    bridge->failed=true;if(bridge->error.empty())bridge->error="Monster AI_IsInMeleeRange source provider failed";return 0;
   }
   return result.value;
  }
  case attack_owner_can_range:{
   bool ranged=false;std::string error;
   if(!actor.source_inventory||!actor.source_inventory->can_range_attack(actor,ranged,error)){
    bridge->failed=true;bridge->error=error.empty()?"Monster AI_CanAttack lacks canonical CanRangeAttack":error;return 0;
   }
   return ranged;
  }
  case attack_in_range:{
   dh2::character_ai_ranged_range::State range_state{
       init.ai->ai_identity,state->owner,request->target};
   const dh2::character_ai_ranged_range::Services services{bridge,attack_ranged_range_service};
   dh2::character_ai_ranged_range::Result result{};
   const auto status=dh2::character_ai_ranged_range::evaluate_ranged(
       &range_state,request->target,&services,&result);
   if(status!=dh2::character_ai_ranged_range::Status::complete||bridge->failed){
    bridge->failed=true;if(bridge->error.empty())bridge->error="Monster AI_IsInRange source provider failed";return 0;
   }
   return result.value;
  }
  }
  bridge->failed=true;bridge->error="Monster AI_CanAttack operation is unsupported";return 0;
 }
 static void attack_service(void* raw,dh2::character::AttackState64* state,
        dh2::character::ControllerAttackState32* controller,
        const dh2::character::AttackRequest32* request,
        dh2::character::AttackResponse16* response) {
  using namespace dh2::character;
  auto* bridge=static_cast<AttackBridge*>(raw);
  if(!bridge||!bridge->init||!state||!request||!response){if(bridge)bridge->failed=true;return;}
  auto& init=*bridge->init;auto& actor=init.actor();*response={};
  const auto fail=[&](const char* text){bridge->failed=true;bridge->error=text;response->reserved=1;};
  switch(static_cast<AttackService>(request->service)){
  case attack_owner_dead:response->word=actor.combat_state.dead!=0;return;
  case attack_owner_ranged:{
   if(!actor.source_inventory){fail("Monster CanRangeAttack has no retained source V4 inventory");response->word=1;return;}
   bool ranged=false;std::string error;
   if(!actor.source_inventory->can_range_attack(actor,ranged,error)){
    fail(error.c_str());response->word=1;return;
   }
   response->word=ranged;return;
  }
  case attack_is_attacking:response->word=init.owner->character.state.current==5;return;
  case attack_range_redirect:{
   const AttackServices16 services{bridge,attack_service};
   if(request->subject!=state->owner||
      dh2_character_ai_range_attack(state,request->payload,request->argument0,&services)!=0||
      bridge->failed)
    fail(bridge->error.empty()?"Monster AI_DoRangeAttack source provider failed":bridge->error.c_str());
   return;
  }
  case attack_range_parameters:{
   // The attack kernel names the CharAI (its state owner) as subject.
   if(request->subject!=actor.identity&&request->subject!=state->owner){
    fail("Monster CanRangeAttack request names neither the Character nor its CharAI");return;
   }
   // ItemInventory::CanRangeAttack is false without an equipped ranged item;
   // an unequipped (template/Limbus) Character simply cannot range attack.
   if(!actor.source_inventory||!actor.source_inventory->source_init_equipment_complete){
    response->word=0;response->identity=0;return;
   }
   std::int32_t parameters[3]{};bool capable=false;std::string error;
   if(!actor.source_inventory->range_parameters(actor,parameters,capable,error)){
    fail(error.empty()?"Monster CanRangeAttack parameter provider failed":error.c_str());return;
   }
   response->word=capable?1u:0u;
   response->identity=capable?std::uintptr_t(std::uint32_t(parameters[1])):0;return;
  }
  case attack_range_list_create:{
   if((request->subject!=actor.identity&&request->subject!=state->owner)||request->argument0!=1||request->argument1!=0||
      !init.level_runtime||!init.level_context_current()){
    fail("Monster ranged TargetList requires its current Level owner and filters (1,0,1)");return;}
   auto& manager=init.level_runtime->manager;
   if(!project_range_character(*bridge,actor.identity,bridge->range_owner)){
    fail("Monster ranged TargetList owner lacks canonical Character/position/rotation projection");return;
   }
   try {bridge->range_heap.resize(std::max<std::size_t>(1,manager.room_object_count()));}
   catch(...){fail("Monster ranged TargetList heap allocation failed");return;}
   bridge->target_services={bridge,range_target_service};
   bridge->target_methods={bridge,range_list_reset,range_list_at_end,
       range_list_get,range_list_next};
   if(dh2_target_list_init_filtered(&bridge->range_target_list,
       bridge->range_heap.data(),std::uint32_t(bridge->range_heap.size()),
       &bridge->range_owner,1,0,1,&bridge->target_services)){
    fail("Monster ranged TargetList source constructor projection failed");return;
   }
   bridge->range_identities.clear();
   bridge->range_list_view={reinterpret_cast<std::uintptr_t>(&bridge->range_list_view),
       bridge->range_identities.data(),0,0};
   response->identity=bridge->range_list_view.token;return;
  }
  case attack_range_list_search:{
   if(request->subject!=bridge->range_list_view.token||
      request->payload!=reinterpret_cast<std::uintptr_t>(&bridge->range_list_view)||
      !request->argument0){fail("Monster ranged TargetList search owner/range is invalid");return;}
   float cone=0;std::memcpy(&cone,&request->argument1,sizeof(cone));
   if(dh2_target_search_object_list(&bridge->range_target_list,&bridge->target_methods,
       static_cast<float>(request->argument0),cone,&bridge->target_services)){
    fail(bridge->error.empty()?"Monster ranged TargetList Search failed in borrowed ObjectManager view":bridge->error.c_str());return;
   }
   try {
    bridge->range_identities.clear();bridge->range_identities.reserve(bridge->range_target_list.count);
    dh2::target_search::Target24 target{};
    while(bridge->range_target_list.count){
     if(dh2_target_pop(&bridge->range_target_list,&target)){
      fail("Monster ranged TargetList Pop failed");return;
     }
     bridge->range_identities.push_back(target.identity);
    }
   } catch(...){fail("Monster ranged ordered target projection allocation failed");return;}
   bridge->range_list_view.entries=bridge->range_identities.data();
   bridge->range_list_view.count=std::uint32_t(bridge->range_identities.size());
   bridge->range_list_view.cursor=0;return;
  }
  case attack_list_reset_sort:
   if(request->subject!=bridge->range_list_view.token||
      request->payload!=reinterpret_cast<std::uintptr_t>(&bridge->range_list_view))
    fail("Monster ranged TargetList sort owner changed");
   return;
  case attack_list_pop:
   if(request->subject!=bridge->range_list_view.token||
      request->payload!=reinterpret_cast<std::uintptr_t>(&bridge->range_list_view)||
      bridge->range_list_view.cursor>=bridge->range_list_view.count)
    fail("Monster ranged TargetList pop owner/cursor is invalid");
   else ++bridge->range_list_view.cursor;
   return;
  case attack_list_destroy:
   if(request->subject!=bridge->range_list_view.token||
      request->payload!=reinterpret_cast<std::uintptr_t>(&bridge->range_list_view)){
    fail("Monster ranged TargetList destroy owner changed");return;
   }
   bridge->range_list_view={};bridge->range_identities.clear();bridge->range_heap.clear();return;
  case attack_frontal_angle:{
   if((request->subject!=actor.identity&&request->subject!=state->owner)){fail("Monster ranged frontal-angle owner changed");return;}
   dh2_pycst_result value{};
   if(dh2_pycst_get(&actor_design,"CharacterDesign",15,"Attack_FrontalAngle",19,&value)||!value.found){
    fail("Monster ranged Attack_FrontalAngle source constant is unavailable");return;
   }
   response->word=std::uint32_t(value.value);return;
  }
  case attack_look_at_target:{
   if((request->subject!=actor.identity&&request->subject!=state->owner)||!request->payload||!init.owner->runtime_ready||
      init.owner->character.owner()!=actor.identity){fail("Monster GameObject::LookAt owner/target is invalid");return;}
   float target[3]{};
   if(!native_character_position_for_target(request->payload,target)){
    fail("Monster GameObject::LookAt target has no canonical GetTargetPosition provider");return;
   }
   dh2::character::LookAtState16 look{{init.owner->runtime.subobjects.position[0],
       init.owner->runtime.subobjects.position[1],init.owner->runtime.subobjects.position[2]},
       init.owner->runtime.rotation.heading_angle};
   if(dh2_character_look_at_point(&look,target)){
    fail("Monster GameObject::LookAt source point kernel rejected target position");return;
   }
   init.owner->runtime.rotation.heading_angle=
       init.owner->runtime.controller.heading.angle=look.heading_angle;
   return;
  }
  case attack_range_melee_fallback:{
   if((request->subject!=actor.identity&&request->subject!=state->owner)){fail("Monster ranged fallback owner changed");return;}
   const AttackServices16 services{bridge,attack_service};
   if(dh2_character_ai_melee_attack(state,request->payload,request->argument0,&services)!=0||bridge->failed)
    fail(bridge->error.empty()?"Monster AI_DoMeleeAttack fallback failed":bridge->error.c_str());
   return;
  }
  case attack_diagnostic:{
   if(!native_debug){fail("Monster AI_DoMeleeAttack debug-switch owner is unavailable");return;}
   if(native_debug->runtime().load(native_debug->globals(),native_debug->services())!=
      dh2::debug_switches::Status::complete){fail("Monster AI_DoMeleeAttack debug-switch load failed");return;}
   std::uint8_t tracing=0;
   if(native_debug->runtime().get_switch("IsTracingCharAITarget",native_debug->globals(),
       native_debug->services(),tracing)!=dh2::debug_switches::Status::complete){
    fail("Monster AI_DoMeleeAttack debug-switch query failed");return;
   }
   response->word=tracing;return;
  }
  case attack_set_target:{
   if(request->subject!=state->owner){fail("Monster AI_SetTarget owner changed");return;}
   if(NativeMonsterInitialization::set_target(&init,actor.identity,request->payload))
    fail("Monster AI_SetTarget source provider failed");
   else state->target=request->payload;
   return;
  }
  case attack_sync_last_target:
   if(request->subject!=state->owner){fail("Monster AI_SyncLastTarget owner changed");return;}
   state->last_target=state->target;
   init.ai->state.last_target_44=state->last_target;return;
  case attack_can_attack_current:{
   if(request->subject!=state->owner||!request->payload){fail("Monster AI_CanAttack owner/current target is invalid");return;}
   dh2::character::AttackQueryState16 query_state{state->owner,state->target};
   const dh2::character::AttackQueryServices16 services{bridge,attack_query_service};
   std::uint32_t value=0;
   if(dh2_character_ai_can_attack(&query_state,request->payload,&services,&value)!=0||bridge->failed){
    fail(bridge->error.empty()?"Monster AI_CanAttack source provider failed":bridge->error.c_str());return;
   }
   response->word=value;return;
  }
  case attack_target_dead:{
   if(request->subject!=state->owner||!request->payload){fail("Monster AI target-dead query owner/target invalid");return;}
   if(request->payload==prince_character.identity())response->word=prince_combat.life.dead!=0;
   else {auto* target=actor_in_level(*bridge->init->level_runtime,request->payload);
    if(!target){fail("Monster AI target-dead query has no canonical target Character");return;}
    response->word=target->combat_state.dead!=0;}
   return;
  }
  case attack_owner_player:response->word=actor.identity==prince_character.identity();return;
  case attack_current_in_melee:{
   AttackBridge range_bridge{};range_bridge.init=&init;
   // CharAI::AI_IsInMeleeRange(0) evaluates the CharAI's current target (+0x40).
   dh2::character_ai_melee_range::State range_state{
     init.ai->ai_identity,actor.identity,init.ai->state.target_40};
   const dh2::character_ai_melee_range::Services services{&range_bridge,attack_range_service};
   dh2::character_ai_melee_range::Result result{};
   const auto status=dh2::character_ai_melee_range::evaluate_object(
       &range_state,request->payload,&services,&result);
   if(status!=dh2::character_ai_melee_range::Status::complete||range_bridge.failed){
    bridge->failed=true;bridge->error=range_bridge.error.empty()?"Monster AI_IsInMeleeRange source provider failed":range_bridge.error;return;
   }
   response->word=result.value;return;
  }
  case attack_set_attack_state:
   if(request->subject!=state->owner||request->argument0!=0){
    fail("Monster SM_SetAttackState owner/AIS/mode changed");return;
   }
   if(!init.ai->state.active_ais_1c||init.owner->character.event(
       0xc354,init.ai->state.active_ais_1c)!=1)
    fail("Monster SM_SetAttackState(activeAIS,false) rejected by canonical FSM");
   return;
  case attack_network_mode:
   if(native_host.online){fail("Monster Cmd_Attack online network mode is unsupported");return;}
   response->word=0;return;
  case attack_controllable_dispatch:{
   const auto controllable=reinterpret_cast<std::uintptr_t>(&init.owner->control_services);
   if(!controller||controller->controllable!=controllable||
      controller->character!=actor.identity||request->subject!=controllable){
    fail("Monster Ctrl_Attack controllable/Character owner mismatch");return;
   }
   const AttackServices16 services{bridge,attack_service};
   if(dh2_character_ai_melee_attack(state,request->payload,0,&services)!=0)
    fail("Monster CharAI::AI_DoMeleeAttack failed");
   return;
  }
  default:fail("Monster AI_DoMeleeAttack reached an unbound search/network provider");return;
  }
 }
