int native_player_buff_fx_service_v1(void* raw,
    const dh2::character_player_buffs_v1::Request* request,
    dh2::character_player_buffs_v1::Response* response) {
 using namespace dh2::native_visual_fx_manager_v1;
 auto* character=static_cast<dh2::character::aggro_search::Character*>(raw);
 if(!character||!request||!response||!character->identity||
    request->character!=character->identity)return 1;
 response->identity=0;
 switch(request->operation) {
  case dh2::character_player_buffs_v1::Operation::fx_load: {
   // Source GrabAnimFX returns null for an invalid numeric table ID, and a
   // full source pool is also an ordinary null result.
   if(request->id<0||!native_fx_owner||!native_fx_catalog||
      static_cast<std::size_t>(request->id)>=native_fx_catalog->sequences.size())
    return native_fx_owner&&native_fx_catalog?0:1;
   sync_prince_search_projection();
   if(character->identity!=prince_character.identity()||
      &prince_search_projection.character!=character)return 1;
   void* instance=nullptr;std::string error;
   const auto status=native_fx_owner->GrabAnimFX(request->id,nullptr,
                                                 &instance,error);
   if(status==Status::pool_exhausted||
      (status==Status::ok&&!instance))return 0;
   if(status!=Status::ok)return 1;
   // Player BuffOwner has no exact C++ GameObject pointer in this renderer.
   // Bind its canonical typed Character projection so the shared renderer
   // places this same AnimatedFX at the current Player source position.
   if(native_fx_owner->BindCharacter(instance,character,error)!=Status::ok||
      native_fx_owner->SyncIrrData(instance,true,error)!=Status::ok) {
    (void)native_fx_owner->DropAnimatedFX(&instance,error);return 1;
   }
   response->identity=reinterpret_cast<std::uintptr_t>(instance);return 0;
  }
  case dh2::character_player_buffs_v1::Operation::fx_release: {
   if(!request->subject)return 0;
   if(!native_fx_owner)return 1;
   void* instance=reinterpret_cast<void*>(request->subject);std::string error;
   return native_fx_owner->DropAnimatedFX(&instance,error)==Status::ok?0:1;
  }
  case dh2::character_player_buffs_v1::Operation::fx_object: {
   if(!request->subject)return 0;
   if(!native_fx_owner)return 1;
   void* controller=nullptr;std::string error;
   const auto status=native_fx_owner->GetAnimController(
       reinterpret_cast<void*>(request->subject),&controller,error);
   if(status!=Status::ok)return 1;
   response->identity=reinterpret_cast<std::uintptr_t>(controller);return 0;
  }
  case dh2::character_player_buffs_v1::Operation::fx_enable: {
   if(!request->subject)return 0;
   if(!native_fx_owner)return 1;
   std::string error;
   return native_fx_owner->PlayAnimControllerClip(
       reinterpret_cast<void*>(request->subject),
       static_cast<std::uint32_t>(request->index),request->enabled==1,error)==
       Status::ok?0:1;
  }
  default:return 1;
 }
}
