GLuint upload(AAssetManager* assets,const std::string& name,std::map<std::string,GLuint>& cache,std::vector<GLuint>& owned,const std::string& folder="textures"){
  auto found=cache.find(name);if(found!=cache.end())return found->second;
  std::vector<std::uint8_t> rgba;unsigned w=1,h=1;
  std::vector<std::uint8_t> raw;
  if(!name.empty()){
    try{raw=read(assets,name,folder);}
    catch(const std::exception& failure){
      if(std::string(failure.what()).rfind("Bundled asset missing: ",0)!=0)throw;
      // The supplied cache keeps source textures under data/3d/textures.
      auto lowered=name;
      std::transform(lowered.begin(),lowered.end(),lowered.begin(),
          [](unsigned char c){return static_cast<char>(std::tolower(c));});
      try{raw=read(assets,"original-cache/data/3d/textures/"+lowered,"");}
      catch(const std::exception&){
        // glitch's texture manager leaves a missing source texture unbound
        // and keeps loading the scene; use a neutral texel instead of
        // rejecting the whole model.
        __android_log_print(ANDROID_LOG_WARN,"DH2Native",
            "Source texture unavailable; using neutral texel | %s/%s",
            folder.c_str(),name.c_str());
      }
    }
  }
  if(raw.empty())rgba={255,255,255,255};
  else{
    dh2::textures::View view{};
    if(dh2_texture_open(raw.data(),raw.size(),&view)!=dh2::textures::Error::ok)throw std::runtime_error("Texture header rejected: "+name);
    w=view.width;h=view.height;rgba.resize(std::size_t(w)*h*4);
    if(dh2_texture_decode(&view,rgba.data(),rgba.size())!=dh2::textures::Error::ok)throw std::runtime_error("Texture decode rejected: "+name);
  }
  GLint max=0;glGetIntegerv(GL_MAX_TEXTURE_SIZE,&max);if(w>unsigned(max)||h>unsigned(max))throw std::runtime_error("Texture exceeds GPU limit");
  GLuint t=0;glGenTextures(1,&t);owned.push_back(t);glBindTexture(GL_TEXTURE_2D,t);
  glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);
  // Original UVs wrap beyond [0,1]; fixture sizes are all powers of two.
  glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_REPEAT);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_REPEAT);
  glPixelStorei(GL_UNPACK_ALIGNMENT,1);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,rgba.data());check("Model texture upload");
  cache[name]=t;return t;
}
bool prepare_source_container_visual_gpu(AAssetManager* assets,
    dh2::destructible_container_visual_owner_v1::Owner& owner,
    std::vector<Draw>& draws_out,std::vector<GLuint>& images_out,
    std::string& error) {
 error.clear();
 if(!assets||!owner.controller_present()||owner.root_animator_count()!=1){
  error="DestructibleContainer GPU preparation requires its retained single-root Animator";
  return false;
 }
 std::vector<Draw> candidate_draws;std::vector<GLuint> candidate_images;
 try {
  const auto& resource=owner.resource();
  std::map<std::string,GLuint> texture_cache;
  candidate_draws.reserve(resource.primitives.size());
  for(const auto& primitive:resource.primitives){
   if(primitive.node>=resource.scene.graph.size()||
      primitive.material>=resource.scene.materials.size()||
      primitive.indices.empty()||primitive.indices.size()>3000000||
      primitive.indices.size()%3||primitive.vertices.empty()||
      primitive.vertices.size()>65536){
    throw std::runtime_error("DestructibleContainer primitive is outside GLES2 draw bounds");
   }
   candidate_draws.emplace_back();auto& batch=candidate_draws.back();
   batch.node=primitive.node;
   batch.material=resource.scene.materials[primitive.material];
   batch.skin=primitive.skin;
   batch.cpu_vertices=primitive.vertices;
   batch.rest_positions=primitive.rest_positions;
   batch.diffuse=upload(assets,batch.material.diffuse,texture_cache,
                        candidate_images);
   batch.alpha=upload(assets,batch.material.alpha_map,texture_cache,
                      candidate_images);
   batch.count=static_cast<GLsizei>(primitive.indices.size());
   glGenBuffers(1,&batch.vertices);glBindBuffer(GL_ARRAY_BUFFER,batch.vertices);
   glBufferData(GL_ARRAY_BUFFER,primitive.vertices.size()*sizeof(Vertex),
                primitive.vertices.data(),GL_DYNAMIC_DRAW);
   glGenBuffers(1,&batch.indices);
   glBindBuffer(GL_ELEMENT_ARRAY_BUFFER,batch.indices);
   glBufferData(GL_ELEMENT_ARRAY_BUFFER,
       primitive.indices.size()*sizeof(std::uint16_t),primitive.indices.data(),
       GL_STATIC_DRAW);
   check("DestructibleContainer VisualObject upload");
  }
  if(candidate_draws.empty())
   throw std::runtime_error("DestructibleContainer BDAE has no drawable primitives");
  release(draws_out,images_out);
  draws_out=std::move(candidate_draws);images_out=std::move(candidate_images);
  error.clear();return true;
 }catch(const std::exception& exception){
  release(candidate_draws,candidate_images);error=exception.what();return false;
 }catch(...){
  release(candidate_draws,candidate_images);
  error="DestructibleContainer GPU preparation failed";return false;
 }
}
void release_source_container_visual_gpu(std::vector<Draw>& draws_out,
    std::vector<GLuint>& images_out,bool gl_context) noexcept {
 if(gl_context)release(draws_out,images_out);
 else {draws_out.clear();images_out.clear();}
}
