 std::array<float,3> origin{};
 dh2::timeline::State timeline{};
 std::uint32_t timeline_timestamp_ms=0;
 dh2::animation::EventCursor event_cursor{};
 bool self_illum=true;
 Matrix placement{};
 double elapsed_ms=0.0,play_elapsed_ms=0.0;
 std::int32_t play_time=-1;
 std::int32_t repeats_remaining=-1;
 float speed=1.0f;
 bool orient_once=false,orient_with_anchor=false,scale_with_anchor=true;
 std::uint64_t gpu_generation=0;
 bool visible=false,loop=true,started=false;
 bool completion_pending=false,callback_armed=false;
 std::int32_t buff_clip_index=-1;
 bool buff_clip_selected=false,buff_clip_enabled=true;
