std::array<float,3> cross(const std::array<float,3>& a,const std::array<float,3>& b){return {a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]};}
void normalize(std::array<float,3>& a){float n=std::sqrt(a[0]*a[0]+a[1]*a[1]+a[2]*a[2]);for(float& x:a)x/=n;}
float dot(const std::array<float,3>& a,const std::array<float,3>& b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];}
void swamp_default_camera_basis(float& camera_yaw,float& camera_pitch){
  // LevelConfig::InitPost defaults an empty camera_file to CameraTests.bdae;
  // its PlayerCamera_Default node has this authored eye offset from its target.
  // Convert the BDAE's renderer-space XYZ into camera()'s orbit convention.
  if(dh2::native::camera_input_v1::orbit_from_eye_offset(
       dh2::native::camera_input_v1::kSwampDefaultCameraEyeOffset,
       &camera_yaw,&camera_pitch))
    throw std::runtime_error("CameraTests default camera basis rejected");
}
Matrix camera(int width,int height){
  const float aspect=float(width)/height;
  float tan=.41421356f;
  const bool source_swamp_camera=world_mode&&
      dh2::native::crypt_camera_frame_v1::source_swamp_static_camera_fallback_ready(
          active_level_assets.name,active_level_assets.level_file,
          active_level_assets.camera_near_clip>0.0f&&
          active_level_assets.camera_far_clip>active_level_assets.camera_near_clip);
  if(source_swamp_camera)
    tan=std::tan(dh2::native::level_camera_config_v1::kVerticalFovRadians*0.5f);
  std::array<float,3> target{center[0],center[1],center[2]};
  if(world_mode){
    // Level::_LoadCamera targets the local Player; CameraTarget::GetTargetPosition
    // resolves that GameObject's camera anchor. Follow the already source-updated
    // AnchorForward target while retaining this level's generic fallback optics.
    const dh2::native::crypt_camera_frame_v1::Vec3 actor_target{
        actor_position[0],actor_position[1],actor_position[2]};
    const auto anchor=dh2::native::crypt_camera_frame_v1::forward_anchor_target(
        &prince_camera_anchor,actor_target);
    target={anchor[0],anchor[1],anchor[2]};
  }
  float distance=radius*1.15f*std::sqrt(1+1/(tan*tan*std::min(1.f,aspect)*std::min(1.f,aspect)))*zoom;
  if(source_swamp_camera){
    float source_distance=0.0f,source_yaw=0.0f,source_pitch=0.0f;
    if(dh2::native::camera_input_v1::orbit_from_eye_offset(
         dh2::native::camera_input_v1::kSwampDefaultCameraEyeOffset,
         &source_yaw,&source_pitch,&source_distance))
      throw std::runtime_error("CameraTests default camera distance rejected");
    (void)source_yaw;(void)source_pitch;
    // The fallback orbit already uses CameraTests' authored azimuth/elevation.
    // Preserve its authored eye-target distance instead of the development
    // scene-radius zoom, which places the camera only about one third as far.
    distance=source_distance*zoom;
  }
  std::array<float,3> eye{target[0]+distance*std::cos(yaw)*std::cos(pitch),target[1]+distance*std::sin(yaw)*std::cos(pitch),target[2]+distance*std::sin(pitch)};
  std::array<float,3> f{target[0]-eye[0],target[1]-eye[1],target[2]-eye[2]};normalize(f);
  auto s=cross(f,{0,0,1});normalize(s);auto u=cross(s,f);
  Matrix view{s[0],u[0],-f[0],0,s[1],u[1],-f[1],0,s[2],u[2],-f[2],0,-dot(s,eye),-dot(u,eye),dot(f,eye),1};
  const float near=source_swamp_camera?active_level_assets.camera_near_clip:
      world_mode?50.f:std::max(.01f,distance-radius*1.5f);
  const float far=source_swamp_camera?active_level_assets.camera_far_clip:
      world_mode?12000.f:distance+radius*3;
  Matrix projection{1/(tan*aspect),0,0,0,0,1/tan,0,0,0,0,-(far+near)/(far-near),-1,0,0,-2*far*near/(far-near),0};
  const auto result=dh2::scene::multiply(projection,view);
  if(world_mode){
    // The follow-camera transform remains the development producer. Its real
    // matrix/eye now exercise the recovered full frustum arithmetic; scene
    // registration and Character culling ownership remain separate work.
    std::memcpy(source_camera.matrix.elements,result.data(),sizeof(source_camera.matrix.elements));
    std::memcpy(source_camera.frustum.position,eye.data(),sizeof(source_camera.frustum.position));
    if(dh2::engine_camera::frustum_runtime::set_from(&source_camera.matrix,&source_camera.frustum)!=
       dh2::engine_camera::frustum_runtime::Status::complete)
      throw std::runtime_error("Source camera frustum rejected live matrix");
    const bool resized=source_camera.width!=width||source_camera.height!=height;
    source_camera.width=width;source_camera.height=height;
    if((source_camera.frames++%128)==0||resized){
      std::string input,output;
      const auto append=[](std::string& text,std::uint32_t word){char hex[10];std::snprintf(hex,sizeof(hex)," %08x",word);text+=hex;};
      for(auto word:source_camera.matrix.elements)append(input,word);
      for(auto word:source_camera.frustum.position)append(output,word);
      for(const auto& plane:source_camera.frustum.planes)for(auto word:plane)append(output,word);
      for(auto word:source_camera.frustum.box_min)append(output,word);
      for(auto word:source_camera.frustum.box_max)append(output,word);
      __android_log_print(ANDROID_LOG_INFO,"DH2Native","Source camera frame | %llu | %dx%d | matrix%s | frustum%s",
        static_cast<unsigned long long>(source_camera.frames),width,height,input.c_str(),output.c_str());
    }
  }
  return result;
}
bool ensure_player_camera_rig(const RuntimeLevelAssets& level,
    const dh2::data::AnimationTables& camera_tables,
    const dh2::data::Dictionary& camera_clips){
 std::string camera_path=level.camera_file;
 if(camera_path.find('/')==std::string::npos)
  camera_path="data/3d/camera/"+camera_path;
 std::transform(camera_path.begin(),camera_path.end(),camera_path.begin(),
     [](unsigned char c){return static_cast<char>(std::tolower(c));});
 const std::string camera_key=camera_path+"\n"+level.camera_animset;
 if(player_camera_rig&&player_camera_rig_cache_key==camera_key)return true;
 if(player_camera_rig_load_attempted&&player_camera_rig_cache_key==camera_key)return false;
 player_camera_rig_cache_key=camera_key;
 player_camera_rig.reset();player_camera_rig_asset=camera_path;
 player_camera_playback=dh2::player_camera_rig_v1::Playback{};
 player_camera_rig_default_target_distance=0.0f;
 player_camera_rig_load_attempted=false;
 if(!player_camera_asset_manager)return false;
 player_camera_rig_load_attempted=true;
 try{
  const auto camera_scene=read(player_camera_asset_manager,camera_path,"actors");
  dh2::camera_animset_v1::Selection selected{};std::string error;
  if(!dh2::camera_animset_v1::select(camera_tables,camera_clips,
                                     level.camera_animset,selected,error))
   throw std::runtime_error("Source-selected CamAnimSet rejected: "+error);
  dh2::camera_animset_v1::PlaybackOwner selected_playback_owner;
  if(!selected_playback_owner.bind(selected))
   throw std::runtime_error("Source-selected CamAnimSet playback owner rejected its resource list");
  dh2::camera_animset_bank_v1::Owner selected_bank;
  if(!selected_bank.load(selected,read_camera_animset_asset,
                         player_camera_asset_manager,error))
   throw std::runtime_error("Source-selected CamAnimSet BDAE bank rejected: "+error);
  dh2::camera_animset_v1::PlayRequest idle_request{};
  if(!selected_playback_owner.level_idle(idle_request,error))
   throw std::runtime_error("Source camera idle request rejected: "+error);
  const auto* idle_clip=selected_bank.resolve(idle_request);
  if(!idle_clip)
   throw std::runtime_error("Source camera idle request is absent from its selected BDAE bank");
  const std::string idle_path=idle_request.resource.path;
  auto candidate=std::make_unique<dh2::player_camera_rig_v1::Rig>();
  dh2::player_camera_rig_v1::Assets camera_assets{
      camera_scene.data(),camera_scene.size(),
      idle_clip->bdae.data(),idle_clip->bdae.size()};
  camera_assets.camera_name=level.camera_name.c_str();
  if(!candidate->load(camera_assets,error))
   throw std::runtime_error("Authored player camera rig rejected: "+error);
  dh2::player_camera_rig_v1::Playback candidate_playback;
  dh2::player_camera_rig_v1::Pose initial{};
  if(!candidate->sample(candidate->animation_start(),&initial,error))
   throw std::runtime_error("Authored player camera initial pose rejected: "+error);
  const dh2::native::crypt_camera_frame_v1::Vec3 eye_offset{
      initial.camera[12]-initial.target[12],
      initial.camera[13]-initial.target[13],
      initial.camera[14]-initial.target[14]};
  player_camera_rig_default_target_distance=candidate->source_default_target_distance();
  if(!std::isfinite(player_camera_rig_default_target_distance)||
     player_camera_rig_default_target_distance<0.0f)
   throw std::runtime_error("CameraLevel::CalculateDefaultTargetDistance source nodes are invalid");
  player_camera_input_yaw=std::atan2(eye_offset[1],eye_offset[0]);
  player_camera_input_pitch=std::atan2(eye_offset[2],std::hypot(eye_offset[0],eye_offset[1]));
  player_camera_rig=std::move(candidate);
  player_camera_playback=std::move(candidate_playback);
  player_camera_animset_selection=std::move(selected);
  player_camera_animset_playback_owner=std::move(selected_playback_owner);
  player_camera_animset_bank=std::move(selected_bank);
  __android_log_print(ANDROID_LOG_INFO,"DH2Native",
      "Authored gameplay camera rig loaded | level %s | asset %s | CamAnimSet %s row %zu idle %d %s | tracks %u | clip %d..%d | BRES fov/aspect/clips %.4f/%.4f/%.0f..%.0f | runtime FOV from Level::_LoadCamera | eye %.3f %.3f %.3f | target %.3f %.3f %.3f",
      level.name.c_str(),camera_path.c_str(),
      selected.name.c_str(),selected.row,selected.idle_clip_id,idle_path.c_str(),
      player_camera_rig->track_count(),player_camera_rig->animation_start(),
      player_camera_rig->animation_end(),player_camera_rig->projection().source_fov_value,
      player_camera_rig->projection().aspect_ratio,player_camera_rig->projection().near_clip,
      player_camera_rig->projection().far_clip,initial.camera[12],initial.camera[13],initial.camera[14],
      initial.target[12],initial.target[13],initial.target[14]);
  return true;
 }catch(const std::exception& error){
  __android_log_print(ANDROID_LOG_ERROR,"DH2Native","Shared authored player camera rig unavailable: %s",error.what());
  return false;
 }
}
bool sample_player_camera_rig(std::uint32_t dt_ms,dh2::player_camera_rig_v1::Pose& pose){
 if(!ensure_player_camera_rig(active_level_assets,actor_animation_tables,actor_clip_table))return false;
 std::string error;
 if(!source_camera_level_owner_ready){
  if(!player_camera_rig->sample(player_camera_rig->animation_start(),&pose,error)){
   __android_log_print(ANDROID_LOG_ERROR,"DH2Native","Initial authored camera pose failed: %s",error.c_str());
   return false;
  }
  return true;
 }
 if(!dh2::camera_animset_bank_playback_v1::advance_rig(
      source_camera_level_owner,*player_camera_rig,player_camera_playback,
      dt_ms,&pose,error)){
  __android_log_print(ANDROID_LOG_ERROR,"DH2Native","Authored gameplay camera sample failed: %s",error.c_str());
  return false;
 }
 return true;
}

struct SourceLevelListenerContext {
 const dh2::player_camera_rig_v1::Pose* pose=nullptr;
};
bool source_listener_player_target(void*,dh2::engine_audio::spatial_playback_contract_v1::Vec3& out){
 if(!prince_character.identity())return false;
 sync_prince_search_projection();
 const auto& object=prince_search_projection.object;
 const auto* point=object.has_target_position?object.target_position:object.position;
 out={point[0],point[1],point[2]};
 return true;
}
bool source_listener_camera_look_at(void* raw,
    dh2::engine_audio::spatial_playback_contract_v1::Vec3& out){
 const auto* context=static_cast<const SourceLevelListenerContext*>(raw);
 if(!context||!context->pose)return false;
 const auto& matrix=context->pose->camera_world;
 out={matrix[4],matrix[5],matrix[6]};
 return true;
}
bool source_listener_camera_up(void* raw,
    dh2::engine_audio::spatial_playback_contract_v1::Vec3& out){
 const auto* context=static_cast<const SourceLevelListenerContext*>(raw);
 if(!context||!context->pose)return false;
 const auto& matrix=context->pose->camera_world;
 out={matrix[8],matrix[9],matrix[10]};
 return true;
}
void update_source_level_listener(const dh2::player_camera_rig_v1::Pose& pose){
 using namespace dh2::engine_audio;
 using namespace native_level_listener_v1;
 // Level::Level writes Level+0xe4 = 1 for the active gameplay Level;
 // Level::UpdateListener's process-static cache keeps the first selected row.
 FrameRequest request{};
 request.level_listener_index=1;
 request.listener_rows=spatial_playback_contract_v1::listener_profiles.data();
 request.listener_row_count=spatial_playback_contract_v1::listener_profiles.size();
 request.camera_node_present=true;
 request.player_object_present=prince_character.identity()!=0;
 SourceLevelListenerContext context{&pose};
 const Services services{&context,nullptr,source_listener_player_target,
     nullptr,nullptr,nullptr,source_listener_camera_look_at,
     source_listener_camera_up,nullptr};
 const auto result=update(request,services,process_state(),process_vox_state());
 if(result.status!=Status::updated){
  static unsigned warned_status=~0u;
  const auto status=static_cast<unsigned>(result.status);
  if(warned_status!=status){
   warned_status=status;
   __android_log_print(ANDROID_LOG_WARN,"DH2Native",
       "Source Vox listener update skipped | listener %d | status %u | provider %u",
       result.selected_listener_index,status,
       static_cast<unsigned>(result.failed_provider));
  }
 }
}
struct SourceCombatAudioContext {
 ObjectActor* receiver_actor=nullptr;
 std::uintptr_t receiver_player=0;
 AuthoredCryptFaeryOwner* receiver_faery=nullptr;
};
bool source_combat_random_index(void*,std::int32_t bound,std::int32_t& index){
 if(bound<=0)return false;
 const auto value=dh2_random_next(&dh2::random_lifecycle::process_state(),
     static_cast<std::uint32_t>(bound),0);
 if(value<0||value>=bound)return false;
 index=value;
 return true;
}
bool source_combat_play_3d(void* raw,std::uint16_t sound_id,
                           std::uintptr_t defender_identity){
 auto* context=static_cast<SourceCombatAudioContext*>(raw);
 if(!context)return false;
 float player_target[3]{};
 const float* point=nullptr;
 if(context->receiver_actor&&
    context->receiver_actor->identity==defender_identity&&
    context->receiver_actor->kind==1){
  sync_search_projection(*context->receiver_actor);
  const auto& object=context->receiver_actor->search_projection.object;
  point=object.has_target_position?object.target_position:object.position;
 }else if(context->receiver_player==defender_identity&&
          defender_identity==prince_character.identity()&&
          prince_combat.savegame&&
          prince_combat.savegame->character()==defender_identity){
  bool target_node=false;std::uint32_t node=UINT32_MAX;std::string error;
  if(!dh2::ui::resolve_scrolling_combat_target_node_v1(
       current_scene,target_node,node,player_target,error))return false;
  const auto visible=prince_character.visibility_80();
  point=target_node&&visible?player_target:prince_runtime.subobjects.position;
 }else if(context->receiver_faery&&
          context->receiver_faery->identity==defender_identity&&
          context->receiver_faery->record&&
          context->receiver_faery->record->character.identity==defender_identity&&
          dh2::character_faery_visual_facade_v1::ready(
             context->receiver_faery->record->faery_visual,defender_identity)) {
  auto& owner=*context->receiver_faery;
  auto& visual=owner.record->faery_visual;
  auto pose=std::dynamic_pointer_cast<AuthoredFaeryPose>(visual.pose);
  if(!pose)return false;
  auto scene=pose->bdae_resource().scene;
  const Matrix placement=faery_visual_placement(owner,visual);
  for(auto& node:scene.graph)node.world=dh2::scene::multiply(placement,node.world);
  bool target_node=false;std::uint32_t node=UINT32_MAX;std::string error;
  if(!dh2::ui::resolve_scrolling_combat_target_node_v1(
       scene,target_node,node,player_target,error))return false;
  const float fallback[]{owner.record->game_object.world_x,
      owner.record->game_object.world_y,visual.position[2]};
  point=target_node&&visual.visible?player_target:fallback;
 }else return false;
 const dh2::engine_audio::spatial_playback_contract_v1::Vec3 emitter{
     point[0],point[1],point[2]};
 dh2::engine_audio::spatial_playback_contract_v1::Request request{};
 auto& vox=dh2::engine_audio::native_level_listener_v1::process_vox_state();
 if(!dh2::engine_audio::native_level_listener_v1::make_spatial_request(
        vox,sound_id,emitter,request))return false;
 // F_ApplyCombatSound uses Play3D with its original non-looping source call;
 // the active non-Java pack path forwards only position and gain arguments.
 return dh2::player_gameplay_audio::enqueue_spatial_source_sound(
     sound_id,defender_identity,false,0,request);
}
void apply_player_source_combat_sound(ObjectActor& defender,
                                      const dh2::data::CombatResult& result){
 static bool warned_provider=false;
 if(!native_debug||
    native_debug->runtime().load(native_debug->globals(),native_debug->services())!=
      dh2::debug_switches::Status::complete){
  if(!warned_provider){warned_provider=true;__android_log_print(ANDROID_LOG_WARN,
      "DH2Native","Source combat sound skipped | DebugSwitches provider unavailable");}
  return;
 }
 std::uint8_t minimal_randoms=0;
 if(native_debug->runtime().get_switch("MP_MinimalRandoms",native_debug->globals(),
      native_debug->services(),minimal_randoms)!=dh2::debug_switches::Status::complete){
  if(!warned_provider){warned_provider=true;__android_log_print(ANDROID_LOG_WARN,
      "DH2Native","Source combat sound skipped | MP_MinimalRandoms query failed");}
  return;
 }
 SourceCombatAudioContext context{&defender,0};
 const dh2::character_combat_sound_v1::Services services{
     &context,source_combat_random_index,source_combat_play_3d};
 // IDA proves Character::F_ApplyCombatSound reads Sounds from resolved
 // Character property 8 (Character+0x1018) for both attacker and defender.
 const auto audio=dh2::player_gameplay_audio::apply_character_combat_sound(
     prince_combat.properties.resolved[8],defender.properties.resolved[8],
     defender.identity,result.amount,defender.combat_state.dead!=0,
     minimal_randoms!=0,services);
 if(audio.status!=dh2::character_combat_sound_v1::Status::complete&&
    audio.status!=dh2::character_combat_sound_v1::Status::minimal_randoms_suppressed){
  static unsigned warned_status=~0u;
  const auto status=static_cast<unsigned>(audio.status);
  if(warned_status!=status){
   warned_status=status;
   __android_log_print(ANDROID_LOG_WARN,"DH2Native",
       "Source combat sound incomplete | defender %s | status %u | random draws %u | playback attempts %u",
       defender.name.c_str(),status,audio.random_draws,audio.playback_attempts);
  }
 }
}
