bool apply_faery_source_combat_sound(AuthoredCryptFaeryOwner& owner,
    const dh2::data::CombatResult& result,std::string& error) {
 if(!owner.record||owner.record->character.identity!=owner.identity||
    !owner.properties_ready||owner.properties.resolved[8]!=2||!native_debug||
    !dh2::character_faery_visual_facade_v1::ready(
      owner.record->faery_visual,owner.identity)) {
  error="Faery F_ApplyCombatSound lacks the selected Default CharSounds row/visual owner";
  return false;
 }
 if(native_debug->runtime().load(native_debug->globals(),native_debug->services())!=
      dh2::debug_switches::Status::complete) {
  error="Faery F_ApplyCombatSound DebugSwitches load failed";return false;
 }
 std::uint8_t minimal_randoms=0;
 if(native_debug->runtime().get_switch("MP_MinimalRandoms",native_debug->globals(),
      native_debug->services(),minimal_randoms)!=dh2::debug_switches::Status::complete) {
  error="Faery F_ApplyCombatSound MP_MinimalRandoms query failed";return false;
 }
 SourceCombatAudioContext context{};context.receiver_faery=&owner;
 const dh2::character_combat_sound_v1::Services services{
     &context,source_combat_random_index,source_combat_play_3d};
 const auto audio=dh2::player_gameplay_audio::apply_character_combat_sound(
     owner.properties.resolved[8],owner.properties.resolved[8],owner.identity,
     result.amount,owner.record->serialized_dead_1449!=0,
     minimal_randoms!=0,services);
 if(audio.status!=dh2::character_combat_sound_v1::Status::complete&&
    audio.status!=dh2::character_combat_sound_v1::Status::minimal_randoms_suppressed) {
  error="Faery F_ApplyCombatSound selected source CharSounds provider failed";
  return false;
 }
 error.clear();return true;
}
