Matrix source_player_camera(int width,int height,std::uint32_t dt_ms){
 using namespace dh2::native::crypt_camera_frame_v1;
 using namespace dh2::camera_level_runtime_v1;
 Frame frame{};
 std::string error;
 dh2::player_camera_rig_v1::Pose pose{};
 if(!sample_player_camera_rig(dt_ms,pose)){
  dh2::engine_audio::native_level_listener_v1::process_vox_state().listener_ready=false;
  static bool warned=false;
  if(!warned){
   __android_log_print(ANDROID_LOG_WARN,"DH2Native",
      "Authored camera rig sample unavailable; keeping gameplay on the level camera fallback");
   warned=true;
  }
  return camera(width,height);
 }
 if(width>0&&height>0){
  const DrawableTargetSize target{width,height};
  if(target.width!=source_camera_drawable_target.width||
     target.height!=source_camera_drawable_target.height){
   source_camera_drawable_target=target;
   if(source_camera_level_owner_ready&&
      !source_camera_zoom_input.update_drawable_target(target))
    throw std::runtime_error("Source ZoomHandler rejected the resized drawable target");
   if(source_camera_overview_owner.live()&&
      !source_camera_overview_owner.resize(target))
    throw std::runtime_error("Source CameraOverview rejected the resized drawable target");
  }
 }
 const dh2::native::crypt_camera_frame_v1::Vec3 authored_target_offset{
     pose.target[12],pose.target[13],pose.target[14]};
 const dh2::native::crypt_camera_frame_v1::Vec3 authored_eye_offset{
     pose.camera[12]-pose.target[12],pose.camera[13]-pose.target[13],
     pose.camera[14]-pose.target[14]};
 const dh2::native::crypt_camera_frame_v1::Vec3 authored_up{
     pose.up_vector[12]-pose.camera[12],pose.up_vector[13]-pose.camera[13],
     pose.up_vector[14]-pose.camera[14]};
 player_camera_input_yaw=std::atan2(authored_eye_offset[1],authored_eye_offset[0]);
 player_camera_input_pitch=std::atan2(authored_eye_offset[2],
     std::hypot(authored_eye_offset[0],authored_eye_offset[1]));
 const auto camera_key=active_level_assets.name+"\n"+active_level_assets.level_file;
 if(source_camera_level_owner_key!=camera_key){
  source_camera_zoom_input.clear_camera();
 source_camera_level_owner=Owner{};source_camera_level_owner_ready=false;
  source_camera_level_root_position={};source_camera_level_pan_offset={};source_camera_level_has_frame=false;source_camera_level_owner_key=camera_key;
 }
 if(!source_camera_overview_owner.live()&&
    !source_camera_overview_owner.construct(
      source_camera_drawable_target.width>0&&source_camera_drawable_target.height>0
       ?source_camera_drawable_target:DrawableTargetSize{width,height}))
  throw std::runtime_error("Level::_LoadCamera CameraOverview construction failed");
 const dh2::native::crypt_camera_frame_v1::Vec3 actor_target{
     actor_position[0],actor_position[1],actor_position[2]};
 const auto actor_anchor=forward_anchor_target(&prince_camera_anchor,actor_target);
 if(!source_camera_design_zoom_bounds_ready)
  throw std::runtime_error("Source CameraLevel DesignSettings projection is not loaded");
 GameObjectSample target_object{};
 target_object.identity=reinterpret_cast<std::uintptr_t>(&prince_character);
 target_object.present=true;
 target_object.object_position={actor_target[0],actor_target[1],actor_target[2]};
 target_object.custom_anchor_present=prince_camera_anchor.has_target;
 target_object.custom_anchor_plus_12={actor_anchor[0],actor_anchor[1],actor_anchor[2]};
 if(!source_camera_level_owner_ready){
  if(!source_camera_level_owner.set_target(&target_object,0,nullptr))
   throw std::runtime_error("Source CameraTarget rejected the live Player owner");
  if(!std::isfinite(player_camera_rig_default_target_distance)||
     player_camera_rig_default_target_distance<=0.0f)
   throw std::runtime_error("Source CameraLevel default target distance is unavailable");
  source_camera_level_owner.set_default_target_distance(player_camera_rig_default_target_distance);
  // ZoomHandler reads the active IRenderTarget's drawable dimensions. The
  // authored SWF stage remains a separate 480x320 logical coordinate space.
  if(!source_camera_zoom_input.set_camera(&source_camera_level_owner,
       source_camera_drawable_target.width>0&&source_camera_drawable_target.height>0
        ?source_camera_drawable_target:DrawableTargetSize{width,height}))
   throw std::runtime_error("Source ZoomHandler could not bind the active CameraLevel owner");
  source_camera_level_root_position={actor_anchor[0],actor_anchor[1],actor_anchor[2]};
  dh2::camera_animset_v1::PlayRequest idle_request{};
  if(!player_camera_animset_playback_owner.level_idle(idle_request,error)||
     dh2::camera_animset_bank_playback_v1::start_rig(
       source_camera_level_owner,player_camera_animset_bank,idle_request,
       *player_camera_rig,player_camera_playback,error)!=
       dh2::camera_animset_bank_playback_v1::Status::started)
   throw std::runtime_error("Source Level::_LoadCamera Idle playback failed: "+error);
  source_camera_level_owner_ready=true;
  const auto level_owner=source_level_owner.snapshot();
  if(level_owner.phase!=dh2::source_level_owner_v1::Phase::active||
     !level_owner.source_level||!source_camera_overview_owner.live()){
   throw std::runtime_error("Level::_LoadCamera cleanup owners are not live for this source Level");
  }
  const auto current_cleanup=source_level_owner.snapshot();
  if(!current_cleanup.cleanup_index_74_known||!current_cleanup.cleanup_index_75_known){
   const auto camera_level_identity=reinterpret_cast<std::uintptr_t>(&source_camera_level_owner);
   const auto camera_overview_identity=source_camera_overview_owner.projection_identity();
   if(!camera_level_identity||!camera_overview_identity||
      !source_level_owner.bind_level_cleanup_owners(level_owner.source_level,
          camera_level_identity,camera_overview_identity))
    throw std::runtime_error("Level::_LoadCamera cleanup owner publication was rejected");
  }
 }
 // Level::UpdateCameraZoom runs before CameraLevel::Update and projects
 // Character +352 through the preceding active CameraBase matrix.
 if(source_camera_level_has_frame){
  dh2::camera_design_zoom_v1::ScreenPoint screen_point{};
  if(dh2::camera_design_zoom_v1::project_screen_point(
       source_camera.matrix.elements,actor_target[0],actor_target[1],actor_target[2],
       &screen_point)){
   float target_zoom=source_camera_level_owner.target_zoom();
   if(!dh2::camera_design_zoom_v1::update_target_zoom(
        source_camera_design_zoom_bounds,&screen_point,1,&target_zoom))
    throw std::runtime_error("Level::UpdateCameraZoom rejected the live Player screen margin");
   source_camera_level_owner.set_zoom(source_camera_level_owner.current_zoom(),target_zoom);
  }
 }
 FrameInput camera_input{};
 camera_input.active_camera=true;camera_input.camera_node_present=true;
 camera_input.target_cam_node_present=true;camera_input.target_game_object_present=true;
 // Script_SetCameraTarget: follow the named object instead of the Player.
 if(native_script_camera_target){
  float position[3]{};
  if(auto* actor=native_char_ai_actor(native_script_camera_target)){
   std::copy(actor->position.begin(),actor->position.end(),position);
   if(actor->spawn_owner&&actor->spawn_owner->runtime_ready)
    std::copy(actor->spawn_owner->runtime.subobjects.position,
              actor->spawn_owner->runtime.subobjects.position+3,position);
   target_object.identity=native_script_camera_target;
   target_object.object_position={position[0],position[1],position[2]};
   target_object.custom_anchor_present=false;
  }else if(native_level_script_position_for_target(native_script_camera_target,position)){
   target_object.identity=native_script_camera_target;
   target_object.object_position={position[0],position[1],position[2]};
   target_object.custom_anchor_present=false;
  }
 }
 if(native_script_camera_target_dirty&&source_camera_level_owner_ready){
  native_script_camera_target_dirty=false;
  if(!source_camera_level_owner.set_target(&target_object,native_script_camera_blend_ms,nullptr))
   throw std::runtime_error("Script_SetCameraTarget rejected by the source CameraTarget owner");
 }
 camera_input.target=target_object;
 camera_input.dt_ms=static_cast<std::int32_t>(std::min<std::uint32_t>(dt_ms,2000));
 camera_input.camera_world_position=source_camera_level_root_position;
 camera_input.animated_target_cam_offset=source_camera_level_pan_offset;
 camera_input.design_zoom_bounds=source_camera_design_zoom_bounds;
 FrameOutput camera_output{};
 const auto camera_status=source_camera_level_owner.update(camera_input,&camera_output);
 if(camera_status!=Status::transition_position_written&&
    camera_status!=Status::follow_position_written)
  throw std::runtime_error("Source CameraLevel/CameraTarget follow update rejected its live providers");
 source_camera_level_root_position=camera_output.camera_world_position;
 const dh2::native::crypt_camera_frame_v1::Vec3 target{
     camera_output.camera_world_position.x,
     camera_output.camera_world_position.y,
     camera_output.camera_world_position.z};
 if(!build_player_frame(target,width,height,&frame,kVerticalFovRadians,
           active_level_assets.camera_near_clip,active_level_assets.camera_far_clip,
           authored_eye_offset,authored_up,authored_target_offset,
           camera_output.target_cam_local_position.z,
           dh2::native::crypt_camera_frame_v1::Vec3{
               pose.target_parent_z_axis[0],pose.target_parent_z_axis[1],
               pose.target_parent_z_axis[2]}))
  throw std::runtime_error("Source gameplay camera frame rejected LevelConfig/viewport/actor");
 std::memcpy(source_camera.matrix.elements,frame.view_projection.data(),sizeof(source_camera.matrix.elements));
 std::memcpy(source_camera.frustum.position,frame.eye.data(),sizeof(source_camera.frustum.position));
 if(dh2::engine_camera::frustum_runtime::set_from(&source_camera.matrix,&source_camera.frustum)!=
    dh2::engine_camera::frustum_runtime::Status::complete)
  throw std::runtime_error("Source gameplay camera frustum rejected live frame");
 update_source_level_listener(pose);
 source_camera_level_has_frame=true;
 const bool resized=source_camera.width!=width||source_camera.height!=height;
 source_camera.width=width;source_camera.height=height;
 if((source_camera.frames++%128)==0||resized){
  __android_log_print(ANDROID_LOG_INFO,"DH2Native",
    "Source gameplay camera frame | %s | %dx%d | eye %.4f %.4f %.4f | target %.4f %.4f %.4f | camera-root %.4f %.4f %.4f | fov %.9g aspect %.9g near %.0f far %.0f | input yaw %.6g pitch %.6g | authored idle rig + CameraTarget follow/damping",
    active_level_assets.name.c_str(),
    width,height,frame.eye[0],frame.eye[1],frame.eye[2],frame.target[0],frame.target[1],frame.target[2],
    target[0],target[1],target[2],kVerticalFovRadians,frame.aspect,active_level_assets.camera_near_clip,
    active_level_assets.camera_far_clip,frame.input_yaw,frame.input_pitch);
 }
 return frame.view_projection;
}
bool load_source_level_camera_clip_planes(AAssetManager* assets,
    RuntimeLevelAssets& level,std::string& error){
 using dh2::native::level_camera_config_v1::ClipPlanes;
 std::vector<std::uint8_t> bytes;
 std::string_view xml;
 std::string source_path;
 try{
  if(level.generated_crypt_layout&&!level.generated_crypt_source_xml.empty()){
   xml=level.generated_crypt_source_xml;
   source_path="generated Crypt LevelConfig";
  }else if(const auto* static_level=static_mlx_level(level.name,level.level_file)){
   source_path=static_mlx_scene_path(*static_level);
   bytes=read(assets,source_path.c_str(),"original-cache");
   xml={reinterpret_cast<const char*>(bytes.data()),bytes.size()};
  }else if(generated_rule_level_name(level.name,level.level_file)){
   bytes=read(assets,level.level_file,"worlds");
   xml={reinterpret_cast<const char*>(bytes.data()),bytes.size()};
   source_path=level.level_file;
  }else{
   error="No source LevelConfig camera clip fields for "+level.name+" / "+level.level_file;
   return false;
  }
  ClipPlanes planes{};
  if(!dh2::native::level_camera_config_v1::parse_clip_planes(xml,&planes)){
   error="Source LevelConfig camera clip fields rejected in "+source_path;
   return false;
  }
  bool combat_music_enabled=true;
  if(!dh2::native::level_camera_config_v1::parse_combat_music_enabled(
      xml,&combat_music_enabled)){
   error="Source LevelConfig combat_music_enabled rejected in "+source_path;
   return false;
  }
  dh2::native::level_camera_config_v1::CameraRoute camera_route{};
  if(!dh2::native::level_camera_config_v1::parse_camera_route(xml,&camera_route)){
   error="Source LevelConfig camera route rejected in "+source_path;
   return false;
  }
  level.camera_near_clip=planes.near_clip;
  level.camera_far_clip=planes.far_clip;
  level.camera_near_clip_default=planes.near_clip;
  level.camera_far_clip_default=planes.far_clip;
  level.source_combat_music_enabled=combat_music_enabled;
  level.camera_file=std::move(camera_route.camera_file);
  level.camera_name=std::move(camera_route.camera_name);
  level.camera_animset=std::move(camera_route.animset);
  error.clear();
  return true;
 }catch(const std::exception& failure){
  error="Source LevelConfig camera read failed for "+level.name+": "+failure.what();
  return false;
 }
}
