bool request_menu_start(bool numeric,std::int32_t requested,std::int32_t& slot,std::string& error){
 // NativeStartGame returns before reading PlayerManager when the current
 // source Level is already in gameplay state 38. The renderer has one retained
 // active-world owner for that state; preserve the native no-op and avoid
 // queuing a second launch against a live Player/Save.
 if(world_mode){
  slot=-1;error.clear();
  __android_log_print(ANDROID_LOG_INFO,"DH2Native",
      "NativeStartGame ignored | retained current world maps to source Level state 38");
  return true;
 }
 // The authored button has already called the real NativeAssign service.
 // Return that same PlayerInfo's slot; the caller transports the parsed SWF
 // arguments until the deferred continuation resolves the source plan.
 if(!selected_menu_save_slot(slot,error))return false;
 __android_log_print(ANDROID_LOG_INFO,"DH2Native","Authored NativeStartGame request accepted | assigned PlayerInfo slot %d | numeric %d | requested difficulty %d | source LevelList resolution deferred until SWF dispatch unwinds",slot,numeric,requested);
 return true;
}
bool request_menu_continue(std::int32_t& slot,std::string& error){
 // Original MenuBase::FS_ContinueGame reads this exact SavegameManager+8
 // word. Keep it authoritative; when its PlayerInfo mirror has not yet been
 // associated in this process, use the existing source Assign owner to bind
 // that same slot before the shared deferred saved-Level resolver runs.
 if(world_mode){slot=-1;error.clear();return true;}
 const auto last_slot=native_host.last_slot_8;
 if(last_slot<0){slot=-1;error.clear();return true;}
 std::int32_t assigned=-1;std::string selection_error;
 if(!selected_menu_save_slot(assigned,selection_error)||assigned!=last_slot){
  if(!assign_menu_save_slot(last_slot,0,error))return false;
 }
 slot=last_slot;error.clear();
 __android_log_print(ANDROID_LOG_INFO,"DH2Native",
     "Authored FS_ContinueGame accepted | canonical SavegameManager last slot %d | saved LevelList/difficulty resolution deferred until SWF dispatch unwinds",
     slot);
 return true;
}
std::string start_menu_game(std::int32_t slot,AAssetManager* assets,std::int32_t debug_level_row,
    bool has_numeric_difficulty,std::int32_t requested_difficulty){
 std::string error;std::int32_t assigned=-1;
 if(!selected_menu_save_slot(assigned,error))return error;
 if(assigned!=slot)return "Start Game selected slot differs";
 try{
  native_host.select_metadata_slot(assigned);
  dh2::data::NativeStartGamePlanV1 plan;RuntimeLevelAssets runtime;
  GeneratedWorldPayload payload;
  if(!prepare_native_menu_start(assigned,has_numeric_difficulty,requested_difficulty,
      assets,debug_level_row,plan,runtime,payload,error))
   return "Start Game failed: "+error;
  active_native_start_plan=plan;active_level_assets=std::move(runtime);
  menu_gameplay_slot=assigned;
  __android_log_print(ANDROID_LOG_INFO,"DH2Native","NativeStartGame plan | slot %d | row %d | %s | source file %s | entry %d | spawn %u | raw seed args %u/%u | resolved local seed %u/%u | current difficulty %d | raw load difficulty %d | metadata SG_Save effects complete before native world load | layout %s",
   plan.slot,plan.level_row,plan.level_name.c_str(),plan.level_file.c_str(),plan.entry_point,
   unsigned(plan.load_spawn_flag),plan.seed,plan.synchronized_seed,active_level_assets.source_load_seed,
   active_level_assets.source_load_synchronized_seed,plan.difficulty_for_level,plan.requested_difficulty_for_load,
   active_level_assets.generated_crypt_layout?"source-generated":
    active_level_assets.development_layout?"development":"source-authored-static");
  const auto result=load_world(payload.dwld_v1.data(),payload.dwld_v1.size(),assets,
      payload.spwn_v1.empty()?nullptr:payload.spwn_v1.data(),payload.spwn_v1.size());
  if(result.rfind("World load failed:",0)==0){deactivate();menu_gameplay_slot=-1;active_native_start_plan.reset();active_level_assets=RuntimeLevelAssets{};}
  else{
   // Source Level::Update's first-update branch clears Vox +0x32 through
   // SetInSafeZoneMusic(false) when needed, then always writes +0x31 = true.
   // Mirror that source startup edge; SetMusicState/PlayMusic do not reset it.
   source_vox_music_state={};
   const auto source_music_uid=source_level_vxn_music_uid();
   if(source_music_uid){
    if(!dh2::player_gameplay_audio::enqueue_source_vxn_music_state(source_music_uid,"ambient"))
     __android_log_print(ANDROID_LOG_WARN,"DH2Native","Source Level ambient cue UID %u could not enter gameplay audio queue after committed level load",unsigned(source_music_uid));
    else __android_log_print(ANDROID_LOG_INFO,"DH2Native","Source Level VXN music | committed row %d | Sounds UID %u | state ambient queued",active_level_assets.row,unsigned(source_music_uid));
   }
  }
  return result;
 }catch(const std::exception& e){return std::string("Start Game failed: ")+e.what();}
}
std::vector<std::uint8_t> read_asset(AAssetManager* assets,const std::string& name){return read(assets,name,"");}
std::int32_t ui_current_level_name_id() noexcept {
 if(!world_mode)return -1;
 // IDA MenuCharMenu_Map::ShowLevelName (0x45335c) uses current Level+0x3c
 // as a LevelList index and reads row+0x24. The decoded row exposes that
 // source field as level_name_id.
 std::int32_t row=active_level_assets.row;
 if(row==-1)row=0;
 if(row<0||std::size_t(row)>=actor_level_tables.levels.size())return -1;
 return actor_level_tables.levels[std::size_t(row)].level_name_id;
}
