std::int32_t player_critical_camera_query(void* raw,
    const dh2::character_critical_camera_bridge_v1::QueryRequest& request,
    std::int32_t* value){
 using namespace dh2::character_critical_camera_bridge_v1;
 auto* context=static_cast<PlayerCritCameraContext*>(raw);
 if(!context||!value||request.character!=context->attacker||
    context->attacker!=prince_character.identity())return -1;
 switch(request.operation){
 case Query::requester_is_player:
  *value=1;return 0; // This callback is bound only to the canonical Player Character.
 case Query::local_player_count:{
  if(native_host.online)return -1; // Online PlayerManager route is not bound in this build.
  auto queries=native_host.locality_services();
  dh2::player_manager_friendly_v1::Services services{&queries,&native_host,nullptr};
  dh2::player_manager_friendly_v1::Result result{};
  if(dh2::player_manager_friendly_v1::get_num_players(
      &native_host.registry,&services,&result)!=
      dh2::player_manager_friendly_v1::Status::complete)return -1;
  *value=result.value;return 0;
 }
 case Query::requester_is_local:{
  const auto locality=native_host.locality_services();
  dh2::player_locality_v1::Result result{};
  if(dh2::player_locality_v1::is_local_player(&native_host.registry,
      &locality,request.character,&result)!=
      dh2::player_locality_v1::Status::complete)return -1;
  *value=result.value?1:0;return 0;
 }
 }
 return -1;
}
int player_critical_camera_before_regen(void* raw,dh2::data::CombatResult& result){
 auto* context=static_cast<PlayerCritCameraContext*>(raw);
 if(!context||context->attacker!=prince_character.identity())return -1;
 // The original caller skips this branch when there is no current CameraLevel.
 if(!world_mode||!source_camera_level_owner_ready||!player_camera_rig)return 0;
 using namespace dh2::character_critical_camera_bridge_v1;
 const Request request{&result,context->attacker,context,
                       player_critical_camera_query};
 dh2::camera_animset_v1::PlayRequest play{};Report report{};
 if(resolve(&request,player_camera_animset_playback_owner,&play,&report)!=
    Status::complete){
  __android_log_print(ANDROID_LOG_ERROR,"DH2Native",
      "Player critical camera result bridge failed | attacker %zu | queries %u/%u",
      std::size_t(context->attacker),report.queries_completed,report.queries_attempted);
  // This optional source camera side effect must not suppress the already
  // reached HitFor result or its following HP/MP regeneration.
  return 0;
 }
 if(!play.present)return 0;
 std::string error;
 const auto status=dh2::camera_animset_bank_playback_v1::start_rig(
     source_camera_level_owner,player_camera_animset_bank,play,
     *player_camera_rig,player_camera_playback,error);
 if(status!=dh2::camera_animset_bank_playback_v1::Status::started){
  // F_ApplyResult ignores CameraLevel::PlayAnim's return; a rejected camera
  // animation must not undo the already-applied hit or interrupt its tail.
  __android_log_print(ANDROID_LOG_WARN,"DH2Native",
      "Player critical Crit animation was not accepted | status %u | %s",
      unsigned(status),error.c_str());
  return 0;
 }
 __android_log_print(ANDROID_LOG_INFO,"DH2Native",
     "Player critical result started source Crit camera animation | attacker %zu | queries %u",
     std::size_t(context->attacker),report.queries_attempted);
 return 0;
}
bool combat_actor(ObjectActor& actor,combat_dispatch::Actor& output,std::string& error){
 output={actor.identity,0,nullptr};
 if(!actor.native_ai)return true;
 const auto active=actor.native_ai->state.active_ais_1c;
 if(!active)return true; // CharAI's source virtual call is a no-op without active AIS.
 const auto& owner=actor.native_ai->initialization;
 if(!owner||!owner->initialized||!owner->vm.ready()||owner->lifecycle.active!=active||
    owner->ais.identity!=active){
  error=std::string("active Monster AIS has no matching retained combat VM/VCB (")+actor.name+": "+
      (!owner?"no initialization owner":!owner->initialized?"not initialized":
       !owner->vm.ready()?"VM not ready":owner->lifecycle.active!=active?"lifecycle active differs":
       "AIS identity differs")+")";
  return false;
 }
 output.ais=active;output.flags_b8=&owner->ais.flags_b8;return true;
}
std::int32_t dispatch_native_combat_callback(void* raw,std::uintptr_t ais,
    combat_dispatch::Callback callback,std::uintptr_t attacker,std::uintptr_t defender){
 auto& context=*static_cast<NativeCombatDispatchContext*>(raw);
 const auto name=callback==combat_dispatch::Callback::target_hit?"OnTargetHit":"OnTargetMissed";
 std::uintptr_t player_ais=0;const std::uint32_t* player_flags=nullptr;
 for(auto* actor:{context.attacker,context.defender})if(actor&&
    (actor->identity==attacker||actor->identity==defender)&&actor->native_ai&&
    actor->native_ai->state.active_ais_1c==ais){
  const auto& owner=actor->native_ai->initialization;
  if(!owner||!owner->initialized||!owner->vm.ready()||owner->lifecycle.active!=ais||owner->ais.identity!=ais){
   context.owner_delivery_failed=true;
   __android_log_print(ANDROID_LOG_ERROR,"DH2Native","AIS combat callback owner mismatch | %s | %s | AIS %zu | retained Monster VM unavailable",actor->name.c_str(),name,std::size_t(ais));return -1;
  }
  std::string error;const auto event=callback==combat_dispatch::Callback::target_hit?
      dh2::monster_external_script::Event::target_hit:dh2::monster_external_script::Event::target_missed;
  const auto status=owner->vm.dispatch_combat_result(event,attacker,defender,error);
  if(status!=dh2::monster_external_script::Status::complete){static bool warned=false;if(!warned){warned=true;__android_log_print(ANDROID_LOG_WARN,"DH2Native",
   "AIS combat callback | %s | %s | attacker %zu | defender %zu | source ignored Lua Call status %u | %s",
   actor->name.c_str(),name,std::size_t(attacker),std::size_t(defender),unsigned(status),error.c_str());}}
  return status==dh2::monster_external_script::Status::complete?0:-1;
 }
 if((attacker==prince_character.identity()||defender==prince_character.identity())&&
    prince_source_ai&&prince_skills&&
    prince_source_ai->character_identity==prince_character.identity()&&
    prince_skills->combat_owner(player_ais,player_flags)&&player_ais==ais&&player_flags){
  std::string error;const int status=prince_skills->dispatch_combat_result(ais,callback,attacker,defender,error);
  if(status){static bool warned=false;if(!warned){warned=true;__android_log_print(ANDROID_LOG_WARN,"DH2Native",
   "AIS combat callback | Player | %s | attacker %zu | defender %zu | source ignored Lua Call status %d | %s",
   name,std::size_t(attacker),std::size_t(defender),status,error.c_str());}}
  return status;
 }
 context.owner_delivery_failed=true;
 __android_log_print(ANDROID_LOG_ERROR,"DH2Native","AIS combat callback owner not found | %s | AIS %zu | attacker %zu | defender %zu",
  name,std::size_t(ais),std::size_t(attacker),std::size_t(defender));
 return -1;
}
std::int32_t player_cast_state_callback(void* raw,
    const dh2::character_cast_lifecycle_v1::Request* request,
    dh2::character_cast_lifecycle_v1::Response* response){
 using namespace dh2::character_cast_lifecycle_v1;
 if(!raw||!request||!response||request->character!=prince_character.identity()||
    !prince_skills||!prince_skills->initialized())return -1;
 auto& host=*static_cast<PlayerSkillStateCallbackHost*>(raw);*response={};
 const auto debug_identity=reinterpret_cast<std::uintptr_t>(native_debug.get());
 const auto playback_identity=reinterpret_cast<std::uintptr_t>(&prince_locomotion);
 switch(request->operation){
 case Operation::debug_load:
  if(!native_debug||request->subject!=debug_identity)return -1;
  return native_debug->runtime().load(native_debug->globals(),native_debug->services())==
      dh2::debug_switches::Status::complete?0:-1;
 case Operation::string_construct:{
  if(request->subject!=debug_identity||!request->text)return -1;
  auto value=std::make_unique<std::string>(request->text);
  const auto id=reinterpret_cast<std::uintptr_t>(value.get());
  if(!id||!host.strings.emplace(id,std::move(value)).second)return -1;
  response->identity=id;return 0;
 }
 case Operation::debug_query:{
  const auto found=host.strings.find(request->string);
  if(!native_debug||request->subject!=debug_identity||found==host.strings.end())return -1;
  std::uint8_t value=0;
  if(native_debug->runtime().get_switch(found->second->c_str(),native_debug->globals(),
       native_debug->services(),value)!=dh2::debug_switches::Status::complete)return -1;
  response->identity=value;return 0;
 }
 case Operation::string_destroy:
  return host.strings.erase(request->subject)==1?0:-1;
 case Operation::raise_event:{
  if(request->subject!=prince_character.identity()||
     (request->argument!=32u&&request->argument!=33u)||
     prince_state.current!=7||!prince_combat.savegame||
     native_save_difficulty<0||native_save_difficulty>2)return -1;
  const auto slot=prince_combat.savegame->current_faery(
      static_cast<std::uint32_t>(native_save_difficulty));
  if(slot<0)return 0;
  dh2::native::player_skills::SkillCallbackResult result{};std::string error;
  const auto callback=request->argument==32u?
      dh2::native::player_skills::SkillCallback::pre:
      dh2::native::player_skills::SkillCallback::post;
  const int status=prince_skills->invoke_faery_callback(static_cast<std::uint32_t>(slot),
      callback,result,error);
  // CSCast::OnFocus (0x3c39d0) raises event 32 and then unconditionally runs
  // SM_SetAnim/ANIM_SetSpeed/CancelSneaking: Character::RaiseEvent discards
  // CharAI::_SpellFocus's OnPreSkill bool and LuaScript::Call swallows script
  // errors. OnBlur does the same for event 33. A script or provider failure must
  // therefore never abort the state callback (it would leave the Player in
  // state 7 with no cast animation to end it); keep it loud in the log instead.
  if(status!=0)__android_log_print(ANDROID_LOG_ERROR,"DH2Native",
      "CSCast %s script call failed; the source ignores it and the cast continues | faery slot %d | status %d | %s",
      request->argument==32u?"OnPreSkill":"OnPostSkill",slot,status,error.c_str());
  return 0;
 }
 case Operation::set_animation:{
  std::uintptr_t machine=0;
  if(request->argument!=UINT32_MAX||
     !prince_skills->cast_state_machine_identity(machine)||
     request->subject!=machine)return -1;
  std::int32_t animation=-1;std::string error;
  if(!prince_skills->select_skill_animation(playback_identity,-1,animation,error))return -1;
  // CSCast::OnFocus consumes the sequence prepared by SM_SetCastState through
  // the same CharStateMachine+0x28 override used by CSSkill.
  if(animation<0)return 0;
  return prince_locomotion.start(actor_animation_tables,animation,actor_random,
      prince_attack_clips,prince_visual,current_scene,1,error)?0:-1;
 }
 case Operation::set_speed:{
  if(request->subject!=playback_identity)return -1;
  float speed=0;std::memcpy(&speed,&request->argument,sizeof(speed));
  std::string error;return prince_locomotion.set_speed(speed,error)?0:-1;
 }
 case Operation::cancel_sneaking:
  if(request->subject!=prince_character.identity())return -1;
  {std::string error;return prince_skills->cancel_sneaking(
      &prince_character_byte_415,error)?0:-1;}
 }
 return -1;
}
bool dispatch_combat_result(ObjectActor* attacker,ObjectActor* defender,
    std::uintptr_t attacker_identity,std::uintptr_t defender_identity,
    const dh2::data::CombatResult& result){
 if(!attacker_identity||!defender_identity||attacker_identity==defender_identity)return false;
 // The source suppresses both AIS callbacks for this mask before resolving
 // either callback owner; a suppressed hit needs no live AIS provider.
 if(result.mask&0x20000000u)return true;
 combat_dispatch::Actor a{attacker_identity,0,nullptr},d{defender_identity,0,nullptr};std::string error;
 if(attacker&&!combat_actor(*attacker,a,error))goto failed;
 if(defender&&!combat_actor(*defender,d,error))goto failed;
 if(attacker_identity==prince_character.identity()){
  const std::uint32_t* flags=nullptr;
  if(!prince_skills||!prince_skills->combat_owner(a.ais,flags)||!flags){error="active Player AIS combat owner unavailable";goto failed;}
  a.character=attacker_identity;a.flags_b8=flags;
 }
 if(defender_identity==prince_character.identity()){
  const std::uint32_t* flags=nullptr;
  if(!prince_skills||!prince_skills->combat_owner(d.ais,flags)||!flags){error="active Player AIS combat owner unavailable";goto failed;}
  d.character=defender_identity;d.flags_b8=flags;
 }
 {
  NativeCombatDispatchContext context{attacker,defender};
  const combat_dispatch::Arguments arguments{&a,&d,&result};
  const combat_dispatch::Services services{&context,dispatch_native_combat_callback};
  combat_dispatch::Report report{};
  const auto status=combat_dispatch::dispatch(&arguments,&services,&report);
  if(status==combat_dispatch::Status::service_failed&&
     !context.owner_delivery_failed&&report.attempts>0&&report.failures>0){
   // AISDefault reaches LuaScript::Call for both selected Characters, but the
   // source ignores that call's return status. We still report the failure,
   // while allowing an already-applied hit to finish its source result tail.
   static bool warned=false;if(!warned){warned=true;__android_log_print(ANDROID_LOG_WARN,"DH2Native",
       "Source AIS combat callback returned failure; continuing result tail | attempts %u | failures %u | last %d",
       report.attempts,report.failures,report.last_status);}
  }else if(status!=combat_dispatch::Status::complete){
   error="source AIS combat dispatch failed (status "+std::to_string(int(status))+")";goto failed;
  }
  if(report.callbacks)__android_log_print(ANDROID_LOG_INFO,"DH2Native",
   "Combat AIS result dispatched | callback %s | owners %u | outcomes %u | mask %08x",
   report.selected==combat_dispatch::Callback::target_hit?"OnTargetHit":"OnTargetMissed",
   report.callbacks,result.outcomes,result.mask);
 }
 return true;
failed:
 __android_log_print(ANDROID_LOG_ERROR,"DH2Native","Combat AIS result dispatch failed after application | attacker %zu | defender %zu | %s",
  std::size_t(attacker_identity),std::size_t(defender_identity),error.c_str());
 return false;
}
