bool spell_npc_status_owner(void* raw,std::uintptr_t character,
                            ObjectActor** actor_out=nullptr) {
 auto* context=static_cast<SpellNpcStatusContext*>(raw);
 auto* actor=context?context->actor:nullptr;
 if(context&&context->player) {
  auto* properties=prince_skills?prince_skills->combat_status_properties():nullptr;
  auto* buffs=prince_skills?prince_skills->combat_status_buffs():nullptr;
  if(character!=prince_character.identity()||!native_actor_ready||!prince_skills||
     !prince_skills->initialized()||prince_skills->character_identity()!=character||
     !prince_character.bound()||prince_character.owner()!=character||
     !prince_character.source_state_handlers_complete()||!properties||!buffs||
     buffs->character_identity()!=character||
     properties->resolved!=prince_combat.properties.resolved.data()||
     prince_combat.properties.resolved.size()!=224)return false;
  if(actor_out)*actor_out=nullptr;
  return true;
 }
 if(!actor||actor->identity!=character||actor->kind!=1||!actor->spawn_owner||
    actor->spawn_owner->actor!=actor||
    actor->spawn_owner->character.owner()!=character||
    !actor->spawn_owner->runtime_ready||
    !actor->spawn_owner->character.source_state_handlers_complete()||
    !actor->spawn_owner->buffs||
    actor->spawn_owner->buffs->character_identity()!=character||
    actor->spawn_owner->buff_properties.resolved!=actor->properties.resolved.data()||
    actor->properties.resolved.size()!=224)return false;
 if(actor_out)*actor_out=actor;
 return true;
}
