int spell_status_animation_table_valid(void* raw,std::uintptr_t character,
    std::uint32_t* valid) {
 ObjectActor* actor=nullptr;
 if(!valid||!spell_npc_status_owner(raw,character,&actor))return 1;
 auto* context=static_cast<SpellNpcStatusContext*>(raw);
 if(context&&context->player) {
  const auto id=prince_combat.animation_table;
  const auto effective=id>=0&&static_cast<std::size_t>(id)<
      actor_animation_tables.characters.size()?id:17;
  *valid=effective>=0&&static_cast<std::size_t>(effective)<
      actor_animation_tables.characters.size()?1u:0u;
  return 0;
 }
 if(!actor||
    !actor->spawn_owner||actor->spawn_owner->actor!=actor||
    actor->spawn_owner->animation_table!=actor->animation_table_id)return 1;
 const auto id=actor->animation_table_id;
 const auto effective=id>=0&&static_cast<std::size_t>(id)<
     actor_animation_tables.characters.size()?id:17;
 *valid=effective>=0&&static_cast<std::size_t>(effective)<
     actor_animation_tables.characters.size()?1u:0u;
 return 0;
}
int spell_status_select_animation(void* raw,std::uintptr_t character,
    std::int32_t row_offset,std::uint32_t stance_mask,std::int32_t* animation) {
 ObjectActor* actor=nullptr;
 if(!animation||row_offset<0||(row_offset&3)!=0||
    !spell_npc_status_owner(raw,character,&actor))return 1;
 auto* context=static_cast<SpellNpcStatusContext*>(raw);
 const bool player=context&&context->player;
 if(!player&&(!actor||!actor->spawn_owner||
    actor->spawn_owner->animation_table!=actor->animation_table_id))return 1;
 const auto id=player?prince_combat.animation_table:actor->animation_table_id;
 const auto effective=id>=0&&static_cast<std::size_t>(id)<
     actor_animation_tables.characters.size()?id:17;
 if(effective<0||static_cast<std::size_t>(effective)>=
      actor_animation_tables.characters.size())return 1;
 const auto& row=actor_animation_tables.characters[static_cast<std::size_t>(effective)];
 // row_offset is a raw Structs::CharAnim byte offset (SM_SetKnockBackState
 // reads +36/+72, Dodging +32, Blocking +12, Injured +60, Scared +124,
 // Stunned +140). The port row stores scalar k at schema index k, so map the
 // dword with the original layout: 4(k+1) for k<=14, 4(k+2) for 16..30 and
 // 4(k+3) for 32..36. Interact (k=15) and Spells (k=31) arrays are rejected.
 const auto dword=row_offset/4;
 std::int32_t field_index=-1;
 if(dword>=1&&dword<=15)field_index=dword-1;
 else if(dword>=18&&dword<=32)field_index=dword-2;
 else if(dword>=35&&dword<=39)field_index=dword-3;
 if(field_index<0)return 1;
 const auto field=static_cast<std::size_t>(field_index);
 if(field>=row.fields.size()||row.fields[field].size()!=1)return 1;
 auto selected=row.fields[field][0];
 dh2_pycst_result source_mask{};
 if(!actor_skill_catalogue||!actor_skill_catalogue->animations_constants.bytes||dh2_pycst_get(&actor_skill_catalogue->animations_constants,"AnimStancedAnim",15,
      "SL__LIST_IPHONE",15,&source_mask)!=0||!source_mask.found)return 1;
 if(static_cast<std::uint32_t>(source_mask.value)&stance_mask) {
  dh2_pycst_result count{};
  if(dh2_pycst_get(&actor_skill_catalogue->animations_constants,"AnimStances",11,"COUNT_IPHONE",12,
       &count)!=0||!count.found||count.value<=0)return 1;
  std::int32_t stance=0;
  if(player) {
   if(prince_dead_state_get_anim_stance(nullptr,character,&stance)!=0)return 1;
  } else {
   const dh2::character::StanceFacts16 facts{0,count.value,{0,0}};
   if(dh2_character_anim_stance(&stance,&facts)!=1)return 1;
  }
  const auto bits=static_cast<std::uint32_t>(selected)+
                  static_cast<std::uint32_t>(stance);
  std::memcpy(&selected,&bits,sizeof(selected));
 }
 *animation=selected;return 0;
}
int spell_status_reaction_value(void* raw,std::uintptr_t character,float* value) {
 ObjectActor* actor=nullptr;
 if(!value||!spell_npc_status_owner(raw,character,&actor))return 1;
 auto* context=static_cast<SpellNpcStatusContext*>(raw);
 if(context&&context->player)
  return prince_character.read_reaction_gate_14fc(character,value)?
      (std::isfinite(*value)?0:1):1;
 *value=actor->reaction_gate_14fc;return std::isfinite(*value)?0:1;
}
int spell_status_prepare_reaction(void* raw,std::uintptr_t character) {
 ObjectActor* actor=nullptr;
 if(!spell_npc_status_owner(raw,character,&actor))return 1;
 auto* context=static_cast<SpellNpcStatusContext*>(raw);
 // Source SM_Set{Dodge,Block,Injured} calls Character::IsPlayer at vtable
 // byte +0x28 (the return is ignored), then writes 0x453b8000 to +0x14fc.
 if(context&&context->player)
  return prince_character.write_reaction_gate_14fc(character,3000.f)?0:1;
 std::uint32_t is_player=0;
 try {is_player=native_character_classification(*actor,
      dh2::character_ai_classification::Query::player);}
 catch(...) {return 1;}
 if(is_player>1)return 1;
 actor->reaction_gate_14fc=3000.f;return 0;
}
int spell_status_set_machine_animation(void* raw,std::uintptr_t character,
    std::int32_t animation) {
 ObjectActor* actor=nullptr;
 if(!spell_npc_status_owner(raw,character,&actor))return 1;
 auto* context=static_cast<SpellNpcStatusContext*>(raw);
 if(context&&context->player) {
  // SM_SetKnockBack/Injure/Dodging/BlockingState only write the machine's
  // pending +0x28 sequence; the state that accepts the event plays it through
  // SM_SetAnim(-1). A refused event (CSSkill, CSCast...) leaves it pending.
  prince_state.animation_override=animation;
  return 0;
 }
 if(!actor||!actor->spawn_owner||actor->spawn_owner->actor!=actor||
    actor->spawn_owner->character.owner()!=character)return 1;
 const dh2::character::Request request{dh2::character::set_animation,
     {animation,0,0},0.f,0,0};
 try {SpawnOwner::service(actor->spawn_owner.get(),
       &actor->spawn_owner->character.state,&request);}
 catch(...) {return 1;}
 return 0;
}
