int spell_status_recalculate(void* raw,std::uintptr_t character,
    dh2::data::PropertyView* properties,std::int32_t property) {
 ObjectActor* actor=nullptr;
 if(!properties||property<0||!spell_npc_status_owner(raw,character,&actor)||
    actor_class_rows.empty())return 1;
 auto* context=static_cast<SpellNpcStatusContext*>(raw);
 if(context&&context->player) {
  auto* canonical=prince_skills?prince_skills->combat_status_properties():nullptr;
  if(properties!=canonical||properties->resolved!=prince_combat.properties.resolved.data())return 1;
  return dh2_class_recalc_base(actor_class_rows.data(),
      static_cast<std::uint32_t>(actor_class_rows.size()),
      prince_combat.properties.base.data(),properties);
 }
 if(!actor||!actor->spawn_owner||properties!=&actor->spawn_owner->buff_properties||
    actor->spawn_owner->buff_properties.resolved!=actor->properties.resolved.data())return 1;
 return dh2_class_recalc_base(actor_class_rows.data(),
     static_cast<std::uint32_t>(actor_class_rows.size()),
     actor->properties.base.data(),properties);
}
dh2::character_combat_status_v1::Bindings spell_status_bindings(
    PlayerSpellCombatContext& context,SpellNpcStatusContext& status_context) {
 if(status_context.player) {
  auto* properties=prince_skills?prince_skills->combat_status_properties():nullptr;
  auto* buffs=prince_skills?prince_skills->combat_status_buffs():nullptr;
  if(!properties||!buffs||!prince_character.bound()||
     prince_character.owner()!=prince_character.identity()||
     !prince_character.source_state_handlers_complete()||
     buffs->character_identity()!=prince_character.identity()||
     properties->resolved!=prince_combat.properties.resolved.data())return {};
  status_context.actor=nullptr;
  return {prince_character.identity(),&prince_character,properties,buffs,
      {nullptr,spell_status_class_id,spell_status_effect_id},
      {&status_context,spell_status_is_boss,spell_status_reaction_value,
       spell_status_prepare_reaction,spell_status_animation_table_valid,
       spell_status_select_animation,spell_status_set_machine_animation,
       spell_status_read_machine_flags,spell_status_write_machine_flags,
       spell_status_set_character_flags,spell_status_recalculate}};
 }
 auto* actor=context.defender;
 auto* owner=actor?actor->spawn_owner.get():nullptr;
 if(!actor||!owner||owner->actor!=actor||owner->character.owner()!=actor->identity||
    !owner->buffs||owner->buffs->character_identity()!=actor->identity)return {};
 status_context.actor=actor;
 return {actor->identity,&owner->character,&owner->buff_properties,
     owner->buffs.get(),{nullptr,spell_status_class_id,spell_status_effect_id},
     {&status_context,spell_status_is_boss,spell_status_reaction_value,
      spell_status_prepare_reaction,spell_status_animation_table_valid,
      spell_status_select_animation,spell_status_set_machine_animation,
      spell_status_read_machine_flags,spell_status_write_machine_flags,
      spell_status_set_character_flags,spell_status_recalculate}};
}
bool spell_npc_effect(void* raw,std::uintptr_t character,bool death,
                      std::uint32_t* output) {
 auto* context=static_cast<PlayerSpellCombatContext*>(raw);
 auto* actor=context?context->defender:nullptr;
 if(!output||!actor||actor->identity!=character||actor->kind!=1||
    !actor->spawn_owner||actor->spawn_owner->actor!=actor||
    actor->spawn_owner->character.owner()!=character||!native_fx_catalog||
    native_fx_catalog->character_effects.empty()||actor->character_table_id<0||
    static_cast<std::size_t>(actor->character_table_id)>=
       actor_character_property_rows.size())return false;
 const auto field=std::find(actor_character_fields.begin(),
                            actor_character_fields.end(),"Effects");
 if(field==actor_character_fields.end())return false;
 const auto property=static_cast<std::size_t>(field-actor_character_fields.begin());
 const auto& source_row=actor_character_property_rows[
      static_cast<std::size_t>(actor->character_table_id)];
 if(property>=actor->properties.resolved.size()||property>=source_row.size()||
    actor->properties.resolved[property]!=source_row[property])return false;
 const auto source_index=actor->properties.resolved[property];
 if(source_index<0||static_cast<std::size_t>(source_index)>=
      native_fx_catalog->character_effects.size())return false;
 const auto effect_index=static_cast<std::size_t>(source_index);
 const auto& effects=native_fx_catalog->character_effects[effect_index];
 if(effects.row!=effect_index)return false;
 const auto effect=death?effects.blood_death_effect:effects.blood_effect;
 *output=static_cast<std::uint32_t>(effect);return true;
}
// The Player victim's blood effect: the same CharacterEffects row lookup keyed by
// its resolved Effects property that spell_npc_effect performs for an NPC.
bool spell_player_effect(bool death,std::uint32_t* output) {
 if(!output||!native_fx_catalog||native_fx_catalog->character_effects.empty())return false;
 const auto field=std::find(actor_character_fields.begin(),
                            actor_character_fields.end(),"Effects");
 if(field==actor_character_fields.end())return false;
 const auto property=static_cast<std::size_t>(field-actor_character_fields.begin());
 if(property>=prince_combat.properties.resolved.size())return false;
 const auto source_index=prince_combat.properties.resolved[property];
 if(source_index<0||static_cast<std::size_t>(source_index)>=
      native_fx_catalog->character_effects.size())return false;
 const auto effect_index=static_cast<std::size_t>(source_index);
 const auto& effects=native_fx_catalog->character_effects[effect_index];
 if(effects.row!=effect_index)return false;
 *output=static_cast<std::uint32_t>(death?effects.blood_death_effect:effects.blood_effect);
 return true;
}
