int skill_attack(void* raw,std::uintptr_t attacker_id,
    std::uintptr_t defender_id,std::uint32_t flags,std::int32_t element,
    dh2::data::CombatResult* result,std::string& error) {
 auto* context=static_cast<PlayerSpellCombatContext*>(raw);
 std::uintptr_t resolved=0;
 if(spell_resolve_character(context,defender_id,&resolved,error))return 1;
 auto* defender=resolved?spell_actor_by_identity(resolved):nullptr;
 if(!result||!spell_combat_actor_owner(context,attacker_id)||
    !spell_combat_actor_owner(context,defender_id)||
    (context->attacker_actor&&attacker_id!=context->attacker_actor->identity)||
    (defender&&context->defender&&context->defender!=defender)||!native_debug||
    (attacker_id!=prince_character.identity()&&
     (!context->attacker_actor||!context->attacker_actor->source_inventory||
      !context->attacker_actor->source_inventory->inventory))) {
  error="F_SkillAttack requires the same canonical attacker and defender Character owners";return 1;
 }
 if(native_debug->runtime().load(native_debug->globals(),native_debug->services())!=
      dh2::debug_switches::Status::complete) {
  error="F_SkillAttack DebugSwitches::load failed";return 1;
 }
 std::uint8_t trace=0;
 if(native_debug->runtime().get_switch("isTracingChar_Attack",
      native_debug->globals(),native_debug->services(),trace)!=
      dh2::debug_switches::Status::complete) {
  error="F_SkillAttack DebugSwitches::GetSwitch failed";return 1;
 }
 (void)trace;
 auto* attacker_actor=attacker_id==prince_character.identity()?nullptr:
     spell_actor_by_identity(attacker_id);
 auto& attacker_state=attacker_actor?attacker_actor->properties:
     prince_combat.properties;
 auto properties=dh2::data::property_view(actor_property_rules,attacker_state);
 auto* inventory=attacker_actor?
     (attacker_actor->source_inventory&&attacker_actor->source_inventory->inventory?
       attacker_actor->source_inventory->inventory.get():nullptr):
     prince_combat.inventory.get();
 if(!inventory||inventory->character()!=attacker_id) {
  error="F_SkillAttack has no canonical same-Character ItemInventory";return 1;
 }
 const auto attacker_state_id=attacker_actor?
     attacker_actor->spawn_owner->character.state.current:prince_state.current;
 const auto attacker_combo=attacker_actor?
     attacker_actor->combat_state.combo_hits:prince_combat.life.combo_hits;
 dh2::data::CombatantView attacker{attacker_state.resolved.data(),
     -1,-1,0,0,0,attacker_state_id,attacker_combo};
 dh2::data::PlayerEquipmentQueriesLiveV1 equipment(*inventory,properties);
 if(!equipment.combat_view(attacker,error))return 1;
 const auto& defender_properties=defender?defender->properties:
     prince_combat.properties;
 const auto defender_state_id=defender?defender->spawn_owner->character.state.current:
     prince_state.current;
 const auto defender_combo=defender?defender->combat_state.combo_hits:
     prince_combat.life.combo_hits;
 dh2::data::CombatantView target{defender_properties.resolved.data(),
     -1,-1,0,0,0,defender_state_id,defender_combo};
 const bool offhand=(flags&dh2::character_skill_combat_roll_v1::offhand_attack_flag)!=0;
 const auto category=offhand?attacker.off_damage_class:attacker.main_damage_class;
 const dh2::data::CombatResultRequest request{&attacker,&target,
     &combat_random,flags|0x08000000u,category,element,0};
 if(dh2_combat_result(result,&request)) {
  error="source _F_CalculateResult rejected F_SkillAttack arguments";return 1;
 }
 context->defender=defender;
 context->apply_attacker=attacker_id;context->apply_defender=defender_id;
 context->kill={defender,attacker_id,false,{}};
 context->camera={attacker_id};error.clear();return 0;
}
