bool ui_player_select_class_specialization(std::uintptr_t identity,
                                            std::int32_t selector,
                                            std::string& error){
 std::uintptr_t current=0;
 if(!ui_player_identity(current,error)||identity!=current||
    !prince_combat.profile_characters||!prince_combat.savegame||
    prince_combat.profile_characters->names.size()!=prince_combat.profile_characters->rows.size()||
    prince_combat.savegame->character()!=identity||
    prince_combat.character_class!=prince_combat.savegame->class_id()||
    prince_combat.character_class<0||
    std::size_t(prince_combat.character_class)>=prince_combat.profile_characters->rows.size()||
    !prince_skills||!prince_skills->initialized()||!prince_combat.save_transport||
    &prince_combat.save_transport->loader().save()!=prince_combat.savegame.get()){
  if(error.empty())error="NativeSelectClassSpec requires the active same-Character Player, Save, AI and CharacterTable";
  return false;
 }
 if(selector<0||selector>1){
  error="NativeSelectClassSpec selector must be 0 or 1";return false;
 }
 const auto target=std::int64_t(prince_combat.character_class)+1+selector;
 if(target<0||target>=std::int64_t(prince_combat.profile_characters->rows.size())){
  error="NativeSelectClassSpec target is outside the CharacterTable";return false;
 }
 if(!dh2::data::property(*prince_combat.profile_characters,
     prince_combat.profile_characters->names[std::size_t(target)],"ClassID")){
  error="NativeSelectClassSpec selected CharacterTable row has no ClassID";return false;
 }
 UiClassSpecializationContext context{identity};
 const dh2::class_specialization_selection_v1::Services services{
     &context,ui_class_spec_load_properties,ui_class_spec_set_class,
     ui_class_spec_reload_skills,ui_class_spec_save};
 dh2::class_specialization_selection_v1::Result result{};
 const auto status=dh2::class_specialization_selection_v1::select(
     prince_combat.character_class,selector,prince_combat.profile_characters->rows.size(),
     services,&result,error);
 return status==dh2::class_specialization_selection_v1::Status::complete;
}
bool native_host_sync_player_class(std::uintptr_t identity,std::int32_t target,
                                   std::string& error){
 if(identity!=prince_character.identity()||!prince_combat.savegame||
    prince_combat.savegame->character()!=identity||!prince_combat.profile_characters||
    target<0||std::size_t(target)>=prince_combat.profile_characters->rows.size()||
    std::size_t(target)>=prince_combat.profile_characters->names.size()){
  error="PlayerManager class synchronization crossed the canonical CharacterTable/Save";return false;
 }
 if(prince_combat.savegame->class_id()==target){error.clear();return true;}
 UiClassSpecializationContext context{identity};
 if(!ui_class_spec_load_properties(&context,target,error)||
    !ui_class_spec_set_class(&context,target,error)||
    !ui_class_spec_reload_skills(&context,error))return false;
 error.clear();return true;
}
bool ui_player_name(std::uintptr_t identity,std::string& name,std::string& error){
 std::uintptr_t current=0;
 if(!ui_player_identity(current,error))return false;
 if(identity!=current){error="Gameplay UI name query crossed the active Player Character owner";return false;}
 name=prince_combat.savegame->name();error.clear();return true;
}

bool native_host_sync_player_class(std::uintptr_t,std::int32_t,std::string&);

// PlayerManager::_ManageCharacters offline branches, limited to the one
// retained local Player Character. Every write targets the existing
// PlayerInfo, Save, PropertyState, inventory, and Player skill runtime owners.
bool native_host_sync_playerinfo_character(std::string& error){
 using namespace dh2;
 if(native_host.online||!native_host.registry_owner||!native_host.metadata_record||
    !native_host.metadata||!prince_combat.savegame||!prince_combat.save_transport||
    !prince_combat.source_save_association||!prince_combat.inventory||!prince_skills||
    !prince_skills->initialized()){
  error="PlayerManager offline sync lacks the canonical PlayerInfo, Save, inventory, or skill owners";return false;
 }
 auto* projection=native_host.host_projection();
 auto* record=native_host.record_for(projection);
 const auto character=prince_character.identity();
 const auto level_snapshot=source_level_owner.snapshot();
 const auto& pm=native_host.player_manager_update;
 const bool active_branch=pm.remove_flag_6c9_known&&
                          pm.manager_remove_flag_6c9==1;
 if(!pm.created_character_count_known||!pm.remove_flag_6c9_known||
    pm.manager_identity!=native_host.registry.manager_identity||
    pm.local_death_count_6c4!=1||pm.counted_player_character!=character||
    level_snapshot.phase!=source_level_owner_v1::Phase::active||
    !level_snapshot.source_level||
    (active_branch&&(level_snapshot.source_level_state!=38||
                     prince_combat.life.dead))||
    (!active_branch&&(pm.manager_remove_flag_6c9!=0||
                      level_snapshot.source_level_state!=0))){
  error="PlayerManager::_ManageCharacters reached an unsupported Level/manager/Player lifecycle branch";return false;
 }
 if(!projection||!record||record!=native_host.metadata_record||
    !record->constructed||!record->local_66c||record->save_slot_664<0||
    !native_host.metadata_ready_for_slot(record->save_slot_664)||
    !character||record->character_660!=character||
    prince_character.save_for(character)!=prince_combat.savegame.get()||
    prince_combat.savegame->character()!=character||
    prince_combat.inventory->character()!=character||
    prince_combat.inventory->properties()!=&prince_combat.properties||
    !prince_combat.source_save_association->same_owners(character,
       *prince_combat.savegame,prince_combat.save_transport->loader())||
    prince_skills->character_identity()!=character){
  error="PlayerManager offline sync crossed the canonical PlayerInfo/Character/Save owners";return false;
 }
 auto* active_level_member=record->at(0x310);
 if(active_branch&&(!active_level_member||!active_level_member->constructed||
    active_level_member->kind!=netstruct_members_v1::Kind::integer||
    active_level_member->header.value!=prince_combat.savegame->level())){
  error="PlayerManager active sync cannot represent a reached PlayerLevelUp script/FX branch";return false;
 }
 if(active_branch){
  const auto* active_transition=record->at(0x4c8);
  if(!active_transition||!active_transition->constructed||
     active_transition->kind!=netstruct_members_v1::Kind::boolean){
   error="PlayerManager active sync requires the source PlayerInfo+0x4c8 status member";return false;
  }
  const auto expected_loaded=std::uint8_t(level_snapshot.transition_flag_144?1:0);
  if(active_transition->header.reserved[0]!=expected_loaded&&
     !native_gameplay_ui&&
     (!native_level_transition_context||!native_level_transition_context->ui)){
   error="PlayerManager active sync needs the retained HUDRoot for the changed +0x4c8 callback";return false;
  }
 }

 // Source compares PlayerInfo's name against the selected +680 Save and
 // writes the Save name back to the same NetStructString on a mismatch.
 const auto* name_member=record->at(0x2b0);
 if(!name_member||!name_member->constructed||name_member->kind!=netstruct_members_v1::Kind::string32){
  error="PlayerManager offline sync selected Save name member is unavailable";return false;
 }
 if(name_member->text!=native_host.metadata->save().name()&&
    player_info_record_v1::set_character_name(*record,native_host.metadata->save().name())!=
      player_info_record_v1::Status::complete){
  error="PlayerManager offline sync could not publish the selected Save name";return false;
 }
 const auto player_name=record->at(0x2b0)->text;
 prince_combat.savegame->set_player_name(player_name);

 // _LoadPropertiesForClassSelect / SG_SetPlayerClass / AI_ReloadSkills are
 // reached only while the current Level's +0x144 transition flag is set.
 // IDA 0x373290: SG_SetPlayerClass from PlayerInfo is in the online unpack
 // only; offline it reloaded the skill list and cleared the starter slots.
 if(native_host.online&&level_snapshot.transition_flag_144){
  const auto* class_member=record->at(0x360);
  if(!class_member||!class_member->constructed||
     !native_host_sync_player_class(character,class_member->header.value,error))return false;
 }

 // IDA PlayerManager::_ManageCharacters 0x37280c: with an existing local
 // Character and GetOnline()+5 clear (0x372b84) both the pack and unpack
 // blocks are skipped. Gold, potions, Properties 33/36, level and skill
 // rows only travel PlayerInfo -> Character online (0x373330..0x373560).
 if(native_host.online){
 // The source's selected-save synchronization reaches ItemInventory setters
 // on this Character before the later level/skill fields.
 const auto gold=record->at(0x478);
 const auto potions=record->at(0x338);
 if(!gold||!potions||!gold->constructed||!potions->constructed||
    !prince_combat.inventory->set_gold(gold->header.value,
       prince_combat.save_inventory_services,error)){
  if(error.empty())error="PlayerManager offline sync gold member is unavailable";
  return false;
 }
 // PlayerInfo +0x338 still holds the unset -1 sentinel until a source
 // writer publishes it; ItemInventory::SetPotionQty would store 0xffffffff.
 // Keep the canonical inventory's potion stack until then.
 const auto potion_target=potions->header.value==-1?
     prince_combat.inventory->num_potions():potions->header.value;
 if(potion_target<0||potion_target>32767){error="PlayerManager SetPotionQty value is outside the source signed16 domain: "+std::to_string(potion_target);return false;}
 auto potion_count=prince_combat.inventory->num_potions();
 if(potion_count<0){error="Canonical Player potion Item has a negative source quantity";return false;}
 if(!prince_combat.inventory->potion()&&potion_target>0){
  const auto& table=prince_combat.inventory->table();
  const auto found=std::find_if(table.rows.begin(),table.rows.end(),
      [](const data::Item& item){return item.name=="Potion0";});
  if(found==table.rows.end()){error="ItemTable Potion0 row unavailable for source SetPotionQty";return false;}
  const auto item_id=std::int32_t(found-table.rows.begin());
  std::unique_ptr<data::ItemInstanceV1> incoming;
  if(!prince_combat.inventory->create_item(item_id,std::uint32_t(potion_target),incoming,
       prince_combat.save_inventory_services,error))return false;
  std::int32_t item_index=-1;
  if(!prince_combat.inventory->add_item(incoming,true,false,item_index,
       prince_combat.save_inventory_services,error))return false;
  potion_count=prince_combat.inventory->num_potions();
 }
 if(potion_count<potion_target){
  auto* potion=const_cast<data::ItemInstanceV1*>(prince_combat.inventory->potion());
  if(!potion||!prince_combat.inventory->add_quantity_to_item(*potion,potion_target-potion_count,error))return false;
 }else while(potion_count>potion_target){
  if(!prince_combat.inventory->remove_one_potion(prince_combat.save_inventory_services,error))return false;
  potion_count=prince_combat.inventory->num_potions();
 }

 auto view=data::property_view(actor_property_rules,prince_combat.properties);
 for(const auto item:std::array<std::pair<std::uint32_t,std::int32_t>,2>{{
       {0x428,33},{0x450,36}}}){
  const auto* member=record->at(item.first);
  if(!member||!member->constructed||dh2_property_set_int(&view,item.second,member->header.value)){
   error="PlayerManager offline sync XP/progression property write failed";return false;
  }
 }

 // Character::SG_SetPlayerLevel writes this same gameplay Save. The source
 // Property 19 boundary is applied through its live PropertyView.
 const auto* level=record->at(0x310);
 if(!level||!level->constructed||level->header.value<0){error="PlayerManager offline sync level member unavailable";return false;}
 prince_combat.savegame->set_player_level(level->header.value);
 // PlayerManager::_ManageCharacters 0x37280c: PROPS_SetInt(19,
 // ((level<<8)-CharacterTable base)>>8), so the resolved Level equals the Save.
 if(dh2_property_set_int(&view,19,
      std::int32_t((std::int64_t(level->header.value)*256-prince_combat.properties.base[19])>>8))){
  error="PlayerManager offline sync level property write failed";return false;
 }

 // Source's three skill slots are signed bytes; values below -1 normalize to
 // -1. Skill levels are the first 30 signed bytes and negative entries do not
 // overwrite the existing Save row.
 const auto* slots=record->at(0x3d8);
 const auto* skill_levels=record->at(0x400);
 if(!slots||!skill_levels||!slots->constructed||!skill_levels->constructed||
    slots->kind!=netstruct_members_v1::Kind::byte_array||
    skill_levels->kind!=netstruct_members_v1::Kind::byte_array||
    slots->bytes.size<3||skill_levels->bytes.size<30||
    !prince_combat.savegame->skills_initialized()){
  error="PlayerManager offline sync skill arrays or initialized Save rows are unavailable";return false;
 }
 struct SkillUpdateContext { std::uintptr_t character; dh2::native::player_skills::Runtime* skills; };
 SkillUpdateContext skill_context{character,prince_skills.get()};
 const data::SavedSkillUpdateServicesV1 skill_services{&skill_context,
  [](void* raw,std::uintptr_t identity,std::string& callback_error)->bool{
   auto& context=*static_cast<SkillUpdateContext*>(raw);
   if(identity!=context.character||!context.skills||!context.skills->initialized()){
    callback_error="PlayerManager skill update crossed the canonical Player Character";return false;
   }
   return context.skills->update_after_saved_skill_slot_write(callback_error);
  }};
 for(std::int32_t slot=0;slot<3;++slot){
  auto row=std::int32_t(static_cast<std::int8_t>(slots->bytes.data[slot]));
  if(row<-1)row=-1;
  const auto previous=prince_combat.savegame->skill_in_slot(slot);
  if(previous==row)continue;
  const auto saved_row=row<0?UINT32_MAX:std::uint32_t(row);
  if(!prince_combat.savegame->set_skill_in_slot(slot,saved_row,skill_services,error))return false;
 }
 bool skill_level_changed=false;
 for(std::uint32_t row=0;row<30&&row<prince_combat.savegame->skills().size();++row){
  const auto incoming=std::int32_t(static_cast<std::int8_t>(skill_levels->bytes.data[row]));
  if(incoming<0||prince_combat.savegame->skill_level(row)==incoming)continue;
  if(!prince_combat.savegame->set_skill_level(row,incoming,error))return false;
  skill_level_changed=true;
 }
 if(skill_level_changed&&!prince_skills->update_after_saved_skill_slot_write(error))return false;
 }

 // _ManageCharacters synchronizes both source transition fields from the
 // active Level. The unload path sees state 0; the loaded path sees state 38.
 // A +0x4e5 change restarts the source resend timer before SetVisible.
 const auto level_state=level_snapshot.source_level_state;
 auto* transition=record->at(0x4c8);auto* progress=record->at(0x508);
 const auto old_transition=transition&&transition->constructed?
     transition->header.reserved[0]:0;
 const std::uint8_t expected_transition=active_branch?
     std::uint8_t(level_snapshot.transition_flag_144?1:0):0;
 const std::uint8_t expected_progress=level_state>35?1:0;
 if(!transition||!progress||!transition->constructed||!progress->constructed||
    netstruct_members_v1::set_bool(*transition,expected_transition)!=netstruct_members_v1::Status::complete||
    netstruct_members_v1::set_bool(*progress,expected_progress)!=netstruct_members_v1::Status::complete){
  error="PlayerManager::_ManageCharacters could not publish same-Player Level-state flags";return false;
 }
 if(old_transition!=expected_transition)
  native_host.player_manager_update.force_resend_timer=2000;
 if(active_branch&&prince_state.current==0&&
    prince_character.transition(3)<0){
  error="PlayerManager active sync could not apply source SM_SetIdleState(false) to the retained Character";return false;
 }
 prince_character.set_visible(expected_transition);
 if(active_branch&&old_transition!=expected_transition){
  auto* ui=native_gameplay_ui;
  if(!ui&&native_level_transition_context)ui=native_level_transition_context->ui;
  if(!ui||!ui->complete_source_hud_refresh(error)){
   if(error.empty())error="PlayerManager active sync changed PlayerInfo+0x4c8 without the retained HUDRoot callback";
   return false;
  }
 }
 error.clear();return true;
}
