bool native_level_quick_save_v1(bool force,std::string& error) {
 const auto source=source_level_owner.snapshot();
 if(source.phase!=dh2::source_level_owner_v1::Phase::active||
    (source.source_level_state!=38&&source.source_level_state!=0)||!source.source_level||
    !source.source_level_savegame||source.player_character!=prince_character.identity()||
    !prince_combat.savegame||source.canonical_player_savegame!=
       reinterpret_cast<std::uintptr_t>(prince_combat.savegame.get())){
  error="Level::QuickSave requires the active Level/Save/Player owner chain";return false;
 }
 std::uint32_t words[3]{};
 if(source.source_level_state==38){
  const float* position=prince_runtime.subobjects.position;
  if(!position){error="Level::QuickSave current Character position is unavailable";return false;}
  for(unsigned i=0;i<3;++i){
   if(!std::isfinite(position[i])){error="Level::QuickSave Character position is non-finite";return false;}
   std::memcpy(&words[i],&position[i],sizeof(words[i]));
  }
 }
 const dh2::level_quick_save_v1::State state{
     source.source_level,source.source_level_savegame,source.player_character,
     source.source_level_state,std::int32_t(prince_combat.life.dead),
     native_host.online,0,0,words[2],words[0],words[1],
     source_level_owner.level_savegame().gate_39()};
 const dh2::level_quick_save_v1::Services services{
     nullptr,&native_level_quick_save_copy_position_v1,
     &native_level_quick_save_gate_v1,&native_level_quick_save_save_v1};
 dh2::level_quick_save_v1::Result result{};
 const auto status=source_level_owner.quick_save(&state,force?1u:0u,
     &services,&result,error);
 if(status==dh2::level_quick_save_v1::Status::saved||
    status==dh2::level_quick_save_v1::Status::skipped){error.clear();return true;}
 if(error.empty())error="Level::QuickSave source kernel failed";
 return false;
}
bool native_level_save_all_players_v1(bool force,std::string& error) {
 if(native_host.online||!prince_combat.savegame||
    !prince_character.identity()||prince_combat.savegame->character()!=
       prince_character.identity()){
  error="Level::SG_SaveAllPlayer currently supports only the retained offline local Player";
  return false;
 }
 // The local PlayerInfo is the active metadata record (its +0x660 is set when
 // the Player is added); the fallback record is used only without a profile.
 const auto* local_record=native_host.metadata_record?native_host.metadata_record:&native_host.fallback;
 if(native_host.registry.manager_plus_8!=&native_host.player||
    native_host.registry.manager_identity==0||
    local_record->character_660!=prince_character.identity()){
  error="Level::SG_SaveAllPlayer PlayerManager does not expose the canonical local Character";
  return false;
 }
 // Level::SG_SavePlayer 0x3efa54: with `force` it first clears the Player's SG
 // block (Character::SG_Block(false)), saves, then writes the captured block
 // byte back; without `force` a blocked PlayerSavegame::SG_Save is a no-op
 // (handled inside ui_player_save_game).
 auto& save=*prince_combat.savegame;
 const bool was_blocked=save.source_save_blocked();
 if(force)save.set_source_save_blocked(false);
 const bool saved=ui_player_save_game(prince_character.identity(),error);
 if(force)save.set_source_save_blocked(was_blocked);
 return saved;
}
bool ui_player_save_trophy_side_effects(std::uintptr_t identity,std::string& error){
 std::uintptr_t current=0;if(!ui_player_identity(current,error))return false;
 if(identity!=current||identity!=prince_character.identity()||
    !prince_combat.savegame||prince_combat.savegame->character()!=identity||
    !actor_design.bytes){
  error="NativeSaveGame trophy tail requires the active Player's canonical Save and design constants";return false;
 }
 const auto read_constant=[&](const char* key,std::int32_t& value){
  dh2_pycst_result result{};
  if(dh2_pycst_get(&actor_design,"CharacterDesign",15,key,
       std::uint32_t(std::strlen(key)),&result)){
   error=std::string("NativeSaveGame design constant lookup failed: ")+key;return false;
  }
  // PyDataConstants::getConstant returns zero when the key is absent.
  value=result.found?result.value:0;return true;
 };
 std::int32_t max_skill_level=0,max_character_level=0;
 if(!read_constant("MaxSkillLevelDVeryHard",max_skill_level)||
    !read_constant("MaxLevelDVeryHard",max_character_level))return false;
 const auto fixed_int=[](std::int32_t raw){
  return raw>=0?raw/256:-static_cast<std::int32_t>((-std::int64_t(raw)+255)/256);
 };
 std::vector<std::int32_t> skill_levels;skill_levels.reserve(prince_combat.savegame->skills().size());
 for(std::uint32_t i=0;i<prince_combat.savegame->skills().size();++i)
  skill_levels.push_back(prince_combat.savegame->skill_level(i));
 const auto unlock=[&](const char* name,std::string& failure){
  return unlock_source_trophy(name,"NativeSaveGame",failure);
 };
 return dh2::ui::apply_skill_save_trophy_effects_v1(
     skill_levels,true,max_skill_level,
     fixed_int(prince_combat.properties.resolved[157]),
     fixed_int(prince_combat.properties.resolved[19]),max_character_level,
     unlock,error);
}
bool ui_player_apply_level_up_state(std::uintptr_t identity,std::string& error){
 std::uintptr_t current=0;if(!ui_player_identity(current,error))return false;
 if(identity!=current||!prince_combat.savegame||!prince_combat.profile_characters||
    !prince_combat.save_transport||
    &prince_combat.save_transport->loader().save()!=prince_combat.savegame.get()||
    prince_combat.savegame->character()!=identity||
    prince_combat.character_class!=prince_combat.savegame->class_id()||
    prince_combat.character_class<0||
    std::size_t(prince_combat.character_class)>=prince_combat.profile_characters->rows.size()||
    prince_combat.profile_characters->names.size()!=prince_combat.profile_characters->rows.size()||
    actor_class_rows.empty()||!native_debug){
  if(error.empty())error="Character::LevelUp requires the active same-Character Player, Save, tables, and Debug owner";
  return false;
 }
 auto view=dh2::data::property_view(actor_property_rules,prince_combat.properties);
 const dh2::character_level_up_properties_v1::Owner owner{
  identity,&view,prince_combat.savegame.get(),prince_combat.properties.base.data()};
 dh2::character_level_up_properties_v1::Result prefix{};
 auto status=dh2::character_level_up_properties_v1::apply(&owner,&prefix);
 if(status!=dh2::character_level_up_properties_v1::Status::complete){
  error="Character::LevelUp AddInt(19,1)/SetInt(33,0) property prefix failed";return false;
 }
 status=dh2::character_level_up_properties_v1::update_base_properties(
  &owner,&actor_property_rules,prince_combat.profile_characters.get(),
  &actor_class_tables,prince_combat.character_class,&prefix);
 if(status!=dh2::character_level_up_properties_v1::Status::complete){
  error="Character::LevelUp UpdateBaseProperties failed after its property prefix";return false;
 }
 dh2::character_level_runtime::Storage storage{
  identity,reinterpret_cast<std::uintptr_t>(&prince_combat.properties),
  prince_combat.properties.base.data(),&view,actor_class_rows.data(),
  std::uint32_t(actor_class_rows.size()),&native_design_binding,1,
  &native_debug->globals(),&native_debug->services()};
 if(!prince_combat.level_up_runtime)
  prince_combat.level_up_runtime=std::make_unique<dh2::character_level_runtime::Runtime>();
 status=prince_combat.level_up_runtime->initialize_hp_mp(
  &storage,&prince_combat.last_level_up_runtime)==
   dh2::character_level_runtime::Status::complete?
   dh2::character_level_up_properties_v1::Status::complete:
   dh2::character_level_up_properties_v1::Status::property_failed;
 if(status!=dh2::character_level_up_properties_v1::Status::complete){
  error="Character::LevelUp RegenHP(-1)/RegenMP(-1) failed after base recalculation";return false;
 }
 // Character::SG_SetPlayerLevel reads current property 19, arithmetic-shifts
 // fixed point, and stores PlayerSavegame+0x30 before Character::SG_Save.
 const auto raw=std::uint32_t(view.resolved[19]);
 auto level_bits=(raw>>8)|((raw&0x80000000u)?0xff000000u:0u);
 std::int32_t save_level=0;std::memcpy(&save_level,&level_bits,sizeof(save_level));
 prince_combat.savegame->set_player_level(save_level);
 if(!ui_player_save_game(identity,error)){
  if(error.empty())error="Character::SG_Save failed after SG_SetPlayerLevel";
  return false;
 }
 // Character::LevelUp 0x3beb88, Player branch, in source order: the localized
 // StrID.MENU_LEVEL_UP StatusMsg is queued (the HUD's onStatusMessage starts when
 // it is the only queued message), the common PlayerLevelUp script starts
 // (GetIDFromName + StartScript(id,-1,false); one PlaySound), and
 // VisualFXManager::PlayAnimFXSet(135, Player) plays at the Player. The port's
 // FX owner places a set at a position, as for the script PlayEffect and the
 // Faery markers, so the effect does not follow the Player afterwards.
 {
  std::string status_error;
  if(!native_gameplay_ui||
     !native_gameplay_ui->enqueue_source_status_constant("StrID","MENU_LEVEL_UP",status_error))
   __android_log_print(ANDROID_LOG_WARN,"DH2Native","Character::LevelUp could not queue its MENU_LEVEL_UP StatusMsg | %s",
       status_error.c_str());
  bool script_started=false;std::string script_error;
  if(!native_start_level_script_by_name("PlayerLevelUp",false,script_started,script_error)&&
     native_tutorial_start_refusals.insert("PlayerLevelUp").second)
   __android_log_print(ANDROID_LOG_WARN,"DH2Native","Character::LevelUp could not start PlayerLevelUp | %s",
       script_error.c_str());
  float fx_point[3]{};
  if(native_fx_owner&&native_level_script_position_for_target(identity,fx_point)){
   bool matched=false,launched=false;std::string fx_error;
   const auto fx_status=native_fx_owner->PlayAnimFXSet(135,{fx_point[0],fx_point[1],fx_point[2]},
       nullptr,matched,launched,fx_error);
   if(fx_status!=dh2::native_visual_fx_manager_v1::Status::ok)
    __android_log_print(ANDROID_LOG_WARN,"DH2Native","Character::LevelUp FX 135 failed | %s",fx_error.c_str());
   else
    __android_log_print(ANDROID_LOG_INFO,"DH2Native","Character::LevelUp FX 135 | matched %u | launched %u | at %.6g %.6g %.6g",
        unsigned(matched),unsigned(launched),fx_point[0],fx_point[1],fx_point[2]);
  }
 }
 // Reaching level 2 offline on Normal then
 // starts cinematic_Tuto_levelUp (settings byte 5, cleared by the caller) and
 // then cinematic_Tuto_menuCharacterSheet (byte 0, left for the menu to clear;
 // no shipped level carries it). cinematic_Tuto_menuSkillSheet only starts when
 // ONLINE in the original, so the offline port never reaches it.
 if(save_level==2){
  native_tutorial_trigger(5,"cinematic_Tuto_levelUp","Character::LevelUp");
  if(native_tutorial_gate_open(0)){
   bool started=false;std::string tutorial_error;
   if(!native_start_level_script_by_name("cinematic_Tuto_menuCharacterSheet",false,started,tutorial_error)&&
      native_tutorial_start_refusals.insert("cinematic_Tuto_menuCharacterSheet").second)
    __android_log_print(ANDROID_LOG_ERROR,"DH2Native","Tutorial script cinematic_Tuto_menuCharacterSheet refused after Character::LevelUp | %s",
        tutorial_error.c_str());
  }
 }
 // Character::LevelUp (0x3beb88) performs the source PlayerManager local-player
 // gate after saving the level, then unlocks only exact level milestones.
 const auto locality_services=native_host.locality_services();
 dh2::player_locality_v1::Result locality{};
 if(dh2::player_locality_v1::is_local_player(&native_host.registry,
       &locality_services,identity,&locality)!=
       dh2::player_locality_v1::Status::complete){
  error="Character::LevelUp PlayerManager::IsLocalPlayer query failed";return false;
 }
 if(locality.value){
  const char* milestone=nullptr;
  switch(save_level){
   case 10:milestone="epic_lvl10";break;case 20:milestone="epic_lvl20";break;
   case 30:milestone="epic_lvl30";break;case 40:milestone="epic_lvl40";break;
   case 50:milestone="epic_lvl50";break;case 60:milestone="epic_lvl60";break;
   case 70:milestone="epic_lvl70";break;case 80:milestone="epic_lvl80";break;
   case 90:milestone="epic_lvl90";break;case 100:milestone="epic_lvl100";break;
   default:break;
  }
  if(milestone&&!unlock_source_trophy(milestone,"Character::LevelUp",error))return false;
 }
 error.clear();return true;
}
