bool native_sct_is_follower_v1(void* raw,std::uintptr_t identity,bool& value,
                                std::string& error){
 using namespace dh2::character_ai_classification;
 State state{};
 std::string player_name;
 auto* context=static_cast<NativeSctActorContextV1*>(raw);
 if(identity==prince_character.identity()){
  if(!prince_combat.savegame||prince_combat.savegame->character()!=identity){
   error="Scrolling combat text Player classification crossed its Save";return false;
  }
  player_name=prince_combat.savegame->name();
  state={identity,prince_combat.properties.resolved[1],
      prince_combat.properties.resolved[0],player_name.c_str(),
      std::uint8_t(prince_combat.life.dead)};
 }else{
  auto* faery=context?context->faery:nullptr;
  if(faery&&faery->identity==identity&&faery->record&&
     faery->record->character.identity==identity&&faery->properties_ready){
   state={identity,faery->properties.resolved[1],
       faery->properties.resolved[0],faery->source.character.c_str(),
       faery->record->serialized_dead_1449};
  }else{
   auto* actor=native_char_ai_actor(identity);
   if((!actor||actor->kind!=1)&&context&&context->actor&&
      context->actor->identity==identity&&context->actor->kind==1)
    actor=context->actor;
   if(!actor||actor->kind!=1){error="Scrolling combat text Character is absent";return false;}
   state={identity,actor->properties.resolved[1],actor->properties.resolved[0],
       actor->name.c_str(),std::uint8_t(actor->combat_state.dead)};
  }
 }
 const Services services{nullptr,native_classification_service};Result result{};
 if(query(Query::follower,&state,&services,&result)!=Status::complete){
  error="Source Character follower classification failed";return false;
 }
 value=result.word!=0;error.clear();return true;
}
bool native_sct_killed_position_lookup_v1(void* raw,std::uintptr_t identity,
    dh2::ui::ScrollingCombatTextPositionFactsV1& facts,std::string& error){
 auto* context=static_cast<NativeSctActorContextV1*>(raw);
 if(context&&identity&&identity==context->player_identity){
  if(!prince_combat.savegame||prince_combat.savegame->character()!=identity||
     prince_character.identity()!=identity){
   error="Player SCT position crossed its canonical Character/Save/visibility owner";return false;
  }
  context->player_visible_80=prince_character.visibility_80();
  context->player_position={identity,prince_combat.savegame->character(),
      &prince_runtime.subobjects,&current_scene,&context->player_visible_80};
  return dh2::player_sct_position_provider_v1::lookup(
      &context->player_position,identity,facts,error);
 }
 if(context&&context->faery&&context->faery->identity==identity&&
    context->faery->record&&
    context->faery->record->character.identity==identity&&
    dh2::character_faery_visual_facade_v1::ready(
      context->faery->record->faery_visual,identity)){
  auto& owner=*context->faery;
  auto& visual=owner.record->faery_visual;
  auto pose=std::dynamic_pointer_cast<AuthoredFaeryPose>(visual.pose);
  dh2::physical::CharacterOwnerBounds bounds{};
  if(!pose||!resolve_authored_faery_owner_bounds(owner.assets,owner,bounds,error))
   return false;
  try {
   auto scene=std::make_unique<dh2::scene::Scene>(pose->bdae_resource().scene);
   const Matrix placement=faery_visual_placement(owner,visual);
   for(auto& node:scene->graph)
    node.world=dh2::scene::multiply(placement,node.world);
   context->static_visual_scene=std::move(scene);
   std::copy(bounds.relative_box,bounds.relative_box+6,
             context->static_relative_box.begin());
  }catch(const std::exception& exception){
   error=exception.what();context->static_visual_scene.reset();return false;
  }
  facts.identity=identity;
  context->faery_position={owner.record->game_object.world_x,
      owner.record->game_object.world_y,visual.position[2]};
  facts.game_object_position=context->faery_position.data();
  facts.visual_scene=context->static_visual_scene.get();
  facts.relative_box=context->static_relative_box.data();
  facts.source_visible_80=visual.visible?1u:0u;
  error.clear();return true;
 }
 if(!context||!context->actor||
    context->actor->identity!=identity){
  error="Scrolling XP position lookup did not match the killed Character owner";return false;
 }
 auto& actor=*context->actor;
 facts.identity=actor.identity;
 if(actor.spawn_owner&&actor.spawn_owner->runtime_ready){
  auto& owner=*actor.spawn_owner;
  facts.game_object_position=owner.runtime.subobjects.position;
  facts.visual_scene=&owner.scene;
  facts.relative_box=owner.owner_bounds.relative_box;
 }else{
  if(!context->static_visual_scene||actor.kind!=1){
   error="Scrolling text Character has neither a live SpawnOwner nor retained static Character projection";return false;
  }
  facts.game_object_position=actor.position.data();
  facts.visual_scene=context->static_visual_scene.get();
  facts.relative_box=context->static_relative_box.data();
 }
 if(actor.visible_80>1||!actor.identity){
  error="Scrolling text Character visibility/identity fields are invalid";return false;
 }
 facts.source_visible_80=actor.visible_80;
 error.clear();return true;
}
