bool native_sct_property_v1(void* raw,std::uintptr_t identity,std::int32_t property,
                            std::int32_t& value,std::string& error){
 if(property<0){error="Scrolling combat text property ID is negative";return false;}
 const dh2::data::PropertyState* source=nullptr;
 if(identity==prince_character.identity())source=&prince_combat.properties;
 else {
  auto* context=static_cast<NativeSctActorContextV1*>(raw);
  if(context&&context->faery&&context->faery->identity==identity&&
     context->faery->record&&
     context->faery->record->character.identity==identity&&
     context->faery->properties_ready)
   source=&context->faery->properties;
  auto* actor=native_char_ai_actor(identity);
  if(!source&&(!actor||actor->kind!=1)&&context&&context->actor&&
     context->actor->identity==identity&&context->actor->kind==1)
   actor=context->actor;
  if(!source&&actor&&actor->kind==1)source=&actor->properties;
 }
 if(!source||std::size_t(property)>=source->resolved.size()){
  error="Scrolling combat text source PropertyView is unavailable";return false;
 }
 value=source->resolved[std::size_t(property)];error.clear();return true;
}
bool native_sct_dual_wield_v1(void* raw,std::uintptr_t identity,bool& value,
                              std::string& error){
 if(identity==prince_character.identity()){
  if(!prince_combat.inventory||prince_combat.inventory->character()!=identity){
   error="Scrolling combat text requires the canonical Player V4 equipment owner";return false;
  }
  auto properties=dh2::data::property_view(actor_property_rules,prince_combat.properties);
  dh2::data::PlayerEquipmentQueriesLiveV1 equipment(*prince_combat.inventory,properties);
  dh2::data::EquipmentWeaponFacts12V1 facts{};
  if(!equipment.facts(facts,error))return false;
  value=(facts.flags&dh2::data::weapon_dual)!=0;error.clear();return true;
 }
 auto* actor=native_char_ai_actor(identity);
 auto* context=static_cast<NativeSctActorContextV1*>(raw);
 if(context&&context->faery&&context->faery->identity==identity&&
    context->faery->record&&
    context->faery->record->character.identity==identity&&
    context->faery->native_ai&&
    context->faery->native_ai->state.word_38==3u){
  // The authored Faery Character is CharType 3 and has no Player V4 weapon
  // inventory. Source dual-wield classification therefore resolves false.
  value=false;error.clear();return true;
 }
 if((!actor||actor->kind!=1)&&context&&context->actor&&
    context->actor->identity==identity&&context->actor->kind==1)
  actor=context->actor;
 if(!actor||actor->kind!=1||!actor->source_inventory){
  error="Scrolling combat text requires the NPC's canonical V4 ItemInventory owner";return false;
 }
 return actor->source_inventory->is_dual_wielding(*actor,value,error);
}
