bool ui_player_weapon_flags(std::uintptr_t identity,bool& offhand,bool& two_handed,std::string& error){
 std::uintptr_t current=0;if(!ui_player_identity(current,error))return false;
 if(identity!=current||!prince_combat.inventory){error="Weapon flags require the active V4 inventory";return false;}
 const auto selected=prince_combat.inventory->current_equipment();
 if(selected<0||selected>=2){error="Selected equipment set is outside the source domain";return false;}
 const auto* off=prince_combat.inventory->equipment()[std::size_t(selected)][2];
 offhand=false;
 if(off){
  if(!off->item){error="Offhand slot has no retained Item instance";return false;}
  const auto* row=dh2::data::item(prince_combat.inventory->table(),off->item->id);
  if(!row){error="Offhand Item has no decoded ItemTable row";return false;}
  offhand=row->record.words[22]!=6;
 }
 if(!prince_combat.inventory->has_two_hander(false,two_handed,error))return false;
 error.clear();return true;
}
bool ui_player_potions(std::uintptr_t identity,std::int32_t& count,std::int32_t& capacity,std::string& error){
 std::uintptr_t current=0;if(!ui_player_identity(current,error))return false;
 if(identity!=current||!prince_combat.inventory){error="Potion read requires the active V4 inventory";return false;}
 count=prince_combat.inventory->num_potions();
 const auto bits=static_cast<std::uint32_t>(prince_combat.properties.resolved[194]);
 std::uint32_t shifted=(bits>>8)|((bits&0x80000000u)?0xff000000u:0u);
 std::int32_t signed_capacity=0;std::memcpy(&signed_capacity,&shifted,sizeof(signed_capacity));
 capacity=static_cast<std::int8_t>(static_cast<std::uint8_t>(std::max(0,signed_capacity)));
 error.clear();return true;
}
bool ui_player_use_potion(std::uintptr_t identity,std::string& error){
 std::uintptr_t current=0;if(!ui_player_identity(current,error))return false;
 if(identity!=current||!prince_combat.inventory||
    prince_combat.inventory->character()!=identity||!player_equipment_native||
    !player_equipment_native->services){
  error="Potion command requires the active Character, canonical V4 inventory and inventory services";return false;
 }
 // NativeUsePotion tests HasPotion before reading either percentage.
 const auto* initial_potion=prince_combat.inventory->potion();
 if(!initial_potion||initial_potion->signed_quantity()<=0){error.clear();return true;}
 // NativeUsePotion calls GetHPPercent/GetMPPercent and dispatches only when
 // either ratio is below 1.0. These source properties are raw 8.8 values, so
 // converting both operands to float preserves the original comparison.
 const auto fixed_float=[](std::int32_t raw){return float(raw)/256.f;};
 const float hp_percent=fixed_float(prince_combat.properties.resolved[36])/
                        fixed_float(prince_combat.properties.resolved[38]);
 const float mp_percent=fixed_float(prince_combat.properties.resolved[41])/
                        fixed_float(prince_combat.properties.resolved[43]);
 if(!(hp_percent<1.f||mp_percent<1.f)){error.clear();return true;}

 // v2Controller::Cmd_UsePotion at 0x4056b0: forced bypasses both checks;
 // otherwise global s_blocked and the per-controller locked byte veto dispatch.
 if(!prince_controller_forced&&(controller_global_blocked||prince_state.controller_locked)){
  error.clear();return true;
 }
 // Character::Ctrl_UsePotion checks IsDead before HasPotion, then consumes the
 // exact ItemInventory potion through RemoveOnePotion.
 if(prince_combat.life.dead){error.clear();return true;}
 auto* potion=prince_combat.inventory->potion();
 if(!potion||potion->signed_quantity()<=0){error.clear();return true;}
 if(!prince_combat.inventory->remove_one_potion(
       player_equipment_native->live_services,error))return false;

 // The Player branch increments Character property 219 before its optional
 // TrophyManager search for "use_100_potions".
 auto property_view=dh2::data::property_view(actor_property_rules,prince_combat.properties);
 if(dh2_property_add(&property_view,219,1)){
  error="Potion consumed but Character property 219 update failed";return false;
 }
 if(prince_combat.properties.resolved[219]>99&&
    !unlock_source_trophy("use_100_potions","Ctrl_UsePotion",error)){
  error="Potion consumed and counter updated, but "+error;return false;
 }

 // Character::Ctrl_UsePotion calls RegenHP(-1), then RegenMP(-1), after the
 // removal and Player achievement prefix. The existing vitals kernel owns the
 // fill-to-maximum arithmetic and mutates this Character's PropertyState.
 dh2::data::VitalsChange hp_change{},mp_change{};
 if(dh2_vitals_regen(&property_view,0,-1,&hp_change)){
  error="Potion consumed and property 219 updated, but source HP regeneration failed";return false;
 }
 if(dh2_vitals_regen(&property_view,1,-1,&mp_change)){
  error="Potion consumed and HP regenerated, but source MP regeneration failed";return false;
 }
 __android_log_print(ANDROID_LOG_INFO,"DH2Native","Character::Ctrl_UsePotion source prefix | remaining %d | HP %d -> %d | MP %d -> %d",
  prince_combat.inventory->num_potions(),hp_change.before,hp_change.after,mp_change.before,mp_change.after);
 return persist_after_inventory_mutation(identity,error);
}
namespace {
struct OoiInteractionContextV1 {
 ObjectActor* actor=nullptr;
 dh2::character_ai_interaction_range::Point points[2]{};
 dh2::character_ai_interaction_range::Point spot{};
 dh2::character_ai_interaction_range::ObjectFacts facts{};
 dh2::character_ai_interaction_range::AiRow ai_row{};
};
const dh2::scene::Scene* ooi_actor_scene(ObjectActor& actor) {
 if(actor.spawn_owner&&actor.spawn_owner->runtime_ready)return &actor.spawn_owner->scene;
 for(const auto& group:object_groups)
  if(std::any_of(group.instances.begin(),group.instances.end(),
      [&](const auto& item){return &item==&actor;}))return &group.resource.scene;
 return nullptr;
}
bool ooi_node_below(const dh2::scene::Scene& scene,unsigned node,unsigned root) {
 std::size_t depth=0;
 while(node<scene.graph.size()&&depth++<scene.graph.size()){
  if(node==root)return true;
  const auto parent=scene.graph[node].parent;
  if(parent<0)return false;
  node=static_cast<unsigned>(parent);
 }
 return false;
}
std::int32_t ooi_get_specific_node(void* raw,std::uintptr_t visual,
        const char* name,std::uintptr_t* node_out) {
 auto* context=static_cast<OoiInteractionContextV1*>(raw);
 if(!context||!context->actor||!name||!node_out||
    visual!=context->actor->visual_object_2d8)return 1;
 const auto* scene=ooi_actor_scene(*context->actor);
 if(!scene||context->actor->visual_root>=scene->graph.size())return 1;
 for(unsigned i=0;i<scene->graph.size();++i){
  if(!ooi_node_below(*scene,i,context->actor->visual_root))continue;
  const auto& entry=scene->graph[i];
  if(entry.id==name||entry.sid==name||entry.name==name){
   *node_out=reinterpret_cast<std::uintptr_t>(&entry);return 0;
  }
 }
 *node_out=0;return 0;
}
std::int32_t ooi_absolute_position(void* raw,std::uintptr_t node,
        const dh2::character_ai_interaction_range::Point** borrowed) {
 auto* context=static_cast<OoiInteractionContextV1*>(raw);
 if(!context||!context->actor||!node||!borrowed)return 1;
 const auto* scene=ooi_actor_scene(*context->actor);if(!scene)return 1;
 const auto found=std::find_if(scene->graph.begin(),scene->graph.end(),
     [&](const auto& value){return reinterpret_cast<std::uintptr_t>(&value)==node;});
 if(found==scene->graph.end())return 1;
 float position[3]{};
 if(context->actor->spawn_owner&&context->actor->spawn_owner->runtime_ready){
  position[0]=found->world[12];position[1]=found->world[13];position[2]=found->world[14];
 }else{
  const auto world=dh2::scene::multiply(context->actor->placement,found->world);
  position[0]=world[12];position[1]=world[13];position[2]=world[14];
 }
 for(unsigned i=0;i<3;++i)std::memcpy(&context->spot.words[i],&position[i],sizeof(float));
 *borrowed=&context->spot;return 0;
}
std::int32_t ooi_target_position(void* raw,std::uintptr_t object,
        const dh2::character_ai_interaction_range::Point** borrowed) {
 auto* context=static_cast<OoiInteractionContextV1*>(raw);
 if(!context||!context->actor||!borrowed)return 1;
 const dh2::character::aggro_search::GameObject* projection=nullptr;
 if(object==prince_character.identity())projection=&prince_search_projection.object;
 else if(object==context->actor->identity)projection=&context->actor->search_projection.object;
 if(!projection||projection->identity!=object)return 1;
  const float* position=projection->has_target_position?
     projection->target_position:projection->position;
 auto& point=context->points[object==prince_character.identity()?0:1];
 for(unsigned i=0;i<3;++i)std::memcpy(&point.words[i],&position[i],sizeof(float));
 *borrowed=&point;return 0;
}
std::int32_t ooi_spot(void* raw,std::uintptr_t object,
        dh2::character_ai_interaction_range::Response* response) {
 using namespace dh2::character_interaction_spot_owner_v1;
 auto* context=static_cast<OoiInteractionContextV1*>(raw);
 if(!context||!context->actor||object!=context->actor->identity||!response)return 1;
 const ObjectView view{object,&context->actor->visual_object_2d8,
     &context->actor->interaction_lookup_started_2ec,
     &context->actor->interaction_node_2e8};
 const Services services{context,ooi_get_specific_node,ooi_absolute_position,
                         ooi_target_position};
 Result result{};
 if(get_interaction_spot(&view,&services,&result)!=Status::complete)return 1;
 context->facts={object,result.node};response->point=result.point;
 response->view=&context->facts;return 0;
}
std::int32_t ooi_interaction_range_service(void* raw,
        dh2::character_ai_interaction_range::State* state,
        const dh2::character_ai_interaction_range::Request* request,
        dh2::character_ai_interaction_range::Response* response) {
 using namespace dh2::character_ai_interaction_range;
 auto* context=static_cast<OoiInteractionContextV1*>(raw);
 if(!context||!context->actor||!state||!request||!response||
    state->owner!=prince_character.identity()||!prince_source_ai||
    state->ai!=prince_source_ai->ai_identity)return 1;
 *response={};
 switch(request->operation){
 case Operation::target_position:{
  if(request->subject!=prince_character.identity())return 1;
  const Point* point=nullptr;
  if(ooi_target_position(context,request->subject,&point))return 1;
  response->view=point;return 0;
 }
 case Operation::interaction_spot:return ooi_spot(context,request->subject,response);
 case Operation::melee_radius:{
  if(!prince_source_ai||request->subject!=prince_source_ai->ai_identity)return 1;
  float radius=0.f;if(!player_melee_radius_v1(radius))return 1;
  std::memcpy(&response->word,&radius,sizeof(radius));return 0;
 }
 case Operation::interaction_radius:response->word=0;return 0;
 case Operation::char_ai:{
  if(request->subject!=prince_character.identity())return 1;
  const auto* props=dh2::data::ai_props(actor_ai_tables,prince_combat.properties.resolved[1]);
  if(!props)return 1;
  // Structs::AIProps (vtable, AttackDelay, CombatBeat, CombatMusic, DelayedLoad,
  // Flags, InteractRadius...): AIProps+0x18 is InteractRadius.
  std::memcpy(&context->ai_row.words[6],&props->interact_radius,sizeof(float));
  response->view=&context->ai_row;return 0;
 }
 case Operation::interaction_type:{
  if(request->subject!=context->actor->identity||request->other!=prince_character.identity())return 1;
  std::uint32_t enemy=0;
  if(!source_relation_for_ooi(prince_character.identity(),context->actor->identity,
       dh2::character_ai_relations::Relation::enemy,enemy))return 1;
  response->word=enemy?8u:3u;return 0;
 }
 }
 return 1;
}
}
bool ui_player_merchant_interaction_target(std::string& merchant_name,
        std::int32_t& module_filter,std::uintptr_t& identity,std::string& error) {
 merchant_name.clear();module_filter=-1;identity=0;
 if(!prince_character.identity()||prince_character.ooi_type()!=3||
    !prince_character.ooi_identity()){error.clear();return false;}
 auto* actor=native_char_ai_actor(prince_character.ooi_identity());
 if(!actor||actor->identity!=prince_character.ooi_identity()||actor->kind!=1||
    actor->source_object_module_id<0||actor->name.empty()||
    !native_character_classification(*actor,
        dh2::character_ai_classification::Query::merchant)){
  error.clear();return false;
 }
 if(!prince_source_ai||prince_source_ai->character_identity!=prince_character.identity()){
  error="Selected merchant OOI has no current Player CharAI";return false;
 }
 std::uintptr_t resolved=0;
 if(!ui_source_merchant_identity(actor->source_object_module_id,actor->name,resolved,error))return false;
 if(resolved!=actor->identity){error="ObjectManager merchant resolution changed the selected OOI identity";return false;}
 OoiInteractionContextV1 context{};context.actor=actor;
 dh2::character_ai_interaction_range::State state{
     prince_source_ai->ai_identity,prince_character.identity(),
     prince_source_ai->state.target_40};
 const dh2::character_ai_interaction_range::Services services{
     &context,ooi_interaction_range_service};
 dh2::character_ai_interaction_range::Result range{};
 const auto status=dh2::character_ai_interaction_range::evaluate_object(
     &state,actor->identity,&services,&range);
 if(status!=dh2::character_ai_interaction_range::Status::complete){
  error="Source Character::GetInteractionRange provider failed for the selected merchant";return false;
 }
 if(!range.value){error.clear();return false;}
 merchant_name=actor->name;module_filter=actor->source_object_module_id;
 identity=actor->identity;error.clear();return true;
}
bool ui_player_hud_projection(std::uintptr_t identity,bool refresh_usable,
                              UiPlayerHudProjectionV1& out,std::string& error){
 std::uintptr_t current=0;if(!ui_player_identity(current,error))return false;
 if(identity!=current||!prince_combat.inventory||
    prince_combat.inventory->character()!=identity||!prince_combat.savegame||
    prince_combat.savegame->character()!=identity||!prince_combat.savegame->skills_initialized()||
    native_save_difficulty<0||native_save_difficulty>2||!prince_skills||
    !prince_skills->initialized()){
  error="Gameplay HUD projection requires the active Character, Save, V4 inventory and V3 skill owner";return false;
 }
 UiPlayerHudProjectionV1 value=out;
 const bool identity_changed=value.character!=identity;
 value.character=identity;value.class_id=prince_combat.savegame->class_id();
 value.object_of_interest_type=prince_character.ooi_type();
 std::array<std::int32_t,3> slots{};
 for(std::int32_t i=0;i<3;++i){
  slots[std::size_t(i)]=prince_combat.savegame->skill_in_slot(i);
  if(slots[std::size_t(i)] < -1){error="Saved HUD skill slot is outside the source empty-or-index domain";return false;}
 }
 const auto faery=prince_combat.savegame->current_faery(std::uint32_t(native_save_difficulty));
 if(faery < -1){error="Saved HUD faery is outside the source empty-or-index domain";return false;}
 const bool refresh=refresh_usable||identity_changed||value.skill_slots!=slots||value.faery_id!=faery;
 value.skill_slots=slots;value.faery_id=faery;
 auto percent=[](float fraction)->std::int32_t{
  if(!std::isfinite(fraction))return 0;
  volatile float raw=fraction*100.f;
  if(raw>=2147483648.f)return std::numeric_limits<std::int32_t>::max();
  if(raw<=-2147483648.f)return std::numeric_limits<std::int32_t>::min();
  return static_cast<std::int32_t>(raw);
 };
 for(std::size_t slot=0;slot<slots.size();++slot){
  auto& cooldown=value.infos[8+slot*2];auto& usable=value.infos[9+slot*2];
  if(slots[slot]<0){cooldown=0;usable=0;continue;}
  std::uint32_t source_usable=refresh?0u:static_cast<std::uint32_t>(usable!=0);
  float fraction=0.f;
  if(!prince_skills->hud_info(false,std::uint32_t(slots[slot]),refresh,
       source_usable,fraction,error))return false;
  cooldown=percent(fraction);
  if(refresh)usable=source_usable?1:0;
 }
 if(faery<0){value.infos[6]=0;value.infos[7]=0;}
 else{
  bool unlocked=false;
  if(!ui_player_faery_unlocked(identity,std::uint32_t(faery),unlocked,error))return false;
  if(!unlocked){value.infos[6]=0;value.infos[7]=0;}
  else{
   std::uint32_t source_usable=refresh?0u:static_cast<std::uint32_t>(value.infos[7]!=0);
   float fraction=0.f;
   if(!prince_skills->hud_info(true,std::uint32_t(faery),refresh,
        source_usable,fraction,error))return false;
   value.infos[6]=percent(fraction);
   if(refresh)value.infos[7]=(prince_state.current==6||prince_state.current==7)?0:(source_usable?1:0);
  }
 }
 value.infos[14]=prince_combat.inventory->num_potions();
 // Native HudManager tests Character property 148 for its level-up marker.
 value.infos[15]=prince_combat.properties.resolved[148];
 out=value;error.clear();return true;
}
// DELIBERATE USER-APPROVED DEVIATION support for the enemy bar follow: the
// displayed target's head point (world position with the same +350 Z offset the
// original InfoHUDManager uses for allies) and the live gameplay camera
// view-projection. valid=false when no live target or camera frame exists.
bool ui_enemy_target_head_projection(std::uintptr_t target,float head_world[3],
        float view_projection[16],int& width,int& height,bool& valid,std::string& error){
 valid=false;error.clear();
 if(!target||!source_camera_level_has_frame||source_camera.width<=0||source_camera.height<=0)return true;
 ObjectActor* actor=nullptr;
 for(auto& group:object_groups){
  const auto found=std::find_if(group.instances.begin(),group.instances.end(),
      [&](const ObjectActor& candidate){return candidate.kind==1&&candidate.identity==target;});
  if(found!=group.instances.end()){actor=&*found;break;}
 }
 if(!actor)return true;
 head_world[0]=actor->position[0];head_world[1]=actor->position[1];
 volatile float head_z=actor->position[2]+350.f;head_world[2]=head_z;
 static_assert(sizeof(source_camera.matrix.elements)==16*sizeof(float));
 std::memcpy(view_projection,source_camera.matrix.elements,16*sizeof(float));
 width=source_camera.width;height=source_camera.height;valid=true;return true;
}
bool ui_player_enemy_hud_projection(std::uintptr_t identity,
        UiEnemyHudProjectionV1& out,std::string& error){
 std::uintptr_t current=0;if(!ui_player_identity(current,error))return false;
 if(identity!=current||!prince_source_ai||
    prince_source_ai->character_identity!=identity||
    prince_source_ai->state.owner_04!=identity){
  error="Enemy HUD projection requires the active Character and its retained CharAI owner";return false;
 }
 const auto source_level=[](std::int32_t raw){
  const auto bits=std::uint32_t(raw);
  const auto shifted=(bits>>8)|((bits&0x80000000u)?0xff000000u:0u);
  std::int32_t value;std::memcpy(&value,&shifted,sizeof value);return value;
 };
 const auto snapshot=[&](ObjectActor* actor,UiEnemyHudActorV1& view){
  if(!actor)return true;
  if(actor->kind!=1||!actor->identity||actor->properties.resolved.size()<39){
   error="Enemy HUD target has no retained Character properties";return false;
  }
  try{
   view.identity=actor->identity;view.debug_name=actor->name.c_str();
   // Property 18 (Name) holds a raw StringManager ID (sheet<<16|string), not
   // a 24.8 fixed-point value like Level.
   view.name_symbol=actor->properties.resolved[18];
   view.level=source_level(actor->properties.resolved[19]);
   view.hp_fraction=(float(actor->properties.resolved[36])/256.f)/
                    (float(actor->properties.resolved[38])/256.f);
   // Target HP 0 means the monster is dead: report no target so the HUD hides
   // the enemy group (InfoHUDManager hides on target clear).
   view.present=view.hp_fraction>0.f;view.is_character=true;
   view.is_monster=native_character_classification(*actor,
       dh2::character_ai_classification::Query::monster)!=0;
   view.is_boss=native_character_classification(*actor,
       dh2::character_ai_classification::Query::boss)!=0;
   error.clear();return true;
  }catch(const std::exception& failure){error=failure.what();return false;}
 };
 UiEnemyHudProjectionV1 value{};value.player_identity=identity;
 value.player_dead=prince_combat.life.dead!=0;
 if(prince_source_ai->state.target_40){
  auto* target=native_char_ai_actor(prince_source_ai->state.target_40);
  if(target&&!snapshot(target,value.ai_target))return false;
 }
 // Character's retained target pointer is represented by the current combat
 // target index. Resolve the record even when its Character has reached 0 HP:
 // source InfoHUDManager keeps displaying that target until the target clears.
 const auto index=prince_combat.target;
 if(index>=0&&std::size_t(index)<world_objects.size()){
  const auto& record=world_objects[std::size_t(index)];ObjectActor* target=nullptr;
  for(auto& group:object_groups){
   const auto found=std::find_if(group.instances.begin(),group.instances.end(),
       [&](const ObjectActor& actor){return actor.kind==1&&actor.room==record.room&&
           actor.name==record.name;});
   if(found!=group.instances.end()){target=&*found;break;}
  }
  if(target&&!snapshot(target,value.character_target))return false;
 }
 out=value;error.clear();return true;
}
