bool faery_hit_for_owner(FaeryHitForOwner* owner,
                         dh2::character_runtime_factory_v1::Record* record,
                         std::uintptr_t character) {
 return owner&&record&&owner->record==record&&owner->identity==character&&
     record->character.identity==character&&native_faery_owner(character)==owner&&
     owner->properties_ready&&owner->properties.resolved.size()==224&&
     record->source_properties_ready()&&record->object_registered&&
     record->character_listed&&record->coordinator&&
     record->coordinator->bound();
}

bool faery_hit_for_death_ai_ready(const FaeryHitForOwner& owner) {
 if(!owner.record||!owner.native_ai||!owner.record->source_external_ais||
    !owner.record->source_external_ais->ready())return false;
 const auto identity=owner.record->external_ais.identity;
 return identity&&owner.native_ai->character_identity==owner.identity&&
     owner.native_ai->state.owner_04==owner.identity&&
     owner.native_ai->state.active_ais_1c==identity&&
     owner.record->external_lifecycle.active==identity&&
     owner.record->external_lifecycle.pending==identity;
}

bool faery_hit_for_debug_switch(const char* key,bool& enabled,
                                std::string& error) {
 if(!native_debug||!key) {
  error="Faery Character::HitFor requires the shared DebugSwitches owner";
  return false;
 }
 if(native_debug->runtime().load(native_debug->globals(),
       native_debug->services())!=dh2::debug_switches::Status::complete) {
  error="Faery Character::HitFor DebugSwitches::load failed";return false;
 }
 std::uint8_t value=0;
 if(native_debug->runtime().get_switch(key,native_debug->globals(),
       native_debug->services(),value)!=dh2::debug_switches::Status::complete) {
  error=std::string("Faery Character::HitFor DebugSwitches::GetSwitch failed: ")+key;
  return false;
 }
 enabled=value!=0;error.clear();return true;
}

bool faery_capture_hit_for_facts(void* raw,
    dh2::character_runtime_factory_v1::Record& record,
    std::uintptr_t attacker,FaeryHitForFacts& facts,std::string& error) {
 auto* owner=static_cast<FaeryHitForOwner*>(raw);
 if(!faery_hit_for_owner(owner,&record,record.character.identity)||!attacker||
    !native_application.identity||!actor_ai_tables.rows.size()) {
  error="Faery Character::HitFor facts lost its canonical Record/Application/AI table";
  return false;
 }
 using namespace dh2::character_ai_classification;
 auto& state=owner->hit_for_classification_state;
 state={record.character.identity,owner->properties.resolved[1],
        owner->properties.resolved[0],owner->source.character.c_str(),
        record.serialized_dead_1449};
 const Services classification{nullptr,native_classification_service};
 Result player{};
 if(query(Query::player,&state,&classification,&player)!=Status::complete) {
  error="Faery Character::HitFor Character::IsPlayer source query failed";
  return false;
 }
 if(player.word)facts.flags|=dh2::data::health_player;
 else facts.flags&=~dh2::data::health_player;
 Result monster{};
 if(query(Query::monster,&state,&classification,&monster)!=Status::complete) {
  error="Faery Character::HitFor Character::IsMonster source query failed";
  return false;
 }
 if(monster.word)facts.flags|=dh2::data::health_monster;
 else facts.flags&=~dh2::data::health_monster;

 const auto online=native_host.online;
 if(online)facts.flags|=dh2::data::health_online;
 else facts.flags&=~dh2::data::health_online;
 const auto level=source_level_owner.snapshot();
 if(level.phase==dh2::source_level_owner_v1::Phase::active)
  facts.flags|=dh2::data::health_game_present;
 else facts.flags&=~dh2::data::health_game_present;
 facts.session_state=level.phase==dh2::source_level_owner_v1::Phase::active?0:1;
 if(prince_character.identity()&&prince_combat.inventory&&
    prince_combat.properties.resolved.size()==224) {
  facts.flags|=dh2::data::health_main_player_present;
  if(prince_combat.life.dead)facts.flags|=dh2::data::health_main_player_dead;
  else facts.flags&=~dh2::data::health_main_player_dead;
 } else {
  facts.flags&=~(dh2::data::health_main_player_present|
                 dh2::data::health_main_player_dead);
 }

 bool god_monster=false;
 if(!faery_hit_for_debug_switch("GOD_Monster",god_monster,error))return false;
 if(god_monster) {
  Result source_monster{};
  if(query(Query::monster,&state,&classification,&source_monster)!=Status::complete) {
   error="Faery Character::HitFor GOD_Monster Character::IsMonster query failed";
   return false;
  }
  if(source_monster.word)facts.flags|=dh2::data::health_god_monster;
 }
 bool one_shot=false;
 const auto saved=dh2::data::savegame_options_v1::is_saved_option_on(
     &owner->saved_options_view,"OneShotKill",&one_shot);
 if(saved!=dh2::data::savegame_options_v1::Status::complete) {
  error="Faery Character::HitFor Application::IsSavedOptionOn failed";
  return false;
 }
 if(!one_shot&&!faery_hit_for_debug_switch("OneShotKill",one_shot,error))
  return false;
 if(one_shot)facts.flags|=dh2::data::health_one_shot;
 else facts.flags&=~dh2::data::health_one_shot;
 error.clear();return true;
}

bool faery_after_hit_for_health(void* raw,
    dh2::character_runtime_factory_v1::Record& record,
    std::uintptr_t attacker,std::uint32_t raw_amount,
    const dh2::data::HealthChange& change,std::string& error) {
 auto* owner=static_cast<FaeryHitForOwner*>(raw);
 if(!faery_hit_for_owner(owner,&record,record.character.identity)||!attacker) {
  error="Faery Character::HitFor post-health callback crossed its canonical Record";
  return false;
 }
 // The reached HitFor achievement block converts the attacker ObjectHandle to
 // Character, then requires IsPlayer and PlayerManager::IsLocalPlayer. This
 // Faery path can reach it only for the canonical local Player attacker.
 if(attacker!=prince_character.identity()) {error.clear();return true;}
 const auto locality=native_host.locality_services();
 dh2::player_locality_v1::Result local{};
 if(dh2::player_locality_v1::is_local_player(&native_host.registry,&locality,
       attacker,&local)!=dh2::player_locality_v1::Status::complete) {
  error="Faery Character::HitFor PlayerManager::IsLocalPlayer failed";
  return false;
 }
 if(!local.value) {error.clear();return true;}
 // HitFor's captured `damage >> 8` is zeroed by the source only when the
 // health gate suppresses the hit (including GOD_Monster). The health kernel's
 // raw_add is the same reached gate certificate; OneShotKill may still zero
 // HP afterward without changing the original damage value.
 const auto damage=change.raw_add?raw_amount:0u;
 if((damage>>8)>199&&!unlock_source_trophy("power_200dam","Character::HitFor",error))return false;
 if((damage>>8)>149&&!unlock_source_trophy("power_150dam","Character::HitFor",error))return false;
 if((damage>>8)>99&&!unlock_source_trophy("power_100dam","Character::HitFor",error))return false;
 if((damage>>8)>49&&!unlock_source_trophy("power_50dam","Character::HitFor",error))return false;
 error.clear();return true;
}

bool faery_hit_for_kill_preflight(void* raw,std::uintptr_t character,
    std::uintptr_t killer,std::uint32_t force,std::string& error) {
 auto* owner=static_cast<FaeryHitForOwner*>(raw);
 if(!owner||!owner->record||!faery_hit_for_owner(owner,owner->record,character)||
    force||!killer||!world_mode||!actor_level_fields_ready||
    !prince_combat.quests||owner->record->source_script_created_539||
    owner->record->source_remote_culling.identity!=character||
    !faery_hit_for_death_ai_ready(*owner)) {
  error="Faery Character::Kill preflight lacks the canonical same-Level Record";
  return false;
 }
 if(killer!=prince_character.identity()&&!native_faery_owner(killer)&&
    !native_char_ai_actor(killer)) {
  error="Faery Character::Kill preflight cannot resolve the actual killer Character";
  return false;
 }
 // The recovered Faery row has Loot=-1 and no outgoing aggro recipients.
 // Those source branches are real no-ops for this row; nonempty aggro would
 // enter CharAI::OnKill/event4 and needs a separate source owner.
 const auto& record=*owner->record;
 const auto loot=std::find(actor_character_fields.begin(),
     actor_character_fields.end(),"Loot");
 if(loot==actor_character_fields.end()) {
  error="Faery Character::Kill cannot locate the source CharacterTable Loot field";
  return false;
 }
 const auto loot_index=static_cast<std::size_t>(loot-actor_character_fields.begin());
 if(loot_index>=owner->properties.resolved.size()||
    owner->properties.resolved[loot_index]>=0) {
  error="Faery Character::Kill reached an unsupported nonnegative Loot table";
  return false;
 }
 const auto live_end=owner->aggro.outgoing.begin()+
     std::min<std::size_t>(owner->aggro.out_count,owner->aggro.outgoing.size());
 if(live_end!=owner->aggro.outgoing.begin()) {
  error="Faery Character::Kill has live aggro recipients without a Faery OnKill provider";
  return false;
 }
 if(!record.kill_field_14e4.constructor_write_seen||
    record.game_object.module_id_64<0||record.property_id_13c8<0||
    !actor_quest_constants.view.bytes) {
  error="Faery Character::Kill objective source fields are incomplete";
  return false;
 }
 error.clear();return true;
}

