bool faery_hit_for_resolve_killer(void* raw,std::uintptr_t character,
    std::uintptr_t killer,std::uintptr_t& resolved,bool& xp_credit,
    std::string& error) {
 auto* owner=static_cast<FaeryHitForOwner*>(raw);
 if(!owner||!owner->record||!faery_hit_for_owner(owner,owner->record,character)||!killer) {
  error="Faery Character::Kill ObjectHandle conversion crossed its canonical Record";
  return false;
 }
 if(killer==prince_character.identity())resolved=killer;
 else if(native_faery_owner(killer))resolved=killer;
 else if(native_char_ai_actor(killer))resolved=killer;
 else {
  error="Faery Character::Kill cannot resolve the actual killer ObjectHandle to a Character";
  return false;
 }
 const auto live_end=owner->aggro.outgoing.begin()+
     std::min<std::size_t>(owner->aggro.out_count,owner->aggro.outgoing.size());
 xp_credit=std::any_of(owner->aggro.outgoing.begin(),live_end,
     [&](const dh2::data::AggroEntry& edge){return edge.character==killer;});
 error.clear();return true;
}

