bool native_level_quest_character_caches(void* raw,
 std::uintptr_t event_owner,std::uintptr_t level_identity,
 std::uintptr_t character_identity,
 dh2::character_saved_class_v1::Bindings& output,std::string& error){
 using SafeGet=dh2::character_saved_class_v1::Bindings;
 auto* context=static_cast<NativeLevelQuestCharacterCacheContextV1*>(raw);
 if(!context||!context->frame||!character_identity||
    event_owner!=context->frame->event_owner_identity||
    level_identity!=context->frame->level_identity||
    !native_level_quest_frame_context_current(*context->frame,error)){
  if(error.empty())error="Character cache request crossed the active Quest/Level frame";
  return false;
 }
 auto& manager=source_level_owner.object_manager();
 const auto active=source_level_owner.snapshot();
 const auto* object=manager.find_by_identity(character_identity);
 if(active.object_manager_identity!=reinterpret_cast<std::uintptr_t>(&manager)||
    active.source_level!=level_identity||!object||object->identity!=character_identity||
    !object->source_handle||manager.find_by_source_handle(object->source_handle)!=object){
  error="Character cache request has no canonical active ObjectManager identity";
  return false;
 }
 std::int16_t* property_cache=nullptr;
 std::int16_t* template_cache=nullptr;
 if(character_identity==prince_character.identity()){
  if(prince_combat.savegame&&prince_combat.savegame->character()!=character_identity){
   error="Player SafeGet cache crossed the active Save Character";return false;
  }
  property_cache=&prince_combat.property_cache;
  template_cache=&prince_combat.template_cache;
 }else if(auto* actor=native_actor_for_identity(character_identity)){
  if(actor->source_handle!=object->source_handle||
     actor->character_table_id<0||actor->character_table_id>32767||
     actor->character_template_id < -1){
   error="ObjectActor SafeGet caches do not match its canonical source identity";
   return false;
  }
  property_cache=&actor->character_table_id;
  template_cache=&actor->character_template_id;
 }else if(active_crypt_room_runtime&&
          active_crypt_room_runtime->character_factory){
  auto* record=active_crypt_room_runtime->character_factory->find_character(
      character_identity);
  if(record&&record->character.identity==character_identity&&
     record->game_object.identity==character_identity){
   property_cache=&record->property_id_13c8;
   template_cache=&record->template_id_13ca;
  }
 }
 if(!property_cache||!template_cache||*property_cache<0||
    *property_cache>32767||*template_cache < -1||*template_cache>32767||
    !prince_combat.profile_characters||
    static_cast<std::size_t>(*property_cache)>=
       prince_combat.profile_characters->names.size()){
  error="Canonical Character +0x13c8/+0x13ca SafeGet caches are not resolved";
  return false;
 }
 output=SafeGet{};
 output.character=character_identity;
 output.property_cache=property_cache;
 output.template_cache=template_cache;
 error.clear();return true;
}
bool native_level_quest_character_property(void* raw,
 std::uintptr_t event_owner,std::uintptr_t level_identity,
 std::uintptr_t character_identity,std::int32_t* output,
 std::string& error){
 if(!output){error="Character SafeGet output slot is null";return false;}
 *output=-1;
 dh2::character_saved_class_v1::Bindings bindings{};
 if(!native_level_quest_character_caches(raw,event_owner,level_identity,
       character_identity,bindings,error))return false;
 dh2::character_saved_class_v1::Runtime safe_get(bindings);
 dh2::character_saved_class_v1::Result result{};
 if(safe_get.resolve(&result,error)!=
      dh2::character_saved_class_v1::Status::complete||result.value<0||
    !prince_combat.profile_characters||
    static_cast<std::size_t>(result.value)>=
       prince_combat.profile_characters->names.size()){
  if(error.empty())error="Canonical Character::SafeGetCharPropsId cache read failed";
  return false;
 }
 *output=result.value;error.clear();return true;
}
