// These Objective providers are assembled from the active Level's retained
// Character census and canonical ObjectManager/CharacterList. Keep every
// vector and callback context alive for exactly the synchronous compile or
// GameEventManager::ReInit operation; the Level-owned Event records retain
// only their immutable definitions and ObjectiveLists.
namespace CurrentLevelRoster=dh2::native::current_level_source_character_roster_v1;
namespace CurrentLevelPopulation=dh2::native::current_level_character_population_v1;
struct NativeLevelObjectiveServicesScopeV1 {
 std::vector<CurrentLevelRoster::CensusRow> source_rows;
 std::vector<CurrentLevelPopulation::ImportedCharacterIdentityV1> imported;
 CurrentLevelPopulation::Bindings population_bindings{};
 std::unique_ptr<CurrentLevelPopulation::Provider> population_provider;
 dh2::native::quests::ObjectiveCompileDispatchServicesV1 objective_services{};
 NativeLevelQuestCompileContextV1 compile_context{};
 std::uintptr_t level_identity=0;
 std::uint32_t level_generation=0;
 std::string callback_error;

 bool initialize(const NativeLevelQuestFrameContextV1& requested_frame,
                 std::string& error) {
  namespace talk=dh2::native::current_level_talk_objective_marker_v1;
  const auto source=source_level_owner.snapshot();
  if(active_level_assets.name!="SWAMP"||
     active_level_assets.level_file!="001_swamp.mlx"||
     !prince_combat.quests||!prince_combat.savegame||!prince_combat.inventory||
     !prince_combat.profile_characters||!active_level_assets.source_level_handle_ledger||
     active_level_assets.source_character_census.empty()||
     actor_level_fields.level_list_index_3c!=source.level_row||
     !native_fx_owner||!actor_xp_design_settings.bytes||
     source.phase!=dh2::source_level_owner_v1::Phase::active||
     source.source_level!=requested_frame.level_identity||
     source.player_character!=requested_frame.character_identity||
     source.quest_owner!=prince_combat.quests.get()) {
   error="Current-Level Objective providers require the active source-complete SWAMP Level/Save/Character/FX owners";
   return false;
  }
  NativeLevelQuestFrameContextV1 frame=requested_frame;
  level_identity=source.source_level;
  level_generation=source.generation;
  frame.event_owner_identity=reinterpret_cast<std::uintptr_t>(prince_combat.quests.get());
  native_level_quest_persistent_frame=frame;
  auto& active_frame=native_level_quest_persistent_frame;
  native_level_quest_cache_context.frame=&active_frame;
  auto& manager=source_level_owner.object_manager();
  if(!CurrentLevelRoster::build_swamp_census_rows(active_level_assets.source_character_census,
       *active_level_assets.source_level_handle_ledger,manager,source_rows,error))
   return false;
  try{imported.reserve(source_rows.size());}
  catch(...){error="Current-Level Objective imported roster allocation failed";return false;}
  for(const auto& row:source_rows){
   if(!row.should_be_in_character_list)continue;
   if(!row.character_identity||row.source_handle<0||row.source_module_id<0){
    error="SWAMP source Character census has an unresolved retained import owner";
    return false;
   }
   imported.push_back({row.character_identity,row.source_handle,row.source_module_id});
  }
  // Dynamic source Characters: the Player and every Character a script created
  // with GameObject::_Summon, each listed once by its canonical factory Record.
  std::vector<std::uintptr_t> dynamic_characters{active_frame.character_identity};
  if(active_crypt_room_runtime) {
   try {
    for(const auto& summoned:active_crypt_room_runtime->script_npcs_by_identity)
     if(summoned.first)dynamic_characters.push_back(summoned.first);
   } catch(...) {
    error="Current-Level Objective dynamic roster allocation failed";return false;
   }
  }
  if(!CurrentLevelPopulation::make_active_level_bindings_from_imported_roster(
       source_level_owner,native_characters,source_level_owner.character_oid_cache(),
       active_frame.event_owner_identity,actor_level_fields.level_list_index_3c,
       static_cast<std::uint32_t>(prince_combat.profile_characters->rows.size()),
       imported.data(),imported.size(),dynamic_characters.data(),dynamic_characters.size(),
       &native_level_quest_cache_context,native_level_quest_character_property,
       native_level_quest_character_caches,population_bindings,error))return false;
  try{population_provider=std::make_unique<CurrentLevelPopulation::Provider>(population_bindings);}
  catch(...){error="Current-Level Objective population provider allocation failed";return false;}
  objective_services={};
  objective_services.population.kill_enemies=population_provider->services();
  objective_services.population.clear_enemies=population_provider->services();
  objective_services.population.kill_enemy_template=
      population_provider->kill_enemy_template_services();
  objective_services.population.clear_enemy_template=
      population_provider->clear_enemy_template_services();
  objective_services.inventory=prince_combat.inventory.get();
  objective_services.object_manager=&manager;
  objective_services.current_level_id=actor_level_fields.level_list_index_3c;
  objective_services.script_context=&active_frame;
  objective_services.start_script=native_level_quest_start_script_id;
  native_level_talk_marker_context.services={
      &native_characters.source(),&source_level_owner,&manager,
      reinterpret_cast<std::uintptr_t>(source.source_level),
      &native_level_quest_cache_context,native_level_talk_character_property,
      native_fx_owner.get(),talk::install_shared_fx_owner,
      talk::remove_shared_fx_owner};
  native_level_talk_marker_context.design_settings={
      actor_xp_design_settings.bytes,actor_xp_design_settings.size};
  objective_services.talk_marker_context=&native_level_talk_marker_context;
  objective_services.talk_marker=talk::callback;
  objective_services.move_in_zone_character={
      &native_level_quest_cache_context,native_level_move_in_zone_character_property,
      native_level_move_in_zone_is_player};
  compile_context={&active_frame,objective_services,{}};
  error.clear();return true;
 }
};
bool native_level_game_event_objective_member(void* raw,
    std::uintptr_t level_identity,std::uintptr_t manager_identity,
    dh2::data::game_event_manager_owner_v1::Row& row,
    const dh2::data::quest_objective_list_v1::MemberCall& call,
    std::string& error){
 error.clear();
 auto* scope=static_cast<NativeLevelObjectiveServicesScopeV1*>(raw);
 auto& owner=source_level_owner.game_event_manager();
 if(!scope||!scope->level_identity||scope->level_identity!=level_identity||
    scope->level_generation!=owner.level_generation()||
    owner.level_identity()!=level_identity||
    owner.manager_identity()!=manager_identity||
    manager_identity!=reinterpret_cast<std::uintptr_t>(&owner)||
    !scope->compile_context.frame||!prince_combat.quests||
    !native_level_quest_frame_context_current(*scope->compile_context.frame,
                                               error)){
  if(error.empty())
   error="GameEvent Objective crossed its retained source Level/manager generation";
  return false;
 }
 return prince_combat.quests->dispatch_game_event_objective_member_v1(
     level_identity,manager_identity,row,call,scope->objective_services,
     error);
}
dh2::data::game_event_manager_owner_v1::Services
native_level_game_event_services(NativeLevelObjectiveServicesScopeV1& scope){
 return {&scope,native_level_game_event_objective_member};
}
bool native_source_level_reinit_game_events_v1(
    std::uint32_t expected_generation,std::string& error){
 const auto active=source_level_owner.snapshot();
 if(active.phase!=dh2::source_level_owner_v1::Phase::active||
    active.source_level_state!=38||active.generation!=expected_generation||
    !active.checkpoint_load_in_progress||!active.source_level||
    !active.player_character||!prince_combat.quests||
    active.quest_owner!=prince_combat.quests.get()){
  error="GameEventManager::ReInit requires the same active checkpoint Level and canonical Quest owner";
  return false;
 }
 NativeLevelQuestFrameContextV1 frame{active.source_level,
     active.player_character,0,native_level_frame.application.last_real_time_ms,
     reinterpret_cast<std::uintptr_t>(prince_combat.quests.get()),active.generation};
 NativeLevelObjectiveServicesScopeV1 scope;
 if(!scope.initialize(frame,error))return false;
 auto& owner=source_level_owner.game_event_manager();
 const auto manager_identity=reinterpret_cast<std::uintptr_t>(&owner);
 if(owner.level_identity()!=active.source_level||
    owner.level_generation()!=active.generation||
    owner.manager_identity()!=manager_identity){
  error="Level::LoadCheckpoint has no same-generation retained GameEventManager";
  return false;
 }
 dh2::data::game_event_manager_owner_v1::Result result{};
 const auto status=owner.reinit(active.source_level,active.generation,
     manager_identity,native_level_game_event_services(scope),&result,error);
 if(status!=dh2::data::game_event_manager_owner_v1::Status::complete){
  if(!scope.callback_error.empty())error=scope.callback_error+" | "+error;
  if(error.empty())error="Level::LoadCheckpoint GameEventManager::ReInit failed";
  return false;
 }
 error.clear();return true;
}
bool native_level_game_event_compile_or_initialize(
    NativeLevelObjectiveServicesScopeV1& scope,std::string& error){
 namespace events=dh2::data::v2_event_table_v1;
 namespace owner_api=dh2::data::game_event_manager_owner_v1;
 const auto active=source_level_owner.snapshot();
 auto& owner=source_level_owner.game_event_manager();
 if(!scope.level_identity||scope.level_identity!=active.source_level||
    scope.level_generation!=active.generation||
    active.phase!=dh2::source_level_owner_v1::Phase::active||
    !prince_combat.quests||!player_camera_asset_manager){
  error="GameEventManager Load/Compile requires the exact active source Level, generation, and ObjectiveFactory owner";
  return false;
 }
 const auto manager_identity=reinterpret_cast<std::uintptr_t>(&owner);
 const auto services=native_level_game_event_services(scope);
 if(owner.table()&&(owner.level_identity()!=active.source_level||
                    owner.level_generation()!=active.generation||
                    owner.manager_identity()!=manager_identity)){
  owner_api::Result close_result{};
  if(owner.close(&close_result,error)!=owner_api::Status::complete)return false;
 }
 if(!owner.table()){
  const auto packed=read(player_camera_asset_manager,
      "v2eventmanager_pyarray.bin","original-cache/data/pydata");
  const auto names=read(player_camera_asset_manager,
      "v2eventmanager_pyarraynames.bin","original-cache/data/pydata");
  const auto constants=read(player_camera_asset_manager,
      "v2eventmanager_pycst.bin","original-cache/data/pydata");
  events::Table table;
  if(!events::load({packed.data(),static_cast<std::uint32_t>(packed.size())},
       {names.data(),static_cast<std::uint32_t>(names.size())},
       {constants.data(),static_cast<std::uint32_t>(constants.size())},
       table,error)){
   if(error.empty())error="GameEventManager Load could not parse the retained v2Event assets";
   return false;
  }
  dh2::data::quest_objective_list_v1::Services objective_services{};
  if(!prince_combat.quests->objective_list_services(objective_services,error))return false;
  owner_api::Result load_result{};
  const auto status=owner.initialize(active.source_level,active.generation,
      manager_identity,table,objective_services,services,&load_result,error);
  if(status!=owner_api::Status::complete){
   if(!scope.callback_error.empty())error=scope.callback_error+" | "+error;
   const std::string load_error=error;
   owner_api::Result close_result{};
   std::string close_error;
   if(owner.close(&close_result,close_error)!=owner_api::Status::complete)
    error=load_error+" | partial GameEventManager cleanup failed: "+close_error;
   else error=load_error;
   if(error.empty())error="GameEventManager Load failed to retain its source rows and ObjectiveLists";
   return false;
  }
 }
 static std::uintptr_t compiled_level=0;
 static std::uint32_t compiled_generation=0;
 if(compiled_level==active.source_level&&compiled_generation==active.generation){
  error.clear();return true;
 }
 owner_api::Result compile_result{};
 const auto status=owner.compile(active.source_level,active.generation,
     manager_identity,services,&compile_result,error);
 if(status!=owner_api::Status::complete){
  if(!scope.callback_error.empty())error=scope.callback_error+" | "+error;
  if(error.empty())error="GameEventManager Compile failed for the retained source Level";
  return false;
 }
 compiled_level=active.source_level;
 compiled_generation=active.generation;
 error.clear();return true;
}
