bool native_level_game_event_start_script(void* raw,
    const dh2::data::v2_event_table_v1::Event& event,
    const std::string& script,std::int32_t argument,bool check_running,
    bool online,bool& started,std::string& error){
 (void)event;
 error.clear();
 auto* context=static_cast<NativeLevelGameEventUpdateContextV1*>(raw);
 started=false;
 if(!context||!context->frame||argument!=-1||check_running||online||
    native_host.online||!native_level_quest_frame_context_current(
        *context->frame,error)){
  if(error.empty())error="GameEvent ExecScript requires the same offline Level VM and source (-1,false) arguments";
  return false;
 }
 if(script.empty()){error.clear();return true;}
 if(!native_level_quest_start_script(context->frame,script,argument,
       check_running,error)){
  if(error.empty())error="GameEvent ExecScript could not start its retained Level script";
  return false;
 }
 started=true;error.clear();return true;
}
bool native_source_level_update_game_events_v1(
    NativeLevelQuestFrameContextV1& frame,std::string& error){
 const auto active=source_level_owner.snapshot();
 auto& owner=source_level_owner.game_event_manager();
 if(!native_level_quest_frame_context_current(frame,error)||
    owner.level_identity()!=active.source_level||
    owner.level_generation()!=active.generation||
    owner.manager_identity()!=reinterpret_cast<std::uintptr_t>(&owner)||
    !owner.table()){
  if(error.empty())error="GameEventManager::Update has no same-generation retained source Level owner";
  return false;
 }
 NativeLevelGameEventUpdateContextV1 context{&frame};
 const dh2::data::game_event_manager_owner_v1::UpdateServices services{
     &context,native_level_game_event_objective_list_valid,
     native_level_game_event_objective_list_eval,
     native_level_game_event_start_script};
 dh2::data::v2_event_update_kernel_v1::Result result{};
 const auto status=owner.update(active.source_level,active.generation,
     reinterpret_cast<std::uintptr_t>(&owner),services,&result,error);
 if(status!=dh2::data::v2_event_update_kernel_v1::Status::complete){
  if(error.empty())error="GameEventManager::Update failed for the current source Level";
  return false;
 }
 error.clear();return true;
}
bool native_level_compile_quests_for_swamp(
 NativeLevelQuestFrameContextV1& frame,std::string& error,
 bool force=false){
 // Source ELF SHA-256 36498eb8180ffb74759e6305e9596db999f18583d460f3b8534abcb6022f5e80:
 // Level::Update (0x3f82d8) calls SG_Update(false) before level scripts/events;
 // CharacterSG_Update (0x3bc480) reaches PlayerSavegameSG_Update (0x4636c4),
 // whose UpdateQuests (0x46bb58) runs CompileQuests (0x46b824) then updates
 // objectives. The source compiles only the selected offline/online QEST log.
 NativeLevelObjectiveServicesScopeV1 scope;
 if(!scope.initialize(frame,error))return false;
 if(!native_level_game_event_compile_or_initialize(scope,error))return false;
 dh2::native::quests::QuestCompileServicesV1 compile_services{
     &scope.compile_context,native_level_quest_difficulty,
     native_level_quest_compile_objective};
 const std::uint32_t log=native_host.online?1u:0u;
 dh2::data::quest_compile_v1::Result result{};
 if(!prince_combat.quests->compile_quests(log,force,compile_services,
       result,error)){
  if(!scope.compile_context.callback_error.empty())
   error=scope.compile_context.callback_error+" | "+error;
  return false;
 }
 error.clear();return true;
}
