bool native_level_character_sg_update(void* raw,std::uintptr_t level_identity,
 std::uintptr_t character_identity,bool checkpoint,std::string& error){
 auto* context=static_cast<NativeLevelQuestFrameContextV1*>(raw);
 const auto source=source_level_owner.snapshot();
 if(!context||context->level_identity!=level_identity||
    context->character_identity!=character_identity||native_save_difficulty<0||
    native_save_difficulty>2||!native_level_quest_frame_context_current(*context,error)||
    (checkpoint&&native_host.online)){
  if(error.empty())error=checkpoint?
      "Character::SG_Update(true) lost the active offline checkpoint frame":
      "Character::SG_Update(false) lost the active Level/Character frame";
  return false;
 }
 if(checkpoint){
  if(source.generation==0||source.source_level!=level_identity||
     !source.checkpoint_load_in_progress){
   error="Character::SG_Update(true) requires the same Level's active LoadCheckpoint scope";
   return false;
  }
  const auto log=std::uint32_t(native_host.online?1:0);
  if(!prince_combat.quests->gameplay_log_states_supported(log,
        std::uint32_t(native_save_difficulty),error))return false;
  if(!prince_combat.savegame->source_quest_sync_update(character_identity,
        native_host.online)){
   error="PlayerSavegame::SG_TryQuestSync could not store its offline flag on the same Character Save";
   return false;
  }
 }
 if(active_level_assets.name=="SWAMP"&&
    active_level_assets.level_file=="001_swamp.mlx"&&
    !native_level_compile_quests_for_swamp(*context,error,checkpoint))return false;
 // Other Levels have no force-CompileQuests provider yet; their checkpoint
 // SG_Update follows the same per-frame path, which does not compile quests.
 // Level::Update calls PlayerManager::Update immediately after this
 // Character::SG_Update(false) callback, while +0x144 is still clear. Keep
 // the offline PM sync on that source boundary, before ScriptManager runs.
 auto update_player_manager=[&](){
  if(checkpoint)return true;
  if(source.phase!=dh2::source_level_owner_v1::Phase::active||
     source.source_level_state!=38||source.transition_flag_144)return true;
  return native_host_run_player_manager_activation(error);
 };
 const dh2::native::level_quest_active_v1::ScriptServices scripts{
  context,native_level_quest_script_running,native_level_quest_start_script};
 const auto difficulty=std::uint32_t(native_save_difficulty);
 bool has_completed=false;
 if(!prince_combat.quests->has_state_in_log(0,difficulty,12,has_completed,error))return false;
 if(!has_completed){
  std::vector<dh2::native::quests::QuestUpdateActiveResultV1> updated;
  if(!dh2::native::level_quest_active_v1::update_active_log(source,
       level_identity,character_identity,*prince_combat.savegame,
       *prince_combat.quests,native_host.online,native_save_difficulty,
       static_cast<std::int32_t>(context->application_time_ms),scripts,updated,error))
   return false;
  if(!update_player_manager())return false;
  return true;
 }
 if(native_host.online||native_save_difficulty<0||native_save_difficulty>2){
  error="Quest state-12 completion requires the current offline Character/QEST services";
  return false;
 }
 auto* player_properties=prince_character.properties_for(character_identity);
 auto* player_save=prince_character.save_for(character_identity);
 const auto& active_object_manager=source_level_owner.object_manager();
 const auto* player_object=active_object_manager.find_by_identity(character_identity);
 if(!player_properties||player_save!=prince_combat.savegame.get()||
    !player_object||player_object->identity!=character_identity||
    !player_object->live_fields.world_x||!player_object->live_fields.world_y){
  error="Quest completion requires the same current Level Player Character/Save/ObjectManager projection";
  return false;
 }
 auto player_view=dh2::data::property_view(actor_property_rules,*player_properties);
 NativeKillDistributeXPContextV1 xp_context{};
 xp_context.give.locality=native_host.locality_services();
 xp_context.give.player_lookup={&native_host.registry,&xp_context.give.locality};
 auto xp_owner=native_kill_give_xp_owner_v1(xp_context);
 dh2::character_distribute_xp_v1::CharacterView xp_character{
     character_identity,&player_view,player_save,*player_object->live_fields.world_x,
     *player_object->live_fields.world_y};
 NativeLevelQuestRewardContextV1 reward_context{};
 reward_context.frame=context;reward_context.xp_owner=&xp_owner;
 reward_context.xp_character=&xp_character;
 reward_context.xp={&xp_owner,&xp_character,character_identity,0,0,{}};
 const dh2::native::quests::QuestUpdateActiveServicesV1 active_services{
     context,native_level_quest_script_running,
     static_cast<std::int32_t>(context->application_time_ms),true,
     native_level_quest_start_script};
 const dh2::native::quests::QuestUpdateCompletedServicesV1 completed_services{
     &reward_context,native_level_quest_reward_character,
     native_level_quest_reward_add_gold,native_level_quest_reward_give_xp,
     native_level_quest_reward_application_time,
     native_level_quest_reward_save_character,native_level_quest_start_script};
 std::vector<dh2::native::quests::QuestUpdateActiveResultV1> updated_active;
 std::vector<dh2::native::quests::QuestUpdateCompletedResultV1> updated_completed;
 if(!prince_combat.quests->update_gameplay_log(0,difficulty,active_services,
      completed_services,updated_active,updated_completed,error))return false;
 if(!update_player_manager())return false;
 return true;
}
bool native_player_character_sg_update_checkpoint_v1(
 std::uint32_t expected_generation,std::string& error){
 const auto source=source_level_owner.snapshot();
 if(source.phase!=dh2::source_level_owner_v1::Phase::active||
    source.generation!=expected_generation||!source.source_level||
    !source.player_character||source.player_character!=prince_character.owner()||
    !source.checkpoint_load_in_progress||!prince_combat.savegame||
    !prince_combat.quests||
    source.canonical_player_savegame!=reinterpret_cast<std::uintptr_t>(
        prince_combat.savegame.get())||
    source.quest_owner!=prince_combat.quests.get()){
  error="Checkpoint SG_Update(true) requires the current generation's same Player/Save/QEST owners";
  return false;
 }
 NativeLevelQuestFrameContextV1 frame{source.source_level,source.player_character,
     0,native_level_frame.application.last_real_time_ms,
     reinterpret_cast<std::uintptr_t>(prince_combat.quests.get()),source.generation};
 return native_level_character_sg_update(&frame,source.source_level,
     source.player_character,true,error);
}
bool native_level_execute_scripts(void* raw,std::uintptr_t level_identity,
 std::string& error){
 auto* context=static_cast<NativeLevelQuestFrameContextV1*>(raw);
 if(!context||context->level_identity!=level_identity||
    !native_level_quest_frame_context_current(*context,error))return false;
 if(!native_level_script_session_is_current()){
  error="Current Level ScriptManager session is stale or unbound for this source Level";
  return false;
 }
 try{advance_native_level_script(context->dt_ms);error.clear();return true;}
 catch(const std::exception& ex){error=ex.what();return false;}
 catch(...){error="Existing Level ScriptManager frame failed";return false;}
}
int native_frame_scene_v1(void* raw,std::uint32_t timestamp_ms) noexcept {
 auto& context=*static_cast<NativeFrameContextV1*>(raw);
 try{
  if(!advance_authored_faery_scene_animations(timestamp_ms,context.error))
   throw std::runtime_error(context.error.empty()?
       "Faery Character Animator scene phase failed":context.error);
  dh2::actor::player_root_motion_policy_v1::Projection root_motion{};
  if(dh2::actor::player_root_motion_policy_v1::project(&root_motion,prince_state.flags)!=
     dh2::actor::player_root_motion_policy_v1::Status::complete)
   throw std::runtime_error("Player root-motion policy projection failed");
  prince_locomotion.displacement=root_motion.displacement;
  prince_scene_phase=true;
  if(!prince_locomotion.scene_phase(timestamp_ms,prince_attack_clips,prince_visual,current_scene,context.error))
   throw std::runtime_error(context.error);
  prince_scene_phase=false;
  return 0;
 }catch(const std::exception& e){prince_scene_phase=false;context.error=e.what();return 1;}
 catch(...){prince_scene_phase=false;context.error="Unknown scene animation provider failure";return 1;}
}
int native_frame_level_v1(void* raw,std::uint32_t dt_ms) noexcept {
 auto& context=*static_cast<NativeFrameContextV1*>(raw);
 try{
  // Original Level::Update runs script/event work before PhysicalWorld; a
  // contact started by actors below is consumed by the next frame. At this
  // boundary, run the bounded Character::SG_Update objective subset through
  // the same Save/QEST and existing ScriptManager before advancing its VM.
  const auto source=source_level_owner.snapshot();
  const bool same_active_level_script=native_level_script_session.ready()&&
      native_level_script_generation==source.generation&&
      native_level_script_level_name==active_level_assets.name&&
      source.phase==dh2::source_level_owner_v1::Phase::active&&
      source.source_level_state==38&&source.source_level&&
      source.player_character==prince_character.owner()&&
      source.quest_owner==prince_combat.quests.get()&&prince_combat.quests&&
      source.canonical_player_savegame==reinterpret_cast<std::uintptr_t>(prince_combat.savegame.get())&&
      prince_combat.savegame&&prince_combat.savegame->character()==source.player_character;
  if(same_active_level_script){
   dh2::native::level_sg_update_v1::FrameV1 frame{};
   if(!dh2::native::level_sg_update_v1::frame_from_source_level_v1(
       source,true,frame,context.error))throw std::runtime_error(context.error);
   NativeLevelQuestFrameContextV1 quest_context{
       source.source_level,source.player_character,dt_ms,
       native_level_frame.application.last_real_time_ms,
       reinterpret_cast<std::uintptr_t>(prince_combat.quests.get()),source.generation};
   const dh2::native::level_sg_update_v1::ServicesV1 services{
       &quest_context,nullptr,nullptr,native_level_character_sg_update,
       native_level_execute_scripts};
   dh2::native::level_sg_update_v1::ResultV1 result{};
   if(!dh2::native::level_sg_update_v1::dispatch_v1(frame,services,result,context.error))
    throw std::runtime_error(context.error);
   // Source Level::Update invokes GameEventManager::Update after the local
   // Character SG_Update/ScriptManager boundary and before PhysicalWorld.
   if(active_level_assets.name=="SWAMP"&&
      active_level_assets.level_file=="001_swamp.mlx"&&
      !native_source_level_update_game_events_v1(quest_context,context.error))
    throw std::runtime_error(context.error);
  }else{
   // Preserve the existing Crypt-only script advance when canonical Level,
   // Character, Save and QEST owners are not all bound to this frame.
   advance_native_level_script(dt_ms);
  }
  request_prince_death();
  // Application::Update -> PlayerManager::Update reaches _CheckLocalDeaths each
  // gameplay frame; only its dead-Player branch has an effect offline.
  if(prince_combat.life.dead&&native_host_pm_check_local_deaths(&native_host,context.error))
   throw std::runtime_error(context.error);
  if(active_crypt_room_runtime&&
     !active_crypt_room_runtime->source_move_in_zones.empty()) {
   std::string zone_error;
   if(!active_crypt_room_runtime->reconcile_source_move_in_zone_conditions(
        zone_error))
    throw std::runtime_error("SWAMP source QuestMoveInZone condition update failed: "+
                             zone_error);
  }
  if(active_crypt_room_runtime&&
     !active_crypt_room_runtime->source_destructible_containers.empty()) {
   std::string container_error;
   if(!active_crypt_room_runtime->reconcile_source_destructible_container_conditions(
         container_error))
    throw std::runtime_error("Source DestructibleContainer condition update failed: "+
                             container_error);
  }
  const auto updated_source=source_level_owner.snapshot();
  if(updated_source.phase==dh2::source_level_owner_v1::Phase::active&&
     updated_source.source_level_state==38&&updated_source.source_level&&
     !updated_source.transition_flag_144){
   if(!source_level_owner.publish_level_update_complete(updated_source.generation))
    throw std::runtime_error("Source Level Update could not publish its +0x144 loaded byte");
   // _ManageCharacters passes Level +0x144 to the Character's vtable +0x40
   // (0x372e8c); the next PlayerManager pass after the loaded byte is set
   // therefore re-enables the local Player that the loading pass hid.
   if(!native_host.online&&updated_source.player_character==prince_character.identity()){
    prince_character.set_visible(1);
    // PlayerManager::_AddCharacter 0x372490 ends with Level::QuickSave(false)
    // once the local Player is in the Level; that entry checkpoint is what an
    // offline ReviveLocalPlayers -> Level::LoadCheckpoint restores.
    std::string checkpoint_error;
    // CheckpointSave's +0x1468/+0x1474 writes precede its saveAll; set them
    // before the shared INFO/OBJS image is published so the checkpoint copy
    // carries the revive destination.
    {
     std::uint32_t entry_xyz[3]{};
     std::memcpy(entry_xyz,prince_runtime.subobjects.position,sizeof(entry_xyz));
     prince_character.save_checkpoint_position(prince_character.identity(),entry_xyz);
     prince_character.save_checkpoint_revive_position(prince_character.identity(),entry_xyz);
    }
    if(!native_level_quick_save_v1(false,checkpoint_error))
     __android_log_print(ANDROID_LOG_WARN,"DH2Native",
         "Level entry QuickSave unavailable | %s",checkpoint_error.c_str());
    else {
     __android_log_print(ANDROID_LOG_INFO,"DH2Native","Level entry QuickSave | generation %u",
         updated_source.generation);
     // Level::_LoadProcess 0x3f6e84 then calls Level::CheckpointSave(Player
     // position, false): +0x1468/+0x1474 take the Player position and
     // LevelSavegame::SaveCheckPoint writes the same INFO/OBJS image under the
     // checkpoint name. Character::SG_SaveCheckpoint's QEST file is not yet
     // reconstructed (its absence is a valid empty checkpoint on load).
     std::uint32_t xyz[3]{};
     std::memcpy(xyz,prince_runtime.subobjects.position,sizeof(xyz));
     std::string checkpoint_name;
     const auto active=source_level_owner.snapshot();
     std::error_code ec;
     if(!prince_character.save_checkpoint_position(prince_character.identity(),xyz)||
        !prince_character.save_checkpoint_revive_position(prince_character.identity(),xyz)||
        active.source_save_slot<0||
        !dh2::level_savegame_owner_v1::format_checkpoint_filename(
            active.source_save_slot,active.difficulty,checkpoint_name,checkpoint_error)){
      __android_log_print(ANDROID_LOG_WARN,"DH2Native","Level entry CheckpointSave unavailable | %s",
          checkpoint_error.c_str());
     }else{
      const auto directory=level_savegame_publisher.directory();
      const auto level_file=directory/std::filesystem::u8path(
          source_level_owner.level_savegame().filename());
      const auto checkpoint_file=directory/std::filesystem::u8path(checkpoint_name);
      std::filesystem::copy_file(level_file,checkpoint_file,
          std::filesystem::copy_options::overwrite_existing,ec);
      if(ec)__android_log_print(ANDROID_LOG_WARN,"DH2Native",
          "Level entry CheckpointSave file write failed | %s",ec.message().c_str());
      else __android_log_print(ANDROID_LOG_INFO,"DH2Native",
          "Level entry CheckpointSave | %s | revive %.1f %.1f %.1f",checkpoint_name.c_str(),
          prince_runtime.subobjects.position[0],prince_runtime.subobjects.position[1],
          prince_runtime.subobjects.position[2]);
     }
    }
   }
  }
  return 0;
 }catch(const std::exception& e){context.error=e.what();return 1;}
 catch(...){context.error="Unknown Level pre-physics provider failure";return 1;}
}
int native_frame_physics_v1(void* raw,std::uint32_t dt_ms,float dt_seconds,
                            std::uint32_t iterations) noexcept {
 auto& context=*static_cast<NativeFrameContextV1*>(raw);
 try{
  if(iterations!=10||!std::isfinite(dt_seconds))throw std::runtime_error("Source PhysicalWorld Step arguments rejected");
  std::string item_motion_error;
  if(!update_native_world_item_motion_before_step(item_motion_error))
   throw std::runtime_error(item_motion_error);
  native_frame_dt_ms=dt_ms;
  actor_world.update(dt_ms);++native_physics_steps;
  sync_native_projectile_positions_after_step_v1(dt_ms);
  update_native_world_items_after_step(dt_ms);
  return 0;
 }catch(const std::exception& e){context.error=e.what();return 1;}
 catch(...){context.error="Unknown PhysicalWorld provider failure";return 1;}
}
