int player_remove_delete_rename_service(void*,std::uintptr_t character,
        const std::string& original_name,const std::string& deleted_name,
        std::string& error){
 using namespace dh2::object_manager_runtime_owner_v1;
 const auto source=source_level_owner.snapshot();
 if(!character||character!=prince_character.identity()||!active_crypt_room_runtime||
    source.phase!=dh2::source_level_owner_v1::Phase::active||
    source.object_manager_identity!=reinterpret_cast<std::uintptr_t>(
        &active_crypt_room_runtime->manager)){
  error="ObjectBase::Delete/SetName requires the same active Player ObjectManager";return 1;
 }
 auto& manager=active_crypt_room_runtime->manager;
 auto* object=manager.find_by_identity(character);
 std::size_t occurrences=0;
 if(!object||object->identity!=character||object->source_handle!=3||
    object->name!=original_name||original_name.empty()||deleted_name.empty()||
    object->live_fields.deleted_state_82!=prince_character.deleted_state_82_storage()||
    object->live_fields.deleted_81!=prince_character.deleted_81_storage()||
    prince_character.deleted_81()!=0||
    !native_characters.contains_identity(character,&occurrences)||occurrences!=1){
  error="ObjectBase::Delete/SetName lost its exact Character/ObjectManager/CharacterList identity";return 1;
 }
 bool changed=false;
 if(manager.delete_object(character,&changed)!=Status::ok||!changed||
    prince_character.deleted_state_82_storage()==nullptr||
    *prince_character.deleted_state_82_storage()!=2||prince_character.deleted_81()!=1){
  error="ObjectBase::Delete did not retain +0x82=2/+0x81=1 on the same Character";return 1;
 }
 if(manager.rename_object(character,deleted_name)!=Status::ok){
  error="ObjectBase::SetName could not update the canonical ObjectManager name index";return 1;
 }
 object=manager.find_by_identity(character);
 occurrences=0;
 if(!object||object->name!=deleted_name||object->source_handle!=3||
    !native_characters.contains_identity(character,&occurrences)||occurrences!=1){
  error="ObjectBase::SetName changed CharacterList membership or lost the canonical named row";return 1;
 }
 error.clear();return 0;
}
int player_remove_level_effects_service(void*,std::int32_t remaining_count,
        bool local_controlled,std::int32_t player_class,std::string& error){
 const auto source=source_level_owner.snapshot();
 if(!local_controlled||player_class==-1||remaining_count!=0||
    source.phase!=dh2::source_level_owner_v1::Phase::active||
    source.source_level_state!=0||!source.source_level||
    source.object_manager_identity!=reinterpret_cast<std::uintptr_t>(
        &source_level_owner.object_manager())){
  error="CurrentLevel::UpdateLightSet branch crossed its canonical Level/Player state";return 1;
 }
 // Source Level::UpdateLightSet(bool,int) at 0x3ef280 is a four-byte RET stub.
 // The caller reaches it as (true,4); this provider verifies that exact branch
 // and intentionally has no state write.
 error.clear();return 0;
}
int player_remove_info_tail_service(void*,
        dh2::player_info_record_v1::Record& record,std::uintptr_t character,
        std::uint8_t manager_flag,std::string& error){
 if(&record!=native_host.record_for(native_host.host_projection())||
    manager_flag!=native_host.player_manager_update.manager_remove_flag_6c9){
  error="PlayerManager::RemoveCharacter tail crossed its canonical PlayerInfo/manager";return 1;
 }
 std::uint8_t online=0;bool active=false;
 if(native_host_pm_read_online(&native_host,&online)||online){
  error="PlayerManager::RemoveCharacter active PlayerInfo query is offline-only";return 1;
 }
 const dh2::player_info_activity_v1::Services activity{
     &native_host,native_host_pm_read_online};
 if(dh2::player_info_activity_v1::player_is_active(record,activity,&active)!=
      dh2::player_info_activity_v1::Status::complete){
  error="PlayerInfo::IsActive failed on the canonical offline record";return 1;
 }
 dh2::player_info_character_removal_tail_v1::Result result{};
 const auto status=dh2::player_info_character_removal_tail_v1::remove_character_tail(
     record,character,manager_flag,active,{},&result);
 if(status!=dh2::player_info_character_removal_tail_v1::Status::complete||
    !result.character_link_cleared||record.character_660!=0){
  error="PlayerManager::RemoveCharacter PlayerInfo field tail failed";return 1;
 }
 error.clear();return 0;
}
