   dh2::level_world::destructible_container_interaction_v1::raise_opened_event(
    container->network_id,container->data_id,event_services,error);
  if(event_status!=dh2::level_world::destructible_container_interaction_v1::Status::complete) {
   if(error.empty())error="DestructibleContainer opened event could not be raised";
   return false;
  }
  if(!container->do_open) {
   error="Container::DoOpen callback was not retained for the source object";
   return false;
  }
  return container->do_open(error);
